using namespace std;

struct TransformationRule {
    string pattern;
    string replacement;
};

void processFile(ifstream& input, ofstream& output, const vector<TransformationRule>& rules, size_t bufferSize, bool prioritizeSpeed) {
    // Dynamic allocation for the output buffer
    char* buffer = new char[bufferSize];
    assert(buffer != nullptr);

    // Read file contents into the buffer
    input.read(buffer, bufferSize);

    // Apply transformation rules
    for (const auto& rule : rules) {
        size_t patternLength = strlen(rule.pattern);
        size_t replacementLength = strlen(rule.replacement);

        char* pos = buffer;
        while ((pos = strstr(pos, rule.pattern)) != nullptr) {
            // Replace the matched pattern with the replacement string
            memcpy(pos, rule.replacement, replacementLength);

            // Update the position of the next search starting from the end of the replaced string
            pos += patternLength;
        }
    }

    // Write buffer contents to output file
    output.write(buffer, strlen(buffer));

    delete[] buffer;
}

int main(int argc, char** argv) {
    if (argc != 6) {
        cerr << "Usage: " << argv[0] << " <input_file> <output_file> <rules> <buffer_size> <prioritize_speed>" << endl;
        return 1;
    }

    // Open input and output files
    ifstream input(argv[1]);
    ofstream output(argv[2]);

    // Parse the rules string into a vector of transformation rules
    vector<TransformationRule> rules;
    size_t patternLength = 0, replacementLength = 0;
    for (const auto& rule : split(argv[3], '|')) {
        patternLength = strlen(rule.pattern);
        replacementLength = strlen(rule.replacement);
        rules.push_back({rule.pattern, rule.replacement});
    }

    // Convert the buffer size string to an integer
    size_t bufferSize = atoi(argv[4]);

    // Check if the prioritize speed flag is set
    bool prioritizeSpeed = argv[5][0] == '1';

    processFile(input, output, rules, bufferSize, prioritizeSpeed);

    input.close();
    output.close();

    return 0;
}

struct Rule {
    char* pattern;
    char* replacement;
};

vector<Rule> split(const string& str, char delimiter) {
    vector<Rule> rules;
    size_t pos = 0;
    while ((pos = str.find(delimiter)) != string::npos) {
        Rule rule;
        rule.pattern = strdup(str.substr(0, pos).c_str());
        rule.replacement = strdup(str.substr(pos + 1).c_str());
        rules.push_back(rule);
    }
    return rules;
}']

