#include <errno.h>

// Define a struct for storing the list of integers
struct IntegerList {
    int *data;
    size_t capacity;
    size_t count;
};

// Define a function to allocate memory for the list
struct IntegerList* createIntegerList(size_t initialCapacity) {
    struct IntegerList* list = malloc(sizeof(struct IntegerList));
    if (list == NULL) {
        fprintf(stderr, "Error: out of memory\n");
        return NULL;
    }
    list->data = malloc(initialCapacity * sizeof(int));
    if (list->data == NULL) {
        fprintf(stderr, "Error: out of memory\n");
        free(list);
        return NULL;
    }
    list->capacity = initialCapacity;
    list->count = 0;
    return list;
}

// Define a function to add an integer to the list
int addIntegerToList(struct IntegerList* list, int value) {
    if (list->count == list->capacity) {
        // Resize the array to double its capacity
        list->capacity *= 2;
        list->data = realloc(list->data, list->capacity * sizeof(int));
        if (list->data == NULL) {
            fprintf(stderr, "Error: out of memory\n");
            free(list);
            return -1;
        }
    }
    list->data[list->count] = value;
    list->count++;
    return 0;
}

// Define a function to find and print the largest integer in the list
int findLargestInteger(struct IntegerList* list) {
    if (list->count == 0) {
        fprintf(stderr, "Error: empty list\n");
        return -1;
    }
    int largest = list->data[0];
    for (size_t i = 1; i < list->count; i++) {
        if (list->data[i] > largest) {
            largest = list->data[i];
        }
    }
    printf("%d\n", largest);
    return 0;
}

// Define a function to free all allocated memory
void freeIntegerList(struct IntegerList* list) {
    free(list->data);
    free(list);
}

int main() {
    struct IntegerList* list = createIntegerList(1000);
    if (list == NULL) {
        return 1;
    }
    while (true) {
        int input;
        scanf("%d", &input);
        if (input == EOF) {
            break;
        }
        addIntegerToList(list, input);
    }
    findLargestInteger(list);
    freeIntegerList(list);
    return 0;
}
```
