int load_algorithm(const char* library_path, const char* algorithm_name) {
    void* handle = dlopen(library_path, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Failed to open library %s: %s\n", library_path, dlerror());
        return -1;
    }

    void* symbol = dlsym(handle, algorithm_name);
    if (!symbol) {
        fprintf(stderr, "Symbol %s not found in library %s: %s\n", algorithm_name, library_path, dlerror());
        return -1;
    }

    int (*init_fn)(void) = symbol;
    if (init_fn() != 0) {
        fprintf(stderr, "Failed to initialize algorithm %s from library %s\n", algorithm_name, library_path);
        return -1;
    }

    return 0;
}

