        return NULL;
    }
    int ret = EVP_EncryptInit_ex(ctx, PADDING_SCHEME, NULL, encryption_key, NULL);
    if (ret != 1) {
        log_function("Error initializing encryption parameters");
        return NULL;
    }
    ret = EVP_CIPHER_CTX_set_padding(ctx, 1);
    if (ret != 1) {
        log_function("Error setting padding scheme");
        return NULL;
    }
    int key_len = strlen(encryption_key);
    ret = EVP_CIPHER_CTX_set_key_length(ctx, key_len);
