            if (ret != 1) {
                log_function("Error encrypting data");
                return NULL;
            }
        }
        ret = EVP_EncryptFinal(ctx, output_buffer + written_bytes, &written_bytes);
        if (ret != 1) {
            log_function("Error finalizing encryption operation");
            return NULL;
        }
        written_bytes += iv_len;
        write(output_fd, output_buffer, written_bytes);
        free(input_buffer);
    } while (read_bytes == BLOCK_SIZE && num_retries < MAX_RETRIES);
    if (num_retries >= MAX_RETRIES) {
        log_function("Maximum number of retries exceeded");
        return NULL;
    }

    // Clean up resources and return the cipher object
    free(iv);
    EVP_CIPHER_CTX_free(ctx);
    close(input_fd);
    close(output_fd);
    return ctx;
}

// Function for decrypting a file using AES-256-CBC with PKCS7 padding
void *decrypt_file(char* config_path, char* encryption_key, void* cipher_ctx) {
    // Set up the decryption parameters and allocate memory for the initialization vector
    EVP_CIPHER_CTX *ctx = (EVP_CIPHER_CTX*)cipher_ctx;
    int ret = EVP_DecryptInit_ex(ctx, PADDING_SCHEME, NULL, encryption_key, NULL);
    if (ret != 1) {
        log_function("Error initializing decryption parameters");
        return NULL;
    }
    int key_len = strlen(encryption_key);
    ret = EVP_CIPHER_CTX_set_key_length(ctx, key_len);
    if (ret != 1) {
        log_function("Error setting decryption key length");
        return NULL;
    }
    unsigned char *iv = malloc(IV_LEN);

    // Read the input file and write the output to the output file
    int num_retries = 0;
    do {
        // Read the input file in blocks
        unsigned char *input_buffer = malloc(BLOCK_SIZE + IV_LEN);
        size_t read_bytes = read(input_fd, input_buffer, BLOCK_SIZE + IV_LEN);
        if (read_bytes == -1) {
            log_function("Error reading from input file");
            return NULL;
        }

        // Decrypt the input block and write it to the output file
        size_t written_bytes = 0;
        while (written_bytes < read_bytes) {
            ret = EVP_DecryptUpdate(ctx, output_buffer + written_bytes, &written_bytes, input_buffer + IV_LEN + written_bytes, read_bytes - written_bytes);
            if (ret != 1) {
                log_function("Error decrypting data");
                return NULL;
            }
        }
        ret = EVP_DecryptFinal(ctx, output_buffer + written_bytes, &written_bytes);
        if (ret != 1) {
            log_function("Error finalizing decryption operation");
            return NULL;
        }
        written_bytes -= iv_len;
        write(output_fd, output_buffer, written_bytes);
        free(input_buffer);
    } while (read_bytes == BLOCK_SIZE + IV_LEN && num_retries < MAX_RETRIES);
    if (num_retries >= MAX_RETRIES) {
        log_function("Maximum number of retries exceeded");
        return NULL;
    }

    // Clean up resources and return the cipher object
    free(iv);
    EVP_CIPHER_CTX_free(ctx);
    close(input_fd);
    close(output_fd);
    return ctx;
}
