import os
import stat
import sys
from typing import Union


def encrypt_file(config_path: str, encryption_key: Union[str, bytes], cipher_ctx):
    # Set up the encryption parameters and allocate memory for the initialization vector
    iv = get_random_iv()
    ctx = init_encryption_context(encryption_key)

    # Open the input file and create an output file with a .enc extension
    input_fd = os.open(config_path, os.O_RDONLY)
    output_path = config_path + ".enc"
    output_fd = os.open(output_path, os.O_WRONLY | os.O_CREAT, stat.S_IRUSR | stat.S_IWUSR)

    # Read the input file in blocks and encrypt it using AES-GCM
    block_size = 16 * 1024
    while True:
        data = os.read(input_fd, block_size)
        if not data:
            break
        encrypted_data = aes_gcm_encrypt(ctx, iv, data)
        os.write(output_fd, encrypted_data)
    # Close the file descriptors and return the cipher object
    os.close(input_fd)
    os.close(output_fd)
    return ctx


def decrypt_file(config_path: str, encryption_key: Union[str, bytes], cipher_ctx):
    # Set up the decryption parameters and allocate memory for the initialization vector
    iv = get_random_iv()
    ctx = init_decryption_context(encryption_key)

    # Open the input file and create an output file with the same name as the config file
    input_fd = os.open(config_path, os.O_RDONLY)
    output_path = config_path[:-4]
    output_fd = os.open(output_path, os.O_WRONLY | os.O_CREAT, stat.S_IRUSR | stat.S_IWUSR)

    # Read the input file in blocks and decrypt it using AES-GCM
    block_size = 16 * 1024
    while True:
        data = os.read(input_fd, block_size)
        if not data:
            break
        decrypted_data = aes_gcm_decrypt(ctx, iv, data)
        os.write(output_fd, decrypted_data)
    # Close the file descriptors and return the cipher object
    os.close(input_fd)
    os.close(output_fd)
    return ctx


def get_random_iv():
    iv = bytearray(16)
    os.urandom(len(iv))
    return iv


def init_encryption_context(key):
    # Initialize the encryption context and set the AES-GCM parameters
    ctx = cipher.AEADCipher()
    ctx.init("aes256gcm", key)
    ctx.set_params(aead_params=cipher.AEADParams(nonce_size=12, tag_size=16))
    return ctx


def init_decryption_context(key):
    # Initialize the decryption context and set the AES-GCM parameters
    ctx = cipher.AEADCipher()
    ctx.init("aes256gcm", key)
    ctx.set_params(aead_params=cipher.AEADParams(nonce_size=12, tag_size=16))
    return ctx


def aes_gcm_encrypt(ctx, iv, data):
    # Encrypt the data using AES-GCM and return the ciphertext
    ciphertext = ctx.update(data)
    ciphertext += ctx.final()
    return iv + ciphertext


def aes_gcm_decrypt(ctx, iv, data):
    # Decrypt the data using AES-GCM and return the plaintext
    plaintext = ctx.update(data)
    plaintext += ctx.final()
    return plaintext
