Implementation:
```cpp
Logger::Logger(const std::string& log_path, size_t max_log_size) {
    // Initialize logging system
    initialize();
}

void Logger::initialize() {
    // Create log buffer for the current thread
    log_buffer = std::make_unique<LogBuffer>();
}

Logger::~Logger() {
    // Flush buffered messages to disk
    flush();
}

void Logger::log(LogLevel level, const std::string& message) {
    // Acquire lock on log buffer
    std::lock_guard<std::mutex> lock(log_buffer->mutex);

    // Add message to log buffer
    log_buffer->messages.push_back({
        std::chrono::system_clock::now().time_since_epoch(),
        level,
        message
    });

    // Check size of log buffer and rotate or compress it if necessary
    check_log_size();
}

void Logger::flush() {
    // Acquire lock on log buffer
    std::lock_guard<std::mutex> lock(log_buffer->mutex);

    // Write log messages to file
    for (const auto& message : log_buffer->messages) {
        write_message_to_file(message.timestamp, message.level, message.message);
    }

    // Clear log buffer
    log_buffer->messages.clear();
}

void Logger::rotate() {
    // Acquire lock on log buffer
    std::lock_guard<std::mutex> lock(log_buffer->mutex);

    // Rotate logs if necessary
    if (log_buffer->size > max_log_size) {
        rotate_logs();
    }
}

void Logger::compress() {
    // Acquire lock on log buffer
    std::lock_guard<std::mutex> lock(log_buffer->mutex);

    // Compress logs if necessary
    if (log_buffer->size > max_log_size) {
        compress_logs();
    }
}

void Logger::check_log_size() {
    // Acquire lock on log buffer
    std::lock_guard<std::mutex> lock(log_buffer->mutex);

    // Rotate or compress logs if necessary
    rotate();
    compress();
}
