using System;
using System.IO;
using System.Xml;
using System.Collections.Generic;

public static string RetrieveConfiguredSetting(string configFilePath, string settingKey) {
    // Validate input parameters
    if (string.IsNullOrEmpty(configFilePath)) {
        throw new ArgumentException("Configuration file path is not specified.", nameof(configFilePath));
    }
    if (string.IsNullOrEmpty(settingKey)) {
        throw new ArgumentException("Setting key is not specified.", nameof(settingKey));
    }

    // Parse the XML document and find the first instance of the specified setting key
    XmlDocument doc = new XmlDocument();
    try {
        doc.Load(configFilePath);
    } catch (IOException e) {
        Console.WriteLine($"Failed to load configuration file: {e.Message}");
        return null;
    } catch (XmlException e) {
        Console.WriteLine($"Invalid XML format in configuration file: {e.Message}");
        return null;
    }
    XmlNode settingNode = doc.SelectSingleNode($"/configuration/setting[@key='{settingKey}']");
    if (settingNode == null) {
        Console.WriteLine($"Setting key '{settingKey}' not found in configuration file.");
        return null;
    }

    // Get the value of the setting node
    string value = settingNode.Attributes["value"].Value;

    // Log a warning message if no value is found, and return a default placeholder value
    if (string.IsNullOrEmpty(value)) {
        Console.WriteLine($"Setting key '{settingKey}' has no value in configuration file.");
        return "DEFAULT_VALUE";
    }

    // Log an informational message if multiple values are found, and return the first occurrence
    if (settingNode.Attributes["value"].Value == settingNode.Attributes["value"].NextSibling) {
        Console.WriteLine($"Setting key '{settingKey}' has multiple values in configuration file.");
        return value;
    }

    // Return the value of the setting node
    return value;
}
