use std::path::PathBuf;

fn InitializeProjectEnvironment(project_dir_name: &str) {
    // Check if the project-specific environment variable is already set
    let mut home_dir = env::var("PROJECT_HOME");
    if !home_dir.is_err() && !home_dir.unwrap().is_empty() {
        // Use the existing value
        println!("Using existing PROJECT_HOME: {}", home_dir.unwrap());
        return;
    }

    // Create a new directory with the specified name
    let mut project_dir = PathBuf::from(project_dir_name);
    project_dir.push("");
    if !project_dir.exists() {
        match fs::create_dir(&project_dir) {
            Ok(_) => {
                // Set the PROJECT_HOME environment variable to the path of the newly created directory
                home_dir = env::set_var("PROJECT_HOME", project_dir.as_os_str().to_string_lossy());
                println!("Created new project directory: {}", &home_dir.unwrap());
            },
            Err(e) => {
                // Log detailed error messages if the directory creation fails
                println!("Failed to create project directory: {}", e);
            }
        }
    } else {
        println!("Project directory already exists.");
    }
}
