package com.example;

import java.security.MessageDigest;
import java.util.stream.Collectors;

public class StringConcatenator {
    /**
     * Converts an array of strings to a single string by concatenating them all together, while ensuring that the resulting string is consistent with the MD5 hash function.
     * @param inputStrings The array of strings to be concatenated.
     * @return A pair consisting of the concatenated string and its corresponding MD5 hash.
     */
    public static Pair<String, String> concatenateAndHash(String[] inputStrings) {
        // Step 1: Handle null or malformed input strings
        if (inputStrings == null || inputStrings.length == 0) {
            return new Pair<>("", "");
        }

        // Step 2: Normalize character encodings and convert to uppercase
        String[] normalizedInputStrings = Arrays.stream(inputStrings).map(String::toUpperCase).toArray(String[]::new);

        // Step 3: Concatenate the normalized strings
        String concatenatedString = Arrays.stream(normalizedInputStrings).collect(Collectors.joining());

        // Step 4: Calculate the MD5 hash of the concatenated string
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(concatenatedString.getBytes());
        String hash = new BigInteger(1, digest).toString(16);

        return new Pair<>(concatenatedString, hash);
    }
}

class Pair<F, S> {
    private final F first;
    private final S second;

    public Pair(F first, S second) {
        this.first = first;
        this.second = second;
    }

    public F getFirst() {
        return first;
    }

    public S getSecond() {
        return second;
    }
}']

