        return json_encode([
            'success' => false,
            'message' => 'Passwords do not match.',
            'error' => null
        ]);
    }

    // handle update or create request
    if ($_REQUEST['id'] === null) {
        // create new user account
        $user = createUser($_REQUEST['name'], $_REQUEST['email'], $_REQUEST['password']);
        if (!$user) {
            return json_encode([
                'success' => false,
                'message' => 'Error creating new user.',
                'error' => null
            ]);
        }
    } else {
        // update existing user account
        $user = getUser($_REQUEST['id']);
        if (!$user) {
            return json_encode([
