                'error' => null
            ]);
        }
        $updatedUser = updateUser($user, $_REQUEST['name'], $_REQUEST['email'], $_REQUEST['password']);
        if (!$updatedUser) {
            return json_encode([
                'success' => false,
                'message' => 'Error updating user data.',
                'error' => null
            ]);
        }
    }

    // handle delete request
    if ($_REQUEST['sub_action'] === 'delete') {
        $deleted = deleteUser($_REQUEST['id']);
        if (!$deleted) {
            return json_encode([
                'success' => false,
                'message' => 'Error deleting user.',
                'error' => null
            ]);
        }
    }

    // persist changes to database
    $saved = saveUser($user);
    if (!$saved) {
        return json_encode([
            'success' => false,
            'message' => 'Error saving user data.',
            'error' => null
        ]);
    }

    // return response with success message and relevant data or error messages
    if ($validationResults['valid'] && $saved) {
        return json_encode([
            'success' => true,
            'message' => 'User account updated successfully.',
            'data' => $user
        ]);
    } else {
        return json_encode([
            'success' => false,
            'message' => 'Error updating user account.',
            'error' => null
        ]);
    }
}
