        _httpClient = httpClient;
        _jsonSerializerOptions = jsonSerializerOptions;
    }

    public async Task<bool> UpdatePageElementAsync(int pageSectionId, int elementId, string htmlContent) {
        // Validate the request data for integrity and authenticity
        if (pageSectionId <= 0 || elementId <= 0 || string.IsNullOrEmpty(htmlContent)) {
            return false;
        }

        // Use a service class to update the element's HTML content
        var elementService = new ElementService(_httpClient, _jsonSerializerOptions);
        await elementService.UpdateElementAsync(pageSectionId, elementId, htmlContent);

        // Invalidate cache if necessary
        if (CacheManager.IsInvalidationRequired()) {
            CacheManager.InvalidateCache();
        }

        return true;
    }
}
