const { promisify } = require('util');

const readFileAsync = promisify(fs.readFile);
const statAsync = promisify(fs.stat);
const readdirAsync = promisify(fs.readdir);

async function aggregateFiles(directory, timeout) {
  const files = await readdirAsync(directory);
  let results = {};

  // Set up a cache for processed file contents
  const cache = new Map();

  // Loop through each file and process it
  for (const file of files) {
    if (cache.has(file)) {
      results[file] = cache.get(file);
    } else {
      try {
        const filePath = path.join(directory, file);
        const fileStats = await statAsync(filePath);

        // Check the file size to prevent hanging
        if (fileStats.size > timeout) {
          throw new Error(`File ${file} is too large and cannot be processed within the specified timeout.`);
        }

        const fileContent = await readFileAsync(filePath, 'utf8');
        cache.set(file, fileContent);
        results[file] = processFile(fileContent);
      } catch (error) {
        // Handle missing or corrupted files gracefully
        console.log(`Error reading file ${file}: ${error}`);
      }
    }
  }

  return results;
}

// Process a single file and return the aggregated result
