  const timeoutDuration = 10 * 1000; // 10 seconds in milliseconds
  for (const [testName, testFunction] of Object.entries(module)) {
    if (Date.now() - startTime > timeoutDuration) {
      console.warn(`Timeout reached while running ${testName} test.`);
      break;
    }
  }

  // Ensure thread safety when multiple instances of the test runner are executed concurrently, avoiding race conditions and ensuring consistent state across all running instances
  const lock = new Mutex();
  for (const [testName, testFunction] of Object.entries(module)) {
    lock.acquire(() => {
      try {
        testFunction(blueslip);
        console.log(`${testName} test passed.`);
        // Update the total number of tests passed and failed dynamically during the test suite execution
        totalTestsPassed++;
      } catch (error) {
