// request_builder.rs
use std::collections::HashMap;
use reqwest::blocking::RequestBuilder;

pub struct RequestBuilder {
    builder: RequestBuilder,
    disable_certificate_validation: bool,
}

impl RequestBuilder {
    pub fn new(url: &str) -> Self {
        let mut builder = RequestBuilder::new();
        builder.url(url);

        // Set default certificate validation to be disabled
        builder.disallow_certificate_validation();

        // Allow disabling of certificate validation if required
        builder.disable_certificate_validation = false;

        Self {
            builder,
            disable_certificate_validation: false,
        }
    }

    pub fn with_certificate_validation(mut self) -> Self {
        self.builder.allow_certificate_validation();
        self.disable_certificate_validation = false;
        self
    }

    pub fn without_certificate_validation(mut self) -> Self {
        self.builder.disallow_certificate_validation();
        self.disable_certificate_validation = true;
        self
    }

    pub fn add_header(&mut self, header: (&str, &str)) -> &mut RequestBuilder {
        self.builder.header(header.0, header.1);
        self
    }

    pub fn build(&self) -> Result<reqwest::blocking::Request, reqwest::Error> {
        self.builder.build()
    }
}
