// http_client.rs
use std::collections::HashMap;
use reqwest::{blocking, header};
use log::info;

pub struct HttpClient {
    client: blocking::Client,
}

impl HttpClient {
    pub fn new() -> Self {
        let mut builder = blocking::Client::builder();

        // Set default certificate validation to be disabled
        builder.disallow_certificate_validation();

        // Allow disabling of certificate validation if required
        builder.disable_certificate_validation = false;

        Self {
            client: builder.build()?,
        }
    }

    pub fn with_certificate_validation(mut self) -> Self {
        self.client.allow_certificate_validation();
        self.disable_certificate_validation = false;
        self
    }

    pub fn without_certificate_validation(mut self) -> Self {
        self.client.disallow_certificate_validation();
        self.disable_certificate_validation = true;
        self
    }

    pub fn get(&self, url: &str) -> Result<blocking::Response, blocking::Error> {
        let request = RequestBuilder::new(url).build()?;
        let response = self.client.execute(request)?;

        // Log metrics for successful requests
        if let Some(response_metrics) = response.metrics() {
            info!("{}", response_metrics);
        }

        Ok(response)
    }
}
```
