function generateRandomString(directoryPath, configFileName, stringLength, maxRetryAttempts) {
  // Read the configuration file from the specified directory
  const config = readFileSync(`${directoryPath}/${configFileName}`, 'utf8');

  // Validate the presence and integrity of the file
  if (!config || !isValidConfig(config)) {
    throw new Error(`Invalid configuration file: ${configFileName}`);
  }

  // Generate a random string using the character set defined in the file
  const charSet = config.charSet;
  let generatedString = '';
  for (let i = 0; i < stringLength; i++) {
    generatedString += charSet[Math.floor(Math.random() * charSet.length)];
  }

  // Dynamically load and execute the user-defined script stored in the same directory
  const scriptPath = `${directoryPath}/${config.scriptName}`;
  try {
    require(scriptPath)(generatedString);
  } catch (err) {
    console.error(`Error executing script: ${err.message}`);
    if (maxRetryAttempts > 0) {
      maxRetryAttempts--;
      generateRandomString(directoryPath, configFileName, stringLength, maxRetryAttempts);
    } else {
      throw new Error(`Exceeded maximum retry attempts: ${err.message}`);
    }
  }

  // Return the generated random string
  return generatedString;
}
