// Define the structure to represent a network request
typedef struct {
    char *url;
    int timestamp;
    int priority_level;
} Request;

// Define the structure to represent the cache data
typedef struct {
    Request **requests; // Array of requests
    int size; // Size of the cache
    int count; // Number of requests in the cache
    int ageout_time; // Time after which unused requests are removed from the cache (in minutes)
} Cache;

// Define the structure to represent the request priority queue
typedef struct {
    Request *request;
    int timestamp;
    int priority_level;
} PriorityQueue;

// Function to create a new cache with a specified size and ageout time
Cache* create_cache(int size, int ageout_time) {
    Cache *cache = (Cache*) malloc(sizeof(Cache));
    cache->size = size;
    cache->ageout_time = ageout_time;
    cache->count = 0;
    cache->requests = (Request**) malloc(sizeof(Request*) * size);
    return cache;
}

// Function to add a new request to the cache
void add_request(Cache* cache, Request* request) {
    // Check if the cache is full
    if (cache->count == cache->size) {
        // Remove the least recently used request from the cache
        evict_request(cache);
    }

    // Add the new request to the cache
    cache->requests[cache->count] = request;
    cache->count++;
}

// Function to remove a request from the cache
void evict_request(Cache* cache) {
    int min_timestamp = INT_MAX;
    int min_index = -1;

    // Find the least recently used request
    for (int i = 0; i < cache->count; i++) {
        if (cache->requests[i]->timestamp < min_timestamp) {
            min_timestamp = cache->requests[i]->timestamp;
            min_index = i;
        }
    }

    // Remove the least recently used request from the cache
    free(cache->requests[min_index]);
    memmove(&cache->requests[min_index], &cache->requests[min_index+1], (cache->count-min_index-1) * sizeof(Request*));
    cache->count--;
}

// Function to update a request in the cache
void update_request(Cache* cache, Request* request) {
    // Check if the request is already in the cache
    for (int i = 0; i < cache->count; i++) {
        if (cache->requests[i]->url == request->url) {
            // Update the timestamp and priority level of the request
            cache->requests[i]->timestamp = request->timestamp;
            cache->requests[i]->priority_level = request->priority_level;
            return;
        }
    }

    // If the request is not in the cache, add it to the cache
    add_request(cache, request);
}

// Function to retrieve the highest priority request from the cache
Request* get_highest_priority_request(Cache* cache) {
    int max_priority = INT_MIN;
    Request *max_request = NULL;

    // Find the highest priority request
    for (int i = 0; i < cache->count; i++) {
        if (cache->requests[i]->priority_level > max_priority) {
            max_priority = cache->requests[i]->priority_level;
            max_request = cache->requests[i];
        }
    }

    return max_request;
}

// Function to update the priority of a request in the cache
void update_request_priority(Cache* cache, Request* request) {
    // Check if the request is already in the cache
    for (int i = 0; i < cache->count; i++) {
        if (cache->requests[i]->url == request->url) {
            // Update the priority level of the request
            cache->requests[i]->priority_level = request->priority_level;
            return;
        }
    }
}

// Function to remove unused requests from the cache
void ageout_requests(Cache* cache) {
    int current_time = get_current_timestamp();

    // Iterate over the requests in the cache and remove those that have not been used recently
    for (int i = 0; i < cache->count; i++) {
        if (cache->requests[i]->timestamp < current_time - cache->ageout_time) {
            free(cache->requests[i]);
            memmove(&cache->requests[i], &cache->requests[i+1], (cache->count-i-1) * sizeof(Request*));
            cache->count--;
        }
    }
}

// Function to get the current timestamp
int get_current_timestamp() {
    return time(NULL);
}
