namespace DynamicRangeValueGenerator
{
    public class DynamicRangeValueGenerator
    {
        private int minValue;
        private int maxValue;

        public DynamicRangeValueGenerator(int initialMin, int initialMax)
        {
            if (initialMin > initialMax)
                throw new ArgumentException("Initial minimum value must be less than or equal to the maximum value.");

            this.minValue = initialMin;
            this.maxValue = initialMax;
        }

        public void UpdateRange(int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value must be less than or equal to the maximum value.");

            this.minValue = min;
            this.maxValue = max;
        }

        public float GetRandomFloat()
        {
            return this.GetRandomFloat(this.minValue, this.maxValue);
        }

        public float GetRandomFloat(int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value must be less than or equal to the maximum value.");

            return RandomNumber.NextDouble() * (max - min) + min;
        }

        public float GetRandomFloatExclusive(int max)
        {
            if (max < 0)
                throw new ArgumentException("Maximum value must be greater than or equal to zero.");

            return RandomNumber.NextDouble() * (max - this.minValue) + this.minValue;
        }

        public int GetRandomInt()
        {
            return this.GetRandomInt(this.minValue, this.maxValue);
        }

        public int GetRandomInt(int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value must be less than or equal to the maximum value.");

            return RandomNumber.Next(min, max + 1);
        }

        public int GetRandomIntExclusive(int max)
        {
            if (max < 0)
                throw new ArgumentException("Maximum value must be greater than or equal to zero.");

            return RandomNumber.Next(this.minValue, max + 1);
        }

        public override string ToString()
        {
            return $"Generated by external API (Min: {this.minValue}, Max: {this.maxValue})";
        }
    }
}
```
