using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading;

public struct ImageMetadata
{
    public int BitsPerSample { get; set; }
    public int SamplesPerPixel { get; set; }
    public int ExtraSamples { get; set; }
}

public class ProcessImageAndComputeHash
{
    private const int DefaultTimeout = 5000; // in milliseconds

    public static string ComputeHash(string imagePath, string inputText, int timeout = DefaultTimeout)
    {
        // Validate the input file path and check for the existence and readability of the TIFF file
        if (!File.Exists(imagePath))
        {
            return "Error: Input file does not exist.";
        }
        else if (!File.CanRead(imagePath))
        {
            return "Error: Input file is not readable.";
        }
        else if (timeout <= 0)
        {
            timeout = DefaultTimeout;
        }

        // Initialize the image metadata and hash accumulator
        ImageMetadata metadata = new ImageMetadata();
        MD5 md5 = MD5.Create();
        byte[] hashAccumulator = Array.Empty<byte>();

        // Parse the TIFF file and compute the MD5 hash of the input text
        using (Tiff tiff = Tiff.Open(imagePath, "r"))
        {
            if (tiff == null)
            {
                return "Error: Could not open TIFF file.";
            }

            // Extract image metadata and check for supported bit depths
            int bitsPerSample = tiff.BitsPerSample();
            if (!SupportedBitDepth(bitsPerSample))
            {
                return $"Error: Unsupported TIFF bit depth ({bitsPerSample}).";
            }
            metadata.BitsPerSample = bitsPerSample;
            metadata.SamplesPerPixel = tiff.SamplesPerPixel();
            metadata.ExtraSamples = tiff.ExtraSamples();

            // Compute the MD5 hash of the input text
            byte[] inputTextBytes = Encoding.UTF8.GetBytes(inputText);
            hashAccumulator = md5.ComputeHash(inputTextBytes);
        }

        // Return the resulting hash as a hexadecimal string
        return BitConverter.ToString(hashAccumulator).Replace("-", "");
    }

    private static bool SupportedBitDepth(int bitsPerSample)
    {
        switch (bitsPerSample)
        {
            case 1:
            case 2:
            case 4:
            case 8:
            case 16:
                return true;
            default:
                return false;
        }
    }
}
