#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

EVP_CIPHER_CTX* initAes256Cbc(const char* password) {
    // Generate a secure IV and key from the password
    unsigned char iv[16];
    unsigned char key[32];
    RAND_bytes(iv, 16);
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), 1000, (unsigned char*)password, strlen(password), iv, key, NULL);

    // Initialize the AES-256-CBC cipher with the generated IV and key
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return NULL;
    }
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set the IV length and key length to 16 bytes and 32 bytes, respectively
    if (!EVP_CIPHER_CTX_set_iv_length(ctx, 16)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    if (!EVP_CIPHER_CTX_set_key_length(ctx, 32)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Return a pointer to the cipher context
    return ctx;
}

