#include <fcntl.h>
#include <limits.h>

#define MAX_FILES 1024 // maximum number of files to process in parallel
#define RETRY_COUNT 3 // number of times to retry serialization if it fails
#define BUFFER_SIZE 8192 // size of buffer for reading/writing files

// structure to hold information about each file being processed
typedef struct {
    char *filename; // name of the original image file
    int fd; // file descriptor for the input file
    int output_fd; // file descriptor for the serialized byte array
} FileInfo;

// function to convert a JPEG file into a byte array using a third-party command-line tool
int jpegToByteArray(const char *filename, unsigned char **output) {
    int ret = 0; // return value
    char cmd[BUFFER_SIZE]; // buffer for the command line
    FILE *pipe; // pipe for reading the output of the command

    // construct the command to convert the JPEG file into a byte array
    sprintf(cmd, "convert %s -o ppm - | tail -c +5 | head -c -2 > temp.ppm", filename);

    // run the command and read the output into a buffer
    pipe = popen(cmd, "r");
    if (!pipe) {
        perror("popen");
        return -1;
    }

    *output = (unsigned char *)malloc(BUFFER_SIZE);
    memset(*output, 0, BUFFER_SIZE);
    fread(*output, sizeof(char), BUFFER_SIZE, pipe);
    pclose(pipe);

    // check if the output buffer is empty
    if (memcmp(*output, "\0", 1) == 0) {
        free(*output);
        *output = NULL;
        return -1;
    }

    return ret;
}

// function to serialize a byte array into a file using a custom serialization mechanism
int serializeByteArray(unsigned char *data, int size, const char *filename) {
    int fd = open(filename, O_CREAT | O_WRONLY, 0644); // create the output file
    if (fd < 0) {
        perror("open");
        return -1;
    }

    write(fd, data, size); // write the byte array to the output file
    close(fd); // close the output file

    return 0;
}

// function to manage memory efficiently and handle cases where the class of the object being serialized is not found
void serializeObject(void *obj) {
    unsigned char *data = NULL; // buffer for the serialized byte array
    int size = 0; // size of the serialized byte array
    const char *filename = NULL; // name of the output file
    FileInfo *file_info = (FileInfo *)obj; // structure to hold information about each file being processed

    if (!obj) {
        return;
    }

    filename = file_info->filename;
    data = (unsigned char *)malloc(BUFFER_SIZE);
    memset(data, 0, BUFFER_SIZE);

    size = jpegToByteArray(filename, &data); // convert the JPEG file into a byte array using a third-party command-line tool
    if (size < 0) {
        free(data);
        return;
    }

    serializeByteArray(data, size, filename); // serialize the byte array into a file using a custom serialization mechanism
    free(data);
}

// function to handle concurrent execution and ensure thread safety and proper synchronization to avoid race conditions
void processFilesParallel(char **filenames, int num_files) {
    FileInfo *file_infos = (FileInfo *)malloc(num_files * sizeof(FileInfo)); // structure to hold information about each file being processed
    pthread_t threads[MAX_FILES]; // array of threads for processing the files in parallel
    int thread_id; // identifier for each thread
    void *status; // status variable for each thread

    if (!filenames || num_files <= 0) {
        return;
    }

    for (thread_id = 0; thread_id < num_files && thread_id < MAX_FILES; thread_id++) {
        file_infos[thread_id].filename = filenames[thread_id]; // initialize the structure with information about each file being processed
        file_infos[thread_id].fd = open(filenames[thread_id], O_RDONLY); // open the input file for reading
        if (file_infos[thread_id].fd < 0) {
            perror("open");
            return;
        }
    }

    for (thread_id = 0; thread_id < num_files && thread_id < MAX_FILES; thread_id++) {
        if (pthread_create(&threads[thread_id], NULL, serializeObject, file_infos + thread_id) != 0) {
            perror("pthread_create");
            return;
        }
    }

    for (thread_id = 0; thread_id < num_files && thread_id < MAX_FILES; thread_id++) {
        if (pthread_join(threads[thread_id], &status) != 0) {
            perror("pthread_join");
            return;
        }
    }
}

// main function to process multiple image files in parallel and handle concurrent execution, resource management, and error handling
int main(int argc, char **argv) {
    int i = 0; // loop variable for processing the files
    int count = 0; // counter for the number of files successfully processed
    int fail_count = 0; // counter for the number of files that failed to serialize
    char **filenames = NULL; // array of file names for input images
    const char *output_dir = "/tmp"; // directory for output files

    if (argc < 2) {
        printf("Usage: %s <input image filenames>\n", argv[0]);
        return -1;
    }

    filenames = malloc(sizeof(char *) * argc);
    for (i = 1; i < argc; i++) {
        if (access(argv[i], F_OK) != 0) {
            perror("access");
            return -1;
        }

        filenames[i] = argv[i];
    }

    processFilesParallel(filenames, argc - 1); // process the input image files in parallel

    for (i = 0; i < argc - 1; i++) {
        if (access(output_dir "/" filenames[i], F_OK) == 0) {
            count++;
        } else {
            fail_count++;
        }
    }

    printf("Processed %d files successfully\n", count);
    if (fail_count > 0) {
        printf("%d files failed to serialize\n", fail_count);
    }

    free(filenames);
    return 0;
}
