#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <errno.h>

#define MAX_SUBPROCESSES 10
#define RETRY_COUNT 3
#define LOG_FILE "./error.log"

typedef struct {
    char *command;
    int fd[2];
} Subprocess;

// Function to execute a command in the background and manage its lifecycle
int executeCommand(char *command) {
    // Create a new subprocess
    Subprocess subproc = { .command = command };
    pid_t pid = fork();
    if (pid == 0) {
        // Child process: execute the command
        close(subproc.fd[1]);
        dup2(subproc.fd[0], STDIN_FILENO);
        execl("/bin/sh", "sh", "-c", subproc.command, NULL);
        exit(1);
    } else if (pid > 0) {
        // Parent process: wait for the command to complete and handle errors
        close(subproc.fd[0]);
        int status;
        wait(&status);
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            fprintf(stderr, "Error executing command: %s\n", subproc.command);
            return 0;
        } else {
            return 1;
        }
    } else {
        // Error forking the process
        perror("Failed to execute command");
        return 0;
    }
}

// Function to handle SIGINT and SIGTERM signals
void signalHandler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Clean up resources
        for (int i = 0; i < MAX_SUBPROCESSES; i++) {
            Subprocess *subproc = &subprocesses[i];
            if (subproc->pid != -1) {
                kill(subproc->pid, signum);
            }
        }
    }
}

int main() {
    // Set up signal handling for SIGINT and SIGTERM
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Initialize subprocesses with pipe file descriptors
    Subprocess subprocesses[MAX_SUBPROCESSES];
    for (int i = 0; i < MAX_SUBPROCESSES; i++) {
        Subprocess *subproc = &subprocesses[i];
        pipe(subproc->fd);
        subproc->pid = -1;
    }

    // Execute commands in the background and handle errors
    for (int i = 0; i < MAX_SUBPROCESSES; i++) {
        Subprocess *subproc = &subprocesses[i];
        if (subproc->pid == -1) {
            int ret = executeCommand(subproc->command);
            if (!ret) {
                fprintf(stderr, "Error executing command: %s\n", subproc->command);
                return 0;
            } else {
                subproc->pid = ret;
            }
        }
    }

    // Wait for all subprocesses to terminate
    int status;
    while (1) {
        wait(&status);
        if (!WIFEXITED(status)) {
            fprintf(stderr, "Error: Child process terminated abnormally\n");
            return 0;
        } else {
            for (int i = 0; i < MAX_SUBPROCESSES; i++) {
                Subprocess *subproc = &subprocesses[i];
                if (subproc->pid == -1) {
                    int ret = executeCommand(subproc->command);
                    if (!ret) {
                        fprintf(stderr, "Error executing command: %s\n", subproc->command);
                        return 0;
                    } else {
                        subproc->pid = ret;
                    }
                }
            }
        }
    }

    // Check for any failed subprocesses and attempt recovery
    int failed_subprocs = 0;
    for (int i = 0; i < MAX_SUBPROCESSES; i++) {
        Subprocess *subproc = &subprocesses[i];
        if (subproc->pid != -1) {
            wait(&status);
            if (!WIFEXITED(status)) {
                failed_subprocs++;
                if (failed_subprocs > RETRY_COUNT) {
                    // Clean up resources
                    for (int i = 0; i < MAX_SUBPROCESSES; i++) {
                        Subprocess *subproc = &subprocesses[i];
                        if (subproc->pid != -1) {
                            kill(subproc->pid, SIGTERM);
                            subproc->pid = -1;
                        }
                    }
                    fprintf(stderr, "Error: All retries failed. Cleaning up resources.\n");
                    return 0;
                } else {
                    // Attempt recovery
                    int ret = executeCommand(subproc->command);
                    if (!ret) {
                        fprintf(stderr, "Error executing command: %s\n", subproc->command);
                        return 0;
                    } else {
                        subproc->pid = ret;
                    }
                }
            }
        }
    }

    // Log any errors and return success or failure status
    if (failed_subprocs > 0) {
        fprintf(stderr, "Error: %d subprocesses failed.\n", failed_subprocs);
        return 0;
    } else {
        fprintf(stdout, "Success: All subprocesses terminated successfully.\n");
        return 1;
    }
}']

