    }

    // Validate the environment variables
    if (strlen(config->environment_variables) == 0 || !isalnum(config->environment_variables)) {
        return false;
    }

    // Validate the health check path, if present
    if (config->health_check_path != NULL && strlen(config->health_check_path) == 0) {
        return false;
    }

    return true;
}
