// Pipeline Class
public class EncryptedMessagePipeline : IPipeline
{
    private readonly IMessageQueue _messageQueue;
    private readonly IDictionary<string, EncryptionScheme> _encryptionSchemes;
    private readonly ICachingService _cachingService;

    public EncryptedMessagePipeline(IMessageQueue messageQueue, IDictionary<string, EncryptionScheme> encryptionSchemes, ICachingService cachingService)
    {
        _messageQueue = messageQueue;
        _encryptionSchemes = encryptionSchemes;
        _cachingService = cachingService;
    }

    public async Task ProcessMessagesAsync(CancellationToken cancellationToken)
    {
        while (true)
        {
            var message = await _messageQueue.DequeueAsync();
            if (message == null) break; // No more messages to process, exit loop

            var encryptionScheme = GetEncryptionScheme(message);
            if (encryptionScheme == null) continue; // Unknown encryption scheme, skip message

            var decryptedMessage = DecryptMessage(message, encryptionScheme);
            if (decryptedMessage == null) continue; // Could not decrypt message, skip it

            await ProcessDecryptedMessageAsync(decryptedMessage, cancellationToken);
        }
    }

    private EncryptionScheme GetEncryptionScheme(string message)
    {
        var encryptionScheme = _encryptionSchemes.GetValueOrDefault(message.Headers["EncryptionScheme"]);
        return encryptionScheme;
    }

    private byte[] DecryptMessage(string message, EncryptionScheme encryptionScheme)
    {
        var decryptedMessage = encryptionScheme.Decrypt(message);
        if (decryptedMessage == null) return null; // Could not decrypt message

        return decryptedMessage;
    }

    private async Task ProcessDecryptedMessageAsync(byte[] decryptedMessage, CancellationToken cancellationToken)
    {
