using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;

public class CompressedFileReader {
    private const int BufferSize = 4096;

    public static T Deserialize<T>(string filePath) where T : class {
        using (var stream = File.OpenRead(filePath)) {
            var metadata = ReadMetadata(stream);

            switch (metadata.CompressionMethod) {
                case CompressionMethod.GZip:
                    return DeserializeFromGZip<T>(stream, metadata.DecompressedSize);
                case CompressionMethod.Deflate:
                    return DeserializeFromDeflate<T>(stream, metadata.DecompressedSize);
            }
        }
    }

    private static FileMetadata ReadMetadata(Stream stream) {
        var metadata = new FileMetadata();

        using (var reader = new BinaryReader(stream)) {
            // Read the file header
            var header = reader.ReadBytes(4);
            if (!header.SequenceEqual(new byte[] { 0x1f, 0x8b, 0x08, 0x00 })) {
                throw new Exception("Invalid file header");
            }

            // Read the compression method and decompressed size from the header
            var compressionMethod = (CompressionMethod)reader.ReadByte();
            metadata.DecompressedSize = reader.ReadInt32();

            return metadata;
        }
    }

    private static T DeserializeFromGZip<T>(Stream stream, int decompressedSize) where T : class {
        using (var gzipStream = new GZipStream(stream, CompressionMode.Decompress)) {
            return DeserializeFromStream<T>(gzipStream, decompressedSize);
        }
    }

    private static T DeserializeFromDeflate<T>(Stream stream, int decompressedSize) where T : class {
        using (var deflateStream = new DeflateStream(stream, CompressionMode.Decompress)) {
            return DeserializeFromStream<T>(deflateStream, decompressedSize);
        }
    }

    private static T DeserializeFromStream<T>(Stream stream, int decompressedSize) where T : class {
        var buffer = new byte[BufferSize];
        var deserializer = new BinaryFormatter();
        var cache = new Dictionary<string, T>();

        using (var memoryStream = new MemoryStream()) {
            while (true) {
                int readBytes = stream.Read(buffer, 0, buffer.Length);
                if (readBytes == 0) break;

                memoryStream.Write(buffer, 0, readBytes);

                // Check the cache for a matching object
                var hash = BitConverter.ToString(memoryStream.ToArray());
                if (cache.ContainsKey(hash)) {
                    return cache[hash];
                }
            }

            memoryStream.Position = 0;

            try {
                var obj = (T)deserializer.Deserialize(memoryStream);
                cache[hash] = obj;
                return obj;
            } catch (SerializationException e) {
                // Handle serialization errors gracefully by providing a meaningful error message without crashing the application
                throw new Exception("Error deserializing object", e);
            }
        }
    }
}

public class FileMetadata {
    public CompressionMethod CompressionMethod { get; set; }
    public int DecompressedSize { get; set; }
}

public enum CompressionMethod {
    GZip = 0,
    Deflate = 1
}
```']

