    }

    close(fd);

    return NULL;
}

// Main program
int main() {
    char **fileList = malloc(MAX_FILES * sizeof(char *));
    int fileCount = 0;
    pthread_t *threadList = malloc(MAX_FILES * sizeof(pthread_t));
    semaphore_t sem;
    bool error = false;

    // Initialize semaphore for thread synchronization
    if ((sem = sem_open("fileSem", O_CREAT, 0644, MAX_FILES)) == SEM_FAILED) {
        fprintf(stderr, "sem_open: %s\n", strerror(errno));
        return -1;
    }

    // Read file list from command line arguments or a file
    // Upload files from URLs concurrently using JavaScript library
    for (int i = 0; i < MAX_FILES; i++) {
        if ((fileList[i] = fileUpload(urlList[i])) == NULL) {
            error = true;
            break;
        }
    }

    // Handle errors gracefully by returning appropriate error code
    if (error) {
        return -1;
    }

    // Create thread for each file and pass file descriptor as argument
    for (int i = 0; i < MAX_FILES; i++) {
        int fd = open(fileList[i], O_RDONLY);
        if (fd == -1) {
            perror("open");
            continue;
        }
        threadList[i] = pthread_create(&fileProcessThread, NULL, &fd);
    }

    // Wait for all threads to complete
    for (int i = 0; i < MAX_FILES; i++) {
        if (pthread_join(threadList[i], NULL) != 0) {
            fprintf(stderr, "pthread_join: %s\n", strerror(errno));
            return -1;
        }
    }

    // Close file descriptors and free memory
    for (int i = 0; i < MAX_FILES; i++) {
        close(fd);
        sem_wait(sem);
        free(fileList[i]);
    }

    return 0;
}
