import json
from typing import Dict, Any

class JsonProcessor:
    def __init__(self):
        self.registry = {}

    def register_factory(self, data_type: str, factory_func: Callable[[], Any]):
        self.registry[data_type] = factory_func

    def unregister_factory(self, data_type: str):
        if data_type in self.registry:
            del self.registry[data_type]

    def serialize(self, obj: Any) -> Dict[str, Any]:
        for factory in self.registry.values():
            try:
                return json.dumps(factory())
            except Exception as e:
                continue
        raise RuntimeError("Failed to serialize object")

    def deserialize(self, data: Dict[str, Any]) -> Any:
        for factory in self.registry.values():
            try:
                return json.loads(data)
            except Exception as e:
                continue
        raise RuntimeError("Failed to deserialize object")
```

