import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class SHA256Hasher {
    private static final int DEFAULT_THRESHOLD = 10000000; // 10 MB
    private static final String LOGGING_FORMAT = "{} - {}";

    private ExecutorService executorService;
    private List<Future<?>> futures;
    private int thresholdSize;

    public SHA256Hasher() {
        this.executorService = Executors.newCachedThreadPool();
        this.futures = new ArrayList<>();
        this.thresholdSize = DEFAULT_THRESHOLD;
    }

    public void setThresholdSize(int thresholdSize) {
        this.thresholdSize = thresholdSize;
    }

    public void processDirectory(String directoryPath) throws IOException, NoSuchAlgorithmException {
        File directory = new File(directoryPath);
        if (!directory.exists()) {
            throw new IllegalArgumentException("Directory does not exist: " + directoryPath);
        }

        // Log the start of processing
        System.out.println(LOGGING_FORMAT, "Starting SHA-256 hashing for directory", directory.getAbsolutePath());

        // Get all files in the directory and its subdirectories
        List<File> files = getFilesRecursively(directory);

        // Process files asynchronously if threshold size is exceeded
        futures.clear();
        for (File file : files) {
            if (file.length() > thresholdSize) {
                // Use a future to handle asynchronous processing
                Future<?> future = executorService.submit(() -> processFile(file));
                futures.add(future);
            } else {
                processFile(file);
            }
        }

        // Wait for all asynchronous tasks to complete
        waitForFutures();

        // Log the end of processing
        System.out.println(LOGGING_FORMAT, "Finished SHA-256 hashing for directory", directory.getAbsolutePath());
    }

    private void processFile(File file) throws IOException, NoSuchAlgorithmException {
        // Verify that the file exists and is not a directory
        if (!file.exists() || file.isDirectory()) {
            return;
        }

        // Compute the SHA-256 hash of the file
        String hash = computeSHA256Hash(file);

        // Log processing details and errors
        System.out.println(LOGGING_FORMAT, "Processed file", file.getAbsolutePath());
        System.out.println(LOGGING_FORMAT, "SHA-256 hash of file", hash);
    }

    private String computeSHA256Hash(File file) throws NoSuchAlgorithmException, IOException {
        // Use a try-with-resources block to ensure the stream is closed properly
        try (InputStream inputStream = Files.newInputStream(Paths.get(file.getAbsolutePath()))) {
            return computeSHA256Hash(inputStream);
        }
    }

    private String computeSHA256Hash(InputStream inputStream) throws NoSuchAlgorithmException, IOException {
        // Initialize the SHA-256 digest instance
        MessageDigest sha256 = MessageDigest.getInstance("SHA-256");

        // Update the digest with the contents of the input stream
        byte[] buffer = new byte[1024];
        int numBytes;
        while ((numBytes = inputStream.read(buffer)) > 0) {
            sha256.update(buffer, 0, numBytes);
        }

        // Return the SHA-256 hash as a hexadecimal string
        return String.format("%064x", new java.math.BigInteger(1, sha256.digest()));
    }

    private void waitForFutures() {
        // Wait for all asynchronous tasks to complete
        futures.stream().forEach(future -> {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                System.out.println("Error processing file: " + e.getMessage());
            }
        });
    }

    private List<File> getFilesRecursively(File directory) throws IOException {
        // Use a try-with-resources block to ensure the stream is closed properly
        try (Stream<Path> pathStream = Files.walk(directory.toPath())) {
            return pathStream.filter(Files::isRegularFile).map(Path::toFile).collect(Collectors.toList());
        }
    }
}
