  int aes_ret = EVP_EncryptInit(aes_ctx, aes, key, NULL);
  int camellia_ret = EVP_EncryptInit(camellia_ctx, camellia, key, NULL);

  // Compute MD5 and SHA1 hashes of extension
  int md5_ret = EVP_DigestUpdate(md5_ctx, config, strlen(config));
  int sha1_ret = EVP_DigestUpdate(sha1_ctx, config, strlen(config));

  // Encrypt MD5 and SHA1 hashes using RSA
  int rsa_ret = RSA_Encrypt(rsa, rsa_ctx, md5_ret, sha1_ret);

  // Write cipher text to file
  FILE *fptr = fopen("file.txt", "w");
  if (fptr != NULL) {
    fwrite(ciphertext, extension_len + EVP_MAX_IV_LENGTH + 1, 1, fptr);
    fclose(fptr);
  } else {
    printf("Error writing to file\n");
  }

  // Clean up resources
  EVP_CIPHER_CTX_free(aes_ctx);
  EVP_CIPHER_CTX_free(camellia_ctx);
  EVP_MD_CTX_free(md5_ctx);
  EVP_MD_CTX_free(sha1_ctx);
