struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    struct CRC_INDICATION_REL8_TAG {
        bool crcflag;
    } crc_indication_rel8_tag;
};

struct connection_state {
    int socket;
    struct sockaddr_in remote_addr;
    enum connection_status {
        CONNECTING,
        ESTABLISHED,
        ERROR
    } status;
};

struct NFAPI_CRC_INDICATION_PDU_T *connect(const char *remote_address) {
    struct NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        return NULL;
    }

    memset(pdu, 0, sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    pdu->crc_indication_rel8_tag.crcflag = true;

    struct connection_state *conn = malloc(sizeof(struct connection_state));
    if (!conn) {
        free(pdu);
        return NULL;
    }

    memset(conn, 0, sizeof(struct connection_state));
    conn->status = CONNECTING;

    int ret = inet_pton(AF_INET, remote_address, &conn->remote_addr.sin_addr);
    if (ret < 0) {
        free(pdu);
        free(conn);
        return NULL;
    }

    conn->socket = socket(AF_INET, SOCK_STREAM, 0);
    if (conn->socket < 0) {
        free(pdu);
        free(conn);
        return NULL;
    }

    ret = connect(conn->socket, (struct sockaddr *) &conn->remote_addr, sizeof(struct sockaddr_in));
    if (ret < 0) {
        close(conn->socket);
        free(pdu);
        free(conn);
        return NULL;
    }

    conn->status = ESTABLISHED;

    pdu->rx_ue_information_tag = rand(); // Generate a random RX_UE_INFORMATION_TAG
    pdu->rnti = rand(); // Generate a random RNTI

    return pdu;
}

void disconnect(struct NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!pdu) {
        return;
    }

    free(pdu);
}
