// NetworkRandom class for generating random numbers
class NetworkRandom {
public:
    // Initialize Mersenne Twister with current time in milliseconds
    NetworkRandom() : mt19937(std::time(0)) {}

    // Generate a random number between 0 and 2^32-1
    uint32_t generate() {
        std::lock_guard<std::mutex> lock(mtx);
        return mt19937();
    }

private:
    // Mutex for thread safety
    std::mutex mtx;

    // Mersenne Twister random number generator
    std::mt19937 mt19937;
};

// NetworkConfigurationManager class for managing network configurations
class NetworkConfigurationManager {
public:
    // Initialize network configuration manager with default values
    NetworkConfigurationManager() : config(defaultConfig()) {}

    // Get current network configuration
    std::map<std::string, std::string> getConfig() {
        return config;
    }

    // Update network configuration
    void updateConfig(const std::map<std::string, std::string>& newConfig) {
        // Generate a random number to avoid conflicts with concurrent updates
        uint32_t randNum = NetworkRandom().generate();

        // Lock the mutex to prevent concurrent access
        std::lock_guard<std::mutex> lock(mtx);

        // Verify new configuration is valid
        validateConfig(newConfig);

        // Sanitize new configuration
        sanitizeConfig(newConfig);

        // Merge new configuration with current one
        mergeConfigs(config, newConfig);

        // Log changes to configuration file
        logChanges();
    }

private:
    // Network configuration data structure
    std::map<std::string, std::string> config;

    // Mutex for thread safety
    std::mutex mtx;

    // Default network configuration
    const std::map<std::string, std::string> defaultConfig() {
        return {{"IP Address", "192.168.0.1"}, {"Subnet Mask", "255.255.255.0"}};
    }

    // Validate new network configuration
    void validateConfig(const std::map<std::string, std::string>& newConfig) {
        for (auto& entry : newConfig) {
            if (!validateEntry(entry)) {
                throw std::invalid_argument("Invalid configuration value");
            }
        }
    }

    // Sanitize new network configuration
    void sanitizeConfig(const std::map<std::string, std::string>& newConfig) {
        for (auto& entry : newConfig) {
            sanitizeEntry(entry);
        }
    }

    // Merge new and current network configurations
    void mergeConfigs(std::map<std::string, std::string>& currConfig, const std::map<std::string, std::string>& newConfig) {
        for (auto& entry : newConfig) {
            auto it = currConfig.find(entry.first);
            if (it != currConfig.end()) {
                // If the configuration key already exists in the current config, update its value
                it->second = entry.second;
            } else {
                // Otherwise, add a new key-value pair to the current config
                currConfig.emplace(entry);
            }
        }
    }

    // Log changes to network configuration file
    void logChanges() {
        std::cout << "Configuration updated: ";
        for (auto& entry : config) {
            std::cout << entry.first << "=" << entry.second << " ";
        }
        std::cout << std::endl;
    }

    // Validate network configuration entry
    bool validateEntry(const std::pair<std::string, std::string>& entry) {
        if (entry.first == "IP Address" || entry.first == "Subnet Mask") {
            return true;
        } else {
            return false;
        }
    }

    // Sanitize network configuration entry
    void sanitizeEntry(const std::pair<std::string, std::string>& entry) {
        if (entry.first == "IP Address") {
            entry.second = sanitizeIPAddress(entry.second);
        } else if (entry.first == "Subnet Mask") {
            entry.second = sanitizeSubnetMask(entry.second);
        }
    }

    // Sanitize IP address by removing any leading zeros
    std::string sanitizeIPAddress(const std::string& ip) {
        return removeLeadingZeros(ip);
    }

    // Sanitize subnet mask by removing any leading zeros
    std::string sanitizeSubnetMask(const std::string& sm) {
        return removeLeadingZeros(sm);
    }

    // Remove any leading zeros from a string
    std::string removeLeadingZeros(const std::string& str) {
        auto pos = str.find_first_not_of('0');
        if (pos == std::string::npos) {
            return "";
        } else {
            return str.substr(pos);
        }
    }
};

int main() {
    // Create a network configuration manager instance
    NetworkConfigurationManager configMgr;

    // Get the current network configuration
    std::map<std::string, std::string> currConfig = configMgr.getConfig();

    // Update the network configuration with new values
    std::map<std::string, std::string> newConfig = {{"IP Address", "192.168.0.1"}, {"Subnet Mask", "255.255.255.0"}};
    configMgr.updateConfig(newConfig);

    // Get the updated network configuration
    std::map<std::string, std::string> updatedConfig = configMgr.getConfig();
}
```
