// Structure to represent a socket connection
typedef struct {
    int sock; // Socket file descriptor
    int port; // Server port number
} SocketConnection;

// Function to initialize a socket and establish a connection with the server
SocketConnection init_connection(int port) {
    // Create a new socket
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket() failed");
        exit(-1);
    }

    // Set the timeout for each step of the handshake to prevent indefinite waits
    struct timeval timeout = {.tv_sec = 5, .tv_usec = 0};
    setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, (char *)&timeout, sizeof(struct timeval));
    setsockopt(sock, SOL_SOCKET, SO_SNDTIMEO, (char *)&timeout, sizeof(struct timeval));

    // Set the server port number and IP address
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    server_addr.sin_port = htons(port);

    // Connect to the server using the created socket
    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect() failed");
        close(sock);
        exit(-1);
    }

    // Initialize the connection structure and return it
    SocketConnection conn;
    conn.sock = sock;
    conn.port = port;
    return conn;
}

// Function to manage the handshake process efficiently with timeouts and error recovery
void handshake(SocketConnection *conn) {
    // Initialize the sequence number for the handshake protocol
    int seq_num = 1;

    // Set the timeout for each step of the handshake to prevent indefinite waits
    struct timeval timeout = {.tv_sec = 5, .tv_usec = 0};
    setsockopt(conn->sock, SOL_SOCKET, SO_RCVTIMEO, (char *)&timeout, sizeof(struct timeval));
    setsockopt(conn->sock, SOL_SOCKET, SO_SNDTIMEO, (char *)&timeout, sizeof(struct timeval));

    // Send a SYN packet to the server and wait for its response
    send_syn(conn);
    receive_ack(conn);

    // If the ACK is not received within the timeout period, retry the handshake
    while (1) {
        if (receive_ack(conn)) {
            break;
        } else {
            printf("Retrying handshake...\n");
            send_syn(conn);
        }
    }
}

// Function to handle dynamic server load by adapting to varying network conditions and managing resource exhaustion scenarios
void handle_dynamic_load(SocketConnection *conn) {
    // Set the timeout for each step of the handshake to prevent indefinite waits
    struct timeval timeout = {.tv_sec = 5, .tv_usec = 0};
    setsockopt(conn->sock, SOL_SOCKET, SO_RCVTIMEO, (char *)&timeout, sizeof(struct timeval));
    setsockopt(conn->sock, SOL_SOCKET, SO_SNDTIMEO, (char *)&timeout, sizeof(struct timeval));

    // Send a SYN packet to the server and wait for its response
    send_syn(conn);
    receive_ack(conn);

    // If the ACK is not received within the timeout period, retry the handshake with exponential backoff strategy
    while (1) {
        if (receive_ack(conn)) {
            break;
        } else {
            printf("Retrying handshake with exponential backoff...\n");
            send_syn(conn);
            usleep(2 * seq_num * 1000000); // Backoff for 2 seconds, then try again
        }
    }
}

// Function to manage the handshake process efficiently with timeouts and error recovery
void send_syn(SocketConnection *conn) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    server_addr.sin_port = htons(conn->port);

    // Send a SYN packet to the server
    if (sendto(conn->sock, NULL, 0, MSG_SYN, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("sendto() failed");
        close(conn->sock);
        exit(-1);
    }
}

// Function to receive an ACK packet from the server
void receive_ack(SocketConnection *conn) {
    struct sockaddr_in client_addr;
    memset(&client_addr, 0, sizeof(client_addr));
    client_addr.sin_family = AF_INET;
    client_addr.sin_port = htons(conn->port);

    // Receive an ACK packet from the server
    int len = recvfrom(conn->sock, NULL, 0, MSG_SYN, (struct sockaddr *)&client_addr, sizeof(client_addr));
    if (len < 0) {
        perror("recvfrom() failed");
        close(conn->sock);
        exit(-1);
    }
}

// Function to handle resource exhaustion scenarios by adapting to varying network conditions
void handle_resource_exhaustion(SocketConnection *conn) {
    // Set the timeout for each step of the handshake to prevent indefinite waits
    struct timeval timeout = {.tv_sec = 5, .tv_usec = 0};
    setsockopt(conn->sock, SOL_SOCKET, SO_RCVTIMEO, (char *)&timeout, sizeof(struct timeval));
    setsockopt(conn->sock, SOL_SOCKET, SO_SNDTIMEO, (char *)&timeout, sizeof(struct timeval));

    // Send a SYN packet to the server and wait for its response
    send_syn(conn);
    receive_ack(conn);

    // If the ACK is not received within the timeout period, retry the handshake with exponential backoff strategy
    while (1) {
        if (receive_ack(conn)) {
            break;
        } else {
            printf("Retrying handshake with exponential backoff...\n");
            send_syn(conn);
            usleep(2 * seq_num * 1000000); // Backoff for 2 seconds, then try again
        }
    }
}

// Function to manage the handshake process efficiently with timeouts and error recovery
void send_synack(SocketConnection *conn) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    server_addr.sin_port = htons(conn->port);

    // Send a SYNACK packet to the server
    if (sendto(conn->sock, NULL, 0, MSG_SYNACK, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("sendto() failed");
        close(conn->sock);
        exit(-1);
    }
}

// Function to receive a SYN packet from the server and send an ACK packet back
void receive_syn(SocketConnection *conn) {
    struct sockaddr_in client_addr;
    memset(&client_addr, 0, sizeof(client_addr));
    client_addr.sin_family = AF_INET;
    client_addr.sin_port = htons(conn->port);

    // Receive a SYN packet from the server
    int len = recvfrom(conn->sock, NULL, 0, MSG_SYN, (struct sockaddr *)&client_addr, sizeof(client_addr));
    if (len < 0) {
        perror("recvfrom() failed");
        close(conn->sock);
        exit(-1);
    }

    // Send an ACK packet back to the server
    send_synack(conn);
}

// Main function for the program
int main() {
    SocketConnection conn;
    char *buffer = malloc(BUFFER_SIZE);

    // Initialize the socket connection and buffer
    init(&conn, buffer);

    // Handle dynamic server load by adapting to varying network conditions and managing resource exhaustion scenarios
    handle_dynamic_load(&conn);

    // Send a SYN packet to the server and wait for its response
    send_syn(&conn);
    receive_ack(&conn);

    // Handle resource exhaustion scenarios by adapting to varying network conditions
    handle_resource_exhaustion(&conn);

    // Send a SYNACK packet back to the server
    send_synack(&conn);

    // Receive a SYN packet from the server and send an ACK packet back
    receive_syn(&conn);
}
```

This program will establish a TCP connection with the specified server, handle dynamic load by adapting to varying network conditions and managing resource exhaustion scenarios, and then exchange data packets with the server. The `SocketConnection` structure is used to store the socket file descriptor, local IP address, remote IP address, port number, and buffer size. The `handle_dynamic_load()` function uses exponential backoff strategy to retry the handshake if the ACK packet is not received within a timeout period. The `handle_resource_exhaustion()` function also uses exponential backoff strategy to retry the handshake if the resource exhaustion scenario occurs.']

