struct entry {
    int type; // 0 for integer, 1 for float
    union {
        long long int_value;
        double float_value;
    } value;
};

struct data_structure {
    struct entry *entries;
    size_t num_entries;
    pthread_mutex_t mutex; // used for thread-safety
};

// function to validate incoming values
int validate_value(const char *value) {
    if (strcmp(value, "nan") == 0 || strcmp(value, "inf") == 0 || strcmp(value, "-inf") == 0) {
        return 0; // invalid value
    }
    return 1; // valid value
}

// function to add an entry to the data structure
void add_entry(struct data_structure *data, const char *value) {
    if (validate_value(value)) {
        struct entry new_entry = { .type = 0 }; // integer
        int num_read = sscanf(value, "%lld", &new_entry.int_value);
        if (num_read == 1) {
            pthread_mutex_lock(&data->mutex);
            data->entries = realloc(data->entries, sizeof(struct entry) * (data->num_entries + 1));
            memcpy(data->entries + data->num_entries++, &new_entry, sizeof(struct entry));
            pthread_mutex_unlock(&data->mutex);
        } else {
            // value is not an integer, treat it as a float
            struct entry new_entry = { .type = 1 }; // float
            num_read = sscanf(value, "%lf", &new_entry.float_value);
            if (num_read == 1) {
                pthread_mutex_lock(&data->mutex);
                data->entries = realloc(data->entries, sizeof(struct entry) * (data->num_entries + 1));
                memcpy(data->entries + data->num_entries++, &new_entry, sizeof(struct entry));
                pthread_mutex_unlock(&data->mutex);
            } else {
                // value is not a valid number, log an error and close the connection
                printf("Error: invalid number received from network stream\n");
                free(data->entries);
                data->num_entries = 0;
                pthread_mutex_destroy(&data->mutex);
            }
        }
    } else {
        // value is not a valid number, log an error and close the connection
        printf("Error: invalid number received from network stream\n");
        free(data->entries);
        data->num_entries = 0;
        pthread_mutex_destroy(&data->mutex);
    }
}

// function to process a list of integers and floating-point numbers received from a network stream
void process_stream(const char *stream) {
    struct data_structure data;
    data.entries = NULL;
    data.num_entries = 0;
    pthread_mutex_init(&data.mutex, NULL);

    // split the stream into individual values
    const char *token = strtok(stream, " ");
    while (token != NULL) {
        add_entry(&data, token);
        token = strtok(NULL, " ");
    }

    // check if the data structure has exceeded its capacity
    if (data.num_entries > 5000) {
        printf("Error: too many entries received from network stream\n");
        free(data.entries);
        data.num_entries = 0;
        pthread_mutex_destroy(&data.mutex);
    }

    // process the data structure asynchronously
    pthread_t thread;
    if (pthread_create(&thread, NULL, &process_data, &data)) {
        printf("Error: failed to create thread\n");
        free(data.entries);
        data.num_entries = 0;
        pthread_mutex_destroy(&data.mutex);
    } else {
        // wait for the thread to finish
        pthread_join(thread, NULL);

        // clean up resources
        free(data.entries);
        data.num_entries = 0;
        pthread_mutex_destroy(&data.mutex);
    }
}

// function to process the data structure asynchronously
void *process_data(void *arg) {
    struct data_structure *data = (struct data_structure *)arg;

    // iterate through the entries and perform desired operations
    for (size_t i = 0; i < data->num_entries; i++) {
        if (data->entries[i].type == 0) {
            printf("Integer value: %lld\n", data->entries[i].int_value);
        } else {
            printf("Float value: %f\n", data->entries[i].float_value);
        }
    }

    // free the entries and the mutex
    pthread_mutex_lock(&data->mutex);
    free(data->entries);
    data->num_entries = 0;
    pthread_mutex_unlock(&data->mutex);
}
