    public static class MyFunctions
    {
        public static XElement FindFirstMatchingElement(string xml, string xpath)
        {
            try
            {
                var navigator = XmlReader.Create(new StringReader(xml));
                var document = new XPathDocument(navigator);
                var context = new XPathNavigator(document);
                var query = context.Compile(xpath);
                var iterator = query.Evaluate(context) as XPathNodeIterator;

                if (iterator != null && iterator.Count > 0)
                {
