            {
                // Log parsing errors here
            }

            return null;
        }

        public static int CountDisjointPairs(int[] arr)
        {
            if (arr == null || arr.Length < 2)
            {
                return 0;
            }

            var uf = new UnionFind();
            var count = 0;

            for (var i = 0; i < arr.Length - 1; i++)
            {
                if (!uf.IsConnected(i, i + 1))
                {
                    uf.Union(i, i + 1);
                    count++;
                }
            }

            return count;
        }
    }
}
