// Structure to store metadata for a single packet
typedef struct {
    uint64_t sequence_number; // Sequence number of the packet
    size_t payload_size; // Size of the packet payload
    uint32_t checksum; // Cumulative checksum of the packet
    time_t timestamp; // Timestamp for accurate frequency calculations
} packet_metadata_t;

// Structure to store a sliding window of recent packets
typedef struct {
    packet_metadata_t *data; // Array of metadata structures
    size_t capacity; // Maximum number of packets in the window
    size_t index; // Current index for writing new packets
} sliding_window_t;

// Function to process a high-throughput network packet stream
packet_metadata_t* process_packets(sliding_window_t *window, const uint8_t *data, size_t length) {
    // Get the current timestamp for accurate frequency calculations
    time_t now = time(NULL);

    // Iterate over each packet in the input data
    for (size_t i = 0; i < length; i++) {
        // Get the metadata for the current packet
        const packet_metadata_t *packet = (const packet_metadata_t *)data + i;

        // Update the sliding window with the new packet metadata
        window->data[window->index] = *packet;
        window->index++;
        if (window->index == window->capacity) {
            window->index = 0;
        }

        // Calculate the cumulative checksum for the current packet
        uint32_t checksum = packet->checksum + calculate_crc(data + i, packet->payload_size);

        // Update the highest cumulative checksum and corresponding sequence number
        if (checksum > window->highest_checksum) {
            window->highest_checksum = checksum;
            window->sequence_number = packet->sequence_number;
        }
    }

    // Return the highest cumulative checksum and corresponding sequence number
    return &window->data[window->index - 1];
}

// Function to calculate the CRC of a packet payload
uint32_t calculate_crc(const uint8_t *data, size_t length) {
    // Initialize the CRC-32 hash with a random value
    uint32_t crc = 0xdeadbeef;

    // Iterate over each byte in the packet payload
    for (size_t i = 0; i < length; i++) {
        // Update the CRC-32 hash with the current byte
        crc = _mm_crc32_u8(crc, data[i]);
    }

    return crc;
}
