    // Check if the numerical values are missing or invalid
    if (!isnan(entry->numericalValues[0]) && !isnan(entry->numericalValues[1])) {
        return true;
    } else {
        return false;
    }
}

// Define the enrichEntry function to add additional information to the entry
void enrichEntry(LogEntry* entry) {
    // Add additional information to the entry using an external API
    entry->extraInfo = getAdditionalInfo();
}
