#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/types.h>
#include <ifaddrs.h>
#include <unistd.h>
#include <fcntl.h>
#include <dirent.h>
#include <limits.h>
#include <linux/netlink.h>
#include <linux/rtnetlink.h>
#include <net/if_arp.h>

#define MAX_INTERFACE_NAME 16
#define MAX_IPV4_ADDR_LEN 15
#define MAX_MAC_ADDR_LEN 17
#define BUFFER_SIZE (8 * 1024)
#define MAX_TRIES 3

typedef struct interface_info {
    char name[MAX_INTERFACE_NAME];
    char ipv4_addr[INET_ADDRSTRLEN];
    char mac_addr[MAX_MAC_ADDR_LEN];
} interface_info;

typedef struct config_data {
    interface_info *interfaces;
    size_t num_interfaces;
} config_data;

config_data *init_config() {
    config_data *config = malloc(sizeof(config_data));
    if (!config) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    config->interfaces = NULL;
    config->num_interfaces = 0;
    return config;
}

void free_config(config_data *config) {
    if (config->interfaces) {
        free(config->interfaces);
    }
    free(config);
}

int update_interface(const char *ifname, const char *ipv4_addr, const char *mac_addr) {
    int ret = 0;
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(struct ifreq));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ);

    // Set IPv4 address
    if (ipv4_addr) {
        struct sockaddr_in *addr = (struct sockaddr_in *)&ifr.ifr_addr;
        ret = inet_pton(AF_INET, ipv4_addr, &addr->sin_addr);
        if (ret < 0) {
            perror("inet_pton");
            return -1;
        } else if (ret == 0) {
            fprintf(stderr, "Invalid IPv4 address '%s'\n", ipv4_addr);
            return -1;
        }
    }

    // Set MAC address
    if (mac_addr) {
        struct sockaddr_ll *addr = (struct sockaddr_ll *)&ifr.ifr_hwaddr;
        ret = inet_pton(AF_INET, mac_addr, &addr->sll_addr);
        if (ret < 0) {
            perror("inet_pton");
            return -1;
        } else if (ret == 0) {
            fprintf(stderr, "Invalid MAC address '%s'\n", mac_addr);
            return -1;
        }
    }

    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    ret = ioctl(sock, SIOCSIFADDR, &ifr);
    if (ret < 0) {
        perror("ioctl(SIOCSIFADDR)");
        close(sock);
        return -1;
    }

    ret = ioctl(sock, SIOCSIFFLAGS, &ifr);
    if (ret < 0) {
        perror("ioctl(SIOCIFFLAGS)");
        close(sock);
        return -1;
    }

    close(sock);
    return 0;
}

int apply_config(config_data *config) {
    int ret = 0;
    size_t i;
    for (i = 0; i < config->num_interfaces; ++i) {
        interface_info *interface = &config->interfaces[i];
        if (interface->ipv4_addr && interface->mac_addr) {
            ret = update_interface(interface->name, interface->ipv4_addr, interface->mac_addr);
            if (ret < 0) {
                perror("update_interface");
                return -1;
            }
        } else {
            fprintf(stderr, "Interface '%s' has invalid configuration\n", interface->name);
            return -1;
        }
    }
    return 0;
}

int load_config(const char *filename, config_data **config) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    size_t num_interfaces;
    interface_info *interfaces;
    ret = parse_config(file, &num_interfaces, &interfaces);
    if (ret < 0) {
        perror("parse_config");
        exit(EXIT_FAILURE);
    }

    config_data *new_config = init_config();
    new_config->num_interfaces = num_interfaces;
    new_config->interfaces = interfaces;

    free(*config);
    *config = new_config;
    return 0;
}

int save_config(const char *filename, config_data *config) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    size_t i;
    for (i = 0; i < config->num_interfaces; ++i) {
        interface_info *interface = &config->interfaces[i];
        fprintf(file, "%s %s %s\n", interface->name, interface->ipv4_addr, interface->mac_addr);
    }

    fclose(file);
    return 0;
}
```

