int process_file_conversion(const char *input_file, const char *output_directory, const char **command_line_args) {
    // Check if the output directory exists and create it if not
    struct stat dir_stats;
    if (stat(output_directory, &dir_stats) == -1) {
        if (mkdir(output_directory, 0755) == -1) {
            perror("Failed to create output directory");
            return 1;
        }
    } else if (!S_ISDIR(dir_stats.st_mode)) {
        fprintf(stderr, "Output path is not a directory\n");
        return 1;
    }

    // Convert the input file to PDF format using a third-party tool
    char *intermediate_file = generate_intermediate_file(input_file);
    if (intermediate_file == NULL) {
        fprintf(stderr, "Failed to generate intermediate file\n");
        return 1;
    }
    char *command = generate_conversion_command(intermediate_file, output_directory, command_line_args);
    if (command == NULL) {
        fprintf(stderr, "Failed to generate conversion command\n");
        free(intermediate_file);
        return 1;
    }
    int status = system(command);
    free(command);
    if (status != 0) {
        fprintf(stderr, "Conversion failed with status %d\n", status);
        remove(intermediate_file);
        free(intermediate_file);
        return 1;
    }

    // Delete temporary files unless the --keep-temp flag is provided
    int keep_temp = check_for_keep_temp_flag(command_line_args);
    if (!keep_temp) {
        remove(intermediate_file);
        free(intermediate_file);
    }

    // Cleanup failed files and return 0 on success
    int cleanup_status = cleanup_failed_files();
    if (cleanup_status != 0) {
        fprintf(stderr, "Cleanup failed with status %d\n", cleanup_status);
        return 1;
    }
    free(intermediate_file);
    return 0;
}

// Generate an intermediate file for the input file based on its extension
char *generate_intermediate_file(const char *input_file) {
    // Get the file extension and strip any leading dots
    const char *extension = strrchr(input_file, '.');
    if (extension == NULL) {
        fprintf(stderr, "Failed to determine input file extension\n");
        return NULL;
    }
    size_t len = strlen(input_file);
    char *intermediate_file = malloc((len + 5) * sizeof(char));
    if (intermediate_file == NULL) {
        fprintf(stderr, "Failed to allocate memory for intermediate file\n");
        return NULL;
    }
    strcpy(intermediate_file, input_file);
    // Replace the extension with a temporary one
    strcpy(intermediate_file + len - 4, ".tmp");
    return intermediate_file;
}

// Generate a conversion command for the input file and output directory
char *generate_conversion_command(const char *input_file, const char *output_directory, const char **command_line_args) {
    // Get the tool path from an environment variable or default to "convert"
    const char *tool_path = getenv("CONVERSION_TOOL");
    if (tool_path == NULL) {
        fprintf(stderr, "Failed to determine conversion tool path\n");
        return NULL;
    }
    // Generate the command line arguments for the conversion tool
    size_t len = strlen(input_file) + strlen(output_directory) + 10;
    char *command = malloc((len + 1) * sizeof(char));
    if (command == NULL) {
        fprintf(stderr, "Failed to allocate memory for conversion command\n");
        return NULL;
    }
    // Check if the input file is a relative or absolute path and adjust accordingly
    const char *input_file_path = input_file;
    if (input_file[0] != '/') {
        char cwd[1024];
        getcwd(cwd, sizeof(cwd));
        len += strlen(cwd);
        command = realloc(command, (len + 1) * sizeof(char));
        if (command == NULL) {
            fprintf(stderr, "Failed to allocate memory for conversion command\n");
            return NULL;
        }
        sprintf(command, "%s/%s", cwd, input_file);
    } else {
        strcpy(command, input_file);
    }
    // Add the output directory and intermediate file arguments to the command line
    len += strlen(output_directory) + strlen(intermediate_file);
    command = realloc(command, (len + 1) * sizeof(char));
    if (command == NULL) {
        fprintf(stderr, "Failed to allocate memory for conversion command\n");
        return NULL;
    }
    sprintf(command + strlen(input_file), " %s/%s", output_directory, intermediate_file);
    // Add the optional command-line arguments if provided
    if (command_line_args != NULL) {
        for (int i = 0; command_line_args[i] != NULL; ++i) {
            len += strlen(command_line_args[i]);
            command = realloc(command, (len + 1) * sizeof(char));
            if (command == NULL) {
                fprintf(stderr, "Failed to allocate memory for conversion command\n");
                return NULL;
            }
            sprintf(command + strlen(input_file), " %s", command_line_args[i]);
        }
    }
    // Execute the conversion tool with the generated command line
    int status = system(command);
    free(command);
    if (status != 0) {
        fprintf(stderr, "Conversion failed with status %d\n", status);
        return NULL;
    }
    return intermediate_file;
}

// Check for the `--keep-temp` flag in the command-line arguments
int check_for_keep_temp_flag(const char **command_line_args) {
    if (command_line_args != NULL) {
        for (int i = 0; command_line_args[i] != NULL; ++i) {
            if (!strcmp(command_line_args[i], "--keep-temp")) {
                return 1;
            }
        }
    }
    return 0;
}

// Cleanup failed files and return 0 on success or non-zero on failure
int cleanup_failed_files() {
    DIR *output_dir = opendir(output_directory);
    if (output_dir == NULL) {
        fprintf(stderr, "Failed to open output directory for cleanup\n");
        return 1;
    }
    struct dirent *entry;
    while ((entry = readdir(output_dir)) != NULL) {
        if (strstr(entry->d_name, ".tmp")) {
            char file_path[1024];
            sprintf(file_path, "%s/%s", output_directory, entry->d_name);
            int status = remove(file_path);
            if (status != 0) {
                fprintf(stderr, "Failed to remove failed file %s\n", file_path);
                closedir(output_dir);
                return 1;
            }
        }
    }
    closedir(output_dir);
    return 0;
}
