        private static void ProcessAndStoreData(Record[] records)
        {
            // Create a database connection and open it
            string connectionString = "Server=myserver;Database=mydatabase;User ID=myusername;Password=mypassword";
            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                connection.Open();

                foreach (Record record in records)
                {
                    // Validate the numeric value and store it in the database
                    if (IsValidNumericValue(record.NumericValue))
                    {
                        using (SqlCommand command = new SqlCommand("INSERT INTO ProcessedData VALUES (@RecordID, @NumericValue)", connection))
                        {
                            command.Parameters.AddWithValue("@RecordID", record.RecordID);
                            command.Parameters.AddWithValue("@NumericValue", record.NumericValue);
                            command.ExecuteNonQuery();
                        }
                    }
                }

                // Retrieve the largest integer value from the database
                int maxValue = RetrieveMaxValueFromDatabase(connection);
                Console.WriteLine($"Largest value stored in the database: {maxValue}");

                connection.Close();
            }
        }

        private static bool IsValidNumericValue(int value)
        {
            // Check if the value is within a valid range
            return (value >= 0 && value <= int.MaxValue);
        }

        private static int RetrieveMaxValueFromDatabase(SqlConnection connection)
        {
            int maxValue = -1;

            try
            {
                using (SqlCommand command = new SqlCommand("SELECT MAX(NumericValue) FROM ProcessedData", connection))
                {
                    maxValue = (int)command.ExecuteScalar();
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error retrieving maximum value from database: {ex.Message}");
            }

            return maxValue;
        }
    }

    [Serializable]
    public class Record
    {
        public int RecordID { get; set; }
        public int NumericValue { get; set; }
    }
}
