import json

class TransformationRules:
    def __init__(self, rules):
        self.rules = rules

    def apply(self, data):
        transformed_data = bytearray()
        for byte in data:
            for rule in self.rules:
                if rule["operation"] == "no-op":
                    continue
                elif rule["operation"] == "bitwise-and":
                    byte &= rule["value"]
                elif rule["operation"] == "bitwise-or":
                    byte |= rule["value"]
            transformed_data.append(byte)
        return bytes(transformed_data)
