import java.util.List;

public class TransformationRules {
    private final List<TransformationRule> rules;

    public TransformationRules(String json) {
        this.rules = new ArrayList<>();
        for (String rule : json.split("\\|")) {
            String[] parts = rule.split(",");
            this.rules.add(new TransformationRule(parts[0], parts[1]));
        }
    }

    public byte[] apply(byte[] data) {
        byte[] transformedData = new byte[data.length];
        for (int i = 0; i < data.length; i++) {
            byte currentByte = data[i];
            for (TransformationRule rule : rules) {
                if (rule.getOperation().equals("no-op")) continue;
                if (rule.getOperation().equals("bitwise-and")) currentByte &= rule.getValue();
                else if (rule.getOperation().equals("bitwise-or")) currentByte |= rule.getValue();
            }
            transformedData[i] = currentByte;
        }
        return transformedData;
    }
}
