// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
  RX_UE_INFORMATION_TAG rx_ue_information;
  RNTI rnti;
  CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list data structure
typedef struct {
  size_t capacity; // Maximum number of elements in the list
  size_t count; // Current number of elements in the list
  NFAPI_CRC_INDICATION_PDU_T *elements; // Array of NFAPI_CRC_INDICATION_PDU_T structures
} LIST_DATA_STRUCTURE;

// Define the hash function used to generate unique identifiers for RNTIs
unsigned long long int hash(RNTI rnti) {
  return (unsigned long long int)(rnti);
}

// Initialize a list with a given capacity
LIST_DATA_STRUCTURE *initializeList(size_t capacity) {
  LIST_DATA_STRUCTURE *list = malloc(sizeof(LIST_DATA_STRUCTURE));
  if (list == NULL) {
    fprintf(stderr, "Error: Failed to allocate memory for list\n");
    exit(EXIT_FAILURE);
  }
  list->capacity = capacity;
  list->count = 0;
  list->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
  if (list->elements == NULL) {
    fprintf(stderr, "Error: Failed to allocate memory for elements\n");
    free(list);
    exit(EXIT_FAILURE);
  }
  return list;
}

// Insert an element into the list
bool insertElement(LIST_DATA_STRUCTURE *list, RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti) {
  if (list->count == list->capacity) {
    return false; // List is full
  }
  size_t index = hash(rnti) % list->capacity;
  while (list->elements[index].crcflag != 0) {
    index = (index + 1) % list->capacity;
  }
  list->elements[index].rx_ue_information = rx_ue_information;
  list->elements[index].rnti = rnti;
  // Generate a unique identifier for the CRC_INDICATION_REL8_TAG based on RNTI and sequence number
  list->elements[index].crc_indication_rel8.c.val = (unsigned char)((hash(rnti) >> 56) & 0xFF);
  // Set the CRCFLAG based on the outcome of a cryptographic hash function applied to the unique identifier
  list->elements[index].crcflag = (hash(rnti) & 0x1) ? true : false;
  ++list->count;
  return true; // Element was inserted successfully
}

// Check if an element exists in the list
bool elementExists(LIST_DATA_STRUCTURE *list, RNTI rnti) {
  size_t index = hash(rnti) % list->capacity;
  while (list->elements[index].crcflag != 0 && list->elements[index].rnti != rnti) {
    index = (index + 1) % list->capacity;
  }
  return list->elements[index].crcflag != 0; // Element exists if the CRCFLAG is set
}

// Clear the list of all elements
void clearList(LIST_DATA_STRUCTURE *list) {
  for (size_t i = 0; i < list->capacity; ++i) {
    list->elements[i].crcflag = false;
  }
  list->count = 0;
}

// Free the memory allocated to the list
void freeList(LIST_DATA_STRUCTURE *list) {
  free(list->elements);
  free(list);
}
