#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure to store CRC information
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T crc_indication;
} CRCInfo;

// Function to create and populate the list with semaphore
void create_and_populate_crc_list_with_semaphore(int max_size, int seq_num) {
    // Create a semaphore for thread-safe access to the list
    sem_t *sem = NULL;
    if (sem_init(&sem, 0, 1)) {
        perror("Failed to initialize semaphore");
        exit(EXIT_FAILURE);
    }

    // Create the list with the specified maximum size and initialize it with empty CRCInfo structures
    List *list = NULL;
    if (!(list = create_list(max_size, sizeof(CRCInfo)))) {
        perror("Failed to create list");
        sem_destroy(&sem);
        exit(EXIT_FAILURE);
    }

    // Iterate over the input sequence numbers and add a CRCInfo structure for each one to the list
    for (int i = 0; i < seq_num; ++i) {
        // Generate a unique identifier composed of the RNTI and the current sequence number
        int rnti = rand() % 10000;
        int seq = i + 1;
        char *id = malloc(strlen(rnti) + strlen(seq) + 1);
        sprintf(id, "%s%d", rnti, seq);

        // Compute the CRC flag using a cryptographic hash function
        unsigned int crc_flag = XXHash32(id, strlen(id), 0);

        // Create a new CRCInfo structure with the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG fields
        CRCInfo *crc_info = malloc(sizeof(CRCInfo));
        crc_info->rx_ue_information_tag = 0x1;
        crc_info->rnti = rnti;
        crc_info->crc_indication_rel8_tag = crc_flag;

        // Add the new CRCInfo structure to the list
        if (!add_to_list(list, crc_info)) {
            perror("Failed to add element to list");
            free(id);
            free(crc_info);
            sem_destroy(&sem);
            exit(EXIT_FAILURE);
        }
    }

    // Clean up memory and destroy the semaphore
    free(id);
    free(crc_info);
    delete_list(list);
    sem_destroy(&sem);
}

// Function to create a list with the specified maximum size and element size
List *create_list(int max_size, int elem_size) {
    // Allocate memory for the list and initialize it with an appropriate number of elements
    List *list = malloc(sizeof(List));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->size = 0;
    list->max_size = max_size;
    list->elem_size = elem_size;
    list->elements = malloc(list->max_size * list->elem_size);
    if (!list->elements) {
        perror("Failed to allocate memory for elements");
        free(list);
        return NULL;
    }
    memset(list->elements, 0, list->max_size * list->elem_size);
    return list;
}

// Function to add an element to a list
bool add_to_list(List *list, void *elem) {
    // Check if the list is full and the element can be added
    if (list->size >= list->max_size) {
        return false;
    }

    // Copy the element to the next available position in the list
    memcpy(&list->elements[list->size], elem, list->elem_size);
    list->size++;

    return true;
}

// Function to delete a list and free all allocated resources
void delete_list(List *list) {
    // Free the elements in the list
    for (int i = 0; i < list->size; ++i) {
        free(&list->elements[i]);
    }

    // Free the memory used by the list and set its size to 0
    free(list->elements);
    list->size = 0;
}
