['#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>

int main(int argc, char **argv) {
    // Check command line arguments
    if (argc < 3) {
        printf("Usage: %s <operation> <key> [files]\n", argv[0]);
        return 1;
    }

    // Get the operation and key from the command line
    const char *operation = argv[1];
    const char *key = argv[2];

    // Create a list of file paths to process
    int num_files = argc - 3;
    char **file_paths = malloc(num_files * sizeof(char *));
    for (int i = 0; i < num_files; i++) {
        file_paths[i] = argv[i + 3];
    }

    // Initialize the OpenSSL library
    OPENSSL_init_crypto(OPENSSL_INIT_ADD_ALL_CIPHERS | OPENSSL_INIT_ADD_ALL_DIGESTS, NULL);

    // Create an AES cipher context for encryption and decryption
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();

    // Create a SHA256 digest context for signing and verifying
    EVP_MD_CTX *digest_ctx = EVP_MD_CTX_create();

    // Iterate over the list of files
    for (int i = 0; i < num_files; i++) {
        const char *file_path = file_paths[i];

        // Open the file and read its contents
        FILE *file = fopen(file_path, "rb");
        if (!file) {
            printf("Error opening file %s\n", file_path);
            continue;
        }
        char *buffer = malloc(1024 * 1024);
        size_t buffer_size = fread(buffer, 1, 1024 * 1024, file);
        fclose(file);

        // Perform the requested operation
        if (strcmp(operation, "encrypt") == 0) {
            // Encrypt the buffer using AES in CBC mode with a 128-bit key and SHA256 HMAC digest
            EVP_EncryptInit_ex(cipher_ctx, EVP_aes_128_cbc(), NULL, key, key);
            EVP_CIPHER_CTX_set_padding(cipher_ctx, 0);
            int ciphertext_len;
            unsigned char *ciphertext = malloc(buffer_size + AES_BLOCK_SIZE);
            EVP_EncryptUpdate(cipher_ctx, ciphertext, &ciphertext_len, buffer, buffer_size);
            EVP_EncryptFinal_ex(cipher_ctx, ciphertext + ciphertext_len, &ciphertext_len);
            free(buffer);
            buffer = ciphertext;
            buffer_size += ciphertext_len;
        } else if (strcmp(operation, "decrypt") == 0) {
            // Decrypt the buffer using AES in CBC mode with a 128-bit key and SHA256 HMAC digest
            EVP_DecryptInit_ex(cipher_ctx, EVP_aes_128_cbc(), NULL, key, key);
            EVP_CIPHER_CTX_set_padding(cipher_ctx, 0);
            int plaintext_len;
            unsigned char *plaintext = malloc(buffer_size + AES_BLOCK_SIZE);
            EVP_DecryptUpdate(cipher_ctx, plaintext, &plaintext_len, buffer, buffer_size);
            EVP_DecryptFinal_ex(cipher_ctx, plaintext + plaintext_len, &plaintext_len);
            free(buffer);
            buffer = plaintext;
            buffer_size += plaintext_len;
        } else if (strcmp(operation, "sign") == 0) {
            // Sign the buffer using SHA256 HMAC with a 128-bit key
            EVP_SignInit_ex(digest_ctx, EVP_sha256(), NULL);
            EVP_SignUpdate(digest_ctx, buffer, buffer_size);
            unsigned char *signature = malloc(EVP_MAX_MD_SIZE);
            unsigned int signature_len;
            EVP_SignFinal(digest_ctx, signature, &signature_len, key);
            free(buffer);
            buffer = signature;
            buffer_size += signature_len;
        } else if (strcmp(operation, "verify") == 0) {
            // Verify the buffer using SHA256 HMAC with a 128-bit key
            EVP_VerifyInit_ex(digest_ctx, EVP_sha256(), NULL);
            EVP_VerifyUpdate(digest_ctx, buffer, buffer_size);
            unsigned char *signature = malloc(EVP_MAX_MD_SIZE);
            int signature_len;
            EVP_SignFinal(digest_ctx, signature, &signature_len, key);
            free(buffer);
            buffer = signature;
            buffer_size += signature_len;
        } else {
            // Operation not supported
            printf("Operation %s is not supported\n", operation);
            continue;
        }

        // Write the output to a file with the same name as the input file, but with an added ".enc" or ".dec" extension
        char *output_file = malloc(strlen(file_path) + 5);
        strcpy(output_file, file_path);
        if (strcmp(operation, "encrypt") == 0 || strcmp(operation, "sign") == 0) {
            strcat(output_file, ".enc");
        } else {
            strcat(output_file, ".dec");
        }
        FILE *output = fopen(output_file, "wb");
        if (!output) {
            printf("Error opening output file %s\n", output_file);
            continue;
        }
        fwrite(buffer, 1, buffer_size, output);
        fclose(output);
    }

