// Define the record structure with a single integer value
typedef struct {
    int val;
} record;

// Define the collection type as a dynamic array of records
typedef struct {
    size_t size; // Current size of the collection
    size_t capacity; // Maximum capacity of the collection
    record* data; // Pointer to the array of records
    pthread_mutex_t mutex; // Mutex for thread-safe access
} collection;

// Initialize a new collection with the specified capacity
collection* init_collection(size_t capacity) {
    collection* col = malloc(sizeof(collection));
    if (col == NULL) {
        return NULL;
    }
    col->data = malloc(capacity * sizeof(record));
    if (col->data == NULL) {
        free(col);
        return NULL;
    }
    col->size = 0;
    col->capacity = capacity;
    pthread_mutex_init(&col->mutex, NULL);
    return col;
}

// Free the memory allocated for a collection
void free_collection(collection* col) {
    if (col == NULL) {
        return;
    }
    free(col->data);
    pthread_mutex_destroy(&col->mutex);
    free(col);
}

// Add a new record to the collection
int add_record(collection* col, int val) {
    if (col == NULL || col->size >= col->capacity) {
        return -1;
    }
    pthread_mutex_lock(&col->mutex);
    col->data[col->size].val = val;
    col->size++;
    pthread_mutex_unlock(&col->mutex);
    return 0;
}

// Remove a record from the collection by its index
int remove_record(collection* col, size_t idx) {
    if (col == NULL || idx >= col->size) {
        return -1;
    }
    pthread_mutex_lock(&col->mutex);
    for (size_t i = idx + 1; i < col->size; i++) {
        col->data[i - 1] = col->data[i];
    }
    col->size--;
    pthread_mutex_unlock(&col->mutex);
    return 0;
}

// Get a record from the collection by its index
int get_record(collection* col, size_t idx, int* val) {
    if (col == NULL || idx >= col->size || val == NULL) {
        return -1;
    }
    pthread_mutex_lock(&col->mutex);
    *val = col->data[idx].val;
    pthread_mutex_unlock(&col->mutex);
    return 0;
}

// Get the size of the collection
size_t get_size(collection* col) {
    if (col == NULL) {
        return -1;
    }
    pthread_mutex_lock(&col->mutex);
    size_t size = col->size;
    pthread_mutex_unlock(&col->mutex);
    return size;
}

// Generate a unique random value for each record
int generate_random_value(collection* col, int* val) {
    if (col == NULL || val == NULL) {
        return -1;
    }
    srand((unsigned int) time(NULL)); // Seed the RNG with the current time
    *val = rand() % 100; // Generate a random value between 0 and 99
    return 0;
}
