  // Check if the message was found
  if (i >= data->num_messages) {
    pthread_mutex_unlock(&message_map_mutex);
    return -1;
  }

  // Remove the message from the map
  int j;
  for (j = i; j < data->num_messages - 1; j++) {
    data->messages[j] = data->messages[j + 1];
  }
  data->num_messages--;

  // Release the mutex
  pthread_mutex_unlock(&message_map_mutex);

  return 0;
}

// Function to clean up the message map
int cleanup(MESSAGE_MAP_DATA *data) {
  // Acquire the mutex for thread-safe access
  pthread_mutex_lock(&message_map_mutex);

