using System;
using System.Xml;
using System.IO;
using System.Collections.Generic;

class GameWorld {
    private Dictionary<string, object> configSettings = new Dictionary<string, object>();
    private GraphDatabase graphDatabase = new GraphDatabase();

    public void Initialize(string xmlFilePath) {
        XmlDocument doc = new XmlDocument();
        doc.Load(xmlFilePath);

        // Load configuration settings from XML file
        foreach (XmlElement configSetting in doc.GetElementsByTagName("configuration")) {
            string settingName = configSetting.Attributes["name"].Value;
            object settingValue = configSetting.Attributes["value"].Value;
            configSettings[settingName] = settingValue;
        }

        // Initialize graph database with random vertices and edges
        int numVertices = Convert.ToInt32(configSettings["numVertices"]);
        int numEdges = Convert.ToInt32(configSettings["numEdges"]);

        for (int i = 0; i < numVertices; i++) {
            graphDatabase.AddVertex(new Vertex {
                id = i,
                properties = new Dictionary<string, object> {
                    ["label"] = $"vertex{i}",
                    ["value"] = i * 2
                }
            });
        }

        for (int i = 0; i < numEdges; i++) {
            graphDatabase.AddEdge(new Edge {
                id = i,
                sourceVertex = Convert.ToInt32(configSettings["sourceVertex"]),
                targetVertex = Convert.ToInt32(configSettings["targetVertex"]),
                properties = new Dictionary<string, object> {
                    ["label"] = $"edge{i}",
                    ["value"] = i * 2
                }
            });
        }
    }

    public void AddCustomScenario(XmlDocument scenarioDoc) {
        // Load custom scenario from XML document
        foreach (XmlElement entity in scenarioDoc.GetElementsByTagName("entity")) {
            string type = entity.Attributes["type"].Value;
            int id = Convert.ToInt32(entity.Attributes["id"].Value);
            object properties = entity.Attributes["properties"].Value;
            graphDatabase.AddEntity(new Entity {
                id = id,
                type = type,
                properties = properties
            });
        }
    }

    public void RemoveCustomScenario(int id) {
        // Remove custom scenario from graph database
        graphDatabase.RemoveEntity(id);
    }

    public void UpdateCustomScenario(XmlDocument scenarioDoc, int id) {
        // Update custom scenario in graph database
        Entity entity = graphDatabase.GetEntity(id);
        foreach (XmlElement property in scenarioDoc.GetElementsByTagName("property")) {
            string name = property.Attributes["name"].Value;
            object value = property.Attributes["value"].Value;
            entity.properties[name] = value;
        }
    }
}

