    // Check input parameter bounds
    if (num_connections < 0 || num_connections > 10000) {
        return -1;
    }

    // Allocate memory for file descriptors and connections
    file_descriptor_t *fd_array = malloc(sizeof(file_descriptor_t) * num_connections);
    connection_t *conn_array = malloc(sizeof(connection_t) * num_connections);

    // Initialize each file descriptor and connection structure
    for (int i = 0; i < num_connections; i++) {
        fd_array[i].fd = -1;
        conn_array[i].state = CONN_CLOSED;
        conn_array[i].timeout = DEFAULT_TIMEOUT;
