    log_entry_t *log_array = malloc(sizeof(log_entry_t) * num_connections);

    // Initialize each log entry structure's timestamp to the current time
    for (int i = 0; i < num_connections; i++) {
        log_array[i].timestamp = get_current_time();
        log_array[i].severity = LOG_INFO;
    }

