    offset_t* offsets = (offset_t*)malloc(num_offsets * sizeof(offset_t));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        exit(-1);
    }

    // Allocate memory for an array of key_t type to store a series of integer keys
    key_t* keys = (key_t*)malloc(num_keys * sizeof(key_t));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(offsets);
        exit(-1);
    }

    // Allocate memory for an array of record_t structures
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        exit(-1);
    }

    // Initialize each record structure's integer value to a random number within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % MAX_VALUE;
    }

    // Initialize each record structure's offset and key to the corresponding values in the offsets and keys arrays
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    // Free allocated memory at the end of execution to prevent memory leaks and ensure resources are released even in case of errors
    free(offsets);
    free(keys);
