#include <openssl/evp.h>
#include <openssl/err.h>
#include <string>
#include <vector>
#include <map>

using namespace std;

class AES256CBC {
private:
    // The derived key and initialization vector (IV) for the encryption/decryption process.
    unsigned char* derivedKey;
    unsigned char* iv;

    // The current encryption or decryption operation.
    bool isEncrypting;

    // The input data to be encrypted or decrypted.
    string inputData;

    // The output data after encryption/decryption.
    string outputData;

public:
    AES256CBC(const string& password, const string& inputData) {
        // Derive the key and IV from the given password.
        derivedKey = EVP_BytesToKey(EVP_aes_256_cbc(), SHA256(), NULL, (unsigned char*)password.data(), password.size());
        iv = new unsigned char[16];
        memset(iv, 0x00, 16);

        // Set the input data and initialize the encryption/decryption operation.
        this->inputData = inputData;
        isEncrypting = true;
    }

    ~AES256CBC() {
        // Clean up the memory allocated for the derived key and IV.
        delete[] derivedKey;
        delete[] iv;
    }

    void encrypt(string& outputData) {
        // Encrypt the input data using AES-256-CBC.
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        int len;
        unsigned char* out = new unsigned char[inputData.size() + 16];
        memset(out, 0x00, inputData.size() + 16);

        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, derivedKey, iv) <= 0 ||
            EVP_EncryptUpdate(ctx, out, &len, (unsigned char*)inputData.data(), inputData.size()) <= 0 ||
            EVP_EncryptFinal_ex(ctx, out + len, &len) <= 0) {
            cerr << "Error: Failed to encrypt the data." << endl;
            return;
        }

        outputData = string((char*)out, len);
        delete[] out;
        EVP_CIPHER_CTX_free(ctx);
    }

    void decrypt(string& outputData) {
        // Decrypt the input data using AES-256-CBC.
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        int len;
        unsigned char* out = new unsigned char[inputData.size() + 16];
        memset(out, 0x00, inputData.size() + 16);

        if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, derivedKey, iv) <= 0 ||
            EVP_DecryptUpdate(ctx, out, &len, (unsigned char*)inputData.data(), inputData.size()) <= 0 ||
            EVP_DecryptFinal_ex(ctx, out + len, &len) <= 0) {
            cerr << "Error: Failed to decrypt the data." << endl;
            return;
        }

        outputData = string((char*)out, len);
        delete[] out;
        EVP_CIPHER_CTX_free(ctx);
    }
};
```
