// Hash table for mapping page IDs to their respective index entries
#define HASH_TABLE_SIZE 1024
#define MAX_HASH_COLLISIONS 5
typedef struct hash_table {
    int size;
    index_entry_t** entries;
} hash_table_t;

// Initialize the hash table with a specified size and number of collisions allowed
void init_hash_table(hash_table_t* ht, int size, int max_collisions) {
    assert(ht != NULL);
    ht->size = size;
    ht->entries = calloc(size, sizeof(index_entry_t*));
    for (int i = 0; i < ht->size; i++) {
        ht->entries[i] = NULL;
    }
}

// Insert a new entry into the hash table
void insert_into_hash_table(hash_table_t* ht, page_id_t page_id, value_t value) {
    assert(ht != NULL);
    int index = (page_id % ht->size);
    if (ht->entries[index] == NULL) {
        // Allocate a new entry for this page ID
        index_entry_t* entry = malloc(sizeof(index_entry_t));
        assert(entry != NULL);
        entry->page_id = page_id;
        entry->value = value;
        ht->entries[index] = entry;
    } else {
        // Collision detected, add the new entry to the linked list
        index_entry_t* head = ht->entries[index];
        while (head->next != NULL) {
            head = head->next;
        }
        index_entry_t* entry = malloc(sizeof(index_entry_t));
        assert(entry != NULL);
        entry->page_id = page_id;
        entry->value = value;
        head->next = entry;
    }
}

// Look up an entry in the hash table
index_entry_t* look_up_in_hash_table(hash_table_t* ht, page_id_t page_id) {
    assert(ht != NULL);
    int index = (page_id % ht->size);
    if (ht->entries[index] == NULL) {
        return NULL;
    } else {
        // Search for the entry with the matching page ID
        index_entry_t* head = ht->entries[index];
        while (head != NULL && head->page_id != page_id) {
            head = head->next;
        }
        if (head == NULL) {
            return NULL;
        } else {
            return head;
        }
    }
}

