// Linked list node insertion
bool insert_node(NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* node) {
    if (list == NULL || node == NULL) {
        return false;
    }
    // If the list is empty, set the first and last nodes to the new node
    if (list->first == NULL && list->last == NULL) {
        list->first = node;
        list->last = node;
    } else {
        // Otherwise, set the next pointer of the last node to the new node
        list->last->next = node;
        list->last = node;
    }
    return true;
}

// Linked list node removal
bool remove_node(NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* node) {
    if (list == NULL || node == NULL) {
        return false;
    }
    // If the node is the first and last node in the list, set both pointers to NULL
    if (list->first == node && list->last == node) {
        list->first = NULL;
        list->last = NULL;
    } else if (list->first == node) {
        // If the node is the first node in the list, set the next pointer of the previous node to the next node
        list->first = node->next;
    } else if (list->last == node) {
        // If the node is the last node in the list, set the previous pointer of the next node to the previous node
        list->last = node->previous;
    } else {
        // Otherwise, set the next and previous pointers of adjacent nodes appropriately
        node->previous->next = node->next;
        node->next->previous = node->previous;
    }
    return true;
}

// Linked list node iteration
void iterate_nodes(NFAPI_CRC_INDICATION_LIST* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (list == NULL || callback == NULL) {
        return;
