struct memory_pool {
    size_t capacity;
    size_t used;
    void **data;
};

int initialize_records(size_t num_records, record_t **records) {
    // Allocate memory for the arrays
    int *keys = (int *)malloc(num_records * sizeof(int));
    long *offsets = (long *)malloc(num_records * sizeof(long));
    record_t *values = (record_t *)malloc(num_records * sizeof(record_t));

    if (!keys || !offsets || !values) {
        // Allocation failed, release all allocated memory and return error
        free(keys);
        free(offsets);
        free(values);
        return -1;
    }

    // Initialize the arrays
    for (size_t i = 0; i < num_records; i++) {
        keys[i] = getUniqueKey();
        offsets[i] = 0;
        values[i].value = NULL;
        values[i].status = 'I';
    }

    // Initialize the memory pool for improved performance under high-concurrency scenarios
    struct memory_pool *memory_pool = (struct memory_pool *)malloc(sizeof(struct memory_pool));
    if (!memory_pool) {
        // Allocation failed, release all allocated memory and return error
        free(keys);
        free(offsets);
        free(values);
        return -1;
    }
    memory_pool->capacity = num_records * sizeof(record_t);
    memory_pool->used = 0;
    memory_pool->data = (void **)malloc(num_records * sizeof(void *));
    if (!memory_pool->data) {
        // Allocation failed, release all allocated memory and return error
        free(keys);
        free(offsets);
        free(values);
        free(memory_pool);
        return -1;
    }

    *records = values;
    return num_records;
}
