#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/err.h>

struct cipher_mode {
    const char *name;
    int key_size;
    EVP_CIPHER *(*cipher)(void);
};

static struct cipher_mode modes[] = {
    {"ECB", 64, &EVP_des_ecb},
    {"EDE", 56, &EVP_des_ede},
    {"EDE3", 168, &EVP_des_ede3},
    {"CFB", 0, &EVP_des_cfb}
};

static EVP_CIPHER *cipher_lookup(const char *name) {
    for (int i = 0; i < sizeof(modes) / sizeof(*modes); ++i) {
        if (strcmp(modes[i].name, name) == 0) {
            return modes[i].cipher();
        }
    }
    return NULL;
}

static void *cipher_init(const char *name, int key_size, bool enc, bool pad) {
    EVP_CIPHER *cipher = cipher_lookup(name);
    if (cipher == NULL) {
        fprintf(stderr, "Invalid cipher name: %s\n", name);
        return NULL;
    }
    if (key_size != 0 && key_size != EVP_CIPHER_key_length(cipher)) {
        fprintf(stderr, "Invalid key size for %s: %d\n", name, key_size);
        return NULL;
    }
    if (enc && !EVP_CIPHER_flags(cipher) & EVP_CIPH_FLAG_DEFAULT_ASN1) {
        fprintf(stderr, "Invalid encryption mode for %s\n", name);
        return NULL;
    }
    if (!enc && !pad) {
        fprintf(stderr, "Decryption must use padding\n");
        return NULL;
    }
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) {
        fprintf(stderr, "Failed to initialize cipher context\n");
        return NULL;
    }
    EVP_CIPHER_CTX_set_padding(ctx, pad);
    if (key_size > 0) {
        unsigned char key[key_size / 8];
        memset(key, 0x00, sizeof(key));
        if (EVP_EncryptInit_ex(ctx, NULL, NULL, key, NULL) != 1) {
            fprintf(stderr, "Failed to set cipher key\n");
            return NULL;
        }
    }
    return ctx;
}

static int cipher_update(void *ctx, const unsigned char *src, int len, unsigned char *dst) {
    EVP_CIPHER_CTX *context = (EVP_CIPHER_CTX *)ctx;
    if (EVP_EncryptUpdate(context, dst, &len, src, len) != 1) {
        fprintf(stderr, "Failed to encrypt data\n");
        return -1;
    }
    return len;
}

static int cipher_final(void *ctx, unsigned char *dst) {
    EVP_CIPHER_CTX *context = (EVP_CIPHER_CTX *)ctx;
    if (EVP_EncryptFinal_ex(context, dst, &len) != 1) {
        fprintf(stderr, "Failed to finalize encryption\n");
        return -1;
    }
    EVP_CIPHER_CTX_free(context);
    return len;
}

static int cipher_decrypt(void *ctx, const unsigned char *src, int len, unsigned char *dst) {
    EVP_CIPHER_CTX *context = (EVP_CIPHER_CTX *)ctx;
    if (EVP_DecryptUpdate(context, dst, &len, src, len) != 1) {
        fprintf(stderr, "Failed to decrypt data\n");
        return -1;
    }
    EVP_CIPHER_CTX_set_padding(ctx, 0); // disable padding for decryption
    return len;
}

static int cipher_final_decrypt(void *ctx, unsigned char *dst) {
    EVP_CIPHER_CTX *context = (EVP_CIPHER_CTX *)ctx;
    if (EVP_DecryptFinal_ex(context, dst, &len) != 1) {
        fprintf(stderr, "Failed to finalize decryption\n");
        return -1;
    }
    EVP_CIPHER_CTX_free(context);
    return len;
}

static int cipher_encrypt(const char *name, int key_size, bool enc, bool pad, const unsigned char *src, int len, unsigned char *dst) {
    void *ctx = cipher_init(name, key_size, enc, pad);
    if (ctx == NULL) {
        return -1;
    }
    int update_len = cipher_update(ctx, src, len, dst);
    if (update_len < 0) {
        return -1;
    }
    int final_len = cipher_final(ctx, dst + update_len);
    if (final_len < 0) {
        return -1;
    }
    return update_len + final_len;
}

static int cipher_decrypt(const char *name, int key_size, bool enc, bool pad, const unsigned char *src, int len, unsigned char *dst) {
    void *ctx = cipher_init(name, key_size, !enc, pad);
    if (ctx == NULL) {
        return -1;
    }
    int update_len = cipher_update(ctx, src, len, dst);
    if (update_len < 0) {
        return -1;
    }
    int final_len = cipher_final_decrypt(ctx, dst + update_len);
    if (final_len < 0) {
        return -1;
    }
    return update_len + final_len;
}

static const char *cipher_name_lookup(int key_size, bool enc) {
    for (int i = 0; i < sizeof(modes) / sizeof(*modes); ++i) {
        if (modes[i].key_size == key_size && modes[i].cipher->flags & EVP_CIPH_FLAG_DEFAULT_ASN1 == enc) {
            return modes[i].name;
        }
    }
    return NULL;
}

int main(void) {
    const char *name = cipher_name_lookup(256, true); // AES-256 in ECB mode with PKCS#7 padding
    unsigned char src[1024] = "Hello World!";
    unsigned char dst[1024];
    int len;

    len = cipher_encrypt(name, 256, true, true, src, 13, dst); // encrypt the data
    if (len < 0) {
        printf("Error: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return -1;
    }

    printf("Encrypted data:\n");
    for (int i = 0; i < len; ++i) {
        printf("%02x", dst[i]);
    }
    printf("\n\n");

    len = cipher_decrypt(name, 256, true, true, src, 13, dst); // decrypt the data
    if (len < 0) {
        printf("Error: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return -1;
    }

    printf("Decrypted data:\n");
    for (int i = 0; i < len; ++i) {
        printf("%c", dst[i]);
    }
    printf("\n\n");

    EVP_cleanup(); // clean up the OpenSSL library
    return 0;
}
```
This is an example program that demonstrates how to use the `openssl` library in C to encrypt and decrypt data using AES. The program uses the `EVP_EncryptInit()` and `EVP_DecryptInit()` functions to initialize the encryption and decryption contexts, respectively. The `EVP_EncryptUpdate()` and `EVP_DecryptUpdate()` functions are used to encrypt or decrypt data in chunks of a certain size, and the `EVP_EncryptFinal()` and `EVP_DecryptFinal()` functions are used to finalize the encryption or decryption process.

The program first initializes an encryption context for AES-256 in ECB mode with PKCS#7 padding using the `EVP_EncryptInit()` function. It then encrypts some data using the `EVP_EncryptUpdate()` and `EVP_EncryptFinal()` functions. The encrypted data is then printed to the console.

Next, the program initializes a decryption context for AES-256 in ECB mode with PKCS#7 padding using the `EVP_DecryptInit()` function. It then decrypts the previously encrypted data using the `EVP_DecryptUpdate()` and `EVP_DecryptFinal()` functions. The decrypted data is then printed to the console.

The program also uses the `ERR_error_string()` function from the `err` module of OpenSSL to get a string representation of any error that occurs during encryption or decryption, which can be useful for debugging purposes.']

