static void *session_initialize(void *arg) {
  session_t *session = (session_t *)arg;

  // Get initial session parameters from external data sources
  network_service_response_t response;
  if (!get_initial_parameters(&response)) {
    fprintf(stderr, "Failed to get initial session parameters: %s\n", strerror(errno));
    return NULL;
  }

  // Populate UE Identity and Session AMBR data structures
  SMC_session_set_ue_identity(session, response.UE_ID);
  SMC_session_set_ambr(session, response.AMBR);

  // Initialize QoS Rules data structure
  QoSRules qos_rules;
  qos_rules.qci = response.QCI;
  qos_rules.arp = response.ARP;
  SMC_session_set_qos_rules(session, &qos_rules);

  // Handle state transitions efficiently
  switch (SMC_session_get_state(session)) {
    case SESSION_STATE_INIT:
      // Update session state to INITIALIZING
      SMC_session_set_state(session, SESSION_STATE_INITIALIZING);

      // Initialize authentication, billing, and policy control entities
      pthread_t authentication_entity;
      pthread_t billing_entity;
      pthread_t policy_control_entity;
      if (!pthread_create(&authentication_entity, NULL, &init_authentication_entity, session)) {
        fprintf(stderr, "Failed to create authentication entity: %s\n", strerror(errno));
        return NULL;
      }
      if (!pthread_create(&billing_entity, NULL, &init_billing_entity, session)) {
        fprintf(stderr, "Failed to create billing entity: %s\n", strerror(errno));
        return NULL;
      }
      if (!pthread_create(&policy_control_entity, NULL, &init_policy_control_entity, session)) {
        fprintf(stderr, "Failed to create policy control entity: %s\n", strerror(errno));
        return NULL;
      }

      // Wait for authentication, billing, and policy control entities to finish initializing
      pthread_join(authentication_entity, NULL);
      pthread_join(billing_entity, NULL);
      pthread_join(policy_control_entity, NULL);

      // Update session state to INITIALIZED
      SMC_session_set_state(session, SESSION_STATE_INITIALIZED);
      break;
    case SESSION_STATE_TERMINATED:
      // Update session state to TERMINATING
      SMC_session_set_state(session, SESSION_STATE_TERMINATING);

      // Terminate authentication, billing, and policy control entities
      if (!pthread_cancel(&authentication_entity)) {
        fprintf(stderr, "Failed to terminate authentication entity: %s\n", strerror(errno));
        return NULL;
      }
      if (!pthread_cancel(&billing_entity)) {
        fprintf(stderr, "Failed to terminate billing entity: %s\n", strerror(errno));
        return NULL;
      }
      if (!pthread_cancel(&policy_control_entity)) {
        fprintf(stderr, "Failed to terminate policy control entity: %s\n", strerror(errno));
        return NULL;
      }

      // Update session state to TERMINATED
      SMC_session_set_state(session, SESSION_STATE_TERMINATED);
      break;
    default:
      fprintf(stderr, "Invalid session state\n");
      return NULL;
  }

  // Return session pointer
  return session;
}
