    uint16_t stream_id;
} SCTP_STREAM;

typedef struct SEQUENCE_NUMBER {
    uint16_t sequence_number;
} SEQUENCE_NUMBER;

// Custom allocator for efficient memory management
struct ListNode {
    LTE_RRC_CONNECTION_RECONFIGURATION *connection_reconfiguration;
    struct ListNode *next;
};

static struct ListNode* head = NULL;
static int list_size = 0;

// Dynamically manages a list of LTE_RRC_CU_DOWNLINK_CCCH_MESSAGE_TYPE1_T structures
LTE_RRC_CONNECTION_RECONFIGURATION* manageList(RRC_CGI *rrc_cgi, SCTP_STREAM *sctp_stream, SEQUENCE_NUMBER *sequence_number) {
    // Check for memory allocation failures
    if (list_size >= MAX_LIST_SIZE) {
        return NULL;
    }

    // Compute unique identifier using RRC_CGI, SCTP_STREAM, and SEQUENCE_NUMBER
    uint8_t unique_id[32];
    memset(unique_id, 0, sizeof(uint8_t) * 32);
    memcpy(unique_id, rrc_cgi->cgi, sizeof(uint8_t) * 32);
    memcpy(&unique_id[32], &sctp_stream->stream_id, sizeof(uint16_t));
    memcpy(&unique_id[34], sequence_number->sequence_number, sizeof(uint16_t));

    // Apply cryptographic hash function to unique identifier
    uint8_t hash[32];
    sha256(unique_id, 32, hash);

    // Check if list is empty
    if (head == NULL) {
        head = malloc(sizeof(struct ListNode));
        assert(head != NULL);
        list_size++;

        head->connection_reconfiguration = malloc(sizeof(LTE_RRC_CONNECTION_RECONFIGURATION));
        assert(head->connection_reconfiguration != NULL);

        head->connection_reconfiguration->CCCH_MESSAGE_FLAG = hash[0] & 1; // Set CCCH_MESSAGE_FLAG based on hash output
    } else {
        struct ListNode* current = head;
        while (current->next != NULL) {
            current = current->next;
        }

        // Check if list size exceeds maximum size
        if (list_size >= MAX_LIST_SIZE) {
            return NULL;
        }

        struct ListNode* new_node = malloc(sizeof(struct ListNode));
        assert(new_node != NULL);
        list_size++;

        new_node->connection_reconfiguration = malloc(sizeof(LTE_RRC_CONNECTION_RECONFIGURATION));
        assert(new_node->connection_reconfiguration != NULL);

        new_node->next = NULL;
        current->next = new_node;
    }

    return head->connection_reconfiguration;
}

// Custom allocator for efficient memory management
struct ListNode* allocateListNode(void) {
    struct ListNode *new_node = malloc(sizeof(struct ListNode));
    assert(new_node != NULL);

    new_node->connection_reconfiguration = malloc(sizeof(LTE_RRC_CONNECTION_RECONFIGURATION));
    assert(new_node->connection_reconfiguration != NULL);

    new_node->next = NULL;
    list_size++;

    return new_node;
}

// Custom allocator for efficient memory management
void deallocateListNode(struct ListNode* node) {
    assert(node != NULL);

    free(node->connection_reconfiguration);
    free(node);

    list_size--;
}
