std::vector<std::unique_ptr<int>>& insertOrAppendUniquePtr(std::vector<std::unique_ptr<int>>& vec, std::unique_ptr<int>&& elem) {
    // Check if the element is already present in the vector
    auto it = std::find(vec.begin(), vec.end(), elem);
    if (it != vec.end()) {
        // Insert the element after the first occurrence
        vec.insert(std::next(it), std::move(elem));
    } else {
        // Append the element to the end of the vector
        vec.emplace_back(std::move(elem));
    }
    return vec;
}
