                crcIndicationPdu.Initialize();

                // add the allocated CRC_INDICATION_PDU to the dictionary
                CRC_INDICATION_PDUs.Add(connectionId, crcIndicationPdu);
            } finally {
                semaphore.Release();
            }
        }

