            if (!semaphore.Wait(0)) {
                throw new Exception("Maximum number of concurrent connections reached");
            }

            try {
                // remove the allocated CRC_INDICATION_PDU from the dictionary
                CRC_INDICATION_PDUs.Remove(connectionId);
            } finally {
                semaphore.Release();
            }
        }

