            if (!semaphore.Wait(0)) {
                throw new Exception("Maximum number of concurrent connections reached");
            }

            try {
                // return the allocated CRC_INDICATION_PDU from the dictionary
                return CRC_INDICATION_PDUs[connectionId];
            } finally {
                semaphore.Release();
