Here is an example implementation of a C function to manage a dynamic linked list of `DeviceSessionInfo` structures:
```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "device_session_info.h"

// Linked list node structure
typedef struct DeviceSessionInfoNode {
  struct DeviceSessionInfoNode *next;
  struct DeviceSessionInfoNode *prev;
  struct DeviceSessionInfo *data;
} DeviceSessionInfoNode;

// Linked list head structure
typedef struct {
  pthread_mutex_t lock;
  DeviceSessionInfoNode *head;
} DeviceSessionInfoList;

// Initializes a new linked list node with the given data
DeviceSessionInfoNode* deviceSessionInfoNodeInit(struct DeviceSessionInfo *data) {
  DeviceSessionInfoNode *node = malloc(sizeof(DeviceSessionInfoNode));
  node->next = NULL;
  node->prev = NULL;
  node->data = data;
  return node;
}

// Adds a new node to the linked list with the given data
void deviceSessionInfoListAdd(DeviceSessionInfoList *list, struct DeviceSessionInfo *data) {
  pthread_mutex_lock(&list->lock);
  DeviceSessionInfoNode *node = deviceSessionInfoNodeInit(data);
  node->next = list->head;
  if (list->head) {
    list->head->prev = node;
  }
  list->head = node;
  pthread_mutex_unlock(&list->lock);
}

// Removes the given node from the linked list
void deviceSessionInfoListRemove(DeviceSessionInfoNode *node) {
  if (node->next) {
    node->next->prev = node->prev;
  }
  if (node->prev) {
    node->prev->next = node->next;
  }
  free(node);
}

// Updates the session information for a given device
void deviceSessionInfoUpdate(DeviceSessionInfoList *list, const char *device_id, struct DeviceSessionInfo *data) {
  pthread_mutex_lock(&list->lock);
  DeviceSessionInfoNode *node = NULL;
  for (node = list->head; node != NULL; node = node->next) {
    if (strcmp(device_id, node->data.sessionID) == 0) {
      break;
    }
  }
  if (node != NULL) {
    deviceSessionInfoListRemove(node);
    deviceSessionInfoNodeInit(data);
    deviceSessionInfoListAdd(list, data);
  } else {
    // Device not found in list, add new node
    deviceSessionInfoListAdd(list, data);
  }
  pthread_mutex_unlock(&list->lock);
}

// Gets the session information for a given device
struct DeviceSessionInfo* deviceSessionInfoGet(DeviceSessionInfoList *list, const char *device_id) {
  struct DeviceSessionInfo *data = NULL;
  pthread_mutex_lock(&list->lock);
  DeviceSessionInfoNode *node = NULL;
  for (node = list->head; node != NULL; node = node->next) {
    if (strcmp(device_id, node->data.sessionID) == 0) {
      data = &node->data;
      break;
    }
  }
  pthread_mutex_unlock(&list->lock);
  return data;
}
```
This implementation uses a mutex lock to protect the linked list from concurrent access and updates, ensuring that the data is consistent and up-to-date. The `deviceSessionInfoNodeInit()` function initializes a new node with the given data, while the `deviceSessionInfoListAdd()` function adds a new node to the linked list. The `deviceSessionInfoListRemove()` function removes a node from the linked list. The `deviceSessionInfoUpdate()` function updates the session information for a given device by removing the old node and adding a new one with the updated data. The `deviceSessionInfoGet()` function retrieves the session information for a given device.

The performance of this implementation can be improved by using a more efficient data structure than a linked list, such as a hash table or an array. Additionally, the use of a mutex lock can be replaced with a reader-writer lock or spinlock to reduce contention and improve performance. The function can also be optimized for scalability by implementing a strategy for managing node allocation and deallocation, ensuring that memory usage is minimized while maintaining data integrity.']

