  void* ptr = custom_alloc(size);
  if (ptr == NULL) {
    // Handle memory allocation failure gracefully
    return NULL;
  }
  return ptr;
}

// Function to initialize and manage a dynamic collection of records
void init_records(record_t** records, size_t num_records) {
  *records = (record_t*)custom_alloc(sizeof(record_t) * num_records);
  if (*records == NULL) {
    // Handle memory allocation failure gracefully
    return;
  }
  for (size_t i = 0; i < num_records; ++i) {
    (*records)[i].value = generate_random_number();
  }
}

// Function to generate unique random values for each record
int generate_random_number() {
  int seed = time(NULL);
  srand(seed);
  return rand();
}

// Synchronization mechanism to manage concurrent access
pthread_mutex_t mutex;

// Function to add a new record to the collection
void add_record(record_t** records, size_t* num_records) {
  pthread_mutex_lock(&mutex);
  *num_records = (*num_records) + 1;
  (*records)[*num_records - 1].value = generate_random_number();
  pthread_mutex_unlock(&mutex);
}

// Function to get a record from the collection by index
record_t* get_record(record_t** records, size_t index) {
  return &(*records)[index];
}

// Function to update a record in the collection
void update_record(record_t** records, size_t index, int value) {
  pthread_mutex_lock(&mutex);
  (*records)[index].value = value;
  pthread_mutex_unlock(&mutex);
}

// Function to remove a record from the collection by index
void remove_record(record_t** records, size_t* num_records, size_t index) {
  pthread_mutex_lock(&mutex);
  for (size_t i = index; i < *num_records - 1; ++i) {
    (*records)[i] = (*records)[i + 1];
  }
  --(*num_records);
  pthread_mutex_unlock(&mutex);
}

// Function to release memory allocated for the records collection
void free_records(record_t** records, size_t num_records) {
  free(*records);
}
