    // Set up the connection state for the socket
    CONNECTION_STATE *connection_state = (CONNECTION_STATE *)malloc(sizeof(CONNECTION_STATE));
    if (!connection_state) {
        printf("Error allocating memory for connection state: %s\n", strerror(errno));
        close(socket);
        return -1;
