    connection_state->local_address = local_address;

    // Connect to the remote address using a Java Channel within the NFAPI_CRC_INDICATION_PDU_T structures
    int connect_result = 0;
    while (connect_result != 1) {
        connect_result = connect(socket, &connection_state->remote_address, sizeof(struct sockaddr_in6));
        if (connect_result == -1 && errno == ECONNREFUSED) {
