    struct in_addr source_ip;
    struct in_addr destination_ip;
} PDU_header;

// Function to initialize and configure the network interface
int init_network_interface(PDU_header *pdu_headers, int num_pdu_headers, int max_packet_size, double current_load) {
    // Set the maximum packet size based on the specified range
    int min_packet_size = 14;
    int max_packet_size = 1500;

    // Adjust the packet generation rate to prevent congestion
    double load_threshold = 0.7;
    if (current_load > load_threshold) {
        num_pdu_headers = (int)(num_pdu_headers * (1 - current_load / load_threshold));
    }

    // Allocate memory for the PDU headers
    int total_packet_size = num_pdu_headers * max_packet_size;
    void *packet_buffer = malloc(total_packet_size);
    if (packet_buffer == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Populate the PDU headers with valid IP packets
    int num_successfully_configured = 0;
    for (int i = 0; i < num_pdu_headers; i++) {
        PDU_header *pdu_header = pdu_headers + i;
        // Generate random source and destination IP addresses
        unsigned int src_ip = arc4random() % (1 << 32);
        unsigned int dst_ip = arc4random() % (1 << 32);
        pdu_header->source_ip.s_addr = htonl(src_ip);
        pdu_header->destination_ip.s_addr = htonl(dst_ip);
        // Set the protocol to UDP
        pdu_header->protocol = 17;
        // Set the version and internet header length fields
        pdu_header->version = 4;
        pdu_header->ihl = 5;
        // Set the total length field to the maximum packet size
        pdu_header->total_length = htons(max_packet_size);
        // Increment the number of successfully configured PDU headers
        num_successfully_configured++;
    }

    // Free the memory allocated for the PDU headers if there were no successful configurations
    if (num_successfully_configured == 0) {
        free(packet_buffer);
        return -1;
    }

    // Return the number of successfully configured PDU headers
    return num_successfully_configured;
}
