    memcpy(crc, &crc_list[crc_list->num_elements - 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // release mutex lock
    pthread_mutex_unlock(&crc_list_mutex);
}

// removes a CRC indication structure from the list
void remove_crc(NFAPI_CRC_INDICATION_PDU_T *crc) {
    // acquire mutex lock
    pthread_mutex_lock(&crc_list_mutex);

    // check if the list is empty
    if (crc_list == NULL || crc_list->num_elements <= 0) {
        printf("Error: CRC indication list is empty\n");
        pthread_mutex_unlock(&crc_list_mutex);
        return;
    }

    // find the structure to remove
    int index = -1;
    for (int i = 0; i < crc_list->num_elements; ++i) {
        if (memcmp(crc, &crc_list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            index = i;
            break;
        }
    }

    // remove the structure from the list
    if (index != -1) {
        crc_list->num_elements--;
        memcpy(&crc_list[index], &crc_list[crc_list->num_elements], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        printf("Error: CRC indication structure not found in list\n");
    }

    // release mutex lock
    pthread_mutex_unlock(&crc_list_mutex);
}

// clears the CRC indication list
void clear_crc_list() {
    // acquire mutex lock
    pthread_mutex_lock(&crc_list_mutex);

    // free memory allocated for the list
    if (crc_list) {
        free(crc_list);
    }

    // set the list pointer to NULL
    crc_list = NULL;

    // release mutex lock
    pthread_mutex_unlock(&crc_list_mutex);
}
```
The `init_crc_list()` function initializes the CRC indication list with a given number of elements. It allocates memory for the list and initializes each structure with random data.

The `add_crc()` function adds a new CRC indication structure to the end of the list. If the list is full, it returns an error. The function acquires a mutex lock before modifying the list to ensure thread-safe access.

The `remove_crc()` function removes a CRC indication structure from the list based on a given structure pointer. It searches for the structure in the list and if found, it removes it by copying the last structure to its place and decrementing the number of elements. If the structure is not found, it returns an error. The function also acquires a mutex lock before modifying the list to ensure thread-safe access.

The `clear_crc_list()` function clears the entire CRC indication list by freeing its memory and setting the pointer to NULL. It also releases any acquired mutex locks before returning.

In terms of performance, this implementation uses a dynamically allocated array to store the list of structures, which allows for efficient insertion and removal of elements. The use of a mutex lock ensures thread-safe access to the list, even in concurrently accessed applications. Additionally, the `memcpy()` function is used to copy the data from the temporary structure to the actual structure, which ensures consistency between the structures in the list.

In terms of scalability, this implementation uses a fixed maximum size for the list, which can be adjusted based on the requirements of the application. The use of a dynamically allocated array also allows for efficient memory allocation and deallocation. Additionally, the `malloc()` and `free()` functions are used to allocate and release memory as needed, which ensures efficient memory usage.

