        ueMeasurementArray[i].ueIdentifier = i + 1;
    }

    return ueMeasurementArray;
}

// Function to add a new sample to the array
void addNewSample(UeMeasurementRecord* record, long long timestamp, int signalStrengthValue, bool qualityIndicator) {
    // Check if the vector is full
    if (record->numSamples == 100) {
        // Remove the oldest sample to make space for a new one
        memmove(&record->samples[0], &record->samples[1], sizeof(SignalStrengthSample) * (99));
        --record->numSamples;
    }

    record->samples[record->numSamples].timestamp = timestamp;
    record->samples[record->numSamples].signalStrengthValue = signalStrengthValue;
    record->samples[record->numSamples].qualityIndicator = qualityIndicator;
    ++record->numSamples;
}

// Function to remove a sample from the array
void removeSample(UeMeasurementRecord* record, int index) {
    // Check if the vector is not empty
    if (record->numSamples > 0) {
        memmove(&record->samples[index], &record->samples[index + 1], sizeof(SignalStrengthSample) * (record->numSamples - index));
        --record->numSamples;
    }
}

// Function to update the timestamp of a record
void updateTimestamp(UeMeasurementRecord* record, long long newTimestamp) {
    record->timestamp = newTimestamp;
}
