    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *indications = malloc(MAX_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (indications == NULL) {
        perror("Failed to allocate memory for indications");
        return NULL;
