    while (index < MAX_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T *indication = &indications[index];
        // Generate random values for RX UE Information Tag, RNTI, and CRC Indication REL8 Tag
        indication->rx_ue_information_tag = rand() % 100;
        indication->rnti = rand() % 65535;
        indication->crc_indication_rel8_tag = rand() % 256;
        // Generate random values for CRCFlag
        indication->crcflag = (rand() % 2 == 0) ? true : false;
        index++;
    }

    sem_post(sem);
    return indications;
}
