typedef struct {
    uint32_t ueId;
    MeasurementReport* measurementReports[100];
    MobilityState mobilityState;
} UEStatusRecord;

// Thread-safe dynamic array for storing UE status records
typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t count;
    UEStatusRecord* data;
} UEDynamicArray;

// Function to initialize and configure a dynamic array of UE status records
void initUEDynamicArray(UEDynamicArray* array) {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&array->mutex, &attr);
    array->capacity = 10; // Initial capacity of 10 records
    array->count = 0;
    array->data = malloc(sizeof(UEStatusRecord) * array->capacity);
}

// Function to add a new record or update an existing one in the dynamic array
void addOrUpdateRecord(UEDynamicArray* array, uint32_t ueId, MeasurementReport* measurementReports, size_t numMeasurements, MobilityState mobilityState) {
    pthread_mutex_lock(&array->mutex);
    // Check if the record already exists
    for (size_t i = 0; i < array->count; i++) {
        if (array->data[i].ueId == ueId) {
            // Update existing record
            array->data[i].mobilityState = mobilityState;
            memcpy(array->data[i].measurementReports, measurementReports, sizeof(MeasurementReport) * numMeasurements);
            pthread_mutex_unlock(&array->mutex);
            return;
        }
    }
    // Add new record
    if (array->count == array->capacity) {
        // Expand capacity by 25%
        size_t newCapacity = array->capacity * 1.25;
        UEStatusRecord* newData = malloc(sizeof(UEStatusRecord) * newCapacity);
        memcpy(newData, array->data, sizeof(UEStatusRecord) * array->count);
        free(array->data);
        array->data = newData;
        array->capacity = newCapacity;
    }
    UEStatusRecord record;
    record.ueId = ueId;
    memcpy(record.measurementReports, measurementReports, sizeof(MeasurementReport) * numMeasurements);
    record.mobilityState = mobilityState;
    array->data[array->count++] = record;
    pthread_mutex_unlock(&array->mutex);
}

// Function to periodically clean up expired records based on a defined time-to-live policy
void cleanupExpiredRecords(UEDynamicArray* array) {
    // Remove all records that have expired according to the TTL policy
    pthread_mutex_lock(&array->mutex);
    size_t i = 0;
    while (i < array->count) {
        if (timeToLive(array->data[i].ueId) <= 0) {
            UEStatusRecord record = array->data[i];
            memcpy(&array->data[i], &array->data[--array->count], sizeof(UEStatusRecord));
            free(record.measurementReports); // Free measurement reports
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

// Function to integrate with an external logging system to log all changes made to UE status records
void logChanges(UEDynamicArray* array) {
    // Log all changes made to the UE status records
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; i++) {
        UEStatusRecord record = array->data[i];
        logChange(record.ueId, record.measurementReports, sizeof(MeasurementReport) * numMeasurements, record.mobilityState);
    }
    pthread_mutex_unlock(&array->mutex);
}

