// Define the MAC_PDU_T structure
typedef struct mac_pdu {
    char *pdcp_pdu;
    float snr;
} MAC_PDU_T;

// Define the array of MAC_PDU_T structures
MAC_PDU_T* pdu_array = NULL;
size_t pdu_count = 0;

// Define the SNR threshold for filtering invalid PDUs
float snr_threshold = 5.0;

void populate_pdu_array(FILE *file) {
    // Read the input file and store the data in a temporary array
    char line[1024];
    size_t line_count = 0;
    while (fgets(line, sizeof(line), file)) {
        line_count++;
        MAC_PDU_T pdu;
        sscanf(line, "%s %f", &pdu.pdcp_pdu, &pdu.snr);
        if (pdu.snr > snr_threshold) {
            // Add the valid PDU to the array
            pdu_array = realloc(pdu_array, (pdu_count + 1) * sizeof(MAC_PDU_T));
            pdu_array[pdu_count] = pdu;
            pdu_count++;
        } else {
            // Ignore the invalid PDU
            continue;
        }
    }
}

void filter_pdu_array(float snr_threshold) {
    // Iterate over the array and filter out any PDUs with SNR below the threshold
    for (size_t i = 0; i < pdu_count; i++) {
        if (pdu_array[i].snr < snr_threshold) {
            // Shift all subsequent PDUs in the array to fill the gap
            memmove(&pdu_array[i], &pdu_array[i + 1], sizeof(MAC_PDU_T) * (pdu_count - i));
            pdu_count--;
            i--;
        }
    }
}

void free_pdu_array() {
    // Free the memory allocated to the array
    free(pdu_array);
    pdu_array = NULL;
    pdu_count = 0;
}
```
