// Structure to represent a user record
typedef struct {
    int key;
    int value;
    char* id;
} UserRecord;

// Thread-safe data structure to store the user records
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static UserRecord** user_records = NULL;
static size_t num_user_records = 0;

// Function to allocate and initialize a new user record
UserRecord* alloc_and_init_user_record(int key, int value, char* id) {
    // Allocate memory for the new user record
    UserRecord* new_record = (UserRecord*) malloc(sizeof(UserRecord));
    if (!new_record) {
        return NULL;
    }

    // Initialize the key, value, and ID fields of the new record
    new_record->key = key;
    new_record->value = value;
    new_record->id = strdup(id);
    if (!new_record->id) {
        free(new_record);
        return NULL;
    }

    // Return the new record
    return new_record;
}

// Function to add a new user record to the collection
void add_user_record(int key, int value, char* id) {
    UserRecord* new_record = alloc_and_init_user_record(key, value, id);
    if (!new_record) {
        return;
    }

    // Acquire the lock to protect the user records collection
    pthread_mutex_lock(&mutex);

    // Allocate memory for the new record and add it to the collection
    UserRecord** new_records = (UserRecord**) realloc(user_records, (num_user_records + 1) * sizeof(UserRecord*));
    if (!new_records) {
        free(new_record);
        pthread_mutex_unlock(&mutex);
        return;
    }
    user_records = new_records;
    user_records[num_user_records] = new_record;
    num_user_records++;

    // Release the lock and return
    pthread_mutex_unlock(&mutex);
}

// Function to remove a user record from the collection
void remove_user_record(int key) {
    // Acquire the lock to protect the user records collection
    pthread_mutex_lock(&mutex);

    // Find the index of the record with the given key
    size_t idx = 0;
    for (size_t i = 0; i < num_user_records; i++) {
        if (user_records[i]->key == key) {
            idx = i;
            break;
        }
    }

    // If the record was found, remove it from the collection and free its memory
    if (idx != 0) {
        UserRecord* old_record = user_records[idx];
        user_records[idx] = user_records[num_user_records - 1];
        num_user_records--;
        free(old_record->id);
        free(old_record);
    }

    // Release the lock and return
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a user record from the collection
UserRecord* get_user_record(int key) {
    // Acquire the lock to protect the user records collection
    pthread_mutex_lock(&mutex);

    // Find the index of the record with the given key
    size_t idx = 0;
    for (size_t i = 0; i < num_user_records; i++) {
        if (user_records[i]->key == key) {
            idx = i;
            break;
        }
    }

    // If the record was found, return a copy of it and release the lock
    if (idx != 0) {
        UserRecord* record = user_records[idx];
        pthread_mutex_unlock(&mutex);
        return record;
    } else {
        // If the record was not found, return NULL and release the lock
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
}
