#include "nfapi_crc_indication_pdu.h" // header file for NFAPI_CRC_INDICATION_PDU_T structure

// Define a cache for storing the CRC indications
typedef struct {
  int num_entries; // number of entries in the cache
  int capacity; // maximum capacity of the cache
  bool* is_full; // array indicating whether each entry is full or not
  NFAPI_CRC_INDICATION_PDU_T** entries; // array of pointers to CRC indication structures
} crc_cache_t;

// Initialize the cache with a specified capacity and number of entries
void init_crc_cache(crc_cache_t* cache, int capacity, int num_entries) {
  if (capacity < 1 || num_entries < 1) {
    printf("Error: invalid input parameters\n");
    return;
  }
  cache->num_entries = num_entries;
  cache->capacity = capacity;
  cache->is_full = calloc(cache->num_entries, sizeof(bool));
  cache->entries = calloc(cache->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
}

// Add a new CRC indication to the cache if it is not already present
void add_crc_indication(crc_cache_t* cache, NFAPI_CRC_INDICATION_PDU_T* crc_ind) {
  // Check if the cache is full
  if (cache->num_entries >= cache->capacity) {
    printf("Error: cache is full\n");
    return;
  }

  // Check if the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG of the new crc_ind are already present in the cache
  bool found = false;
  for (int i = 0; i < cache->num_entries; i++) {
    if (cache->is_full[i] == true) continue;
    NFAPI_CRC_INDICATION_PDU_T* entry = cache->entries[i];
    if (entry->RX_UE_INFORMATION_TAG == crc_ind->RX_UE_INFORMATION_TAG &&
        entry->RNTI == crc_ind->RNTI &&
        entry->CRC_INDICATION_REL8_TAG == crc_ind->CRC_INDICATION_REL8_TAG) {
      found = true;
      break;
    }
  }

  // If the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG are not present in the cache, add a new entry
  if (!found) {
    int index = -1;
    for (int i = 0; i < cache->num_entries; i++) {
      if (cache->is_full[i] == false) {
        index = i;
        break;
      }
    }
    if (index != -1) {
      cache->entries[index] = crc_ind;
      cache->is_full[index] = true;
      printf("CRC indication added to cache\n");
    } else {
      printf("Error: cache is full and cannot add new entry\n");
    }
  }
}

// Retrieve a CRC indication from the cache based on the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG of the crc_ind parameter
NFAPI_CRC_INDICATION_PDU_T* get_crc_indication(crc_cache_t* cache, NFAPI_CRC_INDICATION_PDU_T* crc_ind) {
  // Check if the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG of the new crc_ind are already present in the cache
  for (int i = 0; i < cache->num_entries; i++) {
    if (cache->is_full[i] == true) continue;
    NFAPI_CRC_INDICATION_PDU_T* entry = cache->entries[i];
    if (entry->RX_UE_INFORMATION_TAG == crc_ind->RX_UE_INFORMATION_TAG &&
        entry->RNTI == crc_ind->RNTI &&
        entry->CRC_INDICATION_REL8_TAG == crc_ind->CRC_INDICATION_REL8_TAG) {
      return entry;
    }
  }
  return NULL;
}

// Clear the cache and release all memory allocated to it
void clear_crc_cache(crc_cache_t* cache) {
  free(cache->is_full);
  for (int i = 0; i < cache->num_entries; i++) {
    if (cache->is_full[i] == true) free(cache->entries[i]);
  }
  free(cache->entries);
}
