#include <openssl/evp.h>
#include <string>
#include <vector>
#include <unordered_set>
#include <cstdio>
#include <cstdlib>

std::string readFile(const char* filename, const int& config_param, const std::string& ext_mod) {
  // Open the file using fs library
  FILE* fp = fopen(filename, "r");
  if (fp == NULL) {
    return "";
  }

  // Read the file contents into a string
  char buffer[1024];
  std::string content;
  while (!feof(fp)) {
    size_t read = fread(buffer, 1, sizeof(buffer), fp);
    content.append(buffer, read);
  }
  fclose(fp);

  // Modify the file extension based on specific rules derived from the filename's characters
  std::string new_ext;
  if (config_param == 0) {
    new_ext = ext_mod;
  } else {
    int digits = 1;
    while (digits <= config_param) {
      digits *= 10;
    }
    int num = std::atoi(filename + strlen(filename) - digits);
    new_ext = ext_mod + std::to_string(num);
  }

  // Use AES, Camellia block ciphers, MD5, SHA digests, and RSA with SHA1 to manage these securely without compromising the application's performance or resource usage
  EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
  EVP_EncryptInit(ctx, EVP_aes_256_cbc(), NULL, NULL);
  std::vector<unsigned char> key(EVP_MAX_KEY_LENGTH);
  RAND_bytes(key.data(), key.size());
  EVP_CIPHER_CTX_set_key_length(ctx, key.size());
  EVP_EncryptInit(ctx, NULL, key.data(), NULL);
  EVP_DigestUpdate(ctx, content.c_str(), content.size());
  std::vector<unsigned char> digest(EVP_MAX_MD_SIZE);
  unsigned int length = 0;
  EVP_DigestFinal(ctx, digest.data(), &length);
  EVP_CIPHER_CTX_free(ctx);

  // Modify the file name to include the new extension
  std::string modified_filename = filename + "." + new_ext;

  return content;
}
