// Structure to hold information about a single Layer 3 PDU header
typedef struct {
    unsigned char *data;
    size_t data_len;
} pdu_header_t;

// Function to initialize a network interface and set up a list of Layer 3 PDU headers
int configureNetworkInterface(size_t min_pkt_size, size_t max_pkt_size, size_t num_pdus, int seed) {
    // Initialize variables for tracking progress
    size_t total_bytes = 0;
    size_t bytes_allocated = 0;
    int ret = 0;

    // Set up a random number generator using the given seed value
    srand(seed);

    // Loop over each PDU and generate its contents
    for (size_t i = 0; i < num_pdus; ++i) {
        // Generate a random IP address for the source and destination of this PDU
        char src_ip[16];
        char dst_ip[16];
        generateIPAddress(src_ip, dst_ip);

        // Determine the size of this PDU based on the minimum and maximum packet sizes
        size_t pkt_size = rand() % (max_pkt_size - min_pkt_size) + min_pkt_size;

        // Allocate memory for the PDU header and set its contents
        ret = allocatePduHeader(src_ip, dst_ip, pkt_size);
        if (ret != 0) {
            break;
        }

        // Update the total bytes allocated and the number of PDUs successfully configured
        total_bytes += pkt_size;
        ++i;
    }

    // Log detailed initialization information, including the name of the module being configured, the number of PDUs processed, and any relevant error codes
    logInitializeInformation(total_bytes, i, ret);

    return ret;
}

// Function to generate a random IP address for use in a Layer 3 PDU header
void generateIPAddress(char *src_ip, char *dst_ip) {
    // Generate a random number between 0 and 255 for each octet of the IP address
    unsigned char src_octet1 = rand() % 256;
    unsigned char src_octet2 = rand() % 256;
    unsigned char src_octet3 = rand() % 256;
    unsigned char dst_octet1 = rand() % 256;
    unsigned char dst_octet2 = rand() % 256;
    unsigned char dst_octet3 = rand() % 256;

    // Format the IP addresses as strings
    snprintf(src_ip, 16, "%u.%u.%u.%u", src_octet1, src_octet2, src_octet3);
    snprintf(dst_ip, 16, "%u.%u.%u.%u", dst_octet1, dst_octet2, dst_octet3);
}

// Function to allocate memory for a single Layer 3 PDU header and set its contents
int allocatePduHeader(const char *src_ip, const char *dst_ip, size_t pkt_size) {
    // Allocate memory for the PDU header
    pdu_header_t *pdu = malloc(sizeof(pdu_header_t));
    if (pdu == NULL) {
        return -1;
    }

    // Set the size of the data buffer and allocate memory for it
    pdu->data_len = pkt_size;
    pdu->data = malloc(pkt_size);
    if (pdu->data == NULL) {
        free(pdu);
        return -1;
    }

    // Fill the data buffer with random data
    for (size_t i = 0; i < pkt_size; ++i) {
        pdu->data[i] = rand() % UCHAR_MAX;
    }

    return 0;
}

// Function to log detailed initialization information, including the name of the module being configured, the number of PDUs processed, and any relevant error codes
void logInitializeInformation(size_t total_bytes, size_t num_pdus, int ret) {
    // Log the name of the module being configured and the number of PDUs processed
    printf("configureNetworkInterface: Initializing network interface with %zu PDUs (%zu bytes)\n", num_pdus, total_bytes);

    // Log any relevant error codes
    if (ret != 0) {
        printf("configureNetworkInterface: Failed to initialize network interface (error code %d)\n", ret);
    }
}
