void initialize_log() {
    // Initialize mutex lock for thread safety
    pthread_mutex_init(&log_lock, NULL);

    // Allocate memory for the log entries and set to NULL
    log_entries = (CellularNetworkEventLogEntry*)malloc(sizeof(CellularNetworkEventLogEntry) * MAX_NUM_LOG_ENTRIES);
    memset(log_entries, 0, sizeof(CellularNetworkEventLogEntry) * MAX_NUM_LOG_ENTRIES);
}

void add_log_entry(long long timestamp, int cell_id, int signal_strength, UserEquipment* ues, int num_ues) {
    // Acquire mutex lock for thread safety
    pthread_mutex_lock(&log_lock);

    // Check if log entries are full and need to be resized
    if (num_log_entries >= MAX_NUM_LOG_ENTRIES) {
        CellularNetworkEventLogEntry* new_entries = (CellularNetworkEventLogEntry*)realloc(log_entries, sizeof(CellularNetworkEventLogEntry) * 2 * num_log_entries);
        if (new_entries == NULL) {
            // Reallocation failed, handle error
        } else {
            log_entries = new_entries;
        }
    }

    // Add new log entry to the array
    int index = num_log_entries++;
    log_entries[index].timestamp = timestamp;
    log_entries[index].cell_id = cell_id;
    log_entries[index].signal_strength = signal_strength;
    log_entries[index].num_ues = num_ues;
    memcpy(log_entries[index].ues, ues, sizeof(UserEquipment) * num_ues);

    // Release mutex lock
    pthread_mutex_unlock(&log_lock);
}

void search_log_entry(int cell_id, int rrc_state, int qos_param[NUM_QOS_PARAMS]) {
    // Acquire mutex lock for thread safety
