    // Iterate through log entries and search for matching UE IDs
    for (int i = 0; i < num_log_entries; i++) {
        if (log_entries[i].cell_id == cell_id && log_entries[i].num_ues > 0) {
            for (int j = 0; j < log_entries[i].num_ues; j++) {
                UserEquipment* ue = &(log_entries[i].ues[j]);
                if (ue->rrc_state == rrc_state && memcmp(ue->qos_params, qos_param, sizeof(int) * NUM_QOS_PARAMS) == 0) {
                    // Found matching UE with RRC state and QoS parameters, print its ID
                    printf("Matching UE found: ID %d\n", ue->ue_id);
                }
            }
        }
    }

    // Release mutex lock
    pthread_mutex_unlock(&log_lock);
}
