// Structure to represent a single log entry
typedef struct CellularNetworkEventLogEntry {
    time_t timestamp;
    int cellId;
    int signalStrength;
    int numActiveUes;
    int* ueIds;
    int* rrcStates;
    int* qosParams;
    char* diagnosticSummary;
} CellularNetworkEventLogEntry;

// Function to initialize and populate a dynamic array of CellularNetworkEventLogEntry structures
void initCellularNetworkEventLog(int numEntries, int maxNumActiveUes, char* logFilePath) {
    // Allocate memory for the dynamic array of entries
    CellularNetworkEventLogEntry** logEntries = (CellularNetworkEventLogEntry**)malloc(sizeof(CellularNetworkEventLogEntry*) * numEntries);
    if (!logEntries) {
        fprintf(stderr, "Failed to allocate memory for cellular network event log\n");
        return;
    }

    // Initialize the array of entries with empty structs
    for (int i = 0; i < numEntries; i++) {
        logEntries[i] = (CellularNetworkEventLogEntry*)malloc(sizeof(CellularNetworkEventLogEntry));
        if (!logEntries[i]) {
            fprintf(stderr, "Failed to allocate memory for cellular network event log entry %d\n", i);
            return;
        }
    }

    // Initialize the timestamp of each entry with the current time
    for (int i = 0; i < numEntries; i++) {
        logEntries[i]->timestamp = time(NULL);
    }

    // Allocate memory for the arrays of UE IDs, RRC states, and QoS parameters
    int* ueIds = (int*)malloc(sizeof(int) * maxNumActiveUes * numEntries);
    if (!ueIds) {
        fprintf(stderr, "Failed to allocate memory for UE IDs\n");
        return;
    }
    int* rrcStates = (int*)malloc(sizeof(int) * maxNumActiveUes * numEntries);
    if (!rrcStates) {
        fprintf(stderr, "Failed to allocate memory for RRC states\n");
        return;
    }
    int* qosParams = (int*)malloc(sizeof(int) * maxNumActiveUes * numEntries);
    if (!qosParams) {
        fprintf(stderr, "Failed to allocate memory for QoS parameters\n");
        return;
    }

    // Initialize the arrays of UE IDs, RRC states, and QoS parameters with default values
    for (int i = 0; i < maxNumActiveUes * numEntries; i++) {
        ueIds[i] = -1;
        rrcStates[i] = -1;
        qosParams[i] = -1;
    }

    // Initialize the diagnostic summary of each entry with a default value
    for (int i = 0; i < numEntries; i++) {
        logEntries[i]->diagnosticSummary = "None";
    }

    // Open the log file in append mode
    FILE* fp = fopen(logFilePath, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s\n", logFilePath);
        return;
    }

    // Write the header of the log file with the column names
    char* header = "timestamp,cellId,signalStrength,numActiveUes,ueIds,rrcStates,qosParams,diagnosticSummary\n";
    fwrite(header, 1, strlen(header), fp);

    // Write each log entry to the file
    for (int i = 0; i < numEntries; i++) {
        char* line = malloc(sizeof(char) * 256);
        if (!line) {
            fprintf(stderr, "Failed to allocate memory for log line\n");
            return;
        }
        sprintf(line, "%ld,%d,%d,%d", logEntries[i]->timestamp, logEntries[i]->cellId, logEntries[i]->signalStrength, logEntries[i]->numActiveUes);
        for (int j = 0; j < logEntries[i]->numActiveUes; j++) {
            sprintf(line + strlen(line), ",%d,%d,%d", ueIds[j], rrcStates[j], qosParams[j]);
        }
        sprintf(line + strlen(line), ",%s\n", logEntries[i]->diagnosticSummary);
        fwrite(line, 1, strlen(line), fp);
    }

    // Close the log file
    fclose(fp);
}
