#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>

// CellularNetworkEventLogEntry structure for logging network events
typedef struct {
    time_t timestamp; // Timestamp of the event
    int cellID; // ID of the cell where the event occurred
    int signalStrength; // Signal strength at the time of the event (in dBm)
    char *ueList[MAX_UE_COUNT]; // List of active User Equipment (UE) IDs with their respective RRC states and QoS parameters
} CellularNetworkEventLogEntry;

// Memory pool for dynamic allocation of CellularNetworkEventLogEntry structures
struct MemoryPool {
    CellularNetworkEventLogEntry *pool;
    int size; // Current size of the memory pool (in elements)
    sem_t semaphore; // Semaphore for protecting concurrent access to the memory pool
};

// Initialize and populate a dynamic array of CellularNetworkEventLogEntry structures
void initCellularNetworkEventLog(struct MemoryPool *pool) {
    pthread_mutex_lock(&pool->semaphore);
    if (pool->size == 0) {
        pool->pool = malloc(sizeof(CellularNetworkEventLogEntry) * INITIAL_POOL_SIZE);
        memset(pool->pool, 0, sizeof(CellularNetworkEventLogEntry) * INITIAL_POOL_SIZE);
        pool->size = INITIAL_POOL_SIZE;
    }
    pthread_mutex_unlock(&pool->semaphore);
}

// Add a new log entry to the dynamic array
void addCellularNetworkEventLogEntry(struct MemoryPool *pool, time_t timestamp, int cellID, int signalStrength, char *ueList[MAX_UE_COUNT]) {
    pthread_mutex_lock(&pool->semaphore);
    if (pool->size == 0) {
        initCellularNetworkEventLog(pool);
    }

    // Check for invalid UE IDs or missing QoS parameters and handle them gracefully
    for (int i = 0; i < MAX_UE_COUNT; i++) {
        if (ueList[i] == NULL) {
            continue;
        }

        int ueID = atoi(ueList[i]);
        if (ueID <= 0) {
            printf("Invalid UE ID: %d\n", ueID);
            free(pool->pool[pool->size - 1].ueList[i]);
            pool->pool[pool->size - 1].ueList[i] = NULL;
        } else {
            // Get the RRC state and QoS parameters for the UE ID
            char *rrcState = getRRCState(ueID);
            char *qosParams = getQoSParams(ueID);

            // Update the log entry with the retrieved information
            pool->pool[pool->size - 1].ueList[i] = malloc(sizeof(char) * (strlen(rrcState) + strlen(qosParams) + 2));
            sprintf(pool->pool[pool->size - 1].ueList[i], "%s:%s", rrcState, qosParams);
        }
    }

    // Update the log entry with the new information
    pool->pool[pool->size - 1].timestamp = timestamp;
    pool->pool[pool->size - 1].cellID = cellID;
    pool->pool[pool->size - 1].signalStrength = signalStrength;

    // Increment the size of the memory pool if necessary
    if (pool->size == pool->size) {
        pool->size++;
        pool->pool = realloc(pool->pool, sizeof(CellularNetworkEventLogEntry) * pool->size);
    }

    pthread_mutex_unlock(&pool->semaphore);
}

// Search for a specific UE in the log entries and return its RRC state and QoS parameters if found
char *searchCellularNetworkEventLog(struct MemoryPool *pool, int ueID) {
    pthread_mutex_lock(&pool->semaphore);

    // Check for invalid UE IDs or missing QoS parameters and handle them gracefully
    if (ueID <= 0) {
        printf("Invalid UE ID: %d\n", ueID);
        pthread_mutex_unlock(&pool->semaphore);
        return NULL;
    }

    // Search for the UE in the log entries
    for (int i = 0; i < pool->size; i++) {
        if (strcmp(pool->pool[i].ueList[UE_ID], ueID) == 0) {
            char *rrcState = strtok(pool->pool[i].ueList[UE_ID], ":");
            char *qosParams = strtok(NULL, ":");

