struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG *rxUeInformation;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8;
};

struct NFAPI_CRC_INDICATION_PDU_T *createAndPopulateNfapiCrcIndicationPdu(int numUes, int numRxAntennas) {
    struct NFAPI_CRC_INDICATION_PDU_T *crcIndicationPdu = malloc(numUes * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (!crcIndicationPdu) {
        printf("Failed to allocate memory for crc indication pdu\n");
        return NULL;
    }

    // Initialize each UE's RX information and CRC indication rel8 tag
    for (int i = 0; i < numUes; i++) {
        crcIndicationPdu[i].rxUeInformation = malloc(numRxAntennas * sizeof(RX_UE_INFORMATION_TAG));
        if (!crcIndicationPdu[i].rxUeInformation) {
            printf("Failed to allocate memory for rx ue information\n");
            return NULL;
        }
        crcIndicationPdu[i].rnti = malloc(sizeof(RNTI));
        if (!crcIndicationPdu[i].rnti) {
            printf("Failed to allocate memory for rnti\n");
            return NULL;
        }
        crcIndicationPdu[i].crcIndicationRel8.crflag = 0; // Initialize CR flag to false
    }

    // Set the CR flag based on received signal strength indicators (RSSIs) from connected UEs
    for (int i = 0; i < numUes; i++) {
        if (RSSI_THRESHOLD > RxUeInformation[i].rssi) {
            crcIndicationPdu[i].crcIndicationRel8.crflag = 1; // Set CR flag to true if RSSI is above threshold
        }
    }

    return crcIndicationPdu;
}

// ECB encryption mode
void encryptEcb(struct NFAPI_CRC_INDICATION_PDU_T *crcIndicationPdu, int numUes) {
    for (int i = 0; i < numUes; i++) {
        EVP_CIPHER_CTX *ctx;
        unsigned char key[8]; // DES key size is 64 bits
        memcpy(key, crcIndicationPdu[i].rxUeInformation->rnti, 8); // Use RNTI as encryption key
        if (!EVP_EncryptInit_ex(ctx, EVP_des_ecb(), NULL, key, NULL)) {
            printf("Failed to initialize ECB encryption\n");
            return;
        }
        unsigned char *ciphertext = malloc(sizeof(unsigned char) * 8); // Ciphertext size is 64 bits
        if (!ciphertext) {
            printf("Failed to allocate memory for ciphertext\n");
            return;
        }
        EVP_CIPHER_CTX_set_padding(ctx, 0); // Disable padding to match RRC message size
        int len = EVP_EncryptUpdate(ctx, ciphertext, 8, key, 8);
        if (len != 8) {
            printf("Failed to encrypt RNTI with ECB\n");
            return;
        }
        memcpy(crcIndicationPdu[i].rxUeInformation->rnti, ciphertext, 8); // Replace RNTI with encrypted value
    }
}

// EDE encryption mode
void encryptEde(struct NFAPI_CRC_INDICATION_PDU_T *crcIndicationPdu, int numUes) {
    for (int i = 0; i < numUes; i++) {
        EVP_CIPHER_CTX *ctx;
        unsigned char key[16]; // DES3 key size is 192 bits
        memcpy(key, crcIndicationPdu[i].rxUeInformation->rnti, 16); // Use RNTI as encryption key
        if (!EVP_EncryptInit_ex(ctx, EVP_des_ede3(), NULL, key, NULL)) {
            printf("Failed to initialize EDE encryption\n");
            return;
        }
        unsigned char *ciphertext = malloc(sizeof(unsigned char) * 16); // Ciphertext size is 192 bits
        if (!ciphertext) {
            printf("Failed to allocate memory for ciphertext\n");
            return;
        }
        EVP_CIPHER_CTX_set_padding(ctx, 0); // Disable padding to match RRC message size
        int len = EVP_EncryptUpdate(ctx, ciphertext, 16, key, 16);
        if (len != 16) {
            printf("Failed to encrypt RNTI with EDE\n");
            return;
        }
        memcpy(crcIndicationPdu[i].rxUeInformation->rnti, ciphertext, 16); // Replace RNTI with encrypted value
    }
}

// CFB encryption mode
void encryptCfb(struct NFAPI_CRC_INDICATION_PDU_T *crcIndicationPdu, int numUes) {
    for (int i = 0; i < numUes; i++) {
        EVP_CIPHER_CTX *ctx;
        unsigned char key[8]; // DES key size is 64 bits
        memcpy(key, crcIndicationPdu[i].rxUeInformation->rnti, 8); // Use RNTI as encryption key
        if (!EVP_EncryptInit_ex(ctx, EVP_des_cfb(), NULL, key, NULL)) {
            printf("Failed to initialize CFB encryption\n");
            return;
        }
        unsigned char *ciphertext = malloc(sizeof(unsigned char) * 8); // Ciphertext size is 64 bits
        if (!ciphertext) {
            printf("Failed to allocate memory for ciphertext\n");
            return;
        }
        EVP_CIPHER_CTX_set_padding(ctx, 0); // Disable padding to match RRC message size
        int len = EVP_EncryptUpdate(ctx, ciphertext, 8, key, 8);
        if (len != 8) {
            printf("Failed to encrypt RNTI with CFB\n");
            return;
        }
        memcpy(crcIndicationPdu[i].rxUeInformation->rnti, ciphertext, 8); // Replace RNTI with encrypted value
    }
}

// NULL encryption mode
void encryptNull(struct NFAPI_CRC_INDICATION_T *crcIndication) {
    crcIndication->rxUeInformation->rnti = NULL; // Set RNTI to NULL
}

int main() {
    int numUes = 10; // Number of UEs in the system
    struct NFAPI_CRC_INDICATION_T *crcIndication = malloc(sizeof(struct NFAPI_CRC_INDICATION_T) * numUes); // Allocate memory for CRC indication messages
    if (!crcIndication) {
        printf("Failed to allocate memory for CRC indication\n");
        return -1;
    }
    for (int i = 0; i < numUes; i++) {
        memcpy(crcIndication[i].rxUeInformation->rnti, "rnti", 4); // Initialize RNTI field
    }
    // Encrypt RNTIs using different encryption modes
    encryptNull(crcIndication[0]);
    encryptEcb(crcIndication + 1);
    encryptEde(crcIndication + 2);
    encryptCfb(crcIndication + 3);
    // Print encrypted RNTIs
    for (int i = 0; i < numUes; i++) {
        printf("Encrypted RNTI: %s\n", crcIndication[i].rxUeInformation->rnti);
    }
    return 0;
}
