// Define the structure for a data transfer record
typedef struct {
    int transactionId;
    int dataSize;
    char *data;
} NFDataTransferRecord;

// Define the array of records
NFDataTransferRecord *records = NULL;
int numRecords = 0;
int maxNumRecords = 1000;

// Function to add a new record to the array
void addNewRecord(int transactionId, int dataSize, char *data) {
    // Check if the array is full
    if (numRecords == maxNumRecords) {
        // Double the size of the array
        NFDataTransferRecord *tmp = realloc(records, 2 * maxNumRecords * sizeof(NFDataTransferRecord));
        if (tmp != NULL) {
            records = tmp;
            maxNumRecords *= 2;
        } else {
            // Reallocation failed, abort
            fprintf(stderr, "Error: failed to allocate memory for new record\n");
            return;
        }
    }

    // Add the new record
    records[numRecords].transactionId = transactionId;
    records[numRecords].dataSize = dataSize;
    records[numRecords].data = data;
    numRecords++;
}

// Function to update an existing record in the array by transaction ID
void updateRecordByTransactionId(int transactionId, int dataSize, char *data) {
    // Find the index of the record with the given transaction ID
    int i = 0;
    for (i = 0; i < numRecords; i++) {
        if (records[i].transactionId == transactionId) {
            break;
        }
    }

    // Check if the record was found
    if (i == numRecords) {
        fprintf(stderr, "Error: no record with transaction ID %d found\n", transactionId);
        return;
    }

    // Update the record
    records[i].dataSize = dataSize;
    records[i].data = data;
}

// Function to retrieve all records within a specified data size range
void getRecordsByDataSizeRange(int lowerBound, int upperBound) {
    // Iterate over the records and print them if they are within the specified range
    for (int i = 0; i < numRecords; i++) {
        if (records[i].dataSize >= lowerBound && records[i].dataSize <= upperBound) {
            printf("Transaction ID: %d, Data size: %d\n", records[i].transactionId, records[i].dataSize);
        }
    }
}

// Function to persist the data to a file system for backup purposes
void saveDataToFile(const char *filename) {
    // Open the output file in binary mode
    FILE *out = fopen(filename, "wb");
    if (out == NULL) {
        fprintf(stderr, "Error: failed to open output file %s\n", filename);
        return;
    }

    // Write the data to the file
    for (int i = 0; i < numRecords; i++) {
        fwrite(&records[i].transactionId, sizeof(int), 1, out);
        fwrite(&records[i].dataSize, sizeof(int), 1, out);
        fwrite(records[i].data, records[i].dataSize, 1, out);
    }

    // Close the output file
    fclose(out);
}

// Function to load data from a file system for backup purposes
void loadDataFromFile(const char *filename) {
    // Open the input file in binary mode
    FILE *in = fopen(filename, "rb");
    if (in == NULL) {
        fprintf(stderr, "Error: failed to open input file %s\n", filename);
        return;
    }

    // Read the data from the file and add it to the array
    NFDataTransferRecord record;
    while (fread(&record.transactionId, sizeof(int), 1, in) == 1 &&
           fread(&record.dataSize, sizeof(int), 1, in) == 1 &&
           fread(record.data, record.dataSize, 1, in) == 1) {
        addNewRecord(record.transactionId, record.dataSize, record.data);
    }

    // Close the input file
    fclose(in);
}
