    bool garbageCollected;
} NFAPI_CRC_INDICATION_LIST_T;

// Create a new empty list
NFAPI_CRC_INDICATION_LIST_T *nfapi_crc_indication_list_new() {
    // Allocate memory for the list structure
    NFAPI_CRC_INDICATION_LIST_T *list = custom_malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        return NULL;
    }
    list->pduList = NULL;
    list->listSize = 0;
    list->currentCapacity = 0;
    list->memoryUsage = 0.0;
    list->garbageCollected = false;
    return list;
}

// Add a new PDU to the list
bool nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if the list is full or the memory usage has exceeded the threshold
    if (list->listSize == list->currentCapacity || list->memoryUsage >= MEMORY_THRESHOLD) {
        nfapi_crc_indication_list_garbage_collect(list);
    }
    // Allocate memory for the new PDU
    NFAPI_CRC_INDICATION_PDU_T *newPdu = custom_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newPdu) {
        return false;
