    // Copy the contents of the PDU into the new memory block
    memcpy(newPdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // Add the new PDU to the list
    list->pduList = realloc(list->pduList, (list->listSize + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list->pduList) {
        custom_free(newPdu);
        return false;
    }
    list->pduList[list->listSize++] = newPdu;
    // Update the memory usage and garbage collection flag
    list->memoryUsage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (list->memoryUsage >= MEMORY_THRESHOLD) {
        list->garbageCollected = true;
    }
    return true;
}

// Remove a PDU from the list by its index
bool nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST_T *list, int index) {
