    // Remove the PDU from the list and free its memory
    custom_free(list->pduList[index]);
    for (int i = index; i < list->listSize - 1; ++i) {
        list->pduList[i] = list->pduList[i + 1];
    }
    list->pduList = realloc(list->pduList, (list->listSize - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list->pduList) {
        return false;
    }
    --list->listSize;
    // Update the memory usage and garbage collection flag
    list->memoryUsage -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (list->memoryUsage < MEMORY_THRESHOLD && list->garbageCollected) {
        list->garbageCollected = false;
    }
    return true;
