// Add a new record to the array
void addNFDataTransferRecord(int transactionId, size_t dataSize, char *transferStatus) {
    // Check if the maximum number of records has been reached
    if (recordCount == maxRecordCount) {
        printf("Reached maximum allowed number of records: %zu\n", recordCount);
        return;
    }

    // Allocate memory for the new record
    NFDataTransferRecord *newRecord = malloc(sizeof(NFDataTransferRecord));
    if (newRecord == NULL) {
        printf("Failed to allocate memory for new record\n");
        return;
    }

    // Initialize the fields of the new record
    newRecord->transactionId = transactionId;
    newRecord->dataSize = dataSize;
    newRecord->transferStatus = transferStatus;

    // Add the new record to the end of the array
    recordArray[recordCount++] = newRecord;
}

// Update an existing record in the array by transaction ID
void updateNFDataTransferRecordByTransactionId(int transactionId, size_t dataSize, char *transferStatus) {
    // Find the index of the record with the given transaction ID
    int recordIndex = -1;
    for (size_t i = 0; i < recordCount; i++) {
        if (recordArray[i]->transactionId == transactionId) {
            recordIndex = i;
            break;
        }
    }

    // Check if the record with the given transaction ID was found
    if (recordIndex == -1) {
        printf("Record not found for transaction ID: %d\n", transactionId);
        return;
    }

    // Update the fields of the existing record
    NFDataTransferRecord *existingRecord = recordArray[recordIndex];
    existingRecord->dataSize = dataSize;
    existingRecord->transferStatus = transferStatus;
}

// Retrieve records from the array based on data size range
void retrieveNFDataTransferRecordsByRange(size_t minDataSize, size_t maxDataSize) {
    // Iterate through the records and print those with matching data sizes
    for (size_t i = 0; i < recordCount; i++) {
        NFDataTransferRecord *record = recordArray[i];
        if (record->dataSize >= minDataSize && record->dataSize <= maxDataSize) {
            printf("Transaction ID: %d, Data Size: %zu, Transfer Status: %s\n", record->transactionId, record->dataSize, record->transferStatus);
        }
    }
}

// Periodically compact the array by removing all records with a transfer status of "COMPLETED"
void compactNFDataTransferRecords() {
    // Iterate through the records and remove those with a transfer status of "COMPLETED"
    for (size_t i = 0; i < recordCount;) {
        NFDataTransferRecord *record = recordArray[i];
        if (strcmp(record->transferStatus, "COMPLETED") == 0) {
            // Remove the record from the array and free its memory
            free(record);
            recordCount--;
            memmove(&recordArray[i], &recordArray[i + 1], (recordCount - i) * sizeof(NFDataTransferRecord*));
        } else {
            i++;
        }
    }
}

