class DynamicArray {
public:
  DynamicArray(int size) : data_(new NFDataTransferRecord[size]), capacity_(size) {}
  ~DynamicArray() { delete[] data_; }

  void add(const NFDataTransferRecord& record) {
    std::lock_guard<std::mutex> guard(mtx_);
    // Check if the array is full
    if (size_ == capacity_) {
      resize();
    }
    data_[size_++] = record;
  }

  void update(uint64_t transactionId, const NFDataTransferRecord& record) {
    std::lock_guard<std::mutex> guard(mtx_);
    for (int i = 0; i < size_; ++i) {
      if (data_[i].transactionId == transactionId) {
        data_[i] = record;
        return;
      }
    }
  }

  vector<NFDataTransferRecord> retrieve(uint32_t minSize, uint32_t maxSize) {
    std::lock_guard<std::mutex> guard(mtx_);
    // Check if the array is empty
    if (size_ == 0) {
      return {};
    }
    // Find the first record with data size larger than minSize
    int start = -1;
    for (int i = 0; i < size_; ++i) {
      if (data_[i].dataSize >= minSize) {
        start = i;
        break;
      }
    }
    // Find the last record with data size smaller than maxSize
    int end = -1;
    for (int i = size_ - 1; i >= 0; --i) {
      if (data_[i].dataSize <= maxSize) {
        end = i;
        break;
      }
    }
    // If start or end is not found, return an empty vector
    if (start == -1 || end == -1) {
      return {};
    }
    // Return the records within the specified range
    return vector<NFDataTransferRecord>(data_ + start, data_ + end + 1);
  }

private:
  void resize() {
    std::lock_guard<std::mutex> guard(mtx_);
    // Double the capacity of the array
    capacity_ *= 2;
    NFDataTransferRecord* newData = new NFDataTransferRecord[capacity_];
    for (int i = 0; i < size_; ++i) {
      newData[i] = data_[i];
    }
    delete[] data_;
    data_ = newData;
  }

  NFDataTransferRecord* data_;
  int capacity_;
  atomic<int> size_{0};
  mutex mtx_;
};

class BackupManager {
public:
  BackupManager(const string& filename) : filename_(filename) {}

  void backup() {
    std::lock_guard<std::mutex> guard(mtx_);
    // Open the file for writing
    ofstream outfile(filename_, ios::out | ios::binary);
    if (!outfile.is_open()) {
      cerr << "Failed to open backup file: " << filename_ << endl;
      return;
