    outfile.close();
  }

  void restore() {
    std::lock_guard<std::mutex> guard(mtx_);
    // Open the file for reading
    ifstream infile(filename_, ios::in | ios::binary);
    if (!infile.is_open()) {
      cerr << "Failed to open backup file: " << filename_ << endl;
      return;
    }
    // Read the data structure from the file
    while (infile.good()) {
      NFDataTransferRecord record;
      infile.read((char*)&record, sizeof(record));
      if (infile.gcount() != 0) {
        add(record);
      }
    }
    infile.close();
  }

private:
  void add(const NFDataTransferRecord& record) {
    std::lock_guard<std::mutex> guard(mtx_);
    // Check if the array is full
    if (size_ == capacity_) {
      resize();
    }
    data_[size_++] = record;
  }

