    pthread_mutex_lock(&mutex);

    // Write the size of the array to the file
    if (fwrite(&arr->size, sizeof(size_t), 1, fp) != 1) {
        printf("Error: Failed to write size of dynamic array to file\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Write each element of the array to the file
    for (size_t i = 0; i < arr->size; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T* data = &arr->data[i];
        if (fwrite(data, sizeof(struct NFAPI_CRC_INDICATION_PDU_T), 1, fp) != 1) {
            printf("Error: Failed to write element %zu of dynamic array to file\n", i);
            pthread_mutex_unlock(&mutex);
            return -1;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Define a function for deserializing the dynamic array from a binary file
int deserializeDynamicArray(struct DynamicArray* arr, FILE* fp) {
    // Lock the mutex to protect the array from concurrent access
    pthread_mutex_lock(&mutex);

    // Read the size of the array from the file
    if (fread(&arr->size, sizeof(size_t), 1, fp) != 1) {
        printf("Error: Failed to read size of dynamic array from file\n");
        pthread_mutex_unlock(&mutex);
        return -1;
