        if (fread(data, sizeof(struct NFAPI_CRC_INDICATION_PDU_T), 1, fp) != 1) {
            printf("Error: Failed to read element %zu of dynamic array from file\n", i);
            pthread_mutex_unlock(&mutex);
            return -1;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Define a function for clearing the dynamic array
int clearDynamicArray(struct DynamicArray* arr) {
    // Lock the mutex to protect the array from concurrent access
    pthread_mutex_lock(&mutex);

    // Set the size of the array to 0
    arr->size = 0;

