#define MAX_FRAMES 1000

static NFAPI_MESSAGE_T* nfapi_messages = NULL;
static size_t num_frames = 0;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_nfapi_message(NFAPI_MESSAGE_T* message) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&lock);

    // Check if we need to resize the array
    if (num_frames >= MAX_FRAMES) {
        NFAPI_MESSAGE_T* new_messages = realloc(nfapi_messages, (num_frames + 1) * sizeof(NFAPI_MESSAGE_T));
        if (!new_messages) {
            printf("ERROR: Failed to allocate memory for NFAPI messages\n");
            pthread_mutex_unlock(&lock);
            return;
        }
        nfapi_messages = new_messages;
    }

    // Add the message to the array
    nfapi_messages[num_frames++] = *message;

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}

void remove_nfapi_message(size_t index) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&lock);

    // Check if the index is out of bounds
    if (index >= num_frames) {
        printf("ERROR: Index %zu is out of bounds\n", index);
        pthread_mutex_unlock(&lock);
        return;
    }

    // Shift the elements over to remove the message
    for (size_t i = index + 1; i < num_frames; i++) {
        nfapi_messages[i - 1] = nfapi_messages[i];
    }

    // Decrease the number of frames
    num_frames--;

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}

NFAPI_MESSAGE_T* get_nfapi_message(size_t index) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&lock);

    // Check if the index is out of bounds
    if (index >= num_frames) {
        printf("ERROR: Index %zu is out of bounds\n", index);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Return the message at the given index
    NFAPI_MESSAGE_T* message = &nfapi_messages[index];

    // Unlock the mutex
    pthread_mutex_unlock(&lock);

    return message;
}
