function updateClinicStatus($clinicId, $newStatus, $lastModifiedIp, $lastModifiedDate) {
    // Check if the clinic exists in the database
    $query = "SELECT COUNT(*) AS count FROM clinics WHERE id = :id";
    $stmt = $db->prepare($query);
    $stmt->bindValue(':id', $clinicId, PDO::PARAM_INT);
    $stmt->execute();
    $count = $stmt->fetch(PDO::FETCH_ASSOC)['count'];

