        $stmt = $db->prepare($query);
        $stmt->bindValue(':status', $newStatus, PDO::PARAM_STR);
        $stmt->bindValue(':last_modified_ip', $lastModifiedIp, PDO::PARAM_STR);
        $stmt->bindValue(':last_modified_date', $lastModifiedDate, PDO::PARAM_STR);
        $stmt->execute();

        // Return a success message if the update is successful
