function manageUserAccounts($request) {
    // Check if the request is valid
    $valid = true;
    foreach ($request as $key => $value) {
        if (!in_array($key, ['id', 'name', 'email', 'password', 'theme_id'])) {
            $valid = false;
            break;
        }
    }

    // If the request is not valid, return an error response
    if (!$valid) {
        return json_encode(['status' => 'error', 'message' => 'Invalid request']);
    }

    // Check if the user account already exists
    $id = $request['id'] ?? null;
    $user = User::find($id);
    if ($user) {
        // Update the user account
        $user->name = $request['name'];
        $user->email = $request['email'];
        $user->password = $request['password'];
        $user->theme_id = $request['theme_id'];
        $user->save();
    } else {
        // Create a new user account
        $user = new User;
        $user->name = $request['name'];
        $user->email = $request['email'];
        $user->password = $request['password'];
        $user->theme_id = $request['theme_id'];
        $user->save();
    }

    // Recycle the theme bitmap if necessary
    if ($user->theme_id) {
        $theme = Theme::find($user->theme_id);
        if ($theme && !$theme->bitmap) {
            $theme->bitmap = ThemeBitmap::create();
            $theme->save();
        }
    }

    // Ensure the default theme directory is properly configured
    $defaultTheme = Theme::where('is_default', true)->first();
    if (!$defaultTheme) {
        $defaultTheme = new Theme;
        $defaultTheme->name = 'Default';
        $defaultTheme->is_default = true;
        $defaultTheme->save();
    }

    // Handle deletion of the user account
    if ($request['sub_action'] === 'delete') {
        $user->delete();
        return json_encode(['status' => 'success', 'message' => 'User deleted']);
    }

    // Return a success response
    return json_encode(['status' => 'success', 'message' => 'User updated']);
}
