#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <pthread.h>
#include "nfapi_crc_indication_pdu_t.h" // Custom data structure for NFAPI CRC indications

// Struct to hold the dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    size_t capacity; // Total capacity of the array
    size_t count; // Current number of elements in the array
    pthread_mutex_t mutex; // Mutex for thread-safe access to the array
    NFAPI_CRC_INDICATION_PDU_T *array; // Dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
} NFAPI_CRC_INDICATION_DYNAMIC_ARRAY_T;

// Function to initialize the dynamic array
void nfapi_crc_indication_dynamic_array_init(NFAPI_CRC_INDICATION_DYNAMIC_ARRAY_T *array) {
    array->capacity = 0;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

// Function to add a new element to the dynamic array
void nfapi_crc_indication_dynamic_array_add(NFAPI_CRC_INDICATION_DYNAMIC_ARRAY_T *array, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&array->mutex);
    if (array->count == array->capacity) {
        // Double the capacity of the array if it is full
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            pthread_mutex_unlock(&array->mutex);
            return; // Abort if reallocation fails
        }
        array->capacity = new_capacity;
        array->array = new_array;
    }
    array->array[array->count++] = *pdu;
    pthread_mutex_unlock(&array->mutex);
}

// Function to remove an element from the dynamic array
void nfapi_crc_indication_dynamic_array_remove(NFAPI_CRC_INDICATION_DYNAMIC_ARRAY_T *array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index >= array->count) {
        // Abort if the index is out of bounds
        pthread_mutex_unlock(&array->mutex);
        return;
