        nfapi_crc_indication_array_resize(array, array->capacity * 2);
    }

    // Copy the element into the array
    memcpy(&array->data[array->size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Increment the size of the array
    ++array->size;

    // Unlock mutex
    pthread_mutex_unlock(&array->mutex);
}

// Function to reset all elements in the array to a default value
void nfapi_crc_indication_array_reset(NFAPI_CRC_INDICATION_PDU_ARRAY_T* array) {
    // Lock mutex to prevent concurrent access
    pthread_mutex_lock(&array->mutex);

    // Iterate over all elements in the array and reset their CRCFLAG to default value
    for (size_t i = 0; i < array->size; ++i) {
        array->data[i].crcflag = false;
