// Function to deallocate memory for the array
void nfapi_crc_indication_array_dealloc(NFAPI_CRC_INDICATION_PDU_ARRAY_T* array) {
    // Lock mutex to prevent concurrent access
    pthread_mutex_lock(&array->mutex);

    // Free the memory allocated for the array of structures
    free(array->data);

    // Set the capacity and size of the array to zero
