using System;
using UnityEngine;

public class RandomValueGenerator
{
    private float minValue;
    private float maxValue;

    public RandomValueGenerator(float minValue, float maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public override string ToString()
    {
        return $"Range[{minValue}..{maxValue}]";
    }

    public void ValidateRange(float minValue, float maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException($"Invalid range: {minValue} > {maxValue}");
    }

    public void SetRange(float minValue, float maxValue)
    {
        ValidateRange(minValue, maxValue);
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public int[] GenerateSamples(int count, bool generateInts)
    {
        if (count <= 0)
            throw new ArgumentException("Count must be a positive integer");

        var samples = new int[count];
        for (var i = 0; i < count; ++i)
        {
            samples[i] = generateInts ? GetRandomInt() : GetRandomFloat();
        }
        return samples;
    }

    public void LogSamples(int count, bool generateInts)
    {
        var samples = GenerateSamples(count, generateInts);
        for (var i = 0; i < samples.Length; ++i)
        {
            // Log each sample along with the current range parameters
            Console.WriteLine($"{samples[i]} (Range[{minValue}..{maxValue}])");
        }
    }

    public void HandleExternalDataSourceFailure(Exception exception)
    {
        // Handle external data source failure gracefully by continuing to operate without immediate failure
        Console.WriteLine("External data source failure: " + exception);
    }

    public void ThreadSafeGenerateSamples(int count, bool generateInts)
    {
        lock (this)
        {
            var samples = GenerateSamples(count, generateInts);
            for (var i = 0; i < samples.Length; ++i)
            {
                // Log each sample along with the current range parameters
                Console.WriteLine($"{samples[i]} (Range[{minValue}..{maxValue}])");
            }
        }
    }

    public void Serialize(BinaryWriter writer)
    {
        writer.Write(minValue);
        writer.Write(maxValue);
    }

    public void Deserialize(BinaryReader reader)
    {
        minValue = reader.ReadSingle();
        maxValue = reader.ReadSingle();
    }
}
