// Mutex for thread-safe access to the list
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Linked list of NFAPI_CRC_INDICATION_PDU_T structures
struct crc_indication_list {
    struct crc_indication_node *head;
    struct crc_indication_node *tail;
};

// Node in the linked list of NFAPI_CRC_INDICATION_PDU_T structures
struct crc_indication_node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct crc_indication_node *next;
};

// Add a new element to the list
void add_crc_indication(struct crc_indication_list *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Create a new node for the pdu
    struct crc_indication_node *new_node = malloc(sizeof(struct crc_indication_node));
    new_node->pdu = pdu;
    new_node->next = NULL;

    // Lock the list mutex to prevent concurrent access
    pthread_mutex_lock(&list_mutex);

    // If the list is empty, set the head and tail pointers
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        // Otherwise, add the node to the end of the list
        list->tail->next = new_node;
        list->tail = new_node;
    }

    // Unlock the list mutex
    pthread_mutex_unlock(&list_mutex);
}

// Update an element in the list based on RNTI
void update_crc_indication(struct crc_indication_list *list, uint16_t rnti) {
    // Lock the list mutex to prevent concurrent access
    pthread_mutex_lock(&list_mutex);

    // Find the node in the list with the matching RNTI
    struct crc_indication_node *cur = list->head;
    while (cur != NULL && cur->pdu.rnti != rnti) {
        cur = cur->next;
    }

    // If the node was found, update its CRC flag and unlock the mutex
    if (cur != NULL) {
        cur->pdu.crc_indication_rel8.crcflag = 1;
        pthread_mutex_unlock(&list_mutex);
    } else {
        // Otherwise, unlock the mutex and throw an error
        pthread_mutex_unlock(&list_mutex);
        fprintf(stderr, "RNTI %d not found in list\n", rnti);
    }
}

// Remove an element from the list based on RNTI
void remove_crc_indication(struct crc_indication_list *list, uint16_t rnti) {
    // Lock the list mutex to prevent concurrent access
    pthread_mutex_lock(&list_mutex);

    // Find the node in the list with the matching RNTI
    struct crc_indication_node *cur = list->head;
    while (cur != NULL && cur->pdu.rnti != rnti) {
        cur = cur->next;
    }

    // If the node was found, remove it from the list and free its memory
    if (cur != NULL) {
        struct crc_indication_node *prev = cur->next;
        free(cur);
        list->tail = prev;
        pthread_mutex_unlock(&list_mutex);
    } else {
        // Otherwise, unlock the mutex and throw an error
        pthread_mutex_unlock(&list_mutex);
        fprintf(stderr, "RNTI %d not found in list\n", rnti);
    }
}

// Serialize the list to a file
void serialize_crc_indication_list(struct crc_indication_list *list, char *filename) {
    // Open the file for writing
    FILE *f = fopen(filename, "wb");
    if (f == NULL) {
        perror("Error opening file");
        return;
    }

    // Lock the list mutex to prevent concurrent access
    pthread_mutex_lock(&list_mutex);

    // Write the number of elements in the list to the file
    size_t count = 0;
    struct crc_indication_node *cur = list->head;
    while (cur != NULL) {
        cur = cur->next;
        count++;
    }
    fwrite(&count, sizeof(size_t), 1, f);

    // Write each element of the list to the file
    cur = list->head;
    while (cur != NULL) {
        fwrite(&cur->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, f);
        cur = cur->next;
    }

    // Close the file and unlock the list mutex
    fclose(f);
    pthread_mutex_unlock(&list_mutex);
}

// Deserialize the list from a file
void deserialize_crc_indication_list(struct crc_indication_list *list, char *filename) {
    // Open the file for reading
    FILE *f = fopen(filename, "rb");
    if (f == NULL) {
        perror("Error opening file");
        return;
    }

    // Lock the list mutex to prevent concurrent access
    pthread_mutex_lock(&list_mutex);

    // Read the number of elements in the list from the file
    size_t count = 0;
    fread(&count, sizeof(size_t), 1, f);

    // Create a new node for each element in the list
    for (int i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, f);
        add_crc_indication(list, pdu);
    }

    // Close the file and unlock the list mutex
    fclose(f);
    pthread_mutex_unlock(&list_mutex);
}
