// Define a logging mechanism to track the creation and lifecycle of elements
#define LOGGING 1

#ifdef LOGGING
void logElementCreation(int RX_UE_INFORMATION_TAG, uint32_t RNTI, uint8_t CRCFLAG) {
    printf("Created element with RX_UE_INFORMATION_TAG: %d, RNTI: %u, CRCFLAG: %u\n", RX_UE_INFORMATION_TAG, RNTI, CRCFLAG);
}

void logElementDeletion(int RX_UE_INFORMATION_TAG) {
