}
#endif

// Define a function to add an element to the list
bool addElement(int RX_UE_INFORMATION_TAG, uint32_t RNTI, uint8_t CRCFLAG) {
    // Validate RNTI value
    if (RNTI < 0 || RNTI > 65535) {
        return false;
    }

    // Lock the list to prevent concurrent modifications
    pthread_mutex_lock(&elementList.mutex);

    // Check if the list is full
    if (elementList.count == MAX_ELEMENTS) {
        printf("Error: Element list is full\n");
        return false;
    }

    // Create a new element
    NFAPI_CRC_INDICATION_PDU_T* newElement = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newElement) {
        printf("Error: Failed to allocate memory for new element\n");
        return false;
    }

    // Initialize the element
    newElement->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newElement->RNTI = RNTI;
    newElement->CRCFLAG = CRCFLAG;

#ifdef LOGGING
    // Log the creation of the element
    logElementCreation(newElement->RX_UE_INFORMATION_TAG, newElement->RNTI, newElement->CRCFLAG);
#endif

    // Add the element to the list
    elementList.elements[elementList.count] = newElement;
    elementList.count++;

    // Unlock the list
    pthread_mutex_unlock(&elementList.mutex);

    return true;
}

// Define a function to delete an element from the list
bool deleteElement(int RX_UE_INFORMATION_TAG) {
    // Lock the list to prevent concurrent modifications
    pthread_mutex_lock(&elementList.mutex);

    // Find the index of the element to be deleted
    int i;
    for (i = 0; i < elementList.count; i++) {
        if (elementList.elements[i]->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            break;
        }
    }

    // Check if the element was found
    if (i == elementList.count) {
        printf("Error: Element with RX_UE_INFORMATION_TAG %d not found\n", RX_UE_INFORMATION_TAG);
        return false;
    }

    // Delete the element from the list
    free(elementList.elements[i]);
    elementList.count--;

    // Shift all elements after the deleted element
    for (int j = i; j < elementList.count; j++) {
        elementList.elements[j] = elementList.elements[j + 1];
    }

#ifdef LOGGING
    // Log the deletion of the element
    logElementDeletion(RX_UE_INFORMATION_TAG);
