// Initialize a new list with the given capacity
NFAPI_CRC_INDICATION_LIST_T* nfapi_crc_indication_list_init(size_t capacity) {
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) return NULL; // Error: out of memory

    list->capacity = capacity;
    list->size = 0;
    list->list = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list->list) { // Error: out of memory
