    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) { // List is full, allocate more memory
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T **new_list = realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!new_list) { // Error: out of memory
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    list->list[list->size++] = pdu;

    pthread_mutex_unlock(&list->lock);

    return true;
}

// Remove a PDU from the list by its index
bool nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST_T *list, size_t index) {
