    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *pdu = list->list[index];
    if (index < list->size - 1) { // Not the last element, shift others to fill the gap
        memmove(list->list + index, list->list + index + 1, (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    }
    list->size--;

    pthread_mutex_unlock(&list->lock);

    return true;
}

// Retrieve a PDU from the list by its index
NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_list_get(NFAPI_CRC_INDICATION_LIST_T *list, size_t index) {
