// Define list node structure
struct ListNode {
    LTE_PDCP_PDU_T *data;
    struct ListNode *next;
};

// Define list data structure
typedef struct {
    struct ListNode *head;
    struct ListNode *tail;
} List;

// Function to initialize list
void initList(List *list) {
    list->head = NULL;
    list->tail = NULL;
}

// Function to add element to list
void addToList(List *list, LTE_PDCP_PDU_T *element) {
    struct ListNode *newNode = malloc(sizeof(struct ListNode));
    newNode->data = element;
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }
}

// Function to remove element from list
void removeFromList(List *list, LTE_PDCP_PDU_T *element) {
    struct ListNode *currentNode = list->head;
    while (currentNode != NULL && currentNode->data != element) {
        currentNode = currentNode->next;
    }
    if (currentNode == NULL) {
        return;
    }
    if (currentNode == list->head) {
        list->head = currentNode->next;
    }
    if (currentNode == list->tail) {
        list->tail = currentNode->prev;
    }
    free(currentNode);
}

// Function to search for element in list
int searchInList(List *list, LTE_PDCP_PDU_T *element) {
    struct ListNode *currentNode = list->head;
    while (currentNode != NULL && currentNode->data != element) {
        currentNode = currentNode->next;
    }
    if (currentNode == NULL) {
        return -1;
    }
    return 0;
}

// Function to get first element in list
LTE_PDCP_PDU_T *getFirstInList(List *list) {
    if (list->head == NULL) {
        return NULL;
    }
    return list->head->data;
}

// Function to get last element in list
LTE_PDCP_PDU_T *getLastInList(List *list) {
    if (list->tail == NULL) {
        return NULL;
    }
    return list->tail->data;
}

// Function to get next element in list
LTE_PDCP_PDU_T *getNextInList(List *list, LTE_PDCP_PDU_T *element) {
    struct ListNode *currentNode = list->head;
    while (currentNode != NULL && currentNode->data != element) {
        currentNode = currentNode->next;
    }
    if (currentNode == NULL || currentNode->next == NULL) {
        return NULL;
    }
    return currentNode->next->data;
}

// Function to get previous element in list
LTE_PDCP_PDU_T *getPreviousInList(List *list, LTE_PDCP_PDU_T *element) {
    struct ListNode *currentNode = list->head;
    while (currentNode != NULL && currentNode->data != element) {
        currentNode = currentNode->next;
    }
    if (currentNode == NULL || currentNode->prev == NULL) {
        return NULL;
    }
    return currentNode->prev->data;
}

// Function to free list memory
void freeList(List *list) {
    struct ListNode *currentNode = list->head;
    while (currentNode != NULL) {
        struct ListNode *nextNode = currentNode->next;
        free(currentNode);
        currentNode = nextNode;
    }
}

// Function to validate PDCP sequence number
int validatePDCPSequenceNumber(unsigned int pdcpSN, unsigned int maxSize) {
