    // Iterate over the elements in the list and create a new partition for each range of RNTIs
    int current_partition = 0;
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].RNTI % rnti_range == 0) {
            // Create a new partition and add the element to it
            partitions[current_partition] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(partitions[current_partition], &list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            current_partition++;
        } else {
            // Add the element to the current partition
            partitions[current_partition - 1] = realloc(partitions[current_partition - 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (current_partition + 1));
            memcpy(&partitions[current_partition - 1][current_partition], &list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
