// Define a function to merge multiple partitions of the list into one
void nfapi_crc_indication_list_merge(NFAPI_CRC_INDICATION_LIST_T* list, int num_partitions) {
    // Initialize an array to store the merged elements
    NFAPI_CRC_INDICATION_PDU_T** merged = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (list->size));

    // Iterate over the partitions and add each element to the merged array
    int index = 0;
    for (int i = 0; i < num_partitions; i++) {
        for (int j = 0; j < list->size / rnti_range; j++) {
            merged[index] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(merged[index], partitions[i][j], sizeof(NFAPI_CRC_INDICATION_PDU_T));
