// Logging mechanism to track connection lifecycle events
void log_event(struct tcp_connection *conn, char *msg) {
    printf("[%s] %d: %s\n", conn->peer.s_addr, conn->socket, msg);
}

// Thread-safe function to add a new connection to the list
void add_connection(struct tcp_connection *conn) {
    // Lock mutex for thread safety
    pthread_mutex_lock(&list_mutex);

    // Add new connection to end of list
    conn->next = NULL;
    conn->prev = list_tail;
    if (list_tail != NULL) {
        list_tail->next = conn;
    } else {
        list_head = conn;
    }
    list_tail = conn;

    // Unlock mutex
    pthread_mutex_unlock(&list_mutex);
}

// Thread-safe function to remove a connection from the list
void remove_connection(struct tcp_connection *conn) {
    // Lock mutex for thread safety
    pthread_mutex_lock(&list_mutex);

    // Remove connection from list
    if (conn->prev != NULL) {
        conn->prev->next = conn->next;
    } else {
        list_head = conn->next;
    }
    if (conn->next != NULL) {
        conn->next->prev = conn->prev;
    } else {
        list_tail = conn->prev;
    }

    // Unlock mutex
    pthread_mutex_unlock(&list_mutex);
}

// Thread-safe function to retrieve a connection from the list based on peer address or port number
struct tcp_connection *get_connection(struct in_addr addr, int port) {
    // Lock mutex for thread safety
    pthread_mutex_lock(&list_mutex);

    // Search for connection with matching address and port
    struct tcp_connection *conn = list_head;
    while (conn != NULL) {
        if ((addr.s_addr == conn->peer.s_addr) && (port == conn->socket)) {
            break;
        }
        conn = conn->next;
    }

    // Unlock mutex
    pthread_mutex_unlock(&list_mutex);
    return conn;
}

// Main function for TCP connection management
int main(void) {
    int sock, new_sock;
    struct sockaddr_in server, client;

    // Initialize list head and mutex for thread safety
    list_head = NULL;
    pthread_mutex_init(&list_mutex, NULL);

    // Create socket for listening to incoming connections
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket failed");
        return 1;
    }

    // Set server address and port number
    memset(&server, 0, sizeof(server));
    server.sin_family = AF_INET;
    server.sin_addr.s_addr = htonl(INADDR_ANY);
    server.sin_port = htons(8080);

    // Bind socket to server address and port number
    if (bind(sock, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("bind failed");
        return 1;
    }

    // Listen for incoming connections with maximum of 3 pending connections in queue
    if (listen(sock, 3) < 0) {
        perror("listen failed");
        return 1;
    }

    // Accept incoming connection and store metadata in struct tcp_connection
    while (1) {
        new_sock = accept(sock, (struct sockaddr *)&client, (socklen_t*)&client_len);
        if (new_sock < 0) {
            perror("accept failed");
            return 1;
        }

        // Store connection metadata in struct tcp_connection and add to list
        struct tcp_connection *conn = malloc(sizeof(struct tcp_connection));
        conn->socket = new_sock;
        conn->peer = client.sin_addr;
        conn->timestamp = time(NULL);
        add_connection(conn);

        // Log connection establishment event
        log_event(conn, "Connection established");
    }

    return 0;
}
