int dns_resolve(const char *hostname, u_char *ipaddr) {
    // Perform DNS resolution using the standard library functions
    struct hostent *he;
    int error = 0;

    if ((he = gethostbyname(hostname)) == NULL) {
        fprintf(stderr, "DNS resolution failed for %s\n", hostname);
        return -1;
    }

    // Copy the IP address to the output parameter
    memcpy(ipaddr, he->h_addr, 4);

    // Handle errors gracefully and return an appropriate error code
    if (he->h_length != 4) {
        fprintf(stderr, "Invalid IP address length: %d\n", he->h_length);
        return -2;
    }

    return 0;
}

// Asynchronous DNS resolution using a callback mechanism for handling resolved IP addresses
void dns_async_resolve(const char *hostname, void (*callback)(u_char *ipaddr)) {
    // Perform DNS resolution asynchronously using the standard library functions
    struct hostent *he;
    int error = 0;

    if ((he = gethostbyname(hostname)) == NULL) {
        fprintf(stderr, "DNS resolution failed for %s\n", hostname);
        callback(NULL);
        return -1;
    }

    // Copy the IP address to the output parameter and call the callback function
    u_char *ipaddr = malloc(4);
    memcpy(ipaddr, he->h_addr, 4);
    callback(ipaddr);

    // Handle errors gracefully and return an appropriate error code
    if (he->h_length != 4) {
        fprintf(stderr, "Invalid IP address length: %d\n", he->h_length);
        callback(NULL);
        return -2;
    }

    return 0;
}

