// Optimize memory management to prevent leaks, and ensure thread safety to avoid race conditions or deadlocks in a multi-threaded environment.
#define MAX_THREADS 1024
struct dns_context {
    int num_threads;
    pthread_mutex_t *cache_lock;
    struct dns_cache **cache;
};

void init_dns_context(int num_threads) {
    struct dns_context *ctx = malloc(sizeof(struct dns_context));
    ctx->num_threads = num_threads;
    ctx->cache_lock = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t) * num_threads);
    for (int i = 0; i < num_threads; i++) {
        pthread_mutex_init(&ctx->cache_lock[i], NULL);
    }
    ctx->cache = (struct dns_cache **)malloc(sizeof(struct dns_cache *) * num_threads);
}

void destroy_dns_context(struct dns_context *ctx) {
    for (int i = 0; i < ctx->num_threads; i++) {
        pthread_mutex_destroy(&ctx->cache_lock[i]);
    }
    free(ctx->cache_lock);
}
