void initDynamicArray(NFAPI_CRC_INDICATION_PDU_T** pArr, size_t* capacity) {
    *pArr = malloc(INITIAL_ALLOCATION_SIZE * sizeof(**pArr));
    if (*pArr == NULL) {
        printf("Out of memory\n");
        return;
    }
    *capacity = INITIAL_ALLOCATION_SIZE;
}

void addElementToDynamicArray(NFAPI_CRC_INDICATION_PDU_T** pArr, size_t* capacity) {
    if (*capacity == 0) { // no more space in the dynamic array
        *capacity = MAX_ALLOCATION_SIZE;
        NFAPI_CRC_INDICATION_PDU_T* newArr = realloc(*pArr, *capacity * sizeof(**pArr));
        if (newArr == NULL) { // out of memory
            printf("Out of memory\n");
            return;
        }
        *pArr = newArr;
    }
    (*pArr)[*capacity - 1].rxUeInformationTag = RX_UE_INFORMATION_TAG_INITIALIZER;
    (*pArr)[*capacity - 1].rnti = RNTI_INITIALIZER;
    (*pArr)[*capacity - 1].crcIndicationRel8Tag = CRC_INDICATION_REL8_TAG_INITIALIZER;
    *capacity -= 1;
}

void freeDynamicArray(NFAPI_CRC_INDICATION_PDU_T** pArr, size_t capacity) {
    if (pArr == NULL || *pArr == NULL) return; // no dynamic array to free
    free(*pArr);
    *pArr = NULL;
    capacity = 0;
}

