    struct addrinfo *result, *rp;
    struct addrinfo hints;
    int s, i;
    char ipstr[INET6_ADDRSTRLEN];

    // Initialize the rate limiter with a rate of 10 queries per second
    pthread_mutex_t ratelimiter_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t ratelimiter_cond = PTHREAD_COND_INITIALIZER;
