    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    if ((s = getaddrinfo(hostname, "80", &hints, &result)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(s));
        return -1;
    }

    for (rp = result; rp != NULL; rp = rp->ai_next) {
        void *addr;
        char *ipver;

        if (rp->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)rp->ai_addr;
            addr = &ipv4->sin_addr;
            ipver = "IPv4";
        } else if (rp->ai_family == AF_INET6) { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)rp->ai_addr;
            addr = &ipv6->sin6_addr;
            ipver = "IPv6";
        } else {
            continue;
        }

        void *in_addr = inet_ntop(rp->ai_family, addr, ipstr, sizeof(ipstr));
        if (in_addr == NULL) {
            perror("inet_ntop");
            return -1;
        }

        // Check if the IP address is already in the list
        int found = 0;
        for (i = 0; i < crc_list->len; i++) {
            NFAPI_CRC_INDICATION_PDU_T *entry = &crc_list[i];
            if (strcmp(ipstr, entry->RX_UE_INFORMATION_TAG) == 0) {
                found = 1;
                break;
            }
        }

        // If the IP address is not in the list, add it to the list and generate a random CRCFLAG value
        if (!found) {
            NFAPI_CRC_INDICATION_PDU_T *new_entry = &crc_list[i];
            new_entry->RX_UE_INFORMATION_TAG = ipstr;
            new_entry->RNTI = (uint16_t)rand() % 0xFFFF;
            new_entry->CRCFLAG = (uint8_t)rand() % 256;
        }
    }

    // Free the addrinfo structure and return the list of NFAPI_CRC_INDICATION_PDU_T structures
    freeaddrinfo(result);
    return crc_list;
}
