// Define the maximum size of the array
#define MAX_SIZE 1000

// Structure to hold information about a UE
typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndTag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize a structure with the given UE information
void init_ue_info(NFAPI_CRC_INDICATION_PDU_T* ue, RX_UE_INFORMATION_TAG tag, RNTI rnti) {
    assert(ue != NULL);
    ue->tag = tag;
    ue->rnti = rnti;
    ue->crcIndTag = 0; // Initialize CRCFLAG to 0
}

// Function to validate a structure and set the CRCFLAG based on probabilistic model
void set_crc_indication(NFAPI_CRC_INDICATION_PDU_T* ue) {
    assert(ue != NULL);
    // Probabilistic model to simulate real-world signal conditions
    if (rand() % 2 == 0) {
        ue->crcIndTag = 1; // Set CRCFLAG to 1 with probability of 50%
    } else {
        ue->crcIndTag = 0; // Set CRCFLAG to 0 with probability of 50%
    }
}

// Function to manage the dynamically allocated array of structures
void manage_array(NFAPI_CRC_INDICATION_PDU_T** arr, size_t* size, size_t max_size) {
    assert(arr != NULL && size != NULL);

    // Check if we need to resize the array
    if (*size == 0 || *size >= max_size) {
        // Resize the array by doubling its size
        max_size = max_size > 0 ? max_size : MAX_SIZE;
        NFAPI_CRC_INDICATION_PDU_T* new_arr = realloc(*arr, max_size * sizeof(**arr));
        if (new_arr == NULL) {
            // Reallocation failed, attempt to release resources and retry
            free(*arr);
            *size = 0;
            return;
        }
        *arr = new_arr;
    }

    // Initialize the newly allocated structures
    for (size_t i = *size; i < max_size; i++) {
        init_ue_info(&(*arr)[i], 0, 0);
    }

    // Set the new size of the array
    *size = max_size;
}

// Function to add a structure to the array and set the CRCFLAG based on probabilistic model
void add_ue(NFAPI_CRC_INDICATION_PDU_T** arr, size_t* size, RX_UE_INFORMATION_TAG tag, RNTI rnti) {
    assert(arr != NULL && size != NULL);

    // Manage the array of structures
    manage_array(arr, size, *size + 1);

    // Set the UE information in the new structure
    init_ue_info(&(*arr)[*size - 1], tag, rnti);

    // Set the CRCFLAG based on probabilistic model
    set_crc_indication(&(*arr)[*size - 1]);
}

// Function to remove a structure from the array and release its memory
void remove_ue(NFAPI_CRC_INDICATION_PDU_T** arr, size_t* size) {
    assert(arr != NULL && size != NULL);

    // Release the memory of the removed structure
    free(&(*arr)[*size - 1]);

    // Decrement the size of the array
    *size = *size > 0 ? *size - 1 : 0;
}

// Function to periodically clean up unused structures and release their memory
void clean_up(NFAPI_CRC_INDICATION_PDU_T** arr, size_t* size) {
    assert(arr != NULL && size != NULL);

    // Check if there are any unused structures in the array
    for (size_t i = 0; i < *size; i++) {
        if ((*arr)[i].tag == 0 && (*arr)[i].rnti == 0) {
            remove_ue(arr, size);
        }
    }
}

// Function to handle external data sources for UE information
void handle_ue_info(NFAPI_CRC_INDICATION_PDU_T** arr, size_t* size, RX_UE_INFORMATION_TAG tag, RNTI rnti) {
    assert(arr != NULL && size != NULL);

    // Handle the external data source for UE information
    if (tag == 0 && rnti == 0) {
        // UE information not available, do nothing
    } else {
        add_ue(arr, size, tag, rnti);
