// Function to handle memory fragmentation and cache performance implications
void manage_memory(NFAPI_CRC_INDICATION_PDU_T** arr, size_t* size) {
    assert(arr != NULL && size != NULL);

    // Manage the array of structures to avoid memory fragmentation
    if (*size > 100) {
        // Resize the array by half its size
        NFAPI_CRC_INDICATION_PDU_T* new_arr = realloc(*arr, *size / 2);
        if (new_arr == NULL) {
            // Reallocation failed, attempt to release resources and retry
            free(*arr);
            *size = 0;
