// Struct for storing the context of a cryptographic operation
struct CryptoContext {
    void* ctx; // Pointer to the context object
    int type; // Type of the cryptographic primitive (AES, Camellia, RSA, MD5, SHA-256, or SHA-512)
};

// Function for initializing a cryptographic operation
CryptoContext* crypto_init(int type) {
    // Initialize the context object and set its type
    CryptoContext* ctx = (CryptoContext*)malloc(sizeof(CryptoContext));
    if (!ctx) {
        return NULL;
    }
    ctx->type = type;

    switch (type) {
        case AES_TYPE:
            // Initialize the AES context
            ctx->ctx = EVP_CIPHER_CTX_new();
            if (!ctx->ctx) {
                free(ctx);
                return NULL;
            }
            break;
        case CAMELLIA_TYPE:
            // Initialize the Camellia context
            ctx->ctx = EVP_Camellia_CIPHER_CTX_new();
            if (!ctx->ctx) {
                free(ctx);
                return NULL;
            }
            break;
        case RSA_TYPE:
            // Initialize the RSA context
            ctx->ctx = EVP_PKEY_CTX_new();
            if (!ctx->ctx) {
                free(ctx);
                return NULL;
            }
            break;
        case MD5_TYPE:
            // Initialize the MD5 context
            ctx->ctx = EVP_MD_CTX_create();
            if (!ctx->ctx) {
                free(ctx);
                return NULL;
            }
            break;
        case SHA256_TYPE:
            // Initialize the SHA-256 context
            ctx->ctx = EVP_MD_CTX_create();
            if (!ctx->ctx) {
                free(ctx);
                return NULL;
            }
            break;
        case SHA512_TYPE:
            // Initialize the SHA-512 context
            ctx->ctx = EVP_MD_CTX_create();
            if (!ctx->ctx) {
                free(ctx);
                return NULL;
            }
            break;
    }

    return ctx;
}

// Function for performing a cryptographic operation
int crypto_do(CryptoContext* ctx, unsigned char* data, size_t length, int mode) {
    switch (ctx->type) {
        case AES_TYPE:
            // Perform the AES encryption/decryption
            return EVP_CipherUpdate(ctx->ctx, data, length);
        case CAMELLIA_TYPE:
            // Perform the Camellia encryption/decryption
            return EVP_Camellia_CipherUpdate(ctx->ctx, data, length);
        case RSA_TYPE:
            // Perform the RSA encryption/decryption
            return EVP_PKey_CTX_encrypt(ctx->ctx, data, length);
        case MD5_TYPE:
            // Perform the MD5 hashing
            return EVP_DigestUpdate(ctx->ctx, data, length);
        case SHA256_TYPE:
            // Perform the SHA-256 hashing
            return EVP_DigestUpdate(ctx->ctx, data, length);
        case SHA512_TYPE:
            // Perform the SHA-512 hashing
            return EVP_DigestUpdate(ctx->ctx, data, length);
    }
}

// Function for destroying a cryptographic operation
void crypto_destroy(CryptoContext* ctx) {
    switch (ctx->type) {
        case AES_TYPE:
            // Destroy the AES context
            EVP_CIPHER_CTX_free(ctx->ctx);
            break;
        case CAMELLIA_TYPE:
            // Destroy the Camellia context
            EVP_Camellia_CIPHER_CTX_free(ctx->ctx);
            break;
        case RSA_TYPE:
            // Destroy the RSA context
            EVP_PKEY_CTX_free(ctx->ctx);
            break;
        case MD5_TYPE:
            // Destroy the MD5 context
            EVP_MD_CTX_destroy(ctx->ctx);
            break;
        case SHA256_TYPE:
            // Destroy the SHA-256 context
            EVP_MD_CTX_destroy(ctx->ctx);
            break;
        case SHA512_TYPE:
            // Destroy the SHA-512 context
            EVP_MD_CTX_destroy(ctx->ctx);
            break;
    }

    free(ctx);
}
