using System;
using System.Security.Cryptography;
using System.Text;

namespace TripleDesDecryptionFunction
{
    public static class DecryptionFunction
    {
        // Constant values for the triple DES algorithm
        private const string KEY = "your_key";
        private const string IV = "your_iv";

        public static string Decrypt(string base64EncodedMessage)
        {
            try
            {
                // Validate input parameters
                if (base64EncodedMessage == null || String.IsNullOrEmpty(base64EncodedMessage))
                {
                    throw new ArgumentException("Invalid base64 encoded message");
                }

                // Initialize DES encryption algorithm
                var des = new TripleDESCryptoServiceProvider();

                // Set key and IV for the triple DES algorithm
                des.Key = Encoding.UTF8.GetBytes(KEY);
                des.IV = Encoding.UTF8.GetBytes(IV);

                // Create a memory stream to store the encrypted data
                var ms = new MemoryStream();

                // Convert base64 encoded message into a byte array and write it to the memory stream
                var bytes = Convert.FromBase64String(base64EncodedMessage);
                ms.Write(bytes, 0, bytes.Length);

                // Reset the memory stream position to the beginning
                ms.Position = 0;

                // Create a new instance of the CryptoStream class for decryption
                using (var cryptoStream = new CryptoStream(ms, des.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    // Read the decrypted data from the crypto stream and convert it back to a string
                    var plainTextBytes = new byte[cryptoStream.Length];
                    cryptoStream.Read(plainTextBytes, 0, plainTextBytes.Length);
                    var plainText = Encoding.UTF8.GetString(plainTextBytes);

                    // Return the decrypted string
                    return plainText;
                }
            }
            catch (Exception e)
            {
                // Log any exceptions that occur during decryption
                Console.WriteLine("Error during decryption: " + e.Message);
                throw;
            }
        }
    }
}
