u_char* resolve_hostname(const char* hostname) {
    struct addrinfo hints, *res;
    int ret;

    // Initialize addrinfo structure
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    // Get host address information
    if ((ret = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        perror("getaddrinfo");
        return NULL;
    }

    // Create socket and connect to host
    int sockfd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (connect(sockfd, res->ai_addr, res->ai_addrlen) == -1) {
        perror("connect");
        return NULL;
    }

    // Read hostname from socket
    char buffer[BUFSIZ];
    int n = read(sockfd, buffer, BUFSIZ);
    if (n < 0) {
        perror("read");
        return NULL;
    }
    buffer[n] = '\0';

    // Convert IP address to u_char array
    struct in_addr addr;
    int rc = inet_pton(AF_INET, buffer, &addr);
    if (rc == 1) {
        return (u_char*)&addr.s_addr;
    } else {
        perror("inet_pton");
        return NULL;
    }
