bool nfapi_crc_indication_list_insert(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == 0 || list->data[list->count - 1].rnti <= entry->rnti) {
        // Append to the end of the list
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, (list->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
