    uint64_t ue_id;
    time_t timestamp;
    bool quality_indicator;
    float signal_strength;
    NFAPI_CRC_INDICATION_PDU_T crc_pdu;
} UeMeasurementRecord;

// Define the maximum number of samples to store per record
#define MAX_SAMPLES 100

// Define the function to initialize and manage the dynamically allocated array of UeMeasurementRecord structures
UeMeasurementRecord* init_ue_measurements(void) {
    // Allocate memory for the array of UeMeasurementRecords
    UeMeasurementRecord* ue_measurements = (UeMeasurementRecord*)malloc(sizeof(UeMeasurementRecord) * MAX_SAMPLES);
    if (!ue_measurements) {
        // Handle memory allocation failure
        return NULL;
    }

    // Initialize the UeMeasurementRecords with random values
    for (int i = 0; i < MAX_SAMPLES; i++) {
        ue_measurements[i].ue_id = rand();
        ue_measurements[i].timestamp = time(NULL);
        ue_measurements[i].quality_indicator = (rand() % 2) == 0;
        ue_measurements[i].signal_strength = ((float)(rand() % 150) - 150.0f);
