    ue_measurements[index].crc_pdu.rnti = rand();
    ue_measurements[index].crc_pdu.crcflag = (rand() % 2) == 0;
}

// Define the function to remove the oldest sample from the UeMeasurementRecord array and insert a new one
void update_samples(UeMeasurementRecord* ue_measurements, int index, SignalStrengthSample sample) {
    // Check if the record is full and needs to be resized
    if (index >= MAX_SAMPLES - 1) {
        // Reallocate memory for the array with a larger size
        UeMeasurementRecord* new_ue_measurements = (UeMeasurementRecord*)realloc(ue_measurements, sizeof(UeMeasurementRecord) * MAX_SAMPLES);
        if (!new_ue_measurements) {
            // Handle memory allocation failure
            return;
        }
        ue_measurements = new_ue_measurements;
    }

    // Remove the oldest sample from the record and insert the new one
    UeMeasurementRecord old_sample = ue_measurements[0];
    memmove(&ue_measurements[0], &ue_measurements[1], sizeof(UeMeasurementRecord) * (index + 1));
    ue_measurements[index].timestamp = time(NULL);
    ue_measurements[index].quality_indicator = (rand() % 2) == 0;
    ue_measurements[index].signal_strength = ((float)(rand() % 150) - 150.0f);
    ue_measurements[index].crc_pdu.valid_tag = rand();
    ue_measurements[index].crc_pdu.rnti = rand();
    ue_measurements[index].crc_pdu.crcflag = (rand() % 2) == 0;
}

// Define the function to send the UeMeasurementRecords over the network
void send_ue_measurements(UeMeasurementRecord* ue_measurements, int num_samples) {
    // Send the UeMeasurementRecords over the network
    for (int i = 0; i < num_samples; i++) {
        printf("UE measurement record: %d\n", ue_measurements[i]);
    }
}

// Define the main function to test the UeMeasurementRecords
int main() {
    // Initialize the UeMeasurementRecords with random values
    UeMeasurementRecord* ue_measurements = init_ue_measurements();

    // Insert new samples into the UeMeasurementRecords and update the oldest one
    insert_sample(ue_measurements, 0, {0, 1});
    insert_sample(ue_measurements, 1, {2, 3});
    update_samples(ue_measurements, 2, {4, 5});

    // Send the UeMeasurementRecords over the network
    send_ue_measurements(ue_measurements, MAX_SAMPLES);

    // Free the memory allocated for the UeMeasurementRecords
    free(ue_measurements);

    return 0;
}
