    if (record->samples == NULL || record->samples[0].sample_time > timestamp + 100) {
        return;
    }

    // Add a new sample to the end of the vector and update the timestamp
    record->samples[record->samples[0].sample_time].sample_time = timestamp + 1;
    record->samples[record->samples[0].sample_time].signal_strength = signal_strength;
    record->samples[record->samples[0].sample_time].quality_indicator = quality_indicator;

    // Remove the oldest sample from the vector if it has reached its maximum size
    if (record->samples[record->samples[0].sample_time] > 100) {
        record->samples[record->samples[0].sample_time - 1];
    }
}

void free_ue_measurement_record(UeMeasurementRecord *record) {
