    int size; // Size of the message in bytes
    char* data; // Pointer to the message data
} LTE_ECM_DL_FRAME_MSG_T;

// Structure to represent the dynamic array
typedef struct {
    int capacity; // Maximum number of elements in the array
    int size; // Current number of elements in the array
    LTE_ECM_DL_FRAME_MSG_T* elements; // Pointer to the elements of the array
} DYNAMIC_ARRAY_T;

// Function to initialize and populate a dynamic array of LTE_ECM_DL_FRAME_MSG_T structures
void init_dynamic_array(DYNAMIC_ARRAY_T* arr, int capacity) {
    // Allocate memory for the elements of the array
    arr->elements = (LTE_ECM_DL_FRAME_MSG_T*)malloc(capacity * sizeof(LTE_ECM_DL_FRAME_MSG_T));

    // Initialize the capacity and size of the array
    arr->capacity = capacity;
    arr->size = 0;
}

// Function to add a new message to the dynamic array
void add_message(DYNAMIC_ARRAY_T* arr, int type, int size) {
    // Check if the array is full
    if (arr->size == arr->capacity) {
        // Increase the capacity of the array by 50%
        int new_capacity = arr->capacity + (arr->capacity / 2);
        LTE_ECM_DL_FRAME_MSG_T* new_elements = (LTE_ECM_DL_FRAME_MSG_T*)realloc(arr->elements, new_capacity * sizeof(LTE_ECM_DL_FRAME_MSG_T));
        if (new_elements == NULL) {
            // Reallocation failed, handle error
            printf("Reallocation failed\n");
            return;
        }
        arr->elements = new_elements;
        arr->capacity = new_capacity;
    }

    // Add the new message to the array
    arr->elements[arr->size].type = type;
    arr->elements[arr->size].size = size;
    arr->elements[arr->size].data = (char*)malloc(size * sizeof(char));
    memcpy(arr->elements[arr->size].data, data, size);
    arr->size++;
}

// Function to remove the first message from the dynamic array
void remove_first_message(DYNAMIC_ARRAY_T* arr) {
    // Check if the array is empty
    if (arr->size == 0) {
        return;
    }

    // Free the memory used by the first message
    free(arr->elements[0].data);

    // Shift all messages in the array to fill the gap left by the removed message
    for (int i = 0; i < arr->size - 1; i++) {
        arr->elements[i] = arr->elements[i + 1];
    }

    // Decrement the size of the array
    arr->size--;
}

// Function to retrieve the first message from the dynamic array without removing it
LTE_ECM_DL_FRAME_MSG_T* get_first_message(DYNAMIC_ARRAY_T* arr) {
    // Check if the array is empty
    if (arr->size == 0) {
        return NULL;
    }

    return &arr->elements[0];
}

// Function to retrieve the last message from the dynamic array without removing it
LTE_ECM_DL_FRAME_MSG_T* get_last_message(DYNAMIC_ARRAY_T* arr) {
    // Check if the array is empty
    if (arr->size == 0) {
        return NULL;
    }

    return &arr->elements[arr->size - 1];
}

// Function to retrieve a message from the dynamic array at a given index without removing it
LTE_ECM_DL_FRAME_MSG_T* get_message(DYNAMIC_ARRAY_T* arr, int index) {
    // Check if the array is empty or the index is out of bounds
    if (arr->size == 0 || index < 0 || index >= arr->size) {
        return NULL;
    }

    return &arr->elements[index];
}

// Function to remove a message from the dynamic array at a given index
void remove_message(DYNAMIC_ARRAY_T* arr, int index) {
    // Check if the array is empty or the index is out of bounds
    if (arr->size == 0 || index < 0 || index >= arr->size) {
        return;
    }

    // Free the memory used by the message at the given index
    free(arr->elements[index].data);

    // Shift all messages in the array to fill the gap left by the removed message
    for (int i = index; i < arr->size - 1; i++) {
        arr->elements[i] = arr->elements[i + 1];
    }

    // Decrement the size of the array
    arr->size--;
}

// Function to clear the dynamic array and free all memory allocated for its elements
void clear_dynamic_array(DYNAMIC_ARRAY_T* arr) {
    // Check if the array is empty
    if (arr->size == 0) {
        return;
    }

    // Free the memory used by each element in the array
    for (int i = 0; i < arr->size; i++) {
        free(arr->elements[i].data);
    }

    // Free the memory used by the array itself
    free(arr->elements);

    // Set the size of the array to 0
    arr->size = 0;
}

// Load balancing strategy to distribute messages across available resources, minimizing latency and maximizing throughput
int load_balancing_strategy(DYNAMIC_ARRAY_T* arr) {
    // Implement your own load balancing strategy here

