// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
  unsigned short RX_UE_INFORMATION_TAG;
  int RNTI;
  char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically allocate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* alloc_crc_indications(int num_structures) {
  // Check if the number of structures is valid
  if (num_structures <= 0) {
    printf("Error: Invalid number of structures for CRC indication\n");
    return NULL;
  }

  // Allocate memory for the array of structures
  NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (crc_indications == NULL) {
    printf("Error: Failed to allocate memory for CRC indication\n");
    return NULL;
  }

  // Initialize the CRCFLAG value for each structure
  srand(time(NULL));
  int random_value = rand() % 256 + 1;
  for (int i = 0; i < num_structures; ++i) {
    crc_indications[i].CRCFLAG = random_value % 2 ? '1' : '0';
    random_value++;
  }

  return crc_indications;
}

// Define the function to serialize an array of NFAPI_CRC_INDICATION_PDU_T structures into a binary file
int serialize_crc_indications(NFAPI_CRC_INDICATION_PDU_T* crc_indications, int num_structures, const char* filename) {
  // Check if the number of structures is valid
  if (num_structures <= 0 || crc_indications == NULL) {
    printf("Error: Invalid input for serialization\n");
    return -1;
  }

  // Open the output file in binary mode
  FILE* fp = fopen(filename, "wb");
  if (fp == NULL) {
    printf("Error: Failed to open file for serialization\n");
    return -2;
  }

  // Write the data to the file
  int total_written = 0;
  for (int i = 0; i < num_structures; ++i) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = &crc_indications[i];
    fwrite(&pdu->RX_UE_INFORMATION_TAG, sizeof(unsigned short), 1, fp);
    fwrite(&pdu->RNTI, sizeof(int), 1, fp);
    fwrite(&pdu->CRCFLAG, sizeof(char), 1, fp);
    total_written += sizeof(unsigned short) + sizeof(int) + sizeof(char);
  }

  // Close the file and return the number of bytes written
  int result = fclose(fp);
  if (result != 0) {
    printf("Error: Failed to close file after serialization\n");
    return -3;
  }
  return total_written;
}

// Define the function to deserialize an array of NFAPI_CRC_INDICATION_PDU_T structures from a binary file
int deserialize_crc_indications(NFAPI_CRC_INDICATION_PDU_T* crc_indications, int num_structures, const char* filename) {
  // Check if the number of structures is valid
  if (num_structures <= 0 || crc_indications == NULL) {
    printf("Error: Invalid input for deserialization\n");
    return -1;
  }

  // Open the input file in binary mode
  FILE* fp = fopen(filename, "rb");
  if (fp == NULL) {
    printf("Error: Failed to open file for deserialization\n");
    return -2;
  }

  // Read the data from the file
  int total_read = 0;
  for (int i = 0; i < num_structures; ++i) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = &crc_indications[i];
    fread(&pdu->RX_UE_INFORMATION_TAG, sizeof(unsigned short), 1, fp);
    fread(&pdu->RNTI, sizeof(int), 1, fp);
    fread(&pdu->CRCFLAG, sizeof(char), 1, fp);
    total_read += sizeof(unsigned short) + sizeof(int) + sizeof(char);
  }

  // Close the file and return the number of bytes read
  int result = fclose(fp);
  if (result != 0) {
    printf("Error: Failed to close file after deserialization\n");
    return -3;
  }
  return total_read;
}

// Define the function to update the RNTI and RX_UE_INFORMATION_TAG values in the array of NFAPI_CRC_INDICATION_PDU_T structures
void update_crc_indications(NFAPI_CRC_INDICATION_PDU_T* crc_indications, int num_structures, const char* filename) {
  // Check if the number of structures is valid
  if (num_structures <= 0 || crc_indications == NULL) {
    printf("Error: Invalid input for update\n");
    return;
  }

  // Open the input file in binary mode
  FILE* fp = fopen(filename, "rb");
  if (fp == NULL) {
    printf("Error: Failed to open file for update\n");
    return;
  }

  // Read the data from the file
  int total_read = 0;
  for (int i = 0; i < num_structures; ++i) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = &crc_indications[i];
    fread(&pdu->RX_UE_INFORMATION_TAG, sizeof(unsigned short), 1, fp);
    fread(&pdu->RNTI, sizeof(int), 1, fp);
    total_read += sizeof(unsigned short) + sizeof(int);
  }

  // Close the file and return the number of bytes read
  int result = fclose(fp);
  if (result != 0) {
    printf("Error: Failed to close file after update\n");
    return;
  }
}

// Define the main function
int main() {
  // Allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
  int num_structures = 10;
  NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

  // Initialize the CRCFLAG value for each structure
  for (int i = 0; i < num_structures; ++i) {
    crc_indications[i].CRCFLAG = '0';
  }

  // Serialize the array of NFAPI_CRC_INDICATION_PDU_T structures into a binary file
  const char* filename = "crc_indications.bin";
  int num_bytes_written = serialize_crc_indications(crc_indications, num_structures, filename);
  printf("Serialized %d bytes to %s\n", num_bytes_written, filename);

  // Deserialize the array of NFAPI_CRC_INDICATION_PDU_T structures from a binary file
  int num_bytes_read = deserialize_crc_indications(crc_indications, num_structures, filename);
  printf("Deserialized %d bytes from %s\n", num_bytes_read, filename);

  // Update the RNTI and RX_UE_INFORMATION_TAG values in the array of NFAPI_CRC_INDICATION_PDU_T structures using a file
  update_crc_indications(crc_indications, num_structures, filename);

  // Free the memory allocated for the array of NFAPI_CRC_INDICATION_PDU_T structures
  free(crc_indications);
  return 0;
}
