  long RNTI;
  char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list node to store the elements in the array
typedef struct {
  NFAPI_CRC_INDICATION_PDU_T *data;
  struct Node *next;
} ListNode;

// Define a linked list to store the dynamically allocated array of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
  ListNode *head;
  int size;
} LinkedList;

// Function to create a new node for the linked list
static ListNode* new_node(NFAPI_CRC_INDICATION_PDU_T data) {
  ListNode *node = malloc(sizeof(ListNode));
  node->data = data;
  node->next = NULL;
  return node;
}

// Function to add an element to the linked list
static void add_element(LinkedList *list, NFAPI_CRC_INDICATION_PDU_T data) {
  ListNode *node = new_node(data);
  if (list->head == NULL) {
    list->head = node;
  } else {
    ListNode *temp = list->head;
    while (temp->next != NULL) {
      temp = temp->next;
    }
    temp->next = node;
  }
}

// Function to remove an element from the linked list
static void remove_element(LinkedList *list, int index) {
  ListNode *temp = list->head;
  if (index == 0) {
    list->head = temp->next;
    free(temp);
  } else {
    for (int i = 1; i < index - 1; i++) {
      temp = temp->next;
    }
    ListNode *node = temp->next;
    temp->next = node->next;
    free(node);
  }
}

// Function to validate the RNTI value and add it to the linked list if valid
static void validate_and_add(LinkedList *list, long RNTI) {
  // Check if the RNTI value is already present in the list
  ListNode *temp = list->head;
  while (temp != NULL) {
    if (temp->data.RNTI == RNTI) {
      return;
    }
    temp = temp->next;
  }
  // If not present, add it to the linked list
  NFAPI_CRC_INDICATION_PDU_T data = {0};
  data.RX_UE_INFORMATION_TAG = 0;
  data.RNTI = RNTI;
  data.CRCFLAG = '1'; // Set the CRCFLAG to '1' for a randomly set value
  add_element(list, data);
}

// Function to remove an element from the linked list by its index
static void remove_by_index(LinkedList *list, int index) {
  if (index < 0 || index >= list->size) {
    return;
  }
  remove_element(list, index);
}

// Function to log the detailed information about the linked list contents
static void log_info(LinkedList *list) {
  ListNode *temp = list->head;
  while (temp != NULL) {
    printf("RX_UE_INFORMATION_TAG: %d\n", temp->data.RX_UE_INFORMATION_TAG);
    printf("RNTI: %ld\n", temp->data.RNTI);
    printf("CRCFLAG: %c\n", temp->data.CRCFLAG);
    temp = temp->next;
  }
}

// Function to manage the dynamically allocated array of NFAPI_CRC_INDICATION_PDU_T structures
void manage_array(NFAPI_CRC_INDICATION_PDU_T *array, int size) {
  // Create a linked list to store the elements
  LinkedList list = {NULL, size};
  // Loop through the array and validate and add each element to the linked list
  for (int i = 0; i < size; i++) {
    validate_and_add(&list, array[i].RNTI);
  }
  // Remove any duplicate elements from the linked list
  ListNode *temp = list.head;
  while (temp != NULL) {
    if (temp->next == temp || temp->data.RNTI == temp->next->data.RNTI) {
      remove_element(&list, temp->data.RNTI);
    }
    temp = temp->next;
  }
  // Remove any elements from the linked list that are out of range
  for (int i = size - 1; i >= 0; i--) {
    if (i < list.size) {
      remove_by_index(&list, i);
    }
  }
  // Log the detailed information about the linked list contents
  log_info(&list);
}
```
