// Define a struct to represent an NFAPI_CRC_INDICATION_PDU_T
struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRCFLAG;
};

// Define a list to store the structures
typedef struct NFAPI_CRC_INDICATION_PDU_LIST {
    struct NFAPI_CRC_INDICATION_PDU_T *data;
    int size;
    int capacity;
} NFAPI_CRC_INDICATION_PDU_LIST;

// Initialize the list with a given initial capacity
void nfapi_crc_indication_pdu_list_init(NFAPI_CRC_INDICATION_PDU_LIST *list, int capacity) {
    list->data = malloc(capacity * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    list->size = 0;
    list->capacity = capacity;
}

// Add a new structure to the list and return its index
int nfapi_crc_indication_pdu_list_add(NFAPI_CRC_INDICATION_PDU_LIST *list, unsigned int rx_ue_information_tag, unsigned int rnti, unsigned char crcflag) {
    // Check if the list is full
    if (list->size == list->capacity) {
        return -1;
    }

    // Generate a new RNTI value if it's not provided
    if (rnti == 0) {
        rnti = rand() % 65536;
    }

    // Check if the RNTI value is unique
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].RNTI == rnti) {
            return -2;
        }
    }

    // Add the new structure to the list
    int index = list->size++;
    list->data[index].RX_UE_INFORMATION_TAG = rx_ue_information_tag;
    list->data[index].RNTI = rnti;
    list->data[index].CRCFLAG = crcflag;

    // Log the creation details of the new structure to a file
    char log_str[1024];
    sprintf(log_str, "CRC_INDICATION_REL8_TAG: %u, RNTI: %u, CRCFLAG: %d\n", list->data[index].RX_UE_INFORMATION_TAG, list->data[index].RNTI, list->data[index].CRCFLAG);
    FILE *log_file = fopen("crc_indication_pdu_list.log", "a");
    if (log_file) {
        fputs(log_str, log_file);
        fclose(log_file);
    }

    return index;
}

// Remove an existing structure from the list and return its index
int nfapi_crc_indication_pdu_list_remove(NFAPI_CRC_INDICATION_PDU_LIST *list, unsigned int rx_ue_information_tag, unsigned int rnti) {
    // Find the index of the structure to be removed
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].RX_UE_INFORMATION_TAG == rx_ue_information_tag && list->data[i].RNTI == rnti) {
            return i;
        }
    }

    // Return -1 if the structure is not found
    return -1;
}

// Synchronize the list for concurrent access
pthread_mutex_t nfapi_crc_indication_pdu_list_mutex = PTHREAD_MUTEX_INITIALIZER;

void nfapi_crc_indication_pdu_list_lock() {
    pthread_mutex_lock(&nfapi_crc_indication_pdu_list_mutex);
}

void nfapi_crc_indication_pdu_list_unlock() {
    pthread_mutex_unlock(&nfapi_crc_indication_pdu_list_mutex);
}
