// Define the structure for storing NFAPI_CRC_INDICATION_PDU_T data
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list node for storing the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct NFAPI_CRC_INDICATION_LIST_NODE {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct NFAPI_CRC_INDICATION_LIST_NODE *next;
} NFAPI_CRC_INDICATION_LIST_NODE;

// Define the linked list for storing the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct NFAPI_CRC_INDICATION_LIST {
    NFAPI_CRC_INDICATION_LIST_NODE *head;
    size_t count;
} NFAPI_CRC_INDICATION_LIST;

// Define the configuration options for selecting the encryption mode, key management, and file storage location
typedef struct CONFIG {
    char *encryption_mode;
    char *key_management;
    char *file_storage_location;
} CONFIG;

// Define the function for managing the generation and population of a list of NFAPI_CRC_INDICATION_PDU_T structures
bool generate_crc_indication_list(NFAPI_CRC_INDICATION_LIST *list, size_t n, CONFIG config) {
    // Allocate memory for the linked list node and initialize it with NULL
    NFAPI_CRC_INDICATION_LIST_NODE *node = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_NODE));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return false;
    }
    node->next = NULL;

    // Loop through the given number of NFAPI_CRC_INDICATION_PDU_T structures and allocate memory for each one
    for (size_t i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (data == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            free(node);
            return false;
        }

        // Set the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG randomly
        data->RX_UE_INFORMATION_TAG = (uint16_t) rand();
        data->RNTI = (uint32_t) rand();
        data->CRC_INDICATION_REL8_TAG = (uint8_t) rand();

        // Set the CRCFLAG randomly
        if (rand() % 2 == 0) {
            data->CRCFLAG = 1;
        } else {
            data->CRCFLAG = 0;
        }

        // Add the allocated memory to the linked list node and move on to the next iteration
        node->data = *data;
        node = node->next;
    }

    // Append the last node to the linked list
    list->head = node;
    list->count = n;

    // Serialize the data into a binary file using the given configuration options
    bool success = serialize_crc_indication_list(list, config);
    if (!success) {
        fprintf(stderr, "Serialization failed\n");
        free(node->next);
        return false;
    }

    // Encrypt the serialized data using the given encryption mode and key management
    success = encrypt_crc_indication_list(list, config);
    if (!success) {
        fprintf(stderr, "Encryption failed\n");
        free(node->next);
        return false;
    }

    // Write the encrypted data securely to disk using the given file storage location
    success = write_crc_indication_list(list, config);
    if (!success) {
        fprintf(stderr, "File write failed\n");
        free(node->next);
        return false;
    }

    // Return the success of both the data population and the encryption process
    return true;
}

// Define the function for serializing the NFAPI_CRC_INDICATION_LIST into a binary file using Java's ObjectOutputStream
bool serialize_crc_indication_list(NFAPI_CRC_INDICATION_LIST *list, CONFIG config) {
    // Open the file in binary write mode for serialization
    FILE *file = fopen(config.file_storage_location, "wb");
    if (file == NULL) {
        fprintf(stderr, "File open failed\n");
        return false;
    }

    // Serialize the linked list node by node into the file
    NFAPI_CRC_INDICATION_LIST_NODE *node = list->head;
    while (node != NULL) {
        fwrite(&node->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        node = node->next;
    }

    // Close the file and return success
    fclose(file);
    return true;
}

// Define the function for encrypting the serialized data using the given encryption mode and key management
bool encrypt_crc_indication_list(NFAPI_CRC_INDICATION_LIST *list, CONFIG config) {
    // Initialize the cryptographic library with the desired encryption mode and key management
    if (strcmp(config.encryption_mode, "ECB") == 0) {
