        DES_ede3_cbc_encrypt(const unsigned char *input, unsigned char *output, size_t length, const void *ks1, const void *ks2, const void *ks3, unsigned char *ivec, int enc);
    } else if (strcmp(config.encryption_mode, "CBC") == 0) {
        DES_cbc_encrypt(const unsigned char *input, unsigned char *output, size_t length, const void *schedule, unsigned char *ivec, int enc);
    } else if (strcmp(config.encryption_mode, "PCBC") == 0) {
        DES_pcbc_encrypt(const unsigned char *input, unsigned char *output, size_t length, const void *schedule, unsigned char *ivec, int enc);
    } else if (strcmp(config.encryption_mode, "CFB") == 0) {
        DES_cfb64_encrypt(const unsigned char *input, unsigned char *output, size_t length, const void *schedule, unsigned char *ivec, int enc);
    } else if (strcmp(config.encryption_mode, "OFB") == 0) {
        DES_ofb64_encrypt(const unsigned char *input, unsigned char *output, size_t length, const void *schedule, unsigned char *ivec, int enc);
    } else if (strcmp(config.encryption_mode, "CTR") == 0) {
