        DES_cmac_encrypt(const unsigned char *input, unsigned char *output, size_t length, const void *schedule, unsigned char *ivec, int enc);
    } else if (strcmp(config.encryption_mode, "EAX") == 0) {
        DES_eax_encrypt(const unsigned char *input, unsigned char *output, size_t length, const void *schedule, unsigned char *ivec, int enc);
    } else if (strcmp(config.encryption_mode, "OMAC") == 0) {
        DES_omac_encrypt(const unsigned char *input, unsigned char *output, size_t length, const void *schedule, unsigned char *ivec, int enc);
    } else if (strcmp(config.encryption_mode, "WRAP") == 0) {
        DES_wrap_key(const unsigned char *key, const unsigned char *ivec, unsigned char *output, const void *schedule);
    } else if (strcmp(config.encryption_mode, "XCBC") == 0) {
        DES_xcbc_encrypt(const unsigned char *input, unsigned char *output, size_t length, const void *schedule, unsigned char *ivec, int enc);
    } else if (strcmp(config.encryption_mode, "XTS") == 0) {
        DES_xts_encrypt(const unsigned char *input, unsigned char *output, size_t length, const void *schedule1, const void *schedule2, unsigned char *ivec, int enc);
    } else if (strcmp(config.encryption_mode, "XTS") == 0) {
        DES_xts_decrypt(const unsigned char *input, unsigned char *output, size_t length, const void *schedule1, const void *schedule2, unsigned char *ivec, int enc);
    } else {
        fprintf(stderr, "Encryption mode not supported\n");
        return false;
    }

    // Set the encryption key and iv
    DES_set_key(&key, &schedule);
    DES_cbc_encrypt(plaintext, ciphertext, plaintext_len, &schedule, iv, 1);

    // Clean up
    OPENSSL_cleanse(&key, sizeof(key));
    OPENSSL_cleanse(&schedule, sizeof(schedule));
}
