    arr->messages = malloc(sizeof(NFAPI_MESSAGE_T *) * arr->capacity);
    if (arr->messages == NULL) {
        return -1;
    }
    return 0;
}

int nfapi_add_message(struct nfapi_message_array *arr, uint32_t context_id, uint32_t sequence_number, void *payload, size_t payload_size) {
    int ret = -1;
    pthread_mutex_lock(&arr->mutex);
    if (arr->count >= arr->capacity) {
        // Grow the array by 25% when it reaches capacity
        arr->capacity *= 1.25;
        arr->messages = realloc(arr->messages, sizeof(NFAPI_MESSAGE_T *) * arr->capacity);
        if (arr->messages == NULL) {
            pthread_mutex_unlock(&arr->mutex);
            return -1;
        }
    }
    // Calculate the checksum of the context ID and sequence number
    uint32_t checksum = context_id + sequence_number;
    // Allocate memory for the payload buffer
    void *payload_buffer = malloc(payload_size);
    if (payload_buffer == NULL) {
        pthread_mutex_unlock(&arr->mutex);
        return -1;
    }
    // Copy the payload data into the buffer
    memcpy(payload_buffer, payload, payload_size);
    // Create a new NFAPI_MESSAGE_T structure and initialize it
    NFAPI_MESSAGE_T *message = malloc(sizeof(NFAPI_MESSAGE_T));
    if (message == NULL) {
        free(payload_buffer);
        pthread_mutex_unlock(&arr->mutex);
        return -1;
    }
    message->context_id = context_id;
    message->sequence_number = sequence_number;
    message->payload = payload_buffer;
    // Add the new message to the array
    arr->messages[arr->count] = message;
    arr->count++;
    ret = 0;
    pthread_mutex_unlock(&arr->mutex);
    return ret;
}

void nfapi_destroy_message_array(struct nfapi_message_array *arr) {
    for (size_t i = 0; i < arr->count; i++) {
        free(arr->messages[i]->payload);
        free(arr->messages[i]);
    }
    free(arr->messages);
}
