// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    unsigned short RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG[8];
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically create and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* dynamic_array_creation(int num_structures, int seed) {
    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures);
    if (!arr) {
        printf("Error: Failed to allocate memory for array of NFAPI_CRC_INDICATION_PDU_T structures\n");
        return NULL;
    }

    // Initialize the array with random RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG values
    srand(seed);
    for (int i = 0; i < num_structures; i++) {
        arr[i].RX_UE_INFORMATION_TAG = rand() % 65536;
        arr[i].RNTI = rand() % 65536;
        for (int j = 0; j < 8; j++) {
            arr[i].CRCFLAG[j] = rand() % 256;
        }
    }

    return arr;
}

// Define the function to compute the CRCFLAG efficiently but accurately
void crc_flag_computation(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Compute the CRC using a 32-bit polynomial (x^32 + x^26 + x^23 + x^22 + x^16 + x^12 + x^11 + x^10 + x^8 + x^5 + x^4 + x^3 + x^2 + 1)
    unsigned int poly = 0xEDB88320;
    unsigned char* data = (unsigned char*)pdu;
    unsigned int crc = 0;
    for (int i = 0; i < sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
        crc ^= data[i] << (8 - (i % 4));
        for (int j = 0; j < 8; j++) {
            if (crc & 1) {
                crc = (crc >> 1) ^ poly;
            } else {
                crc >>= 1;
            }
        }
    }
    // Store the computed CRC in the CRCFLAG field of the NFAPI_CRC_INDICATION_PDU_T structure
    memcpy(pdu->CRCFLAG, &crc, sizeof(unsigned int));
}

int main(int argc, char* argv[]) {
    // Parse the command-line arguments to determine the number of structures and seed value for randomization
    if (argc < 3) {
        printf("Usage: %s <num_structures> <seed>\n", argv[0]);
        return 1;
    }
    int num_structures = atoi(argv[1]);
    int seed = atoi(argv[2]);

    // Dynamically create and populate the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* arr = dynamic_array_creation(num_structures, seed);
    if (!arr) {
        printf("Error: Failed to dynamically create and populate the array of NFAPI_CRC_INDICATION_PDU_T structures\n");
        return 1;
    }

    // Compute the CRCFLAG for each structure in the array efficiently but accurately
    for (int i = 0; i < num_structures; i++) {
        crc_flag_computation(&arr[i]);
    }

    // Print the computed CRCFLAG values for each structure in the array
    printf("CRCFLAG values:\n");
    for (int i = 0; i < num_structures; i++) {
        printf("%u\n", arr[i].CRCFLAG[0]);
    }

