// Define the structure for the LTE_DL_FRAME array elements
typedef struct {
    char DL_FRAME[strlenT];
    int CELL_ID;
    int PHY_RX_POWER;
} LTE_DL_FRAME;

// Define the maximum number of frames and their corresponding power levels
#define MAX_NUM_FRAMES 100
#define INITIAL_POWER_LEVEL 30
#define FREQUENCY_OF_EXTERNAL_DATA_UPDATES 5 // in seconds

// Define the array to store the LTE_DL_FRAME structures
LTE_DL_FRAME frames[MAX_NUM_FRAMES];

// Define a mutex for protecting concurrent access to the array
pthread_mutex_t frame_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a condition variable to signal when new data is available
pthread_cond_t new_data_available = PTHREAD_COND_INITIALIZER;

// Function to initialize and populate the array of LTE_DL_FRAME structures
void initFramesAndPopulateData(int strlenT) {
    // Initialize the frames array with the maximum number of frames
    for (int i = 0; i < MAX_NUM_FRAMES; i++) {
        char DL_FRAME[strlenT];
        int CELL_ID;
        int PHY_RX_POWER = INITIAL_POWER_LEVEL - (i / MAX_NUM_FRAMES) * 10;

        // Ensure that the power level is within an acceptable range
        if (PHY_RX_POWER < 0) {
            PHY_RX_POWER = 0;
        } else if (PHY_RX_POWER > 100) {
            PHY_RX_POWER = 100;
        }

        // Store the frame information in the frames array
        frames[i].DL_FRAME = DL_FRAME;
        frames[i].CELL_ID = CELL_ID;
        frames[i].PHY_RX_POWER = PHY_RX_POWER;
    }
}

// Function to handle concurrent requests for frame initialization and population
void *handleConcurrentRequests(void *data) {
    // Define a pointer to the current thread's context
    pthread_t current_thread = (pthread_t) data;

    // Loop until a termination signal is received
    while (1) {
        // Acquire the mutex for protecting concurrent access to the array
        pthread_mutex_lock(&frame_mutex);

        // Check if new data is available and condition variable is signaled
        if (new_data_available == 1) {
            // Update the frames array with the latest data from the external source
            initFramesAndPopulateData(strlenT);

            // Reset the condition variable to prevent unnecessary waiting
            new_data_available = 0;
        }

        // Release the mutex and sleep for a short period of time to allow other threads to acquire it
        pthread_mutex_unlock(&frame_mutex);
        usleep(1000);
    }

    return NULL;
}

// Function to update the frames array with new data from the external source
void updateFramesWithExternalData() {
    // Acquire the mutex for protecting concurrent access to the array
    pthread_mutex_lock(&frame_mutex);

    // Update the frames array with the latest data from the external source
    initFramesAndPopulateData(strlenT);

    // Signal that new data is available and notify all threads waiting on the condition variable
    new_data_available = 1;
    pthread_cond_broadcast(&new_data_available);

    // Release the mutex
    pthread_mutex_unlock(&frame_mutex);
}

// Function to handle network outages gracefully by reinitializing the frames array and resetting the power levels
void handleNetworkOutage() {
    // Acquire the mutex for protecting concurrent access to the array
    pthread_mutex_lock(&frame_mutex);

    // Initialize the frames array with the maximum number of frames
    for (int i = 0; i < MAX_NUM_FRAMES; i++) {
        char DL_FRAME[strlenT];
        int CELL_ID;
        int PHY_RX_POWER = INITIAL_POWER_LEVEL - (i / MAX_NUM_FRAMES) * 10;

        // Ensure that the power level is within an acceptable range
        if (PHY_RX_POWER < 0) {
            PHY_RX_POWER = 0;
        } else if (PHY_RX_POWER > 100) {
            PHY_RX_POWER = 100;
        }

        // Store the frame information in the frames array
        frames[i].DL_FRAME = DL_FRAME;
        frames[i].CELL_ID = CELL_ID;
        frames[i].PHY_RX_POWER = PHY_RX_POWER;
    }

    // Release the mutex and sleep for a short period of time to allow other threads to acquire it
    pthread_mutex_unlock(&frame_mutex);
    usleep(1000);
}
