// Function to establish a connection with a remote address
int connect_to_remote(char *remote_addr) {
    // Acquire mutex for protecting connections array
    pthread_mutex_lock(&connections_mutex);

    // Loop through existing connections and find an unused slot
    int i;
    for (i = 0; i < MAX_CONNECTIONS; i++) {
        if (connections[i].state == CONN_INIT) {
            break;
        }
    }

    // Check if we found an unused slot
    if (i >= MAX_CONNECTIONS) {
        printf("Maximum number of connections reached, cannot establish new connection\n");
        pthread_mutex_unlock(&connections_mutex);
        return -1;
    }

    // Initialize new connection structure
    connections[i].fd = -1;
    connections[i].remote_addr = strdup(remote_addr);
    connections[i].state = CONN_CONNECTING;

    // Release mutex for protecting connections array
