    // Attempt to connect to remote address
    printf("Establishing connection with %s\n", remote_addr);
    int ret = nfapi_crc_indication_pdu_connect(remote_addr, &connections[i].fd);

    // Handle connection attempt failure
    if (ret != 0) {
        printf("Connection failed with error: %s\n", strerror(errno));
        connections[i].state = CONN_INIT;
        return -1;
    }

    // Connection established successfully, update state and return file descriptor
    connections[i].state = CONN_ESTABLISHED;
    printf("Connection established with %s\n", remote_addr);
    return connections[i].fd;
}

// Function to close a connection with a remote address
int close_connection(char *remote_addr) {
    // Acquire mutex for protecting connections array
    pthread_mutex_lock(&connections_mutex);

    // Loop through existing connections and find the specified slot
    int i;
    for (i = 0; i < MAX_CONNECTIONS; i++) {
        if (strcmp(remote_addr, connections[i].remote_addr) == 0) {
            break;
        }
    }

    // Check if we found the specified slot
    if (i >= MAX_CONNECTIONS || connections[i].state == CONN_INIT) {
        printf("No such connection with %s\n", remote_addr);
        pthread_mutex_unlock(&connections_mutex);
        return -1;
    }

    // Close the file descriptor and update state
    int ret = close(connections[i].fd);
    if (ret != 0) {
        printf("Error closing connection with %s: %s\n", remote_addr, strerror(errno));
    } else {
        connections[i].state = CONN_CLOSED;
        printf("Connection closed with %s\n", remote_addr);
    }

    // Release mutex for protecting connections array
    pthread_mutex_unlock(&connections_mutex);

    return ret;
}
