using NFAPI_RXUEINFO_PDU_T = new List<NFAPI_RXUEINFO_PDU_T>;

public static IDataReader ExecuteQueryWithParameters(List<NFAPI_RXUEINFO_PDU_T> list, SqlConnection conn, SqlCommand cmd) {
    try {
        // Set up caching mechanism to reuse database connections and reduce number of round trips
        var connectionPool = new ConnectionPool();
        var cachedConn = connectionPool.GetCachedConnection(conn);

        // Construct parameterized SQL command using the provided list of values
        cmd.CommandText = "SELECT * FROM YourTable WHERE RX_UE_INFORMATION_TAG IN @RX_UE_INFORMATION_TAGS AND RNTI IN @RNTIS";
        var paramTags = new SqlParameter("@RX_UE_INFORMATION_TAGS", list.Select(x => x.RX_UE_INFORMATION_TAG).ToArray());
        var paramRntis = new SqlParameter("@RNTIS", list.Select(x => x.RNTI).ToArray());
        cmd.Parameters.Add(paramTags);
        cmd.Parameters.Add(paramRntis);

        // Execute the parameterized SQL command and retrieve the result set as an IDataReader
        var reader = cmd.ExecuteReader();

        // Handle potential failures in the connection object and handle them gracefully
        if (reader == null) {
            Console.WriteLine("Error executing query");
            return null;
        }

        // Return the result set as an IDataReader
        return reader;
    } catch (Exception e) {
        Console.WriteLine("Exception caught: " + e);
        return null;
    } finally {
        if (conn != null) {
            conn.Close();
        }
    }
}

public class ConnectionPool {
    private readonly Dictionary<SqlConnection, int> connectionCounts = new Dictionary<SqlConnection, int>();

    public SqlConnection GetCachedConnection(SqlConnection conn) {
        if (connectionCounts.ContainsKey(conn)) {
            // Increment the count for this connection in the cache
            connectionCounts[conn]++;
        } else {
            // Add a new entry to the cache with a count of 1 for this connection
            connectionCounts.Add(conn, 1);
        }
        return conn;
    }

    public void ReleaseConnection(SqlConnection conn) {
        if (connectionCounts.ContainsKey(conn)) {
            // Decrement the count for this connection in the cache
            connectionCounts[conn]--;
            if (connectionCounts[conn] == 0) {
                // If the count is 0, remove the entry from the cache and close the connection
                connectionCounts.Remove(conn);
                conn.Close();
            }
        }
    }
}
