// Define the hash function used for hashing the random strings
unsigned int defaultHashFunction(const char* str) {
    unsigned int hash = 5381;
    while (*str != '\0') {
        hash = ((hash << 5) + hash) ^ *str++;
    }
    return hash;
}

// Generate a random string of the specified length using the given character set
char* generateRandomString(const char* charset, int len) {
    // Initialize the random number generator
    srand(time(NULL));

    // Allocate memory for the random string
    char* str = (char*)malloc(len + 1);
    if (!str) {
        return NULL;
    }

    // Generate a random character from the character set and add it to the string
    for (int i = 0; i < len; i++) {
        int index = rand() % strlen(charset);
        str[i] = charset[index];
    }
    str[len] = '\0';

    return str;
}

