        pduList[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        pduList[i].RNTI = rand() % 10000;
        pduList[i].CRC_INDICATION_REL8_TAG = rand() % 10000;
    }

    // Generate a random string for each structure and hash it using the default hash function
    for (int i = 0; i < n; i++) {
