    pthread_mutex_t lock;
};

// Define structure for a single memory block
struct MemoryBlock {
    // Pointer to the next free memory block
    struct MemoryBlock *next_free_block;

    // Pointer to the previous free memory block
    struct MemoryBlock *prev_free_block;

    // Pointer to the allocated data
    void *data;
};

// Initialize memory pool manager
void init_memory_pool_manager(struct MemoryPoolManager *mgr) {
    mgr->num_available_blocks = 0;
    mgr->lock = PTHREAD_MUTEX_INITIALIZER;
}

// Allocate memory block from the pool manager
void *allocate_memory_block(struct MemoryPoolManager *mgr, size_t size) {
    pthread_mutex_lock(&mgr->lock);
    struct MemoryBlock *block = mgr->memory_blocks;
    while (block && block->next_free_block) {
        if (block->size >= size) {
            block->next_free_block = block->next_free_block->prev_free_block;
            break;
        }
        block = block->next_free_block;
    }

    // If no block is found, allocate a new one
    if (!block) {
        block = malloc(sizeof(struct MemoryBlock));
        block->size = size;
        block->next_free_block = NULL;
        block->prev_free_block = NULL;
        block->data = malloc(size);
    } else {
        // Update the available blocks count
        mgr->num_available_blocks--;
    }

    pthread_mutex_unlock(&mgr->lock);

    return block->data;
}

// Free memory block back to the pool manager
void free_memory_block(struct MemoryPoolManager *mgr, void *data) {
    struct MemoryBlock *block = (struct MemoryBlock *)data - 1;

    pthread_mutex_lock(&mgr->lock);
    // Add the block to the list of available blocks
    if (block->prev_free_block) {
        block->prev_free_block->next_free_block = block;
    } else {
        mgr->memory_blocks = block;
    }
    block->next_free_block = NULL;
    block->prev_free_block = mgr->memory_blocks;
    mgr->num_available_blocks++;
    pthread_mutex_unlock(&mgr->lock);
}

// Function to create and populate a list of RX_UE_INFORMATION_TAG structures
void create_crc_indication_pdu(int N, struct MemoryPoolManager *mgr) {
    // Initialize the memory pool manager if necessary
    init_memory_pool_manager(mgr);

    // Allocate memory for the list of RX_UE_INFORMATION_TAG structures
    size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;
    void *data = allocate_memory_block(mgr, size);

    // Populate the list with valid RX_UE_INFORMATION_TAG structures
    int i;
    for (i = 0; i < N; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T *pdu = data + i * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        pdu->RNTI = rand() % 1024; // Generate random RNTI value
        pdu->CRCFLAG = (i % 1024) < 512; // Set CRCFLAG based on pseudo-random sequence
    }

    // Validate the integrity of the populated structures
    for (i = 0; i < N; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T *pdu = data + i * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        assert(pdu->RNTI >= 0 && pdu->RNTI <= 1023); // Validate RNTI range
    }
}

// Function to handle duplicates in the list of RX_UE_INFORMATION_TAG structures
void handle_duplicates(struct MemoryPoolManager *mgr, struct NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if there are any duplicate entries in the list
    for (int i = 0; i < pdu->size / sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
        struct NFAPI_CRC_INDICATION_PDU_T *pdu2 = data + i * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (pdu->RNTI == pdu2->RNTI) {
            // Handle duplicate entries gracefully by logging an error and attempting to reuse previously allocated resources
            fprintf(stderr, "Duplicate RNTI value found in CRC indication PDU\n");
            free_memory_block(mgr, pdu2);
            pdu2->RNTI = -1; // Set invalid RNTI value to indicate duplicate
        }
    }
}

// Function to track and report the number of entries with a CRCFLAG set to true
void track_crc_indications(struct MemoryPoolManager *mgr, struct NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Count the number of entries with a CRCFLAG set to true
    int count = 0;
    for (int i = 0; i < pdu->size / sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
        struct NFAPI_CRC_INDICATION_PDU_T *pdu2 = data + i * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (pdu->CRCFLAG) {
            count++;
        }
    }

    // Report the number of CRCFLAG entries to a log file or console
    fprintf(stderr, "Number of CRC indications with CRCFLAG set to true: %d\n", count);
}
```

