  if (pthread_create(&worker, NULL, resolve_hostname_worker, &query) != 0) {
    perror("pthread_create() failed");
    return -1;
  }

  // Wait for the worker thread to finish and retrieve the DNS response
  pthread_join(worker, NULL);
  dns_query_t* resolved_query = query.resolved_query;

  // Check if the DNS resolution was successful
  if (resolved_query == NULL) {
    printf("DNS resolution failed for %s\n", hostname);
    return -1;
  }

  // Check if the resolved IP address is in the whitelist
  int i;
  for (i = 0; i < 3; i++) {
    if (!strcmp(resolved_query->hostname, whitelist[i])) {
      printf("Resolved hostname %s is in the whitelist\n", resolved_query->hostname);
      break;
    }
  }
  if (i == 3) {
    printf("Resolved hostname %s is not in the whitelist\n", resolved_query->hostname);
  }

  // Clean up resources
  free(resolved_query->hostname);
  free(resolved_query->ipv4);
  free(resolved_query->ipv6);
  free(resolved_query);
  free(whitelist[0]);
  free(whitelist[1]);
  free(whitelist[2]);
  free(whitelist);
  close(sock);

  return 0;
}

// Define a worker thread function to perform DNS resolution
void* resolve_hostname_worker(void* arg) {
  dns_query_t* query = (dns_query_t*)arg;

  // Set up the socket
  int sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
  if (sock < 0) {
    perror("socket() failed");
    return NULL;
  }

  // Set up the DNS query and response buffers
  char* query_buffer = malloc(512);
  size_t query_len = snprintf(query_buffer, 512, "%s\n", query->hostname);
  struct sockaddr_in server;
  memset(&server, 0, sizeof(server));
  server.sin_family = AF_INET;
  server.sin_port = htons(53);
  server.sin_addr.s_addr = inet_addr("8.8.8.8"); // Google DNS IP address
  char* response_buffer = malloc(512);
  size_t response_len = 512;

  // Perform DNS resolution using a timeout mechanism
  struct timeval timeout;
  timeout.tv_sec = timeout;
  timeout.tv_usec = 0;
  if (setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) < 0) {
    perror("setsockopt() failed");
    return NULL;
  }

  // Send the DNS query and receive the response
  sendto(sock, query_buffer, query_len, 0, (struct sockaddr*)&server, sizeof(server));
  recvfrom(sock, response_buffer, response_len, 0, NULL, NULL);

  // Parse the DNS response and extract the IP address
  char* ip = strtok(response_buffer, "\n");
  if (ip == NULL) {
    perror("strtok() failed");
    return NULL;
  }
  int len = strlen(ip);
  if (len >= 16) { // IPv4 address
    query->resolved_query = malloc(sizeof(dns_query_t));
    memcpy(query->resolved_query, &ip[0], 16);
    query->resolved_query->hostname = strdup(query->hostname);
  } else if (len >= 40) { // IPv6 address
    query->resolved_query = malloc(sizeof(dns_query_t));
    memcpy(query->resolved_query, &ip[0], 40);
    query->resolved_query->hostname = strdup(query->hostname);
  } else {
    perror("Unexpected DNS response length");
    return NULL;
  }

  // Clean up resources
  free(query_buffer);
  free(response_buffer);
  close(sock);

  return query->resolved_query;
}
