    std::queue<int> attackQueue;

    // Fill the queue with available attacks
    for (int i = 0; i < 100; ++i) {
        attackQueue.push(i);
    }

    // Create a timer to enforce the cooldown period
    std::chrono::time_point<std::chrono::high_resolution_clock> startTime = std::chrono::high_resolution_clock::now();

    // Populate the list of CRC indications
