// Custom network packet structure
struct Packet {
    uint32_t sourceIP;
    uint32_t destinationIP;
    uint8_t protocolType;
    uint64_t timestamp;
};

// List of packets
struct PacketList {
    struct Packet *packets;
    size_t numPackets;
    size_t capacity;
};

void managePacketList(struct PacketList *list, bool clear) {
    if (clear) {
        // Clear the list and reset all internal states
        free(list->packets);
        list->numPackets = 0;
        list->capacity = 100;
        list->packets = malloc(sizeof(struct Packet) * list->capacity);
    } else {
        // Add new packet to the list and remove duplicates based on source and destination IPs
        size_t index = list->numPackets++;
        struct Packet *packet = &list->packets[index];
        packet->sourceIP = rand() % 256;
        packet->destinationIP = rand() % 256;
        packet->protocolType = rand() % 256;
        packet->timestamp = (uint64_t)time(NULL);

        // Remove duplicates based on source and destination IPs
        for (size_t i = 0; i < list->numPackets; i++) {
            if (list->packets[i].sourceIP == packet->sourceIP && list->packets[i].destinationIP == packet->destinationIP) {
                list->packets[i] = list->packets[--list->numPackets];
            }
        }

        // Handle the addition of packets in real-time with minimal impact on performance
        if (list->numPackets == list->capacity) {
            list->capacity *= 2;
            list->packets = realloc(list->packets, sizeof(struct Packet) * list->capacity);
        }
    }
}
