Here's an example implementation of a modular C library for asynchronous DNS resolution:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/select.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <assert.h>

// Configuration options
#define MAX_CONCURRENT_QUERIES 100
#define CACHE_SIZE 1024 * 1024 // 1 MB cache size
#define EVICTION_POLICY "LRU" // Least Recently Used (LRU) eviction policy
#define DNS_PROVIDER "google" // Default DNS provider

// Cache data structure
typedef struct {
    char* hostname;
    struct in_addr ip;
    time_t ttl; // Time To Live (TTL) in seconds
} cache_entry_t;

cache_entry_t* cache = NULL; // Global cache instance
int cache_size = 0; // Current cache size

// Error codes
#define ERR_SUCCESS 0
#define ERR_DNS_FAILED 1
#define ERR_INVALID_HOSTNAME 2
#define ERR_CACHE_FULL 3
#define ERR_CONCURRENT_QUERIES 4

// Function declarations
int dns_resolve(char* hostname, struct in_addr* ip);
void cache_add(char* hostname, struct in_addr* ip);
cache_entry_t* cache_get(char* hostname);
void cache_evict();

// Function definitions
int dns_resolve(char* hostname, struct in_addr* ip) {
    // Check if the hostname is a valid IP address
    if (inet_pton(AF_INET, hostname, ip) == 1) {
        return ERR_SUCCESS;
    }

    // Check if the hostname is already cached
    cache_entry_t* entry = cache_get(hostname);
    if (entry != NULL) {
        *ip = entry->ip;
        return ERR_SUCCESS;
    }

    // Check for concurrent queries limit
    if (cache_size >= MAX_CONCURRENT_QUERIES) {
        return ERR_CONCURRENT_QUERIES;
    }

    // Perform DNS resolution and cache the result
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        return ERR_DNS_FAILED;
    }

    // Cache the IP address and TTL
    cache_add(hostname, &res->ai_addr->sin_addr);
    *ip = res->ai_addr->sin_addr;

    freeaddrinfo(res);
    return ERR_SUCCESS;
}

void cache_add(char* hostname, struct in_addr* ip) {
    // Check if the cache is full and evict the least recently used entry
    if (cache_size >= CACHE_SIZE) {
        cache_evict();
    }

    // Add the new cache entry
    cache_entry_t* entry = malloc(sizeof(cache_entry_t));
    assert(entry != NULL);
    entry->hostname = strdup(hostname);
    entry->ip = *ip;
    entry->ttl = 3600; // Default TTL of 1 hour

    cache[cache_size++] = entry;
}

cache_entry_t* cache_get(char* hostname) {
    // Check if the hostname is cached
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i]->hostname, hostname) == 0) {
            return cache[i];
        }
    }

    return NULL;
}

void cache_evict() {
    // Evict the least recently used entry based on the eviction policy
    if (strcmp(EVICTION_POLICY, "LRU") == 0) {
        int min_ttl = INT_MAX;
        int index = -1;
        for (int i = 0; i < cache_size; i++) {
            if (cache[i]->ttl < min_ttl) {
                min_ttl = cache[i]->ttl;
                index = i;
            }
        }
        free(cache[index]);
        cache[index] = NULL;
    }
}
