void dynamic_list_creation(int num_of_structures, nfapi_crc_indication_pdu_t **structures) {
    // Check if the input is valid and return an error if it is not
    if (num_of_structures <= 0 || structures == NULL) {
        printf("Invalid input for dynamic list creation. Returning...\n");
        return;
    }

    // Initialize the memory for the structures
    *structures = malloc(sizeof(nfapi_crc_indication_pdu_t) * num_of_structures);
