// Define the function to allocate memory for the array of CRC indication PDUs
NFAPI_CRC_INDICATION_PDU_T* allocateCrcIndicationPduArray(int numElements) {
    // Check if the number of elements is valid
    if (numElements <= 0 || numElements > MAX_CONCURRENT_CALLS) {
        return NULL;
    }

    // Allocate memory for the array of CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T* crcIndicationPduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numElements);
    if (!crcIndicationPduArray) {
        return NULL;
    }

    // Initialize the memory for each element of the array
    for (int i = 0; i < numElements; ++i) {
        crcIndicationPduArray[i].rxUeInformationTag.tag = RX_UE_INFORMATION_TAG;
        crcIndicationPduArray[i].rnti = 0;
        crcIndicationPduArray[i].crcIndicationRel8Tag.tag = CRC_INDICATION_REL8_TAG;
        crcIndicationPduArray[i].crcIndicationRel8Tag.crcFlag = (rand() % 2 == 0) ? 1 : 0;
    }

    return crcIndicationPduArray;
}

// Define the function to free memory for the array of CRC indication PDUs
