    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_INDICATION_LIST_T {
    pthread_mutex_t mutex;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *data;
} NFAPI_CRC_INDICATION_LIST_T;

void init_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    list->mutex = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    list->count = 0;
    list->data = NULL;
}

void destroy_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
}

int add_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= SIZE_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, (list->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    list->data = new_data;
    list->data[list->count++] = *pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, int index) {
    if (index >= list->count || index < 0) {
        return -1;
    }
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, (list->count - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    for (int i = index + 1; i < list->count; i++) {
        new_data[i - 1] = list->data[i];
    }
    list->count--;
    free(list->data);
    list->data = new_data;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int get_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, int index) {
    if (index >= list->count || index < 0) {
        return -1;
    }
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *pdu = &list->data[index];
    pthread_mutex_unlock(&list->mutex);
    return 0;
}
