#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure for NIC configuration details
typedef struct NicConfig {
    char mac_addr[18]; // MAC address of the NIC
    int vlan_id; // VLAN ID for the NIC
    union {
        struct ipv4_config {
            uint32_t addr; // IPv4 address of the NIC
            uint32_t mask; // IPv4 subnet mask
        } ipv4;
        struct ipv6_config {
            uint8_t addr[16]; // IPv6 address of the NIC
            uint8_t prefix; // IPv6 prefix length
        } ipv6;
    } ip_cfg;
    time_t timestamp; // Timestamp for last update
} NicConfig;

// Define a dynamic array for storing NIC configurations
typedef struct NicConfigArray {
    NicConfig** configs; // Array of NIC configuration structures
    size_t size; // Current number of elements in the array
    size_t capacity; // Maximum number of elements that can be stored in the array
} NicConfigArray;

// Initialize a new dynamic array for NIC configurations
NicConfigArray* init_nic_config_array(size_t capacity) {
    NicConfigArray* array = malloc(sizeof(NicConfigArray));
    if (array == NULL) {
        return NULL;
    }
    array->configs = calloc(capacity, sizeof(NicConfig*));
    if (array->configs == NULL) {
        free(array);
        return NULL;
    }
    array->size = 0;
    array->capacity = capacity;
    return array;
}

// Add a new NIC configuration to the dynamic array
bool add_nic_config(NicConfigArray* array, const char* mac_addr, int vlan_id, const union ip_config *ip_cfg) {
    if (array == NULL || mac_addr == NULL || ip_cfg == NULL) {
        return false;
    }
    if (array->size >= array->capacity) {
        // Grow the array by a factor of 2 when it reaches capacity
        size_t new_capacity = array->capacity * 2;
        NicConfig** new_configs = realloc(array->configs, new_capacity * sizeof(NicConfig*));
        if (new_configs == NULL) {
            return false;
        }
        array->configs = new_configs;
        array->capacity = new_capacity;
    }
    NicConfig* config = malloc(sizeof(NicConfig));
    if (config == NULL) {
        return false;
    }
    strncpy(config->mac_addr, mac_addr, 18);
    config->vlan_id = vlan_id;
    memcpy(&config->ip_cfg, ip_cfg, sizeof(union ip_config));
    config->timestamp = time(NULL);
    array->configs[array->size++] = config;
    return true;
}

// Update an existing NIC configuration in the dynamic array
bool update_nic_config(NicConfigArray* array, const char* mac_addr, int vlan_id, const union ip_config *ip_cfg) {
    if (array == NULL || mac_addr == NULL || ip_cfg == NULL) {
        return false;
    }
    for (size_t i = 0; i < array->size; ++i) {
        if (!strncmp(array->configs[i]->mac_addr, mac_addr, 18)) {
            // Found the configuration to update
            NicConfig* config = array->configs[i];
            config->vlan_id = vlan_id;
            memcpy(&config->ip_cfg, ip_cfg, sizeof(union ip_config));
            config->timestamp = time(NULL);
            return true;
        }
    }
    // Configuration not found, add it as a new entry
    return add_nic_config(array, mac_addr, vlan_id, ip_cfg);
}

// Delete an existing NIC configuration from the dynamic array
bool delete_nic_config(NicConfigArray* array, const char* mac_addr) {
    if (array == NULL || mac_addr == NULL) {
        return false;
    }
    for (size_t i = 0; i < array->size; ++i) {
        if (!strncmp(array->configs[i]->mac_addr, mac_addr, 18)) {
            // Found the configuration to delete
            NicConfig* config = array->configs[i];
            free(config);
            --array->size;
            for (size_t j = i; j < array->size; ++j) {
                array->configs[j] = array->configs[j + 1];
            }
            return true;
        }
    }
    // Configuration not found, return false
    return false;
}

// Free the memory used by the dynamic array of NIC configurations
void free_nic_config_array(NicConfigArray* array) {
    if (array == NULL) {
        return;
    }
    for (size_t i = 0; i < array->size; ++i) {
        free(array->configs[i]);
    }
    free(array->configs);
    free(array);
}
