#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the maximum allowed length for P-TMSI values
#define MAX_PTMSI_LEN 10

// Define the valid range for CGI values
#define MIN_CGI 0
#define MAX_CGI 65535

// Define the threshold for the timestamp in seconds
#define TIMESTAMP_THRESHOLD 3600

typedef struct {
    NAS_MESSAGE_T message;
    uint16_t ptmsi;
    char imsi[IMSI_LEN + 1];
    uint8_t qci;
    uint16_t mme_ue_s1ap_id;
    time_t timestamp;
} nas_message_t;

typedef struct {
    size_t capacity;
    size_t count;
    nas_message_t *messages;
} nas_message_list_t;

// Function to create a new NAS message list with the given capacity
nas_message_list_t* nas_message_list_create(size_t capacity) {
    nas_message_list_t *list = malloc(sizeof(nas_message_list_t));
    if (!list) {
        return NULL;
    }

    list->capacity = capacity;
    list->count = 0;
    list->messages = calloc(capacity, sizeof(nas_message_t));
    if (!list->messages) {
        free(list);
        return NULL;
    }

    return list;
}

// Function to add a new NAS message to the list
bool nas_message_list_add(nas_message_list_t *list, const char *imsi, uint16_t ptmsi, uint8_t qci, uint16_t mme_ue_s1ap_id) {
    if (!list || !imsi) {
        return false;
    }

    // Check that the P-TMSI value is within the valid range
    if (ptmsi > MAX_PTMSI_LEN) {
        return false;
    }

    // Check that the CGI value is within the valid range for the given TAI
    if (mme_ue_s1ap_id < MIN_CGI || mme_ue_s1ap_id > MAX_CGI) {
        return false;
    }

    // Check that the timestamp is not too old
    time_t now = time(NULL);
    if (now - list->messages[list->count].timestamp >= TIMESTAMP_THRESHOLD) {
        return false;
    }

    // Add the new message to the list
    nas_message_t *new_message = &list->messages[list->count];
    strncpy(new_message->imsi, imsi, IMSI_LEN);
    new_message->ptmsi = ptmsi;
    new_message->qci = qci;
    new_message->mme_ue_s1ap_id = mme_ue_s1ap_id;
    new_message->timestamp = now;
    list->count++;

    return true;
}

// Function to remove a NAS message from the list by its index
bool nas_message_list_remove(nas_message_list_t *list, size_t index) {
    if (!list || index >= list->count) {
        return false;
    }

    // Shift all messages after the specified index to fill the gap
    for (size_t i = index + 1; i < list->count; i++) {
        list->messages[i - 1] = list->messages[i];
    }

    list->count--;
    return true;
}

// Function to search for a NAS message in the list by its IMSI and MME UE S1AP ID
size_t nas_message_list_search(nas_message_list_t *list, const char *imsi, uint16_t mme_ue_s1ap_id) {
    if (!list || !imsi || list->count == 0) {
        return -1;
    }

    for (size_t i = 0; i < list->count; i++) {
        nas_message_t *message = &list->messages[i];
        if (!strncmp(message->imsi, imsi, IMSI_LEN) && message->mme_ue_s1ap_id == mme_ue_s1ap_id) {
            return i;
        }
    }

    return -1;
}

// Function to update the list with external data source updates
void nas_message_list_update(nas_message_list_t *list, const char *imsi, uint16_t mme_ue_s1ap_id) {
    if (!list || !imsi || list->count == 0) {
        return;
    }

    size_t index = nas_message_list_search(list, imsi, mme_ue_s1ap_id);
    if (index != -1) {
        // Update the existing message with the new information
        nas_message_t *message = &list->messages[index];
        strncpy(message->imsi, imsi, IMSI_LEN);
        message->mme_ue_s1ap_id = mme_ue_s1ap_id;
    } else {
        // Add the new message to the list
        nas_message_list_add(list, imsi, 0, 0, mme_ue_s1ap_id);
    }
}
