    struct tx_packet_tag *tx_packets; // Array of TX packets associated with this frame
    size_t num_tx_packets; // Number of TX packets in the array
    time_t last_modified; // Timestamp representing when the frame was last modified
};

// Structure to represent a single TX packet within a NICP frame
