    size_t payload_length; // Length of the TX packet's payload
    time_t timestamp; // Timestamp representing when the packet was last modified
};

// Function to initialize and manage NICP frames
void init_nicp_frames(struct nicp_frame **frames, size_t num_frames) {
    size_t i;

    // Allocate memory for the array of NICP frames
    *frames = malloc(num_frames * sizeof(**frames));
    if (*frames == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for NICP frames\n");
        exit(1);
    }

    // Initialize each NICP frame with a valid RX session tag, MAC address, and VLAN ID
    for (i = 0; i < num_frames; i++) {
        (*frames)[i].rx_session_tag = rand();
        sprintf((*frames)[i].mac_address, "%02x:%02x:%02x:%02x:%02x:%02x", 
            rand() % 256, rand() % 256, rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        (*frames)[i].vlan_id = rand() % 4096;

        // Initialize each TX packet with a unique sequence number and randomly generated payload length
        size_t j;
        for (j = 0; j < (*frames)[i].num_tx_packets; j++) {
            (*frames)[i].tx_packets[j].sequence_number = rand();
            (*frames)[i].tx_packets[j].payload_length = rand() % 256;
        }
    }
}

// Function to free all resources associated with NICP frames
void destroy_nicp_frames(struct nicp_frame **frames) {
    size_t i;

    // Free the memory allocated for each frame's TX packet array
    for (i = 0; i < (*frames)->num_tx_packets; i++) {
        free((*frames)[i].tx_packets);
    }

    // Free the memory allocated for the frame array itself
    free(*frames);
}
