void manage_crc_list(NF_CRC_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T* new_entry) {
    // Check if the RNTI is unique within the list
    int exists = 0;
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i]->RNTI == new_entry->RNTI) {
            exists = 1;
            break;
        }
    }

    // If the RNTI is unique, add it to the list
    if (!exists) {
        // Check if the list is full and needs to be resized
        if (list->size == list->capacity) {
            // Discard the oldest entry in the list
            NF_CRC_LIST_T* old_entry = list->entries[0];
            free(old_entry);

            // Shift all entries in the list to make room for the new entry
            for (int i = 1; i < list->size; i++) {
                list->entries[i - 1] = list->entries[i];
            }
        }

        // Add the new entry to the end of the list
        list->entries[list->size++] = new_entry;
    } else {
        // If the RNTI is not unique, update the existing entry in the list
        for (int i = 0; i < list->size; i++) {
            if (list->entries[i]->RNTI == new_entry->RNTI) {
                list->entries[i] = new_entry;
                break;
            }
