    // Verbosity level
    int verbose;
    // Logging service URL
    char *logging_url;
};

// Define function to manage configuration settings
void load_configuration(struct Configuration *config) {
    // Load configuration from external JSON file
    FILE *file = fopen("configuration.json", "r");
    if (file == NULL) {
        printf("Error: unable to open configuration file\n");
        exit(1);
    }
    char *buffer;
    size_t len;
    ssize_t read;
    while ((read = getline(&buffer, &len, file)) != -1) {
        // Parse line as JSON object and validate settings
        json_object *obj = json_tokener_parse(buffer);
        if (json_object_is_type(obj, json_type_object)) {
            struct Configuration config;
            config.input_file = json_object_get_string(obj, "input_file");
            config.output_file = json_object_get_string(obj, "output_file");
            config->verbose = json_object_get_int(obj, "verbose");
            config->logging_url = json_object_get_string(obj, "logging_url");
            // Validate configuration settings and exit if any are invalid
            if (config->input_file == NULL || config->output_file == NULL) {
                printf("Error: missing input or output file in configuration\n");
                exit(1);
            } else if (config->verbose < 0 || config->verbose > 3) {
                printf("Error: invalid verbose level in configuration\n");
                exit(1);
            } else if (config->logging_url == NULL) {
                printf("Error: missing logging URL in configuration\n");
                exit(1);
            }
            // Assign validated configuration settings to structure
            *config = config;
        }
    }
}

