// Define maximum number of concurrent calls to the function
#define MAX_CONCURRENT_CALLS 1024

// Define size limit for each allocation
#define ALLOCATION_SIZE_LIMIT (512 * 1024)

// Define synchronization object for access to memory pool
pthread_mutex_t mempool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define memory pool for storing allocated memory blocks
struct MemoryPool {
    // Pointer to next available block in the pool
    void* next_block;
    // Size of the current block in the pool
    size_t block_size;
};
MemoryPool mempool;

// Function to allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_alloc(size_t count) {
    // Check if the request exceeds the maximum number of concurrent calls
    if (count > MAX_CONCURRENT_CALLS) {
        errno = EINVAL;
        return NULL;
    }

    // Calculate the total size required for the allocation
    size_t total_size = count * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Check if the total size exceeds the allocation size limit
    if (total_size > ALLOCATION_SIZE_LIMIT) {
        errno = ENOMEM;
        return NULL;
    }

    // Lock access to memory pool
    pthread_mutex_lock(&mempool_mutex);

    // Check if there is enough space in the memory pool for the allocation
    if (total_size > mempool.block_size - (void*)mempool.next_block) {
        errno = ENOMEM;
        pthread_mutex_unlock(&mempool_mutex);
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)mempool.next_block;
    mempool.next_block += total_size;

    // Unlock access to memory pool
    pthread_mutex_unlock(&mempool_mutex);

    // Initialize the structures with random values for RX_UE_INFORMATION_TAG, RNTI and CRC_INDICATION_REL8_TAG
    for (size_t i = 0; i < count; i++) {
        pdu[i].RX_UE_INFORMATION_TAG.tag = rand();
        pdu[i].RNTI.value = rand();
        pdu[i].CRC_INDICATION_REL8_TAG.tag = rand();
    }

    // Return the allocated memory block
    return pdu;
}

// Function to free memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
void nfapi_crc_indication_pdu_free(NFAPI_CRC_INDICATION_PDU_T* pdu, size_t count) {
    // Lock access to memory pool
    pthread_mutex_lock(&mempool_mutex);

    // Free the memory block for the array of structures
    free(pdu);

    // Unlock access to memory pool
    pthread_mutex_unlock(&mempool_mutex);
}
