#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <net/if.h>
#include <unistd.h>
#include <errno.h>

#define BUFFER_SIZE 1024
#define NIC_NAME_LENGTH 16
#define NIC_DESCRIPTION_LENGTH 64

struct nic_stats {
    char name[NIC_NAME_LENGTH];
    char description[NIC_DESCRIPTION_LENGTH];
    long packets_received;
    long packets_sent;
    long bytes_received;
    long bytes_sent;
    float packet_loss_rate;
    float latency;
    float throughput;
    float avg_bandwidth_utilization;
};

struct nic_stats* initialize_nic_stats(char* name) {
    struct nic_stats* stats = malloc(sizeof(struct nic_stats));
    if (!stats) {
        return NULL;
    }

    strncpy(stats->name, name, NIC_NAME_LENGTH);
    strncpy(stats->description, "NA", NIC_DESCRIPTION_LENGTH);
    stats->packets_received = 0;
    stats->packets_sent = 0;
    stats->bytes_received = 0;
    stats->bytes_sent = 0;
    stats->packet_loss_rate = 0.0f;
    stats->latency = 0.0f;
    stats->throughput = 0.0f;
    stats->avg_bandwidth_utilization = 0.0f;

    return stats;
}

int populate_nic_stats(struct nic_stats* stats) {
    int sock, ifindex;
    struct ifreq ifr;
    unsigned char buffer[BUFFER_SIZE];
    struct ethtool_drvinfo drvinfo = {0};
    struct ethtool_gstrings gstrings = {0};
    struct ethtool_estats estats = {0};
    int ret, nstats;

    // Get the interface index from the name
    ifindex = if_nametoindex(stats->name);
    if (ifindex == 0) {
        return -1;
    }

    // Open the socket for the ioctl() calls
    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket() failed");
        return -2;
    }

    // Get the driver information
    strncpy(ifr.ifr_name, stats->name, NIC_NAME_LENGTH - 1);
    ifr.ifr_data = (void*)&drvinfo;
    ret = ioctl(sock, SIOCETHTOOL, &ifr);
    if (ret < 0) {
        perror("ioctl() failed");
        return -3;
    }

    // Get the number of statistics supported by the driver
    strncpy(ifr.ifr_name, stats->name, NIC_NAME_LENGTH - 1);
    ifr.ifr_data = (void*)&gstrings;
    ret = ioctl(sock, SIOCETHTOOL, &ifr);
    if (ret < 0) {
        perror("ioctl() failed");
        return -4;
    }

    // Get the statistics values
    nstats = gstrings.cmd_nr;
    strncpy(ifr.ifr_name, stats->name, NIC_NAME_LENGTH - 1);
    ifr.ifr_data = (void*)&estats;
    ret = ioctl(sock, SIOCETHTOOL, &ifr);
    if (ret < 0) {
        perror("ioctl() failed");
        return -5;
    }

    // Calculate the packet loss rate
    stats->packet_loss_rate = (float)(estats.rx_dropped + estats.tx_dropped) / (estats.rx_packets + estats.tx_packets);

    // Calculate the latency
    stats->latency = (float)(estats.rx_over_errors + estats.rx_crc_errors + estats.collisions) / (estats.rx_packets + estats.tx_packets);

    // Calculate the throughput
    stats->throughput = (float)(estats.rx_bytes + estats.tx_bytes) / 1024;

    // Calculate the average bandwidth utilization percentage for the past hour
    if (estats.tx_packets > 0 && estats.tx_bytes > 0) {
        stats->avg_bandwidth_utilization = (float)(estats.tx_bytes * 8 / 1024) / (float)(clock() - clock());
    }

    close(sock);

    return 0;
}

int update_nic_stats(struct nic_stats* stats, int interval) {
    struct timespec current_time;
    long packets_received, packets_sent;
    long bytes_received, bytes_sent;

    clock_gettime(CLOCK_MONOTONIC, &current_time);
    if (stats->prev_time.tv_sec == 0) {
        stats->prev_time = current_time;
        return populate_nic_stats(stats);
    } else {
        packets_received = get_network_metric("rx_packets");
        packets_sent = get_network_metric("tx_packets");
        bytes_received = get_network_metric("rx_bytes");
        bytes_sent = get_network_metric("tx_bytes");

        stats->packet_loss_rate = (float)(stats->packets_received - packets_received + stats->packets_sent - packets_sent) / interval;
        stats->latency = (float)(stats->rx_over_errors - get_network_metric("rx_over_errors") + stats->rx_crc_errors - get_network_metric("rx_crc_errors") + stats->collisions - get_network_metric("collisions")) / interval;
        stats->throughput = (float)(stats->rx_bytes - bytes_received + stats->tx_bytes - bytes_sent) / 1024 / interval;
        if (stats->tx_packets > 0 && stats->tx_bytes > 0) {
            stats->avg_bandwidth_utilization = (float)(stats->tx_bytes * 8 / 1024) / (float)(clock() - clock());
        }

        stats->prev_time = current_time;
    }

    return populate_nic_stats(stats);
}

int get_network_metric(char* metric) {
    struct ifreq ifr;
    int socket_fd, result;
    char buffer[1024];

    // Open the raw socket for ioctl() calls
    socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        perror("socket() failed");
        return -1;
    }

    // Get the interface name using ioctl()
    strncpy(ifr.ifr_name, metric, NIC_NAME_LENGTH - 1);
    result = ioctl(socket_fd, SIOCGIFNAME, &ifr);
    if (result < 0) {
        perror("ioctl() failed");
        return -2;
    }

    // Close the socket
    close(socket_fd);

    // Get the metric value using getifaddrs()
    struct ifaddrs* addrs, * tmp;
    result = getifaddrs(&addrs);
    if (result < 0) {
        perror("getifaddrs() failed");
        return -3;
    }

    // Find the interface address structure using the interface name
    for (tmp = addrs; tmp != NULL; tmp = tmp->ifa_next) {
        if (strcmp(ifr.ifr_name, tmp->ifa_name) == 0) {
            result = strtol(tmp->ifa_data, buffer, 10);
            break;
        }
    }

    // Free the memory allocated for the interface addresses
    freeifaddrs(addrs);

    return result;
}

int main() {
    struct nic_stats stats[5];
    int i, j;

    for (i = 0; i < 5; i++) {
        strncpy(stats[i].iface_name, "eth0", NIC_NAME_LENGTH - 1);
        populate_nic_stats(&stats[i]);
    }

    // Update the network statistics every second
    for (j = 0; j < 5; j++) {
        update_nic_stats(&stats[j], 1);
    }

    return 0;
}
```

This code first defines a `struct` to represent the network interface stats, including the interface name and the statistics values. It then defines a function called `populate_nic_stats()` that retrieves the current network statistics for a given interface using the `ioctl()` system call. The `update_nic_stats()` function updates the network statistics every second using the `getifaddrs()` system call, and stores the updated values in the `struct`. Finally, the main function demonstrates how to use the functions to retrieve and update the network statistics for a given interface.

Note that this code is just an example of how to retrieve and update network statistics, and may not be suitable for all use cases. For instance, you may want to consider using a different system call or library function depending on your specific needs. Additionally, you should make sure to handle errors appropriately in your code and check the documentation for each system call and library function you are using to understand their behavior and limitations.']

