#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/queue.h>

#define MAX_CONCURRENT_CALLS 1024
#define MEMORY_LIMIT 512 * 1024
#define MIN_MEMORY_PER_ALLOCATION (sizeof(NFAPI_CRC_INDICATION_PDU_T) + sizeof(RX_UE_INFORMATION_TAG))
#define MAX_MEMORY_PER_ALLOCATION 10 * 1024 * 1024
#define CRCFLAG true

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG RX_UE_INFORMATION;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8;
} NFAPI_CRC_INDICATION_PDU_T;

struct memory_pool {
    size_t total_size;
    size_t free_size;
    void *free_head;
};

struct allocation_request {
    struct memory_pool *memory_pool;
    size_t requested_size;
    void *allocation;
    int status;
};

struct backlogged_request {
    struct allocation_request request;
    TAILQ_ENTRY(backlogged_request) entries;
};

struct connection_info {
    size_t total_allocated;
    size_t free_capacity;
    TAILQ_HEAD(, backlogged_request) backlog;
};

struct memory_pool *memory_pools[MAX_CONCURRENT_CALLS];
struct connection_info connections[MAX_CONCURRENT_CALLS];

void *allocate_memory(size_t size, int connection_id) {
    struct memory_pool *memory_pool = memory_pools[connection_id];
    void *allocation = NULL;

    if (size > MEMORY_LIMIT) {
        return NULL;
    }

    // Allocate from the free list first
    allocation = memory_pool->free_head;
    if (allocation != NULL) {
        memory_pool->free_head = (void *)((size_t)allocation + size);
        return allocation;
    }

    // If the free list is empty, allocate a new chunk of memory from the system
    allocation = malloc(size);
    if (allocation == NULL) {
        return NULL;
    }

    memory_pool->total_size += size;
    memory_pool->free_size += size;

    return allocation;
}

void free_memory(void *allocation, int connection_id) {
    struct memory_pool *memory_pool = memory_pools[connection_id];
    if (memory_pool->free_head == NULL) {
        memory_pool->free_head = allocation;
    } else {
        ((void **)memory_pool->free_head)[-1] = allocation;
    }
    memory_pool->free_size += MIN_MEMORY_PER_ALLOCATION;
}

int create_connection(int connection_id) {
    if (connection_id >= MAX_CONCURRENT_CALLS) {
        return -1;
    }
    struct memory_pool *memory_pool = malloc(sizeof(struct memory_pool));
    if (memory_pool == NULL) {
        return -1;
    }
    memory_pools[connection_id] = memory_pool;
    connections[connection_id].total_allocated = 0;
    connections[connection_id].free_capacity = MEMORY_LIMIT;
    TAILQ_INIT(&connections[connection_id].backlog);
}

void destroy_connection(int connection_id) {
    struct memory_pool *memory_pool = memory_pools[connection_id];
    free(memory_pool);
    memory_pools[connection_id] = NULL;
}

int allocate_array(size_t size, void **array, int connection_id) {
    if (size > MEMORY_LIMIT || size % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0) {
        return -1;
    }

    struct allocation_request request = {memory_pools[connection_id], size};
    TAILQ_INSERT_TAIL(&connections[connection_id].backlog, &request, entries);

    return 0;
}

void deallocate_array(void *array, int connection_id) {
