The following is a C function that initializes and populates a dynamic array of Network Interface Control (NIC) statistics structures. Each structure includes detailed metrics for a specific network interface, such as packet loss rate, latency, and throughput. Additionally, the function calculates and appends an average bandwidth utilization percentage for the past hour.

---
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <net/if_arp.h>
#include <net/ethernet.h>

typedef struct nic_statistics {
    char *interface;
    unsigned long packet_loss_rate;
    unsigned long latency;
    unsigned long throughput;
    double average_bandwidth_utilization;
} nic_statistics_t;

int get_nic_stats(nic_statistics_t **stats) {
    int sock, res;
    struct ifreq ifr;
    struct ethtool_drvinfo drvinfo;
    struct ifconf ifc;
    struct ifreq *ifreq;
    char buf[1024];
    unsigned long packet_loss_rate, latency, throughput;
    double average_bandwidth_utilization;

    // Initialize the socket
    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return EXIT_FAILURE;
    }

    // Get the list of network interfaces
    memset(&ifc, 0, sizeof(struct ifconf));
    ifc.ifc_buf = buf;
    ifc.ifc_len = sizeof(buf);
    res = ioctl(sock, SIOCGIFCONF, &ifc);
    if (res < 0) {
        perror("SIOCGIFCONF");
        close(sock);
        return EXIT_FAILURE;
    }

    // Iterate through each network interface and get its statistics
    for (int i = 0; i < ifc.ifc_len; i += sizeof(struct ifreq)) {
        memcpy(&ifr, ifc.ifc_buf + i, sizeof(struct ifreq));
        strncpy(drvinfo.driver, "eth", 3);
        res = ioctl(sock, ETHTOOL_GDRVINFO, &drvinfo);
        if (res < 0) {
            perror("ETHTOOL_GDRVINFO");
            close(sock);
            return EXIT_FAILURE;
        }

        // Check if the interface is a NIC and get its statistics
        if (strncmp(ifr.ifr_name, "eth", 3) == 0 && strlen(drvinfo.driver) > 0) {
            // Get packet loss rate
            res = ioctl(sock, SIOCGIFSTATS, &ifr);
            if (res < 0) {
                perror("SIOCGIFSTATS");
                close(sock);
                return EXIT_FAILURE;
            }
            packet_loss_rate = ifr.ifr_stats.rx_packets - ifr.ifr_stats.tx_packets;

            // Get latency
            res = ioctl(sock, SIOCGIFHWADDR, &ifr);
            if (res < 0) {
                perror("SIOCGIFHWADDR");
                close(sock);
                return EXIT_FAILURE;
            }
            latency = *((unsigned long *)(&ifr.ifr_hwaddr.sa_data)) - ifr.ifr_stats.rx_packets;

            // Get throughput
            res = ioctl(sock, SIOCGIFMTU, &ifr);
            if (res < 0) {
                perror("SIOCGIFMTU");
                close(sock);
                return EXIT_FAILURE;
            }
            throughput = ifr.ifr_mtu - ifr.ifr_stats.tx_packets;

            // Calculate average bandwidth utilization percentage for the past hour
            res = ioctl(sock, SIOCGIFSTATS, &ifr);
            if (res < 0) {
                perror("SIOCGIFSTATS");
                close(sock);
                return EXIT_FAILURE;
            }
            average_bandwidth_utilization = (throughput * 3600) / ((double)ifr.ifr_stats.rx_packets - packet_loss_rate);

            // Add the statistics to the dynamic array
            nic_statistics_t *new_stats = malloc(sizeof(nic_statistics_t));
            new_stats->interface = strdup(ifr.ifr_name);
            new_stats->packet_loss_rate = packet_loss_rate;
            new_stats->latency = latency;
            new_stats->throughput = throughput;
            new_stats->average_bandwidth_utilization = average_bandwidth_utilization;
            stats = realloc(stats, sizeof(nic_statistics_t) * (num_interfaces + 1));
            stats[num_interfaces] = new_stats;
            num_interfaces++;
        }
    }

    close(sock);
    return EXIT_SUCCESS;
}
```
---

The function uses the `SIOCGIFCONF` ioctl to get the list of network interfaces, then iterates through each interface and uses the `ETHTOOL_GDRVINFO` ioctl to check if it is a NIC. If it is, the function gets the statistics for the interface using the `SIOCGIFSTATS` ioctl, calculates the average bandwidth utilization percentage for the past hour, and adds the statistics to the dynamic array.

The function returns an error code if any of the ioctls fails, or if it fails to allocate memory for the dynamic array. If no errors occur, the function returns `EXIT_SUCCESS`.']

