    STATE_C,
} state_t;

// Data structures to hold the current and next state
state_t curr_state = STATE_A;
state_t next_state = STATE_A;

// Function to validate and sanitize state transitions
bool isValidTransition(state_t from, state_t to) {
    // Check if the transition is valid based on the current state
    bool valid = true;

    switch (from) {
        case STATE_A:
            if (to != STATE_B && to != STATE_C) {
                valid = false;
            }
            break;
        case STATE_B:
            if (to == STATE_A || to == STATE_C) {
                valid = false;
            }
            break;
        case STATE_C:
            if (to != STATE_A && to != STATE_B) {
                valid = false;
            }
            break;
    }

    return valid;
}

// Function to handle incoming data and transition the state machine
void handleData(const char* data, size_t len) {
    // Parse the incoming data to determine the next state
    state_t next_state = STATE_A;

    if (strncmp(data, "a", 1) == 0) {
        next_state = STATE_B;
    } else if (strncmp(data, "b", 1) == 0) {
        next_state = STATE_C;
    } else if (strncmp(data, "c", 1) == 0) {
        next_state = STATE_A;
    }

    // Validate the transition and update the current state
    bool valid = isValidTransition(curr_state, next_state);
    if (valid) {
        curr_state = next_state;
    } else {
        printf("Invalid transition from %d to %d\n", curr_state, next_state);
    }
}

// Function to log state transitions and ensure the integrity of state data post-transition
