// Structure for TickerEvents
typedef struct {
    int timestamp;
    char event_type[20];
    int unique_identifier;
} TickerEvent;

// List of TickerEvents
TickerEvent *event_list = NULL;
size_t list_size = 0;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the event log system
void init_event_log(int max_events) {
    // Allocate memory for the list of events
    event_list = malloc(max_events * sizeof(TickerEvent));
    memset(event_list, 0, max_events * sizeof(TickerEvent));
    list_size = max_events;
}

// Function to append a new event to the list
void append_event(int timestamp, char *event_type, int unique_identifier) {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // Check if the list is full and needs to be resized
    if (list_size == 0 || list_size == event_list->count) {
        resize_event_list();
    }

    // Add new event to the end of the list
    TickerEvent *new_event = &event_list[event_list->count++];
    new_event->timestamp = timestamp;
    strcpy(new_event->event_type, event_type);
    new_event->unique_identifier = unique_identifier;

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve the last N events from the list
TickerEvent *get_last_events(int n) {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // Check if the list is empty
    if (event_list->count == 0) {
        return NULL;
    }

    // Calculate the index of the last event
    int last_index = event_list->count - n;

    // Create a new array to hold the events
    TickerEvent *events = malloc(n * sizeof(TickerEvent));

    // Copy the last N events from the list into the new array
    for (int i = 0; i < n; i++) {
        memcpy(&events[i], &event_list[last_index + i], sizeof(TickerEvent));
    }

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);

    return events;
}

// Function to resize the event list when it becomes full
void resize_event_list() {
    // Double the size of the list
    list_size *= 2;

    // Allocate new memory for the resized list
    TickerEvent *new_list = malloc(list_size * sizeof(TickerEvent));

    // Copy the old list into the new one
    memcpy(new_list, event_list, (event_list->count * sizeof(TickerEvent)));

    // Free the old list and update the pointer to the new one
    free(event_list);
    event_list = new_list;
}

// Function to garbage collect expired events from the list
void garbage_collect() {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // Check if there are any expired events in the list
    int i = 0;
    while (i < event_list->count && event_list[i].timestamp < get_current_time()) {
        // Free the memory associated with the event
        free(&event_list[i]);

        // Move all subsequent events back one index
        for (int j = i + 1; j < event_list->count; j++) {
            memcpy(&event_list[j - 1], &event_list[j], sizeof(TickerEvent));
        }

        // Decrement the count of events in the list
        event_list->count--;
    }

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}

// Function to integrate the event log with an external database for archiving older events
void archive_events() {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // Iterate through the list of events and archive each one
    for (int i = 0; i < event_list->count; i++) {
        // Archive the event with an external database
        archive_event(event_list[i]);
    }

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}

// Function to decide on a strategy for garbage collection of expired events
void garbage_collect_strategy() {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // Check if the list is more than half full and needs to be resized
    if (event_list->count > list_size / 2) {
        resize_event_list();
    }

    // Garbage collect expired events from the list
    garbage_collect();

    // Release lock on mutex
    pthread_mutex_unlock(&mutex);
}

// Function to design the function for future extensions, such as adding support for geolocation data or integrating with additional third-party systems
void extend_functionality() {
    // Acquire lock on mutex
    pthread_mutex_lock(&mutex);

    // Check if there are any events in the list that require geolocation data
    for (int i = 0; i < event_list->count; i++) {
        // If the event requires geolocation data, add it to the list
        if (event_list[i].geolocation == NULL) {
