// Function to initialize and populate a list of TickerEvents
void initAndPopulateTickerEventList(struct TickerEventList* list, uint8_t eventType, char* id) {
    // Initialize the list with a capacity of 1024 events
    list->capacity = 1024;
    list->size = 0;
    list->tail = 0;
    list->events = malloc(sizeof(TickerEvent*) * list->capacity);
    assert(list->events != NULL);

    // Loop through the events and populate the list
    for (int i = 0; i < list->capacity; i++) {
        TickerEvent* event = malloc(sizeof(TickerEvent));
        assert(event != NULL);
        event->timestamp = time(NULL);
        event->eventType = eventType;
        event->id = id;
        list->events[i] = event;
    }
}

// Function to append a new TickerEvent to the list, thread-safe
void appendTickerEventToList(struct TickerEventList* list, uint8_t eventType, char* id) {
    // Ensure that we have enough capacity for the new event
    if (list->size == list->capacity) {
        // Increase the capacity by 50% to ensure efficient growth
        list->capacity = list->capacity * 1.5;
        list->events = realloc(list->events, sizeof(TickerEvent*) * list->capacity);
        assert(list->events != NULL);
