    // Create a new TickerEvent and append it to the list
    TickerEvent* event = malloc(sizeof(TickerEvent));
    assert(event != NULL);
    event->timestamp = time(NULL);
    event->eventType = eventType;
    event->id = id;
    list->events[list->tail] = event;

    // Increment the tail and size of the list
    list->tail++;
    if (list->tail == list->capacity) {
        list->tail = 0;
    }
    list->size++;
}

// Function to retrieve the last N events from the list, thread-safe
