// Function to filter out invalid PDUs based on a configurable SNR threshold, optimizing for both performance and usability
void filter_mac_pdu_array(MAC_PDU_T **mac_pdu_array, int *num_pdus) {
  // Define variables for tracking the number of valid PDUs and memory usage
  int total_valid_pdus = 0;
  size_t total_memory = 0;

