// Function to parse a PDCP_PDU and corresponding SNR value from a line of the input file, optimizing for both performance and usability
int parse_pdcp_pdu(char *line, PDCP_PDU *pdcp_pdu, float *snr) {
  // Define variables for tracking the number of tokens and memory usage
  int token_count = 0;
  size_t total_memory = 0;

  // Split the line into tokens using the delimiter ','
  char **tokens = strsplit(line, ',');
  if (tokens == NULL) {
    return -1;
  }

  // Parse each token and populate the PDCP_PDU structure
  for (int i = 0; i < MAX_TOKENS; i++) {
    if (strcmp(tokens[i], "PDCP_PDU") == 0) {
      pdcp_pdu->pdcp_header.present = PDCP_HEADER_PRESENT;
      token_count++;
    } else if (strcmp(tokens[i], "SN") == 0) {
      pdcp_pdu->sn.present = SN_PRESENT;
      token_count++;
    } else if (strcmp(tokens[i], "RNTI") == 0) {
      pdcp_pdu->rnti.present = RNTI_PRESENT;
      token_count++;
    } else if (strcmp(tokens[i], "CID") == 0) {
      pdcp_pdu->cid.present = CID_PRESENT;
      token_count++;
    } else if (strcmp(tokens[i], "DATA") == 0) {
      pdcp_pdu->data.present = DATA_PRESENT;
      token_count++;
    } else if (strcmp(tokens[i], "STATUS") == 0) {
      pdcp_pdu->status.present = STATUS_PRESENT;
      token_count++;
    } else if (strcmp(tokens[i], "SNRC") == 0) {
      pdcp_pdu->snrc.present = SNRC_PRESENT;
      token_count++;
    } else {
      // Log an error if a token is not recognized
      printf("Error: Token %s not recognized in file %s\n", tokens[i], "");
      free(tokens);
      return -1;
    }
  }

  // Parse the SNR value from the line
  char *snr_string = strstr(line, "SNR=") + 4;
  if (sscanf(snr_string, "%f", snr) != 1) {
    printf("Error: Failed to parse SNR value from file %s\n", "");
    free(tokens);
    return -1;
  }

  // Free the tokens and return the number of tokens parsed
  total_memory += sizeof(char *) * token_count;
  for (int i = 0; i < token_count; i++) {
    free(tokens[i]);
  }
  free(tokens);
  printf("Total memory usage: %zu bytes\n", total_memory);
  return token_count;
}

// Function to split a string into tokens using the delimiter ',' and allocate memory for each token, optimizing for both performance and usability
char **strsplit(const char *str, const char delim) {
  // Define variables for tracking the number of tokens and memory usage
  int token_count = 0;
  size_t total_memory = 0;

  // Count the number of tokens in the input string
  const char *token = strtok((char *)str, delim);
  while (token != NULL) {
    token_count++;
    token = strtok(NULL, delim);
  }

  // Allocate memory for each token and store them in an array of pointers
  total_memory += sizeof(char *) * token_count;
  char **tokens = malloc(sizeof(char *) * token_count);
  if (tokens == NULL) {
    return NULL;
  }
  token = strtok((char *)str, delim);
  for (int i = 0; i < token_count; i++) {
    tokens[i] = malloc(sizeof(char) * (strlen(token) + 1));
    if (tokens[i] == NULL) {
      return NULL;
    }
    strcpy(tokens[i], token);
    total_memory += sizeof(char) * (strlen(token) + 1);
    token = strtok(NULL, delim);
  }

  // Return the array of pointers to tokens
  printf("Total memory usage: %zu bytes\n", total_memory);
  return tokens;
