    if (num_frames >= max_frames) {
        return false; // no space left in the array
    }
    LTE_DL_FRAMEINFO* new_frame = malloc(sizeof(LTE_DL_FRAMEINFO));
    if (!new_frame) {
        return false; // failed to allocate memory for the frame
    }
    new_frame->frame_number = frame_number;
    new_frame->bsr_info = bsr_info;
    size_t old_size = num_frames * sizeof(LTE_DL_FRAMEINFO*);
    size_t new_size = (num_frames + 1) * sizeof(LTE_DL_FRAMEINFO*);
    frame_array = realloc(frame_array, new_size);
    if (!frame_array) {
        free(new_frame);
        return false; // failed to allocate memory for the array
    }
