void initHashTable(int numBuckets) {
    // Allocate memory for the hash table
    hashTable = (struct CUSTOMER_TRANSACTION_RECORD**)malloc(numBuckets * sizeof(struct CUSTOMER_TRANSACTION_RECORD*));
    if (hashTable == NULL) {
        // Handle memory allocation failure gracefully
        return;
    }

    // Initialize the hash table with a specified number of buckets
    for (int i = 0; i < numBuckets; i++) {
        hashTable[i] = NULL;
    }
}

// Function to insert a new transaction record into the hash table
void insertTransactionRecord(struct CUSTOMER_TRANSACTION_RECORD* record) {
    // Calculate the hash value for the record's transaction ID
    int hashValue = calculateHashValue(record->transactionID);

    // Check if a bucket exists at the calculated hash value
    struct CUSTOMER_TRANSACTION_RECORD* existingRecord = getBucket(hashTable, hashValue);
    if (existingRecord != NULL) {
        // Handle collision gracefully by chaining records together
        while (existingRecord->next != NULL) {
            existingRecord = existingRecord->next;
        }
        existingRecord->next = record;
    } else {
        // Insert the new record into the bucket
        hashTable[hashValue] = record;
    }
}

// Function to retrieve a transaction record from the hash table
struct CUSTOMER_TRANSACTION_RECORD* getTransactionRecord(int transactionID) {
    int hashValue = calculateHashValue(transactionID);
    struct CUSTOMER_TRANSACTION_RECORD* existingRecord = getBucket(hashTable, hashValue);
    if (existingRecord != NULL) {
        while (existingRecord->next != NULL && existingRecord->transactionID != transactionID) {
            existingRecord = existingRecord->next;
        }
        if (existingRecord->transactionID == transactionID) {
            return existingRecord;
        }
    }
    return NULL;
}

// Function to calculate the hash value for a given transaction ID
int calculateHashValue(int transactionID) {
    // Use a simple modulo-based hash function
    return transactionID % numBuckets;
}

// Function to get a bucket from the hash table based on its hash value
struct CUSTOMER_TRANSACTION_RECORD* getBucket(struct CUSTOMER_TRANSACTION_RECORD** hashTable, int hashValue) {
    return hashTable[hashValue];
}
