// Structure to represent a PDU in the array
struct PDU {
    struct RX_UE_INFORMATION_TAG rx_info;
    int crc_indication_rel8;
    struct PDCP_PDU pdcp_pdu;
};

// Structure to represent a structure in the array
struct UE_INFO {
    int rnti;
    double snr;
    struct PDU *pdu_array;
};

// Function to generate a random number between 0 and max
int get_random(int max) {
    return rand() % max;
}

// Function to add a new UE to the array
struct UE_INFO* add_ue(struct UE_INFO *array, int rnti, double snr) {
    // Allocate memory for the new UE
    struct UE_INFO *new_ue = malloc(sizeof(struct UE_INFO));
    if (new_ue == NULL) {
        perror("Error allocating memory for new UE");
        exit(1);
    }

    // Initialize the fields of the new UE
    new_ue->rnti = rnti;
    new_ue->snr = snr;
    new_ue->pdu_array = NULL;

    // Add the new UE to the array
    if (array == NULL) {
        array = new_ue;
    } else {
        struct UE_INFO *cur = array;
        while (cur->next != NULL) {
            cur = cur->next;
        }
        cur->next = new_ue;
    }

    return new_ue;
}

// Function to add a new PDU to the array of a given UE
void add_pdu(struct UE_INFO *ue, struct PDU *new_pdu) {
    // Check if the PDU is already present in the array
    bool pdu_present = false;
    for (int i = 0; i < ue->num_pdus; i++) {
        if (memcmp(ue->pdu_array[i].rx_info.tag, new_pdu->rx_info.tag, sizeof(new_pdu->rx_info.tag)) == 0 &&
            memcmp(ue->pdu_array[i].pdcp_pdu.data, new_pdu->pdcp_pdu.data, sizeof(new_pdu->pdcp_pdu.data)) == 0) {
            pdu_present = true;
            break;
        }
    }

    // If the PDU is not present in the array, add it
    if (!pdu_present) {
        ue->num_pdus++;
        ue->pdu_array = realloc(ue->pdu_array, sizeof(struct PDU) * ue->num_pdus);
        memcpy(&ue->pdu_array[ue->num_pdus - 1], new_pdu, sizeof(struct PDU));
    }
}

// Function to read data from multiple input files and merge them into a single output array
void merge_data(char **filenames, int num_files, struct UE_INFO **output) {
    // Initialize the output array
    *output = NULL;

    // Read data from each file and add it to the output array
    for (int i = 0; i < num_files; i++) {
        FILE *file = fopen(filenames[i], "r");
        if (file == NULL) {
            perror("Error opening input file");
            exit(1);
        }

        // Read data from the file and add it to the output array
        struct UE_INFO *ue = NULL;
        while (!feof(file)) {
            struct PDU new_pdu;
            fread(&new_pdu, sizeof(struct PDU), 1, file);
            if (new_pdu.rx_info.tag[0] == '\0') {
                // If the PDU is invalid, skip it
                continue;
            }

            ue = add_ue(*output, new_pdu.rx_info.rnti, new_pdu.rx_info.snr);
            add_pdu(ue, &new_pdu);
        }

        // Close the file
        fclose(file);
    }
}

// Function to filter out invalid PDUs based on a given SNR threshold
void filter_pdus(struct UE_INFO *array, double snr_threshold) {
    // Traverse the array and filter out invalid PDUs
    for (int i = 0; i < array->num_pdus; i++) {
        if (array->pdu_array[i].rx_info.snr < snr_threshold) {
            memcpy(&array->pdu_array[i], &array->pdu_array[i+1], sizeof(struct PDU));
            array->num_pdus--;
            i--;
        }
    }
}

// Function to handle errors and warnings encountered during execution
void log_message(char *message) {
    printf("Error/Warning: %s\n", message);
}

// Main function for the program
int main() {
    // Initialize random number generator
    srand(time(NULL));

    // Declare variables to store input and output files
    char **filenames = NULL;
    int num_files = 0;
    struct UE_INFO *output = NULL;

    // Prompt the user for the number of input files
    printf("Enter the number of input files: ");
    scanf("%d", &num_files);

    // Allocate memory for the input and output files
    filenames = malloc(sizeof(char*) * num_files);
    if (filenames == NULL) {
        perror("Error allocating memory for input files");
        exit(1);
    }

    // Prompt the user for each file name and store it in an array
    for (int i = 0; i < num_files; i++) {
        filenames[i] = malloc(MAX_FILENAME_LENGTH * sizeof(char));
        if (filenames[i] == NULL) {
            perror("Error allocating memory for file name");
            exit(1);
        }
        printf("Enter the name of input file %d: ", i+1);
        scanf("%s", filenames[i]);
    }

    // Call the function to read data from each file and merge it into a single output array
    merge_data(filenames, num_files, &output);

    // Print the number of valid PDUs in the output array
    printf("Number of valid PDUs: %d\n", output->num_pdus);

    // Filter out invalid PDUs based on a given SNR threshold
    filter_pdus(output, 5.0);

    // Print the number of valid PDUs in the filtered array
    printf("Number of valid PDUs after filtering: %d\n", output->num_pdus);

    return 0;
}']

