// Define the function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void createAndPopulateNfapiCrcIndicationList(int minRnti, int maxRnti, int numElements) {
    // Initialize an empty list for the NFAPI_CRC_INDICATION_PDU_T structures
    List<NFAPI_CRC_INDICATION_PDU_T> nfapiCrcIndicationList = new ArrayList<>();

    // Loop over the range of RNTIs to generate a list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int rnti = minRnti; rnti <= maxRnti; ++rnti) {
        // Allocate memory for a new NFAPI_CRC_INDICATION_PDU_T structure
        NFAPI_CRC_INDICATION_PDU_T* nfapiCrcIndication = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (nfapiCrcIndication == NULL) {
            // Handle allocation failure gracefully by skipping this iteration and continuing with the next RNTI value
            continue;
        }

        // Set the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG fields of the structure randomly
        nfapiCrcIndication->RX_UE_INFORMATION_TAG = rand();
        nfapiCrcIndication->RNTI = rnti;
        nfapiCrcIndication->CRC_INDICATION_REL8_TAG = rand() % 2 == 0 ? 1 : 0;

        // Add the generated structure to the list of NFAPI_CRC_INDICATION_PDU_T structures
        nfapiCrcIndicationList.add(nfapiCrcIndication);
    }

    // Filter the list based on the specified minimum RNTI value, removing any structures with an RNTI less than this value
    List<NFAPI_CRC_INDICATION_PDU_T> filteredList = nfapiCrcIndicationList.stream().filter(nfapiCrcIndication -> nfapiCrcIndication->RNTI >= minRnti).collect(Collectors.toList());

    // Log the number of elements added to the list and any errors encountered during the process
    int numElementsAdded = filteredList.size();
    printf("Number of NFAPI_CRC_INDICATION_PDU_T structures added to the list: %d\n", numElementsAdded);

    // Clear stale data periodically by removing any elements from the list that are older than a certain time threshold
    long dataRetentionThreshold = 30 * 24 * 60 * 60 * 1000; // 30 days in milliseconds
    nfapiCrcIndicationList.removeIf(nfapiCrcIndication -> System.currentTimeMillis() - nfapiCrcIndication->creationTime > dataRetentionThreshold);
}
