// Define the configuration file for policy settings
static const char* config_file = "/etc/crypto_policies.conf";

// Define the function to retrieve the list of available algorithms
static void get_available_algorithms(const char* filter, size_t len) {
    // Open the configuration file
    FILE* fp = fopen(config_file, "r");
    if (fp == NULL) {
        perror("Error opening configuration file");
        return;
    }

    // Read the policy settings from the configuration file
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), fp)) {
        // Check if the line is a comment or empty
        if (buffer[0] == '#' || buffer[0] == '\n') {
            continue;
        }

        // Extract the algorithm name and its priority from the line
        char* alg_name = strtok(buffer, " ");
        int alg_priority = atoi(strtok(NULL, " "));

        // Check if the algorithm is in the filter list
        bool found = false;
        for (size_t i = 0; i < len; i++) {
            if (strcmp(alg_name, filter[i]) == 0) {
                found = true;
                break;
            }
        }

        // If the algorithm is not in the filter list or its priority is greater than zero, add it to the available algorithms list
        if (!found || alg_priority > 0) {
            printf("%s\n", alg_name);
        }
    }

    // Close the configuration file
    fclose(fp);
}

