        perror("bind");
        exit(1);
    }

    // listen for incoming connections
    if (listen(sockfd, MAX_CONNECTIONS) < 0) {
        perror("listen");
        exit(1);
    }

    // initialize connection context pool
    connection_pool = malloc(sizeof(connection_context_t) * MAX_CONNECTIONS);
    if (connection_pool == NULL) {
        perror("malloc");
        exit(1);
    }
}

// Add a new connection context to the pool and establish a connection with the remote endpoint
void add_new_connection(const char* ip, int port, qos_priority_t priority) {
    // find an unused connection context slot in the pool
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (!connection_pool[i].is_connected) {
            int sockfd = socket(AF_INET, SOCK_DGRAM | SOCK_NONBLOCK, 0);
            if (sockfd < 0) {
                perror("socket");
                exit(1);
            }

            // set up IP address and port number for the remote endpoint
            struct sockaddr_in addr;
            memset(&addr, 0, sizeof(addr));
            addr.sin_family = AF_INET;
            addr.sin_port = htons(port);
            inet_pton(AF_INET, ip, &addr.sin_addr);

            // establish a connection with the remote endpoint
            if (connect(sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
                perror("connect");
                exit(1);
            }

            // allocate buffers for incoming and outgoing data
            size_t buffer_size = MIN_BUFFER_SIZE * BUFFER_MULTIPLIER;
            char* incoming_buffer = malloc(buffer_size);
            if (incoming_buffer == NULL) {
                perror("malloc");
                exit(1);
            }
            char* outgoing_buffer = malloc(buffer_size);
            if (outgoing_buffer == NULL) {
                perror("malloc");
                exit(1);
            }

            // initialize connection context
            connection_pool[i].socket = sockfd;
            connection_pool[i].incoming_buffer = incoming_buffer;
            connection_pool[i].outgoing_buffer = outgoing_buffer;
            connection_pool[i].incoming_buffer_size = buffer_size;
            connection_pool[i].outgoing_buffer_size = buffer_size;
            connection_pool[i].is_connected = true;

            // set the QoS for the connection based on the priority level
            int qos_level = priority == LOW ? 1 : (priority == MEDIUM ? 2 : 3);
            if (setsockopt(sockfd, SOL_SOCKET, SO_PRIORITY, &qos_level, sizeof(int)) < 0) {
                perror("setsockopt");
                exit(1);
            }

            // log the new connection
            logging_stats_t stats;
            stats.packet_loss = 0;
            stats.retransmissions = 0;
            stats.latency_avg = 0;
            stats.latency_min = 0;
            stats.latency_max = 0;
            log_connection(i, &stats);
        }
    }
}

// Remove a connection context from the pool and close the socket
void remove_connection(int index) {
    // close socket
    if (close(connection_pool[index].socket) < 0) {
        perror("close");
        exit(1);
    }

    // free buffers for incoming and outgoing data
    free(connection_pool[index].incoming_buffer);
    free(connection_pool[index].outgoing_buffer);

    // reset connection context
    connection_pool[index].is_connected = false;
}

// Send a message to a specific connection context in the pool
void send_message(int index, const char* message) {
    // calculate buffer size for outgoing data
    int message_size = strlen(message);
    size_t buffer_size = sizeof(message_size) + message_size;

    // construct outgoing message
    char* buffer = malloc(buffer_size);
    if (buffer == NULL) {
        perror("malloc");
        exit(1);
    }
    memcpy(buffer, &message_size, sizeof(message_size));
    memcpy(buffer + sizeof(message_size), message, message_size);

    // send outgoing message to the remote endpoint
    if (send(connection_pool[index].socket, buffer, buffer_size, 0) < 0) {
        perror("send");
        exit(1);
    }

    // free buffer for outgoing data
    free(buffer);
}

// Receive a message from a specific connection context in the pool
void receive_message(int index, char* buffer, size_t buffer_size) {
    // receive incoming message from the remote endpoint
    if (recv(connection_pool[index].socket, buffer, buffer_size, 0) < 0) {
        perror("recv");
        exit(1);
    }
}

// Calculate QoS for a specific connection context based on the current logging statistics
qos_level_t calculate_qos(int index) {
    // get logging statistics for the connection
    logging_stats_t stats = get_connection_logging_stats(index);

    // calculate average QoS based on the current logging statistics
    double qos_average = (stats.packet_loss + stats.retransmissions) / (stats.latency_avg * 2);
    return qos_level_t(qos_average);
}

// Update QoS for a specific connection context based on the current logging statistics
void update_qos(int index, qos_level_t level) {
    // set QoS level for the connection
    int qos_level = level == LOW ? 1 : (level == MEDIUM ? 2 : 3);
    if (setsockopt(connection_pool[index].socket, SOL_SOCKET, SO_PRIORITY, &qos_level, sizeof(int)) < 0) {
        perror("setsockopt");
        exit(1);
    }
}

// Close the network interface and free resources
void close_network_interface() {
    // close socket
    if (close(connection_pool[index].socket) < 0) {
        perror("close");
        exit(1);
    }

    // free buffers for incoming and outgoing data
    free(connection_pool[index].incoming_buffer);
    free(connection_pool[index].outgoing_buffer);

    // reset connection context
    connection_pool[index].is_connected = false;
}
