  int i;
  unsigned int crcFlag;
  NFAPI_CRC_INDICATION_PDU *structure;
  struct NFAPI_CRC_INDICATION_PDU_T *tempMaxWeightedSumTransactionId = NULL;
  int maxWeightedSum = -1;

  // Allocate memory for the array of structures
  *structures = malloc(numStructures * sizeof(**structures));
  MEM_ALLOC_CHECK(*structures);
  *numSuccessfullyAllocatedStructures = numStructures;

  // Initialize each structure and generate random CRC flag
