void manage_phy_stats(size_t num_structures, noise_figure_config_t *noise_figure_config, signal_strength_range_t *signal_strength_range, size_t *total_allocated_structures, external_config_t *external_config) {
    // allocate memory for the array of phy_stats structures
    phy_stats_t *phy_stats = (phy_stats_t *)malloc(sizeof(phy_stats_t) * num_structures);
    if (!phy_stats) {
        // handle memory allocation failure
        return;
    }

    // initialize the phy_stats structures
    for (size_t i = 0; i < num_structures; i++) {
        phy_stats[i].tx_power_level = 0.0f;
        phy_stats[i].rx_quality = 0.0f;
        phy_stats[i].snr = 0.0f;
    }

    // calculate the SNR for each structure using the provided signal strength and noise figure configuration
    for (size_t i = 0; i < num_structures; i++) {
        float signal_strength = signal_strength_range->min + (float)(i % (signal_strength_range->max - signal_strength_range->min)) / (float)num_structures * (signal_strength_range->max - signal_strength_range->min);
        float noise_figure = noise_figure_config->value + (float)(i % (noise_figure_config->max - noise_figure_config->min)) / (float)num_structures * (noise_figure_config->max - noise_figure_config->min);
        phy_stats[i].snr = signal_strength / noise_figure;
    }

    // update the total number of successfully allocated structures
    *total_allocated_structures = num_structures;

    // handle external configuration for alignment and padding settings
    if (external_config->alignment && !(external_config->alignment % sizeof(phy_stats_t))) {
        phy_stats = (phy_stats_t *)memalign(external_config->alignment, num_structures * sizeof(phy_stats_t));
    } else if (external_config->padding && !(external_config->padding % sizeof(phy_stats_t))) {
        phy_stats = (phy_stats_t *)memalign(external_config->padding, num_structures * sizeof(phy_stats_t));
    } else if (!external_config->alignment && !external_config->padding) {
        // default alignment and padding settings
        phy_stats = (phy_stats_t *)memalign(sizeof(phy_stats_t), num_structures * sizeof(phy_stats_t));
    }

    // handle optional external data source for runtime adjustments to the signal strength range
    if (external_config->data_source) {
        // update the signal strength range configuration based on the external data source
        *signal_strength_range = external_config->data_source;
    }

    // free memory allocated for phy_stats structures upon function exit
    free(phy_stats);
}
