    string name = root["name"].asString();
    vector<Tile> tiles;
    for (auto& tile : root["tiles"]) {
        Tile new_tile;
        new_tile.x = tile["x"].asInt();
        new_tile.y = tile["y"].asInt();
        new_tile.type = tile["type"].asString();
        tiles.push_back(new_tile);
