    vector<Entity> entities;
    for (auto& entity : root["entities"]) {
        Entity new_entity;
        new_entity.id = entity["id"].asInt();
        new_entity.x = entity["x"].asInt();
        new_entity.y = entity["y"].asInt();
        new_entity.type = entity["type"].asString();
        entities.push_back(new_entity);
