// Define memory pool to minimize allocation overhead
#define MEMORY_POOL_SIZE 1024*1024 // 1MB
static char memory_pool[MEMORY_POOL_SIZE];

// Define function to allocate memory for L2PDU_T structures
L2PDU_T *allocate_l2pdu(int num_structures) {
    // Check if there is enough memory in the pool to allocate requested number of structures
    if (num_structures * sizeof(L2PDU_T) > MEMORY_POOL_SIZE - used_memory) {
        printf("Memory allocation failed: Insufficient resources");
        return NULL;
    }

    // Allocate memory for the requested number of structures
    L2PDU_T *l2pdu = (L2PDU_T *)(memory_pool + used_memory);
    used_memory += num_structures * sizeof(L2PDU_T);

    // Initialize each allocated structure properly
    for (int i = 0; i < num_structures; i++) {
        l2pdu[i].mac_pdu = NULL;
        l2pdu[i].pdcp_sn = -1;
        memset(&l2pdu[i].rlc_am_pdu, 0, sizeof(RLC_AM_PDU));
    }

    return l2pdu;
}

// Define function to release memory for L2PDU_T structures
void release_l2pdu(L2PDU_T *l2pdu) {
    // Check if the input is NULL
    if (l2pdu == NULL) {
        printf("Memory deallocation failed: Input is NULL");
        return;
    }

    // Release memory for the allocated structures
    free(l2pdu);
}

// Define function to monitor and adjust memory usage dynamically
void manage_memory() {
    // Check if there is enough memory available in the pool
    if (used_memory > MEMORY_POOL_SIZE * 0.8) { // 80% of the total pool size
        // Release non-critical structures to free up memory
        release_l2pdu(non_critical);
    }
}
