  // possibility of missing or malformed configuration entries and implement a
  // fallback mechanism to provide default values where necessary.

  EVP_CIPHER_CTX *ctx = NULL;
  int ret = 0;
  FILE *fp = fopen(filepath, "r");
  if (fp == NULL) {
    return NULL;
  }

  char line[1024];
  while (fgets(line, sizeof(line), fp)) {
    // Remove any comments and leading/trailing whitespace from the line
    char *comment_start = strchr(line, '#');
    if (comment_start != NULL) {
      *comment_start = '\0';
    }
    line[strcspn(line, "#\r\n")] = '\0';

    // Split the line into key-value pairs using whitespace as a delimiter
    char *key = strtok(line, " \t");
    if (key == NULL) {
      continue;
    }
    char *value = strtok(NULL, " \t");
    if (value == NULL) {
      continue;
    }

    // Check for the target encryption algorithm
    if (strcmp(key, "target_encryption_algorithm") == 0) {
      int alg_id = OBJ_txt2nid(value);
      if (alg_id == NID_undef) {
        // The specified algorithm is not supported
        fprintf(stderr, "Unsupported encryption algorithm: %s\n", value);
        continue;
      }
    } else if (strcmp(key, "key_length") == 0) {
      int key_len = atoi(value);
      // Check for a valid key length and whether it is supported by the
      // specified algorithm
      if (key_len < MIN_KEY_LENGTH || key_len > MAX_KEY_LENGTH ||
          !EVP_CIPHER_CTX_set_key_length(ctx, key_len)) {
        fprintf(stderr, "Invalid key length: %s\n", value);
        continue;
      }
    } else if (strcmp(key, "encryption") == 0) {
      int encrypt = atoi(value);
      if (encrypt != ENCRYPT && encrypt != DECRYPT) {
        fprintf(stderr, "Invalid encryption flag: %s\n", value);
        continue;
      }
    } else {
      // Unknown key-value pair
      fprintf(stderr, "Unknown configuration parameter: %s=%s\n", key, value);
      continue;
    }
  }

  // Step 4: Validate the loaded parameters to ensure they meet predefined
  // criteria (e.g., supported algorithms, valid key lengths). Design a
  // strategy to handle partial failures gracefully, allowing the function to
  // proceed with a subset of valid parameters while logging issues for invalid
  // ones.

  // Step 5: Initialize an OpenSSL cipher object using the specified parameters.
  // Evaluate the impact of different cipher initialization methods on performance
  // and resource usage. Consider caching initialized cipher objects to reduce
  // overhead for repeated calls with similar parameters.

  if (ctx == NULL) {
    // No valid parameters were found in the configuration file
    return NULL;
  }

  ret = EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, NULL);
  if (ret != 1) {
    ERR_print_errors_fp(stderr);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
