// Define a structure to hold the NFAPI data
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a function to resolve the DNS name and populate the list of NFAPI structures
void resolve_dns(char* hostname, int num_requests) {
    // Initialize the list of NFAPI structures
    NFAPI_CRC_INDICATION_PDU_T* nfapi_list = malloc(num_requests * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memset(nfapi_list, 0, num_requests * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Resolve the DNS name using getaddrinfo()
    struct addrinfo hints;
    struct addrinfo* res;
    int err = getaddrinfo(hostname, NULL, &hints, &res);
    if (err != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(err));
        return;
    }

    // Populate the list of NFAPI structures with the IP address and CRC flag
    int i = 0;
    for (struct addrinfo* p = res; p != NULL && i < num_requests; p = p->ai_next) {
        nfapi_list[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG_CRC_INDICATION;
        nfapi_list[i].rnti = (RNTI) malloc(sizeof(struct rnti));
