void update_packet_info(char *source_ip, char *destination_ip, size_t data_packet_size) {
    // Lock the mutex to prevent race conditions between threads
    pthread_mutex_lock(&mutex);

    // Check if the buffer cache is empty and update it if necessary
    if (buffer_cache.front == buffer_cache.back &&
            last_update_time.tv_sec < time(NULL) - DEFAULT_TIMEOUT) {
        FILE *config_file = fopen(CONFIG_FILE_PATH, "r");
        if (!config_file) {
            // Handle error case
            return;
