        fapi_packet_info_t packet_info = {0};
        while (fscanf(config_file, "%s %s %lu\n", packet_info.source_ip, packet_info.destination_ip, &packet_info.data_packet_size) != EOF) {
            if (!strcmp(packet_info.source_ip, source_ip) && !strcmp(packet_info.destination_ip, destination_ip)) {
                buffer_cache.buffer[buffer_cache.back++] = packet_info;
                break;
            }
        }

        fclose(config_file);
    }

    // Update the last update time and unlock the mutex
    gettimeofday(&last_update_time, NULL);
    pthread_mutex_unlock(&mutex);
}

