    if (buffer_cache.front == buffer_cache.back &&
            last_update_time.tv_sec < time(NULL) - DEFAULT_TIMEOUT) {
        FILE *config_file = fopen(CONFIG_FILE_PATH, "r");
        if (!config_file) {
            // Handle error case
            return NULL;
        }

        fapi_packet_info_t packet_info = {0};
        while (fscanf(config_file, "%s %s %lu\n", packet_info.source_ip, packet_info.destination_ip, &packet_info.data_packet_size) != EOF) {
            if (!strcmp(packet_info.source_ip, source_ip) && !strcmp(packet_info.destination_ip, destination_ip)) {
                buffer_cache.buffer[buffer_cache.back++] = packet_info;
                break;
            }
        }

        fclose(config_file);
    }

    // Check if the required information is available in the cache
    for (int i = buffer_cache.front; i < buffer_cache.back; i++) {
        if (!strcmp(buffer_cache.buffer[i]->source_ip, source_ip) && !strcmp(buffer_cache.buffer[i]->destination_ip, destination_ip)) {
            FAPI_PACKET_INFO_PDU_T *packet_info = malloc(sizeof(FAPI_PACKET_INFO_PDU_T));
            packet_info->source_ip = strdup(buffer_cache.buffer[i]->source_ip);
            packet_info->destination_ip = strdup(buffer_cache.buffer[i]->destination_ip);
            packet_info->data_packet_size = buffer_cache.buffer[i]->data_packet_size;
            return packet_info;
        }
    }

    // Handle the case when the required information is not available in the cache
    // ...

