forward_list<NFAPI_CRC_INDICATION_PDU> manageDynamicallyAllocatedArray(
    const int maxSize = 10000) {
  // Initialize the forward list with a capacity of maxSize
  forward_list<NFAPI_CRC_INDICATION_PDU> list(maxSize);

  // Set up a random engine to generate random CRCFLAG values
  random_device rd;
  mt19937 gen(rd());
  uniform_int_distribution<> dis(0, 1);

