    pdu.RNTI = 1234;
    pdu.CRC_INDICATION_REL8_TAG = "someRel8Tag";
    pdu.CRCFLAG = dis(gen);

    // Attempt to insert the element into the list
    try {
      list.push_front(pdu);
    } catch (bad_alloc& e) {
      // Memory allocation failed, exit the loop and return the current list
      break;
    }
  }

  return list;
}
