#define MAX_NFAPI_CRC_INDICATION_PDU_SIZE sizeof(struct NFAPI_CRC_INDICATION_PDU_T)

// Define a structure to represent a user's RX information
struct UserRxInfo {
    // A unique identifier for the user, composed of their RNTI and RX_UE_INFORMATION_TAG
    uint16_t rnti;
    uint32_t rx_ue_information_tag;

    // The CRC indication data received from the user
    struct NFAPI_CRC_INDICATION_PDU_T crc_indication;
};

// Define a linked list to store all users' RX information
struct UserRxInfoList {
    struct UserRxInfo *head;
    struct UserRxInfo *tail;
};

// Initialize the user RX info linked list
static void initUserRxInfoList(struct UserRxInfoList *list) {
    list->head = NULL;
    list->tail = NULL;
}

// Add a new user to the linked list of users with RX information
static void addNewUserToRxInfoList(struct UserRxInfoList *list, uint16_t rnti, uint32_t rx_ue_information_tag) {
    struct UserRxInfo *new_node = malloc(sizeof(struct UserRxInfo));
    new_node->rnti = rnti;
    new_node->rx_ue_information_tag = rx_ue_information_tag;
    new_node->crc_indication.crflag = rand() % 2; // Randomly set the CRCFLAG for this user
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
}

// Remove a user from the linked list of users with RX information
static void removeUserFromRxInfoList(struct UserRxInfoList *list, uint16_t rnti) {
    struct UserRxInfo *current = list->head;
    struct UserRxInfo *previous = NULL;
    while (current != NULL && current->rnti != rnti) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        return; // User not found in list
    }
    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
}

// Get the user RX information for a given RNTI
static struct UserRxInfo *getUserRxInfo(struct UserRxInfoList *list, uint16_t rnti) {
    struct UserRxInfo *current = list->head;
    while (current != NULL && current->rnti != rnti) {
        current = current->next;
