    // Validate configuration parameters
    if (name == NULL || type < 0 || mtu <= 0 || up < 0 || ipv4_addr.s_addr == 0 || gateway.s_addr == 0 || dns1.s_addr == 0 || dns2.s_addr == 0) {
        return -EINVAL;
    }

