    netif_data->config.dns2 = sanitized_dns2;

    // Configure network interface using ioctl() system call
    int ret = 0;
    if (type == ETHERNET) {
        struct ifreq ifr;
        memset(&ifr, 0, sizeof(struct ifreq));
        strcpy(ifr.ifr_name, sanitized_name);
        ifr.ifr_addr = sanitized_ipv4_addr;
        ret = ioctl(sockfd, SIOCSIFADDR, &ifr);
        if (ret < 0) {
            return -errno;
        }
    } else if (type == WIFI) {
        struct wifi_device_params params;
        memset(&params, 0, sizeof(struct wifi_device_params));
        params.ssid = sanitized_name;
        params.ipv4_addr = sanitized_ipv4_addr;
        params.gateway = sanitized_gateway;
        params.dns1 = sanitized_dns1;
        params.dns2 = sanitized_dns2;
        ret = ioctl(sockfd, SIOCSIFWDEVICE, &params);
