    write_log("Configuration changed for %s: MTU = %d, IPv4 address = %s, gateway = %s, DNS1 = %s, DNS2 = %s", sanitized_name, sanitized_mtu, inet_ntoa(sanitized_ipv4_addr), inet_ntoa(sanitized_gateway), inet_ntoa(sanitized_dns1), inet_ntoa(sanitized_dns2));
    track_data_integrity();

    return 0;
}

// Function to update network interface configuration
