    write_log("Configuration updated for %s: MTU = %d, IPv4 address = %s, gateway = %s, DNS1 = %s, DNS2 = %s", name, mtu, inet_ntoa(ipv4_addr), inet_ntoa(gateway), inet_ntoa(dns1), inet_ntoa(dns2));
