#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_CONFIG_ID 100
#define MEMORY_BUDGET (2 * 1024 * 1024) // 2 MB
#define PAGE_SIZE 4096
#define DEFAULT_ALIGNMENT 8

typedef struct {
    size_t id;
    int default_value;
    int current_value;
} ConfigStruct;

ConfigStruct *configs = NULL;
size_t configs_count = 0;
int *memory_allocations = NULL;
int memory_allocated = 0;

void init_system() {
    // Allocate memory for the config structures and initialize them to default values
    size_t config_struct_size = sizeof(ConfigStruct) + DEFAULT_ALIGNMENT - 1;
    size_t alignment_offset = (config_struct_size % PAGE_SIZE);
    if (alignment_offset != 0) {
        config_struct_size += PAGE_SIZE - alignment_offset;
    }
    configs = (ConfigStruct *)malloc(config_struct_size * MAX_CONFIG_ID);
    memory_allocations = (int *)malloc(sizeof(int) * MAX_CONFIG_ID);
    for (size_t i = 0; i < MAX_CONFIG_ID; i++) {
        configs[i].id = i + 1;
        configs[i].default_value = 0;
        configs[i].current_value = 0;
    }

    // Initialize the memory allocations array and set all elements to -1
    for (size_t i = 0; i < MAX_CONFIG_ID; i++) {
        memory_allocations[i] = -1;
    }
}

void shutdown_system() {
    // Release all allocated memory
    free(configs);
    configs = NULL;
    free(memory_allocations);
    memory_allocations = NULL;
}

int allocate_memory(size_t size) {
    // Ensure that the requested size is within the memory budget
    if (size > MEMORY_BUDGET) {
        return -1;
    }

    // Find a free slot in the memory allocations array and set it to the new size
    for (size_t i = 0; i < MAX_CONFIG_ID; i++) {
        if (memory_allocations[i] == -1) {
            memory_allocations[i] = size;
            return i + 1;
        }
    }

    // If no free slots were found, return an error
    return -1;
}

void deallocate_memory(int id) {
    // Set the allocation for the specified ID to -1
    if (id > 0 && id <= MAX_CONFIG_ID) {
        memory_allocations[id - 1] = -1;
    }
}

void garbage_collect() {
    // Iterate over all allocations and release those with a size of 0
    for (size_t i = 0; i < MAX_CONFIG_ID; i++) {
        if (memory_allocations[i] == 0) {
            deallocate_memory(i + 1);
        }
    }
}

int lock_config(int id) {
    // Select a suitable locking mechanism based on the ID and return its handle
    if (id > 0 && id <= MAX_CONFIG_ID) {
        pthread_mutex_t *lock = &mutexes[id - 1];
        pthread_mutex_lock(lock);
        return (int)lock;
    } else {
        return -1;
    }
}

void unlock_config(int handle) {
    // Release the lock for the specified handle
    if (handle > 0) {
        pthread_mutex_t *lock = (pthread_mutex_t *)handle;
        pthread_mutex_unlock(lock);
    }
}

int set_config_value(int id, int value) {
    // Ensure that the ID is valid and return an error otherwise
    if (id <= 0 || id > MAX_CONFIG_ID) {
        return -1;
    }

    // Allocate memory for the new value if it doesn't exist yet
    size_t size = sizeof(int);
    int allocation_id = allocate_memory(size);
    if (allocation_id == -1) {
        return -1;
    }

    // Set the new value and update the current value for the specified ID
    configs[allocation_id - 1].current_value = value;
    memory_allocations[allocation_id - 1] = size;
    return allocation_id;
}

int get_config_value(int id) {
    // Ensure that the ID is valid and return an error otherwise
    if (id <= 0 || id > MAX_CONFIG_ID) {
        return -1;
    }

    // Return the current value for the specified ID
    return configs[id - 1].current_value;
}

