// Define the structure for holding CRC information
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCINDICATION_PRESENT;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the maximum size of the dynamic list
#define MAX_LIST_SIZE 1024

// Function to initialize the dynamic list
void init_list(NFAPI_CRC_INDICATION_PDU_T **list) {
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_LIST_SIZE);
}

// Function to add a new element to the list
void add_element(NFAPI_CRC_INDICATION_PDU_T **list, uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG, bool CRCINDICATION_PRESENT) {
    if (*list == NULL) {
        init_list(list);
    }

    // Check for overflow condition and resize the list if necessary
    if (sizeof((*list)->CRCINDICATION_PRESENT) > sizeof(bool)) {
        printf("Overflow condition detected. Resizing the list.\n");
        *list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(*list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (MAX_LIST_SIZE + 1));
    }

    // Add the new element to the list
    (*list)[MAX_LIST_SIZE - 1].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    (*list)[MAX_LIST_SIZE - 1].RNTI = RNTI;
    (*list)[MAX_LIST_SIZE - 1].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    (*list)[MAX_LIST_SIZE - 1].CRCINDICATION_PRESENT = CRCINDICATION_PRESENT;
}

// Function to remove an element from the list
void remove_element(NFAPI_CRC_INDICATION_PDU_T **list, uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    if (*list == NULL) {
        return;
    }

    // Search for the element to remove
    int index = 0;
    while (index < MAX_LIST_SIZE && ((*list)[index].RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG || (*list)[index].RNTI != RNTI)) {
        index++;
    }

    // Check if the element was found and remove it if necessary
    if (index < MAX_LIST_SIZE) {
        for (int i = index; i < MAX_LIST_SIZE - 1; i++) {
            (*list)[i] = (*list)[i + 1];
        }
        MAX_LIST_SIZE--;
    }
}

// Function to check if a given RNTI value is already in the list
bool contains(NFAPI_CRC_INDICATION_PDU_T **list, uint16_t RNTI) {
    if (*list == NULL) {
        return false;
    }

    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        if ((*list)[i].RNTI == RNTI) {
            return true;
        }
    }

    return false;
}

// Function to print the contents of the list
void print_list(NFAPI_CRC_INDICATION_PDU_T **list) {
    if (*list == NULL) {
        printf("The list is empty.\n");
        return;
    }

    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCINDICATION_PRESENT: %s\n", (*list)[i].RX_UE_INFORMATION_TAG, (*list)[i].RNTI, (*list)[i].CRC_INDICATION_REL8_TAG, (*list)[i].CRCINDICATION_PRESENT ? "true" : "false");
    }
}

// Main function to test the list functions
int main() {
    NFAPI_CRC_INDICATION_PDU_T *list = NULL;

    // Add some elements to the list
    add_element(&list, 10, 20, 30, true);
    add_element(&list, 40, 50, 60, false);
    add_element(&list, 70, 80, 90, true);

