public class HttpPostHandler
{
    private const int MAX_KEYS = 1000; // maximum number of keys to store
    private const int MAX_OFFSETS = 1000; // maximum number of offsets to store
    private const int MEMORY_BUDGET = 1000 * 1024 * 1024; // maximum memory budget for the data structure (1GB)
    private const int REPRODUCIBLE_SEED = 42; // reproducible seed for testing purposes

    private class Record
    {
        public int Key { get; set; }
        public long Offset { get; set; }
        public int Value { get; set; }
    }

    private readonly List<Record> _records = new List<Record>(); // list of records for efficient lookups and updates
    private readonly Dictionary<int, int> _keys = new Dictionary<int, int>(MAX_KEYS); // dictionary for fast key lookup
    private readonly Dictionary<long, long> _offsets = new Dictionary<long, long>(MAX_OFFSETS); // dictionary for fast offset lookup

    public async Task HandleHttpPostRequestAsync(string id, string htmlContent)
    {
        var record = await ValidateAndGetRecordAsync(id);
        if (record == null) return;

        // update the HTML content of the specified element
        record.Value = htmlContent;

        // save the updated record to the data structure
        _records[record.Key] = record;
    }

    private async Task<Record> ValidateAndGetRecordAsync(string id)
    {
        var key = int.Parse(id);
        if (_keys.ContainsKey(key))
        {
            return _records[_keys[key]];
        }
        else
        {
            // generate a random value within the specified range for testing purposes
            var value = RandomUtils.Next(REPRODUCIBLE_SEED, 1000);

            // create a new record and add it to the data structure
            var record = new Record
            {
                Key = key,
                Offset = GetOffset(),
                Value = value
            };
            _records.Add(record);
            _keys.Add(key, _records.Count - 1);
            return record;
        }
    }

    private long GetOffset()
    {
        var offset = RandomUtils.NextLong(REPRODUCIBLE_SEED, MAX_OFFSETS);
        while (_offsets.ContainsKey(offset))
        {
            offset = RandomUtils.NextLong(REPRODUCIBLE_SEED, MAX_OFFSETS);
        }
        return offset;
    }

