// LTE_PHY_FRAME_T structure definition
typedef struct {
    int OFDM_SYMBOL_INDEX;
    float CHAN_QUALITY_MEASUREMENT;
    char BULK_DATA_TRANSFER_REQUEST[1024];
    int STATUS_FLAG;
} LTE_PHY_FRAME_T;

// Function to dynamically generate and populate an array of LTE_PHY_FRAME_T structures
void generate_frames(int num_structures, int seed, float timeout) {
    // Initialize random number generator with seed value
    srand(seed);

    // Allocate memory for the array of structures
    LTE_PHY_FRAME_T *frames = (LTE_PHY_FRAME_T *) malloc(num_structures * sizeof(LTE_PHY_FRAME_T));

    // Iterate over each structure in the array and populate it with random values
    for (int i = 0; i < num_structures; i++) {
        frames[i].OFDM_SYMBOL_INDEX = rand() % 1024;
        frames[i].CHAN_QUALITY_MEASUREMENT = rand() / (float) RAND_MAX;
        strcpy(frames[i].BULK_DATA_TRANSFER_REQUEST, "random data");
        frames[i].STATUS_FLAG = 0;
    }

    // Compute the STATUS_FLAG for each structure based on its CHAN_QUALITY_MEASUREMENT value
    for (int i = 0; i < num_structures; i++) {
        if (frames[i].CHAN_QUALITY_MEASUREMENT > 0.75) {
            frames[i].STATUS_FLAG = 1;
        } else {
            frames[i].STATUS_FLAG = 0;
        }
    }

    // Print the array of structures to stdout
    for (int i = 0; i < num_structures; i++) {
        printf("Frame %d: OFDM symbol index: %d, CHAN quality measurement: %.2f, BULK data transfer request: %s, STATUS flag: %d\n", i + 1, frames[i].OFDM_SYMBOL_INDEX, frames[i].CHAN_QUALITY_MEASUREMENT, frames[i].BULK_DATA_TRANSFER_REQUEST, frames[i].STATUS_FLAG);
    }

    // Free the memory allocated for the array of structures
    free(frames);
}

int main(int argc, char **argv) {
    // Check command-line arguments and parse them as needed
    if (argc < 4) {
        printf("Usage: %s [num_structures] [seed] [timeout]\n", argv[0]);
        return 1;
    }
    int num_structures = atoi(argv[1]);
    int seed = atoi(argv[2]);
    float timeout = atof(argv[3]);

    // Call the generate_frames function with the parsed arguments
    generate_frames(num_structures, seed, timeout);

    return 0;
}
