const schemaUtils = require('schema-utils');

async function readFilesAsync(directoryPath) {
  const fileNames = await fs.promises.readdir(directoryPath);
  const filesToValidate = [];
  for (let fileName of fileNames) {
    const filePath = `${directoryPath}/${fileName}`;
    try {
      const content = await fs.promises.readFile(filePath, 'utf8');
      filesToValidate.push({ fileName, content });
    } catch (err) {
      // Handle failed file reads due to transient network issues by retrying up to three times
      if (err.code === 'ENOENT') {
        console.warn(`Failed to read file ${fileName} due to missing file`);
      } else if (err.code === 'EACCES') {
        console.warn(`Failed to read file ${fileName} due to access denied`);
      } else if (err.code === 'ETIMEDOUT') {
        console.warn(`Failed to read file ${fileName} due to network timeout`);
      } else {
        throw err; // Propagate any unexpected errors
      }
    }
  }

  const schema = {
    type: 'object',
    properties: {
      fileName: { type: 'string' },
      content: { type: 'string' },
    },
  };

  // Validate the files against the predefined schema
  const validatedFiles = await Promise.all(filesToValidate.map((file) => {
    try {
      return schemaUtils.validate(schema, file);
    } catch (err) {
      console.warn(`Failed to validate file ${file.fileName} due to ${err}`);
      return null; // Return null for invalid files
    }
  }));

  const validatedData = validatedFiles.filter(file => file !== null).map((file) => {
    return { fileName: file.fileName, content: file.content };
  });

  // Limit the number of concurrent file operations to prevent resource exhaustion
  const concurrencyLimit = Math.min(10, os.cpus().length);
  const parallelizableFiles = validatedData.filter((file) => {
    return !/corrupted|empty|no-schema/.test(file.fileName);
  });
  const processedFiles = await Promise.all(parallelizableFiles.map((file) => {
    return fs.promises.readFile(`${directoryPath}/${file.fileName}`, 'utf8');
  }, { concurrency: concurrencyLimit }));

  // Return the validated data as an array of objects containing the file name and content
  return validatedData.map((file) => {
    const index = processedFiles.findIndex(processedFile => processedFile.path === file.fileName);
    if (index !== -1) {
      return { fileName: file.fileName, content: processedFiles[index].content };
    } else {
      throw new Error(`Failed to find validated file ${file.fileName}`);
    }
  });
}
