void initialize_ue_info() {
  // Initialize the hash table with a size of 10,000 elements
  ue_info_hash = malloc(sizeof(struct UE_INFO) * 10000);
}

int32_t process_crc_indication(uint32_t user_equipment_id, uint8_t rnti, uint8_t crcflag) {
  // Check if the UE information is already stored in the hash table
  struct UE_INFO *ue_info = find_ue_info(user_equipment_id);
  if (ue_info == NULL) {
    return -1;
  }

  // Create a new CRC indication PDU structure and add it to the array of structures
