  crc_pdu->rx_ue_information_tag = RX_UE_INFORMATION_TAG_CRC;
  crc_pdu->rnti = rnti;
  crc_pdu->crc_indication_rel8_tag.crcflag = crcflag;
  ue_info->crc_pdu_array[ue_info->num_of_crcs++] = crc_pdu;

  return 0;
}

struct UE_INFO *find_ue_info(uint32_t user_equipment_id) {
  // Iterate through the hash table to find the matching UE information structure
  struct UE_INFO *ue_info = NULL;
  for (int i = 0; i < 10000; i++) {
    if (ue_info_hash[i].user_equipment_id == user_equipment_id) {
      ue_info = &ue_info_hash[i];
      break;
    }
  }
  return ue_info;
}

// Thread-safe function to safely iterate over the CRC indication PDU structures in an UE information structure
void iterate_crc_pdus(struct UE_INFO *ue_info, void (*callback)(struct NFAPI_CRC_INDICATION_PDU_T *)) {
  pthread_mutex_lock(&ue_info->mutex);
  for (int i = 0; i < ue_info->num_of_crcs; i++) {
    callback(ue_info->crc_pdu_array[i]);
