['Here is a C function that initializes and manages a dynamically allocated array of `UeMeasurementRecord` structures, each containing a unique UE identifier, a timestamp, and a vector of `SignalStrengthSample` structures. The vector should limit the number of samples to a maximum of 100, automatically removing the oldest sample when a new one is added. Each `SignalStrengthSample` includes a sample time, signal strength value, and a quality indicator flag, all initialized with randomly generated values within specified ranges. The signal strength value should be constrained to a minimum of -150 dBm and a maximum of -30 dBm, and the quality indicator should be a boolean value. Timestamps must be updated at the time of each new sample insertion.

```c
#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <time.h>

// Structure to represent a UE measurement record
typedef struct UeMeasurementRecord {
    uint32_t ueId; // Unique UE identifier
    time_t timestamp; // Timestamp of the measurement
    vector<SignalStrengthSample> samples; // Vector of signal strength samples
} UeMeasurementRecord;

// Structure to represent a signal strength sample
typedef struct SignalStrengthSample {
    uint64_t sampleTime; // Timestamp of the sample
    int8_t signalStrengthValue; // Signal strength value in dBm
    bool qualityIndicatorFlag; // Quality indicator flag (true/false)
} SignalStrengthSample;

// Structure to represent an NFAPI CRD indication PDU
typedef struct NFAPI_CRC_INDICATION_PDU {
    uint16_t rx_ue_information_tag; // RX UE information tag
    uint32_t rnti; // RNTI
    bool crcFlag; // CRC flag (true/false)
} NFAPI_CRC_INDICATION_PDU;

// Function to initialize and manage a dynamically allocated array of UeMeasurementRecord structures
void ueMeasurements(UeMeasurementRecord** measurements, uint32_t maxNumMeasurements) {
    // Initialize the array with NULL pointers
    for (uint32_t i = 0; i < maxNumMeasurements; i++) {
        measurements[i] = NULL;
    }

    // Add a new measurement record to the array
    void addMeasurementRecord(UeMeasurementRecord* record) {
        // If there is no space left in the array, remove the oldest sample and update the timestamp
        if (measurements[0] != NULL) {
            uint32_t oldestIdx = 0;
            for (uint32_t i = 1; i < maxNumMeasurements; i++) {
                if (measurements[i] == NULL) {
                    oldestIdx = i - 1;
                    break;
                }
            }
            measurements[oldestIdx]->timestamp = record->timestamp;
        }

        // Add the new measurement record to the array
        for (uint32_t i = 0; i < maxNumMeasurements; i++) {
            if (measurements[i] == NULL) {
                measurements[i] = record;
                break;
            }
        }
    }

    // Remove a measurement record from the array
    void removeMeasurementRecord(UeMeasurementRecord* record) {
        for (uint32_t i = 0; i < maxNumMeasurements; i++) {
            if (measurements[i] == record) {
                measurements[i] = NULL;
                break;
            }
        }
    }

    // Add a new signal strength sample to the array
    void addSignalStrengthSample(UeMeasurementRecord* record, SignalStrengthSample sample) {
        // If there is no space left in the vector, remove the oldest sample and update the timestamp
        if (record->samples.size() == 100) {
            uint32_t oldestIdx = 0;
            for (uint32_t i = 1; i < record->samples.size(); i++) {
                if (record->samples[i] == NULL) {
                    oldestIdx = i - 1;
                    break;
                }
            }
            record->timestamp = sample.sampleTime;
        }

        // Add the new signal strength sample to the vector
        for (uint32_t i = 0; i < record->samples.size(); i++) {
            if (record->samples[i] == NULL) {
                record->samples[i] = sample;
                break;
            }
        }
    }

    // Remove a signal strength sample from the array
    void removeSignalStrengthSample(UeMeasurementRecord* record, uint64_t sampleTime) {
        for (uint32_t i = 0; i < record->samples.size(); i++) {
            if (record->samples[i].sampleTime == sampleTime) {
                record->samples[i] = NULL;
                break;
            }
        }
    }

    // Update the timestamp of a measurement record
    void updateTimestamp(UeMeasurementRecord* record) {
        record->timestamp = time(NULL);
    }

    // Initialize the NFAPI CRD indication PDU structure with a valid RX UE information tag, RNTI, and CRC flag
    void initializeNfapiCrcIndicationPdu(UeMeasurementRecord* record) {
        NFAPI_CRC_INDICATION_PDU pdu;
        pdu.rx_ue_information_tag = 0xFFFF;
        pdu.rnti = record->rnti;
        pdu.crcFlag = true;
    }
}

// Example usage of the ueMeasurements function
void exampleUsage() {
    UeMeasurementRecord** measurements = (UeMeasurementRecord**)malloc(sizeof(UeMeasurementRecord*) * 10);
    uint32_t maxNumMeasurements = 10;
    ueMeasurements(measurements, maxNumMeasurements);
}
```
