    if (num_packets >= MAX_PACKETS) {
        printf("Maximum number of packets reached, cannot add more\n");
        return;
    }
    packets[num_packets] = new_packet;
}

// Function to remove old packets from the array
void removeOldPackets(long long current_timestamp) {
    // Iterate through the packets and remove any that are older than the specified duration
