            // Shift all subsequent packets to fill the gap
            for (int j = i; j < sizeof(packets) / sizeof(packets[0]) - 1; ++j) {
                packets[j] = packets[j + 1];
            }

            // Decrement the number of packets by one
            --num_packets;
        }
    }
}

// Function to retrieve packets within a given time range
void getPackets(long long start_timestamp, long long end_timestamp) {
    // Iterate through the packets and return any that are within the specified range
    for (int i = 0; i < sizeof(packets) / sizeof(packets[0]); ++i) {
