            // Print the packet information
            printf("Packet %d: timestamp=%lld, unique_id=%d, payload_size=%d\n", i, packets[i]->timestamp, packets[i]->unique_id, packets[i]->payload_size);
        }
    }
}

// Function to handle external service calls with retries and error handling
void handleServiceCall(void (*service_call)()) {
    // Initialize the number of attempts and the delay interval
    int num_attempts = 0;
    long long delay_interval = RETRY_DELAY_MS;

    // Repeat the service call until it succeeds or the maximum number of retries is reached
    while (num_attempts < MAX_RETRIES) {
        try {
            // Call the service with the appropriate delay between attempts
            service_call();
            break;
        } catch (Exception e) {
            // Handle transient errors and wait for the retry interval to elapse before attempting again
            printf("Transient error encountered, waiting %lld milliseconds\n", delay_interval);
            sleep(delay_interval / 1000);
            ++num_attempts;
        }
    }
}
