// Function to dynamically manage data packets
void manage_data_packets(DataPacket **packets, int *num_packets, long max_duration) {
    // Add a new packet to the list of packets
    void add_packet(DataPacket *packet) {
        if (*num_packets == MAX_NUM_PACKETS) {
            // Maximum number of packets reached, remove oldest one
            remove_oldest_packet();
        }
        packet->next = NULL;
        if (*packets == NULL) {
            *packets = packet;
        } else {
            DataPacket *cur = *packets;
            while (cur->next != NULL) {
                cur = cur->next;
            }
            cur->next = packet;
        }
        (*num_packets)++;
    }

    // Remove packets older than the specified duration
    void remove_old_packets(long duration) {
        long current_time = get_current_timestamp();
        DataPacket *cur = *packets;
        while (cur != NULL && cur->timestamp + duration <= current_time) {
            DataPacket *prev = cur;
            cur = cur->next;
            prev->next = NULL;
            free(prev);
            (*num_packets)--;
        }
    }

    // Get packets within the specified time range
    void get_packets(long start, long end) {
        DataPacket *cur = *packets;
        while (cur != NULL && cur->timestamp >= start && cur->timestamp <= end) {
            printf("%lu\n", cur->timestamp);
            cur = cur->next;
        }
    }
}
