// Structure to hold information about a CRC indication PDU
typedef struct {
    uint8_t rx_ue_information_tag; // RX_UE_INFORMATION_TAG
    uint16_t rnti; // RNTI
    uint8_t crc_indication_rel8_tag; // CRC_INDICATION_REL8_TAG
    uint32_t crcflag; // CRCFLAG
} nfapi_crc_indication_pdu_t;

// Structure to hold the list of CRC indications and their associated RX UEs
typedef struct {
    uint8_t num_structures; // Number of structures in the list
    nfapi_crc_indication_pdu_t *structures[MAX_STRUCTURES]; // Array of pointers to structures
} nfapi_crc_indication_list_t;

// Function to initialize the CRC indication list
void init_crc_indication_list(nfapi_crc_indication_list_t *list) {
    // Set the number of structures in the list to 0
    list->num_structures = 0;
}

// Function to add a new CRC indication structure to the list
void add_crc_indication(nfapi_crc_indication_list_t *list, uint8_t rx_ue_information_tag, uint16_t rnti, uint32_t crcflag) {
    // Check if the list is full
    if (list->num_structures == MAX_STRUCTURES) {
        printf("Error: CRC indication list is full. Unable to add new structure.\n");
        return;
    }

    // Allocate memory for the new structure and populate it with the given values
    nfapi_crc_indication_pdu_t *new_structure = malloc(sizeof(nfapi_crc_indication_pdu_t));
    new_structure->rx_ue_information_tag = rx_ue_information_tag;
    new_structure->rnti = rnti;
    new_structure->crc_indication_rel8_tag = 0; // Randomly set CRCFLAG

    // Add the new structure to the list and increment the number of structures
    list->structures[list->num_structures++] = new_structure;
}

// Function to check the integrity of a CRC indication PDU
int is_crc_indication_integrity_ok(nfapi_crc_indication_pdu_t *crc_indication) {
    // Check if the CRCFLAG is less than or equal to the CRC indication threshold
    if (crc_indication->crcflag <= CRC_INDICATION_THRESHOLD) {
        return 1;
    } else {
        return 0;
    }
}

// Function to update a CRC indication PDU in the list with a new CRCFLAG value
void update_crc_indication(nfapi_crc_indication_list_t *list, uint8_t rx_ue_information_tag, uint16_t rnti, uint32_t crcflag) {
    // Iterate through the list to find the matching RX UE information tag and RNTI
    for (int i = 0; i < list->num_structures; i++) {
        nfapi_crc_indication_pdu_t *current_structure = list->structures[i];
        if (current_structure->rx_ue_information_tag == rx_ue_information_tag && current_structure->rnti == rnti) {
            // Update the CRCFLAG value and return
            current_structure->crcflag = crcflag;
            return;
        }
    }
}

// Function to serialize the CRC indication list to a binary file
void serialize_crc_indications(nfapi_crc_indication_list_t *list, char *filename) {
    // Open the file for writing in binary mode
    int fd = open(filename, O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        printf("Error: Unable to open %s for writing. Error code: %d\n", filename, errno);
        return;
    }

    // Write the number of structures in the list to the file
    write(fd, &list->num_structures, sizeof(uint8_t));

    // Iterate through the list and serialize each structure
    for (int i = 0; i < list->num_structures; i++) {
        nfapi_crc_indication_pdu_t *current_structure = list->structures[i];
        write(fd, current_structure, sizeof(nfapi_crc_indication_pdu_t));
    }

    // Close the file and return
    close(fd);
}

// Function to deserialize a binary file containing CRC indications
void deserialize_crc_indications(char *filename, nfapi_crc_indication_list_t *list) {
    // Open the file for reading in binary mode
    int fd = open(filename, O_RDONLY, 0644);
    if (fd == -1) {
        printf("Error: Unable to open %s for reading. Error code: %d\n", filename, errno);
        return;
    }

    // Read the number of structures in the list from the file
    read(fd, &list->num_structures, sizeof(uint8_t));

    // Allocate memory for each structure in the list
    for (int i = 0; i < list->num_structures; i++) {
        nfapi_crc_indication_pdu_t *new_structure = malloc(sizeof(nfapi_crc_indication_pdu_t));
        read(fd, new_structure, sizeof(nfapi_crc_indication_pdu_t));
    }

    // Close the file and return
    close(fd);
}

// Function to print a CRC indication list for debugging purposes
void print_crc_indications(nfapi_crc_indication_list_t *list) {
    printf("CRC Indications: %d\n", list->num_structures);
    for (int i = 0; i < list->num_structures; i++) {
        nfapi_crc_indication_pdu_t *current_structure = list->structures[i];
        printf("RX UE Information Tag: %d\n", current_structure->rx_ue_information_tag);
        printf("RNTI: %d\n", current_structure->rnti);
        printf("CRCFLAG: %d\n", current_structure->crcflag);
    }
}

// Function to check if a CRC indication PDU exists in the list
int is_crc_indication_exists(nfapi_crc_indication_list_t *list, uint8_t rx_ue_information_tag, uint16_t rnti) {
    // Iterate through the list to find the matching RX UE information tag and RNTI
    for (int i = 0; i < list->num_structures; i++) {
        nfapi_crc_indication_pdu_t *current_structure = list->structures[i];
        if (current_structure->rx_ue_information_tag == rx_ue_information_tag && current_structure->rnti == rnti) {
            return 1;
        }
    }
    return 0;
}

// Function to remove a CRC indication PDU from the list
void remove_crc_indication(nfapi_crc_indication_list_t *list, uint8_t rx_ue_information_tag, uint16_t rnti) {
    // Iterate through the list to find the matching RX UE information tag and RNTI
    for (int i = 0; i < list->num_structures; i++) {
        nfapi_crc_indication_pdu_t *current_structure = list->structures[i];
        if (current_structure->rx_ue_information_tag == rx_ue_information_tag && current_structure->rnti == rnti) {
            // Remove the structure from the list and return
            free(list->structures[i]);
            list->num_structures--;
            return;
        }
    }
}

// Function to clear all CRC indication PDUs from the list
void clear_crc_indications(nfapi_crc_indication_list_t *list) {
    // Iterate through the list and free each structure
    for (int i = 0; i < list->num_structures; i++) {
        nfapi_crc_indication_pdu_t *current_structure = list->structures[i];
        free(list->structures[i]);
    }
    // Reset the number of structures to zero
    list->num_structures = 0;
}
