typedef struct NFAPI_CRC_INDICATION_PDU {
    RX_UE_INFORMATION_TAG *rx_ue_information_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *init_linked_list(size_t n) {
    // Allocate memory for the linked list nodes
    NFAPI_CRC_INDICATION_PDU_T *nodes = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (nodes == NULL) {
        return NULL;
    }

    // Initialize the linked list nodes with valid values
    for (size_t i = 0; i < n; i++) {
        nodes[i].rx_ue_information_tag = malloc(sizeof(RX_UE_INFORMATION_TAG));
        nodes[i].rnti = i + 1; // randomly set RNTI
        nodes[i].crc_indication_rel8_tag.CRCFLAG = (uint8_t)((rand() % 2) ? 0 : 1); // randomly set CRCFLAG
    }

    return nodes;
}

void free_linked_list(NFAPI_CRC_INDICATION_PDU_T *nodes, size_t n) {
    for (size_t i = 0; i < n; i++) {
        free(nodes[i].rx_ue_information_tag);
    }
    free(nodes);
}

NFAPI_CRC_INDICATION_PDU_T *get_random_node(NFAPI_CRC_INDICATION_PDU_T *nodes, size_t n) {
    // Select a random node from the linked list
    size_t idx = rand() % n;
    return &nodes[idx];
}

void garbage_collect(NFAPI_CRC_INDICATION_PDU_T **node_ptr, size_t *n) {
    // Check if any nodes are not properly aligned or have circular references
    for (size_t i = 0; i < *n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *node = node_ptr[i];
        if (!is_properly_aligned(node) || has_circular_reference(node)) {
            // Remove the node from the linked list and decrease the count
            (*n)--;
            for (size_t j = i + 1; j < *n; j++) {
                node_ptr[j - 1] = node_ptr[j];
            }
            free(node);
        }
    }
}

int is_properly_aligned(NFAPI_CRC_INDICATION_PDU_T *node) {
    return (((uintptr_t)node) % 8 == 0); // check if node address is properly aligned
}

int has_circular_reference(NFAPI_CRC_INDICATION_PDU_T *node) {
    NFAPI_CRC_INDICATION_PDU_T *next;
    for (next = node; next != NULL; next = next->rx_ue_information_tag->next) {
        if (next == node) { // check for circular reference
            return 1;
        }
    }
    return 0;
}
