// Define a struct to hold a MAC PDU
typedef struct mac_pdu {
    int identifier;
    char *data;
} mac_pdu_t;

// Define a struct to hold the dynamic array of MAC PDUs
typedef struct mac_pdu_array {
    size_t capacity; // Current capacity of the array
    size_t count; // Number of elements in the array
    mac_pdu_t *elems; // Pointer to the first element in the array
} mac_pdu_array_t;

// Function to add a new MAC PDU to the array
void add_mac_pdu(mac_pdu_array_t *arr, int identifier, char *data) {
    // Check if there is enough space in the array
    if (arr->count == arr->capacity) {
        // If not, reallocate the memory to double the capacity
        arr->capacity *= 2;
        arr->elems = realloc(arr->elems, sizeof(mac_pdu_t) * arr->capacity);
    }

    // Add the new MAC PDU at the end of the array
    arr->elems[arr->count].identifier = identifier;
    arr->elems[arr->count].data = malloc(strlen(data) + 1);
    strcpy(arr->elems[arr->count].data, data);
    arr->count++;
}

// Function to remove a MAC PDU from the array by identifier
void remove_mac_pdu_by_id(mac_pdu_array_t *arr, int identifier) {
    // Find the index of the MAC PDU with the given identifier
    size_t i;
    for (i = 0; i < arr->count; i++) {
        if (arr->elems[i].identifier == identifier) {
            break;
        }
    }

    // Check if the MAC PDU was found
    if (i < arr->count) {
        // Remove the MAC PDU at the index
        for (size_t j = i; j < arr->count - 1; j++) {
            memcpy(&arr->elems[j], &arr->elems[j + 1], sizeof(mac_pdu_t));
        }
        arr->count--;
    } else {
        // If not, raise an error
        printf("MAC PDU with identifier %d was not found\n", identifier);
    }
}

// Function to update the content of a MAC PDU in the array by identifier
void update_mac_pdu_by_id(mac_pdu_array_t *arr, int identifier, char *data) {
    // Find the index of the MAC PDU with the given identifier
    size_t i;
    for (i = 0; i < arr->count; i++) {
        if (arr->elems[i].identifier == identifier) {
            break;
        }
    }

    // Check if the MAC PDU was found
    if (i < arr->count) {
        // Update the data field of the MAC PDU
        free(arr->elems[i].data);
        arr->elems[i].data = malloc(strlen(data) + 1);
        strcpy(arr->elems[i].data, data);
    } else {
        // If not, raise an error
        printf("MAC PDU with identifier %d was not found\n", identifier);
    }
}

// Function to serialize the array of MAC PDUS to a binary file
void serialize_mac_pdus(mac_pdu_array_t *arr, const char *filename) {
    // Open the output file in binary write mode
    FILE *out = fopen(filename, "wb");
    if (out == NULL) {
        printf("Failed to open %s for writing\n", filename);
        return;
    }

    // Write the number of MAC PDUS in the array to the file
    size_t num_pdus = arr->count;
    fwrite(&num_pdus, sizeof(size_t), 1, out);

    // Write each MAC PDU in the array to the file
    for (size_t i = 0; i < arr->count; i++) {
        mac_pdu_t *pdu = &arr->elems[i];
        fwrite(&pdu->identifier, sizeof(int), 1, out);
        fwrite(pdu->data, strlen(pdu->data) + 1, 1, out);
    }

    // Close the output file
    fclose(out);
}

// Function to deserialize an array of MAC PDUS from a binary file
void deserialize_mac_pdus(const char *filename, mac_pdu_array_t **arr) {
    // Open the input file in binary read mode
    FILE *in = fopen(filename, "rb");
    if (in == NULL) {
        printf("Failed to open %s for reading\n", filename);
        return;
    }

    // Read the number of MAC PDUS from the file
    size_t num_pdus = 0;
    fread(&num_pdus, sizeof(size_t), 1, in);

    // Allocate memory for the array
    *arr = malloc(sizeof(mac_pdu_array_t));
    (*arr)->capacity = num_pdus;
    (*arr)->count = num_pdus;
    (*arr)->elems = malloc(num_pdus * sizeof(mac_pdu_t));

    // Read each MAC PDU from the file and add it to the array
    for (size_t i = 0; i < num_pdus; i++) {
        mac_pdu_t *pdu = &(*arr)->elems[i];
        fread(&pdu->identifier, sizeof(int), 1, in);
        pdu->data = malloc(strlen((char *)in) + 1);
        fread(pdu->data, strlen((char *)in) + 1, 1, in);
    }

    // Close the input file
    fclose(in);
}
