// Function to apply periodic updates to the existing structures while minimizing latency and maximizing throughput
void nfapi_crc_indication_list_update(struct NFAPI_CRC_INDICATION_PDU_LIST* list, RX_UE_INFORMATION_TAG rx_ue_information) {
    pthread_mutex_lock(&list->mutex);
    // Batch updates are more efficient than individual updates for this use case
    for (int i = 0; i < list->size; ++i) {
        struct NFAPI_CRC_INDICATION_PDU* pdu = &list->array[i];
        if (pdu->rx_ue_information == rx_ue_information) {
            // Apply the update to the structure
            pdu->crc_indication_rel8.flags[0]++;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to destroy the list of CRC indication PDUs and free all memory
void nfapi_crc_indication_list_destroy(struct NFAPI_CRC_INDICATION_PDU_LIST* list) {
