#include <pthread.h>

#define MAX_PDU_COUNT 1024 // maximum number of PDUs that can be initialized
#define MAX_BUFFER_SIZE 16384 // maximum size of the buffer for PDU data

// LTE_TRANSPORT_CHANNEL_DESCRIPTION struct definition
typedef struct {
    int channel_id;
    char *channel_name;
} LTE_TRANSPORT_CHANNEL_DESCRIPTION;

// PHY_LAYER_PARAMETERS struct definition
typedef struct {
    float tx_power_level;
    float rx_sensitivity;
} PHY_LAYER_PARAMETERS;

// PDU structure definition
typedef struct {
    LTE_TRANSPORT_CHANNEL_DESCRIPTION channel_desc;
    PHY_LAYER_PARAMETERS phy_params;
} PDU;

// buffer for storing PDU data
char pdu_buffer[MAX_BUFFER_SIZE];

// mutex for synchronizing access to the PDU buffer
pthread_mutex_t pdu_buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_pdu(PDU *pdu, int channel_id, char *channel_name) {
    // initialize the LTE_TRANSPORT_CHANNEL_DESCRIPTION struct
    pdu->channel_desc.channel_id = channel_id;
    pdu->channel_desc.channel_name = channel_name;

    // initialize the PHY_LAYER_PARAMETERS struct
    pdu->phy_params.tx_power_level = 10.0f;
    pdu->phy_params.rx_sensitivity = 5.0f;
}

void configure_pdu(PDU *pdu, float tx_power_level, float rx_sensitivity) {
    // update the PHY_LAYER_PARAMETERS struct with new values
    pdu->phy_params.tx_power_level = tx_power_level;
    pdu->phy_params.rx_sensitivity = rx_sensitivity;
}

int allocate_pdu(PDU **ppdu, int channel_id, char *channel_name) {
    // acquire the mutex for accessing the PDU buffer
    pthread_mutex_lock(&pdu_buffer_mutex);

    // check if there is enough space in the buffer for a new PDU
    if (sizeof(PDU) + strlen(channel_name) > MAX_BUFFER_SIZE - pdu_buffer_size) {
        // release the mutex and return an error code
        pthread_mutex_unlock(&pdu_buffer_mutex);
        return 1;
    }

    // allocate memory for the new PDU
    *ppdu = (PDU*)malloc(sizeof(PDU));
    if (*ppdu == NULL) {
        // release the mutex and return an error code
        pthread_mutex_unlock(&pdu_buffer_mutex);
        return 2;
    }

    // initialize the PDU with default values
    init_pdu(*ppdu, channel_id, channel_name);

    // update the buffer size and release the mutex
    pdu_buffer_size += sizeof(PDU) + strlen(channel_name);
    pthread_mutex_unlock(&pdu_buffer_mutex);

    return 0;
}

int deallocate_pdu(PDU *pdu) {
    // acquire the mutex for accessing the PDU buffer
    pthread_mutex_lock(&pdu_buffer_mutex);

    // check if the PDU is in the buffer
    if (pdu->channel_desc.channel_name == NULL) {
        // release the mutex and return an error code
        pthread_mutex_unlock(&pdu_buffer_mutex);
        return 1;
    }

    // free the memory allocated for the PDU
    free(pdu);

    // update the buffer size and release the mutex
    pdu_buffer_size -= sizeof(PDU) + strlen(pdu->channel_desc.channel_name);
    pthread_mutex_unlock(&pdu_buffer_mutex);

    return 0;
}

int configure_pdu_from_file(PDU *pdu, char *file_path) {
    // open the file for reading
    FILE *fp = fopen(file_path, "r");
    if (fp == NULL) {
        return 1;
    }

    // read the channel ID and name from the file
    int channel_id;
    char channel_name[256];
    if (fscanf(fp, "%d %s", &channel_id, channel_name) != 2) {
        fclose(fp);
        return 1;
    }

    // close the file and update the PDU with the new values
    fclose(fp);
    configure_pdu(pdu, pdu->phy_params.tx_power_level, pdu->phy_params.rx_sensitivity);

    return 0;
}
