['#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <semaphore.h>
#include <signal.h>

#define MAX_CONNECTIONS 1024
#define BUFFER_SIZE 1024

typedef struct {
    int socket;
    struct sockaddr_in address;
} connection_t;

connection_t connections[MAX_CONNECTIONS];

sem_t *semaphore;
pthread_mutex_t mutex;
int num_connections = 0;

void init() {
    int i;
    for (i = 0; i < MAX_CONNECTIONS; i++) {
        connections[i].socket = -1;
    }
}

void accept_incoming(int socket) {
    struct sockaddr_in client_address;
    socklen_t address_length = sizeof(client_address);
    int new_socket = accept(socket, (struct sockaddr *)&client_address, &address_length);
    if (new_socket == -1) {
        perror("accept");
        return;
    }
    pthread_mutex_lock(&mutex);
    int i;
    for (i = 0; i < MAX_CONNECTIONS; i++) {
        if (connections[i].socket == -1) {
            connections[i].socket = new_socket;
            connections[i].address = client_address;
            break;
        }
    }
    if (i == MAX_CONNECTIONS) {
        close(new_socket);
    } else {
        num_connections++;
        printf("New connection %d from %s:%d\n", i, inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));
    }
    pthread_mutex_unlock(&mutex);
}

void *service_connection(void *arg) {
    int socket = (int)arg;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;
    while ((bytes_received = recv(socket, buffer, BUFFER_SIZE, 0)) > 0) {
        printf("Received %d bytes from client\n", bytes_received);
        // process incoming data
    }
    if (bytes_received == -1) {
        perror("recv");
    } else {
        close(socket);
    }
    pthread_mutex_lock(&mutex);
    num_connections--;
    connections[socket].socket = -1;
    printf("Connection closed\n");
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void handle_signals(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        int i;
        for (i = 0; i < MAX_CONNECTIONS; i++) {
            if (connections[i].socket != -1) {
                close(connections[i].socket);
            }
        }
        pthread_mutex_destroy(&mutex);
        sem_close(semaphore);
        printf("Signal %d received. Closing connections and exiting\n", signal);
        exit(0);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signals;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int socket = socket(AF_INET, SOCK_STREAM, 0);
    if (socket == -1) {
        perror("socket");
        return 1;
    }

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_port = htons(1234);
    address.sin_addr.s_addr = INADDR_ANY;
    if (bind(socket, (struct sockaddr *)&address, sizeof(address)) == -1) {
        perror("bind");
        return 1;
    }

    if (listen(socket, MAX_CONNECTIONS) == -1) {
        perror("listen");
        return 1;
    }

    semaphore = sem_open("/sem", O_CREAT, 0644, 0);
    if (semaphore == SEM_FAILED) {
        perror("sem_open");
        return 1;
    }

    pthread_mutex_init(&mutex, NULL);

    init();

    while (1) {
        sem_wait(semaphore);
        accept_incoming(socket);
        sem_post(semaphore);

        if (num_connections > 0) {
            pthread_t thread;
            int i;
            for (i = 0; i < num_connections; i++) {
                if (connections[i].socket != -1) {
                    sem_wait(semaphore);
                    pthread_create(&thread, NULL, service_connection, (void *)connections[i].socket);
                    sem_post(semaphore);
                }
            }
        }
    }

    return 0;
}

