typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
} CRC_INDICATION_LIST_T;

/**
 * Initialize the CRC indicator list with a given capacity.
 */
void crcIndicatorListInit(CRC_INDICATION_LIST_T* list, size_t capacity) {
    assert(list != NULL);
    assert(capacity > 0);

    // Allocate memory for the list and its elements
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    list->capacity = capacity;
    list->size = 0;
}

/**
 * Add a new CRC indication data structure to the list, updating an existing one if duplicates exist.
 */
void crcIndicatorListAdd(CRC_INDICATION_LIST_T* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    assert(list != NULL);
    assert(pdu != NULL);

    // Check if the RNTI is already in the list
    bool found = false;
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].rnti == pdu->rnti) {
            // Update the existing entry with the new data
            list->data[i] = *pdu;
            found = true;
            break;
        }
    }

    // Add a new entry if the RNTI was not found in the list
    if (!found) {
        list->data[list->size++] = *pdu;
    }
}

/**
 * Remove an entry from the CRC indicator list by its RNTI.
 */
void crcIndicatorListRemove(CRC_INDICATION_LIST_T* list, uint16_t rnti) {
    assert(list != NULL);

    // Find the index of the entry to be removed
    size_t i = 0;
    for (; i < list->size; ++i) {
        if (list->data[i].rnti == rnti) {
            break;
        }
    }

    // Remove the entry by shifting all elements after it one position to the left
    if (i < list->size) {
        for (size_t j = i; j < list->size - 1; ++j) {
            list->data[j] = list->data[j + 1];
        }
        --list->size;
    }
}

/**
 * Check if an entry with a given RNTI exists in the CRC indicator list.
 */
bool crcIndicatorListContains(CRC_INDICATION_LIST_T* list, uint16_t rnti) {
    assert(list != NULL);

    // Iterate through the entries and check if the given RNTI exists
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].rnti == rnti) {
            return true;
        }
    }
    return false;
}

/**
 * Discard the oldest entries in the CRC indicator list to maintain a maximum size of 100 elements.
 */
void crcIndicatorListDiscard(CRC_INDICATION_LIST_T* list) {
    assert(list != NULL);

    // Check if the list needs to be trimmed
    if (list->size > 100) {
        size_t discardCount = list->size - 100;
        for (size_t i = 0; i < discardCount; ++i) {
            // Remove the oldest entry by shifting all elements one position to the left
            list->data[i] = list->data[i + 1];
        }
        --list->size;
    }
}

/**
 * Main function for handling CRC indications.
 */
void handleCrcIndication(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    assert(pdu != NULL);

    // Initialize the CRC indicator list if it has not been initialized yet
    static CRC_INDICATION_LIST_T crcIndicatorList;
    if (crcIndicatorList.data == NULL) {
        crcIndicatorListInit(&crcIndicatorList, 100);
    }

    // Add the new CRC indication data structure to the list
    crcIndicatorListAdd(&crcIndicatorList, pdu);

    // Check if the list needs to be trimmed
    crcIndicatorListDiscard(&crcIndicatorList);
}
