// Custom data structure to represent a network event
typedef struct {
    uint64_t timestamp;   // Timestamp of the event
    int type;             // Type of the event (e.g., connection established)
    int status;           // Status of the event (e.g., success, failure)
    char* metadata;       // Associated metadata (e.g., IP address and payload size)
} network_event_t;

// Structure to hold a list of network events
typedef struct {
    int num_events;         // Number of events in the list
    network_event_t* events;   // Array of event structures
} network_event_list_t;

// Function to add an event to the list and update cache
void add_event(network_event_list_t* list, network_event_t event) {
    int index = 0;
    while (index < list->num_events && list->events[index].timestamp < event.timestamp) {
        index++;
    }
    if (index == list->num_events) {
        list->events = realloc(list->events, (list->num_events + 1) * sizeof(network_event_t));
        list->events[list->num_events].timestamp = event.timestamp;
        list->events[list->num_events].type = event.type;
        list->events[list->num_events].status = event.status;
        list->events[list->num_events].metadata = event.metadata;
        list->num_events++;
    } else {
        memmove(&list->events[index + 1], &list->events[index], (list->num_events - index) * sizeof(network_event_t));
        list->events[index].timestamp = event.timestamp;
        list->events[index].type = event.type;
        list->events[index].status = event.status;
        list->events[index].metadata = event.metadata;
    }
}

// Function to update an event in the list and update cache
void update_event(network_event_list_t* list, network_event_t event) {
    int index = 0;
    while (index < list->num_events && list->events[index].timestamp < event.timestamp) {
        index++;
    }
    if (index == list->num_events) {
        add_event(list, event);
    } else {
        list->events[index].timestamp = event.timestamp;
        list->events[index].type = event.type;
        list->events[index].status = event.status;
        list->events[index].metadata = event.metadata;
    }
}

// Function to retrieve an event from the list by timestamp
network_event_t get_event(network_event_list_t* list, uint64_t timestamp) {
    int index = 0;
    while (index < list->num_events && list->events[index].timestamp < timestamp) {
        index++;
    }
    if (index == list->num_events) {
        return NULL;
    } else {
        return list->events[index];
    }
}

// Function to retrieve all events from the list by status
network_event_list_t* get_events(network_event_list_t* list, int status) {
    network_event_list_t* result = malloc(sizeof(network_event_list_t));
    result->num_events = 0;
    for (int i = 0; i < list->num_events; i++) {
        if (list->events[i].status == status) {
            network_event_t* event = malloc(sizeof(network_event_t));
            event->timestamp = list->events[i].timestamp;
            event->type = list->events[i].type;
            event->status = list->events[i].status;
            event->metadata = list->events[i].metadata;
            result->num_events++;
            result->events = realloc(result->events, result->num_events * sizeof(network_event_t));
            result->events[result->num_events - 1] = event;
        }
    }
    return result;
}

// Function to retrieve all events from the list by source IP
network_event_list_t* get_events_by_source(network_event_list_t* list, char* ip) {
    network_event_list_t* result = malloc(sizeof(network_event_list_t));
    result->num_events = 0;
    for (int i = 0; i < list->num_events; i++) {
        if (strcmp(list->events[i].metadata.ip, ip) == 0) {
            network_event_t* event = malloc(sizeof(network_event_t));
            event->timestamp = list->events[i].timestamp;
            event->type = list->events[i].type;
            event->status = list->events[i].status;
            event->metadata = list->events[i].metadata;
            result->num_events++;
            result->events = realloc(result->events, result->num_events * sizeof(network_event_t));
            result->events[result->num_events - 1] = event;
        }
    }
    return result;
}
