Here is a sample C function for managing a dynamic list of custom data structures representing network events:
```c
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for each event in the list
typedef struct {
    long timestamp;
    char* event_type;
    int status;
    char* source_ip;
    unsigned short port;
} Event;

// Create a linked list to store the events
struct ListNode {
    Event event;
    struct ListNode* next;
};

// Define the head node of the list
static struct ListNode* head = NULL;

// Function to add a new event to the list
void add_event(long timestamp, char* event_type, int status, char* source_ip, unsigned short port) {
    // Create a new node for the event
    struct ListNode* new_node = malloc(sizeof(struct ListNode));
    if (new_node == NULL) {
        printf("Failed to allocate memory for new event\n");
        return;
    }

    // Initialize the event fields
    new_node->event.timestamp = timestamp;
    new_node->event.event_type = strdup(event_type);
    new_node->event.status = status;
    new_node->event.source_ip = strdup(source_ip);
    new_node->event.port = port;

    // Add the event to the list
    if (head == NULL) {
        head = new_node;
    } else {
        struct ListNode* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to update an existing event in the list by timestamp
void update_event(long timestamp, char* event_type, int status, char* source_ip, unsigned short port) {
    // Find the node with the specified timestamp
    struct ListNode* current = head;
    while (current != NULL && current->event.timestamp != timestamp) {
        current = current->next;
    }

    // If the event is found, update its fields
    if (current != NULL) {
        current->event.event_type = strdup(event_type);
        current->event.status = status;
        current->event.source_ip = strdup(source_ip);
        current->event.port = port;
    } else {
        printf("Event with timestamp %ld not found\n", timestamp);
    }
}

// Function to retrieve events filtered by status, source IP, or event type
void get_events(int status, char* source_ip, char* event_type) {
    // Create a new linked list for the retrieved events
    struct ListNode* retrieved = NULL;

    // Iterate through the list and add the events that match the filters
    struct ListNode* current = head;
    while (current != NULL) {
        if ((status == -1 || current->event.status == status) &&
            (source_ip == NULL || strcmp(current->event.source_ip, source_ip) == 0) &&
            (event_type == NULL || strcmp(current->event.event_type, event_type) == 0)) {
                struct ListNode* new_node = malloc(sizeof(struct ListNode));
                if (new_node != NULL) {
                    new_node->event = current->event;
                    new_node->next = retrieved;
                    retrieved = new_node;
                } else {
                    printf("Failed to allocate memory for retrieved event\n");
                    break;
                }
            }
        current = current->next;
    }

    // Print the retrieved events in JSON format
    char* json = NULL;
    struct ListNode* current2 = retrieved;
    while (current2 != NULL) {
        if (json == NULL) {
            json = malloc(1024);
            if (json == NULL) {
                printf("Failed to allocate memory for JSON string\n");
                break;
            }
            snprintf(json, 1024, "{\"timestamp\":%ld,\"event_type\":\"%s\",\"status\":%d,\"source_ip\":\"%s\",\"port\":%u}",
                     current2->event.timestamp, current2->event.event_type, current2->event.status, current2->event.source_ip, current2->event.port);
        } else {
            json = realloc(json, strlen(json) + 1024);
            if (json == NULL) {
                printf("Failed to allocate memory for JSON string\n");
                break;
            }
            snprintf(json + strlen(json), 1024, "{\"timestamp\":%ld,\"event_type\":\"%s\",\"status\":%d,\"source_ip\":\"%s\",\"port\":%u}",
                     current2->event.timestamp, current2->event.event_type, current2->event.status, current2->event.source_ip, current2->event.port);
        }
        current2 = current2->next;
    }
    if (json != NULL) {
        printf("%s\n", json);
    } else {
        printf("No events found that match the filters\n");
    }
}

// Function to export the list to a file in JSON format
void export_events(char* filename) {
    // Open the file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Failed to open file %s for writing\n", filename);
        return;
    }

    // Write the JSON-formatted events to the file
    struct ListNode* current = head;
    while (current != NULL) {
        char* json = malloc(1024);
        if (json == NULL) {
            printf("Failed to allocate memory for JSON string\n");
            break;
        }
        snprintf(json, 1024, "{\"timestamp\":%ld,\"event_type\":\"%s\",\"status\":%d,\"source_ip\":\"%s\",\"port\":%u}",
                 current->event.timestamp, current->event.event_type, current->event.status, current->event.source_ip, current->event.port);
        fprintf(fp, "%s\n", json);
        free(json);
        current = current->next;
    }

    // Close the file
    fclose(fp);
}

// Function to import events from a JSON-formatted file
void import_events(char* filename) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Failed to open file %s for reading\n", filename);
        return;
    }

    // Read the events from the file and add them to the list
    char buffer[1024];
    while (fgets(buffer, 1024, fp) != NULL) {
        char* json = malloc(strlen(buffer));
        if (json == NULL) {
            printf("Failed to allocate memory for JSON string\n");
            break;
        }
        strcpy(json, buffer);
        struct ListNode* new_node = malloc(sizeof(struct ListNode));
        if (new_node == NULL) {
            printf("Failed to allocate memory for new node\n");
            free(json);
            break;
        }
        new_node->event.timestamp = strtol(strchr(json, ':') + 1, &buffer, 10);
        new_node->event.event_type = malloc(strlen(buffer));
        if (new_node->event.event_type == NULL) {
            printf("Failed to allocate memory for event type\n");
            free(json);
            free(new_node);
            break;
        }
        strcpy(new_node->event.event_type, buffer);
        new_node->event.status = atoi(strchr(buffer, ':') + 1);
        new_node->event.source_ip = malloc(strlen(buffer));
        if (new_node->event.source_ip == NULL) {
            printf("Failed to allocate memory for source IP\n");
            free(json);
            free(new_node->event.event_type);
            free(new_node);
            break;
        }
        strcpy(new_node->event.source_ip, buffer);
        new_node->event.port = atoi(strchr(buffer, ':') + 1);
        if (head == NULL) {
            head = new_node;
        } else {
            struct ListNode* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    // Close the file
    fclose(fp);
}
```

This code defines a `struct ListNode` that represents a node in a linked list. The `head` variable is used to keep track of the beginning of the linked list. The `add_event()` function adds an event to the end of the linked list, and the `get_events()` function retrieves events from the linked list based on their timestamp, event type, and source IP.

The `export_events()` function exports all events in the linked list to a JSON-formatted file, while the `import_events()` function imports events from a JSON-formatted file into the linked list.

This code uses a combination of `malloc()`, `realloc()`, and `free()` to dynamically allocate memory for each node in the linked list, as well as for temporary buffers used during the export and import operations. It also uses `fopen()`, `fgets()`, and `fclose()` to read and write from the file, respectively.

This code assumes that the events are stored in a file with one event per line, and that each event is formatted as JSON data (i.e., an object containing timestamp, event type, source IP, and port information). The events are exported in the same format, and they can be imported back into the linked list by passing the file to the `import_events()` function.']

