#define NF_API_FILE_STAT_INFO struct nf_api_file_stat_info { \
    char file_name[PATH_MAX]; \
    unsigned long size; \
    time_t last_modified_time; \
    mode_t permissions; \
}
#endif

// Function to read and validate the file paths from standard input
// and calculate the size of the largest file in bytes.
int get_largest_file_size() {
    // Array to store the file paths
    char **files = NULL;

    // Number of files in the array
    int n_files = 0;

    // Pointer to the largest file size
    unsigned long *largest_file_size = NULL;

    // Loop through each file path provided by standard input
    while (fgets(file, PATH_MAX, stdin)) {
        // Trim newlines from the file path
        file[strcspn(file, "\n")] = '\0';

        // Check if the file exists and is accessible
        struct stat buf;
        if (stat(file, &buf) == -1) {
            fprintf(stderr, "Error: File '%s' does not exist or is not accessible.\n", file);
            continue;
        }

        // Add the file path to the array of files
        n_files++;
        char **tmp = realloc(files, n_files * sizeof(*files));
        if (tmp == NULL) {
            fprintf(stderr, "Error: Realloc failed.\n");
            free(files);
            return -1;
        }
        files = tmp;
        files[n_files - 1] = strdup(file);

        // Calculate the size of the largest file so far
        if (largest_file_size == NULL) {
            largest_file_size = malloc(sizeof(*largest_file_size));
            *largest_file_size = buf.st_size;
        } else if (buf.st_size > *largest_file_size) {
            *largest_file_size = buf.st_size;
        }
    }

    // Print the size of the largest file in bytes
    printf("Largest file size: %lu\n", *largest_file_size);

    // Populate an array of `NF_API_FILE_STAT_INFO` structures with detailed metadata about each file
    NF_API_FILE_STAT_INFO *file_stats = malloc(n_files * sizeof(*file_stats));
    if (file_stats == NULL) {
        fprintf(stderr, "Error: Malloc failed.\n");
        free(files);
        return -1;
    }
    for (int i = 0; i < n_files; i++) {
        char *file_name = files[i];
        struct stat buf;
        if (stat(file_name, &buf) == -1) {
            fprintf(stderr, "Error: File '%s' does not exist or is not accessible.\n", file_name);
            continue;
        }
        file_stats[i].file_name = strdup(file_name);
        file_stats[i].size = buf.st_size;
        file_stats[i].last_modified_time = buf.st_mtime;
        file_stats[i].permissions = buf.st_mode;
    }

    // Clean up resources
    free(files);
    free(largest_file_size);
    return 0;
}
