void process_lists(int *lists, int list_count) {
    // Initialize the structures to hold the data
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list_count);
    if (!pdu_list) {
