        pdu_list[i].rnti = lists[i];
        pdu_list[i].crc_indication_rel8_tag = (unsigned char)rand() % 256;
        pdu_list[i].crcflag = (pdu_list[i].crc_indication_rel8_tag == 0) ? 1 : 0;
    }

    // Print the largest integer in each list using a separate helper function
    for (int i = 0; i < list_count; ++i) {
        printf("List %d: ", i + 1);
        print_largest_integer(pdu_list[i]);
    }

    // Clean up the memory allocated for the PDU list
    free(pdu_list);
}

// Define the helper function to print the largest integer in a list
void print_largest_integer(NFAPI_CRC_INDICATION_PDU_T pdu) {
    int max = -1;
    for (int i = 0; i < pdu.rnti; ++i) {
        if (max < lists[i]) {
            max = lists[i];
