    return records;
}

// function to append a slash to a string if within size limit
char* appendSlashIfWithinLimit(const char *string, int size_limit) {
    int length = strlen(string);
    if (length >= size_limit) {
        return NULL;
    } else {
        char *new_string = malloc(sizeof(char) * (size_limit + 1));
        memcpy(new_string, string, length);
        new_string[length] = '/';
        new_string[length + 1] = '\0';
        return new_string;
    }
}
