// Establish a connection to the remote server using an asynchronous I/O framework
void establish_connection(struct conn *conn) {
    // Define the connection attempt counter and maximum backoff time
    int retry_counter = 0;
    double max_backoff_time = 60;

    // Loop until a successful connection is established or the maximum number of retries is reached
    while (retry_counter < MAX_RETRIES) {
        // Initialize the SSL context and BIO
        struct ssl_ctx ctx;
        init_ssl_ctx(&ctx);

        // Create a new SSL object for the connection
        SSL *ssl = SSL_new(ctx.ssl_context);
