  // Read the individual structures from the file and add them to the list
  for (size_t i = 0; i < len; ++i) {
    size_t struct_len;
    if (fread(&struct_len, sizeof(size_t), 1, fp) != 1) {
      perror("fread failed");
      exit(EXIT_FAILURE);
    }

    // Dynamically allocate memory for the structure
    NFAPI_UE_CAPABILITY_INDICATION *new_struct = calloc(struct_len, 1);
    if (!new_struct) {
      perror("calloc failed");
      exit(EXIT_FAILURE);
    }

    // Read the structure from the file
    if (fread(new_struct, struct_len, 1, fp) != 1) {
      perror("fread failed");
      exit(EXIT_FAILURE);
    }

    add_structure(new_struct);
  }

  // Close the binary file for reading
  if (fclose(fp)) {
    perror("fclose failed");
    exit(EXIT_FAILURE);
  }

  // Release the mutex for protecting the list data structure from concurrent access
  pthread_mutex_unlock(&list_lock);

  return true;
}
