// Define the maximum size of the queue as a constant
#define QUEUE_MAX_SIZE 512

// Structure to hold the data for each measurement
typedef struct {
    NFAPI_RRC_MEASUREMENT_T *measurement; // Pointer to the actual measurement data
    size_t capacity; // The capacity of the current structure
} MeasurementStruct;

// Function to enqueue a new measurement in the queue
int enqueueMeasurement(NFAPI_RRC_MEASUREMENT_T *measurement) {
    // Check if the queue is full
    if (queue_size == QUEUE_MAX_SIZE) {
        return -1;
    }

    // Allocate memory for the new measurement structure
    MeasurementStruct *new_struct = malloc(sizeof(MeasurementStruct));
    if (!new_struct) {
        return -2;
    }

    // Copy the contents of the current measurement into the new structure
    memcpy(new_struct, measurement, sizeof(NFAPI_RRC_MEASUREMENT_T));

    // Enqueue the new structure in the queue
    queue[queue_size++] = new_struct;

    return 0;
}

// Function to dequeue a measurement from the queue
int dequeueMeasurement(NFAPI_RRC_MEASUREMENT_T *measurement) {
    // Check if the queue is empty
    if (queue_size == 0) {
        return -1;
    }

    // Copy the contents of the current measurement into the output parameter
    memcpy(measurement, queue[--queue_size], sizeof(NFAPI_RRC_MEASUREMENT_T));

    // Free the memory of the dequeued structure
    free(queue[queue_size]);

    return 0;
}

// Function to resize the queue when it reaches its maximum size
void resizeQueue() {
    // Allocate a new buffer for the resized queue
    MeasurementStruct *new_queue = malloc(QUEUE_MAX_SIZE * sizeof(MeasurementStruct));
    if (!new_queue) {
        return;
    }

    // Copy the contents of the old queue to the new one
    memcpy(new_queue, queue, queue_size * sizeof(MeasurementStruct));

    // Free the memory of the old queue
    free(queue);

    // Update the pointers and size of the queue
    queue = new_queue;
    queue_size = QUEUE_MAX_SIZE;
}

// Main function to handle enqueuing, dequeuing, and resizing the queue
int main() {
    int i;

    // Initialize the queue with a default size of 512 elements
    MeasurementStruct *queue = malloc(QUEUE_MAX_SIZE * sizeof(MeasurementStruct));
    if (!queue) {
        return -1;
    }
    queue_size = 0;

    // Enqueue some sample measurements
    for (i = 0; i < 5; ++i) {
        NFAPI_RRC_MEASUREMENT_T measurement;
        measurement.measurement_type = MEASUREMENT_TYPE_CELLULAR;
        measurement.cell_id = 12345;
        measurement.tx_power_level = 10;

        enqueueMeasurement(&measurement);
    }

    // Dequeue the measurements and print them to the console
    for (i = 0; i < queue_size; ++i) {
        NFAPI_RRC_MEASUREMENT_T measurement;

        dequeueMeasurement(&measurement);

        printf("Measurement %d: Type=%d, Cell ID=%d, TX Power Level=%d\n", i + 1, measurement.measurement_type, measurement.cell_id, measurement.tx_power_level);
    }

    // Resize the queue to accommodate a larger burst of data
    resizeQueue();

    // Enqueue more sample measurements
    for (i = 0; i < 10; ++i) {
        NFAPI_RRC_MEASUREMENT_T measurement;
        measurement.measurement_type = MEASUREMENT_TYPE_CELLULAR;
        measurement.cell_id = 12345 + i;
        measurement.tx_power_level = 10 * (i + 1);

        enqueueMeasurement(&measurement);
    }

    // Dequeue the measurements and print them to the console
    for (i = 0; i < queue_size; ++i) {
        NFAPI_RRC_MEASUREMENT_T measurement;

        dequeueMeasurement(&measurement);

        printf("Measurement %d: Type=%d, Cell ID=%d, TX Power Level=%d\n", i + 1, measurement.measurement_type, measurement.cell_id, measurement.tx_power_level);
    }

    // Free the memory of the queue
    free(queue);

    return 0;
}
