    LTE_RRC_UE_IDENTITY_RESPONSE response;
} LTE_RRC_Message_Type;

// Define the array for storing the LTE RRC messages
LTE_RRC_Message_Type *messages = NULL;

// Define the size of the array
int message_size = 0;

// Define the semaphore to control access from multiple threads
sem_t mutex;

// Define the method for logging array operations
#define LOGGING_ENABLED false
#define LOG(format, ...) if (LOGGING_ENABLED) { printf(format, __VA_ARGS__); }

void init_messages() {
    // Initialize the array to hold 10 messages by default
    message_size = 10;
    messages = malloc(sizeof(LTE_RRC_Message_Type) * message_size);
    if (messages == NULL) {
        LOG("Error: Failed to allocate memory for message array\n");
    }
}

void add_message(LTE_RRC_Message_Type *message) {
    // Acquire the mutex to ensure thread-safe access
    sem_wait(&mutex);

    // Check if the array needs to be resized
    if (message_size == messages->count) {
        message_size += 10;
        LTE_RRC_Message_Type *new_messages = realloc(messages, sizeof(LTE_RRC_Message_Type) * message_size);
        if (new_messages == NULL) {
            LOG("Error: Failed to resize message array\n");
        } else {
            messages = new_messages;
        }
    }

    // Add the new message to the end of the array
    messages[messages->count++] = *message;

    // Release the mutex
    sem_post(&mutex);
}

LTE_RRC_Message_Type* get_message(int index) {
    // Acquire the mutex to ensure thread-safe access
    sem_wait(&mutex);

    // Check if the index is within bounds
    if (index < 0 || index >= messages->count) {
        LOG("Error: Index out of bounds\n");
        return NULL;
    }

    // Return the message at the specified index
    LTE_RRC_Message_Type *message = &messages[index];

    // Release the mutex
    sem_post(&mutex);

    return message;
}

void cleanup() {
    // Acquire the mutex to ensure thread-safe access
    sem_wait(&mutex);

    // Free any unused messages in the array
    int i = 0;
    while (i < messages->count) {
        if (messages[i].request == NULL && messages[i].response == NULL) {
            for (int j = i; j < messages->count - 1; j++) {
                messages[j] = messages[j + 1];
            }
            messages->count--;
        } else {
            i++;
        }
    }

    // Release the mutex
    sem_post(&mutex);
}
