    // Check if the array is full
    if (num_ues >= MAX_ARRAY_SIZE) {
        return -2;
    }

    // Allocate memory for the new UE instance
    NFAPI_LTE_PHY_PDU_T *new_instance = (NFAPI_LTE_PHY_PDU_T *)calloc(1, sizeof(NFAPI_LTE_PHY_PDU_T));
    if (new_instance == NULL) {
        return -3;
    }

    // Add the new UE instance to the array
    (*pdu_array)[num_ues] = new_instance;
    num_ues++;

    // Return success
    return 0;
}

// Define the function to remove a UE instance from the array
int remove_ue_instance(NFAPI_LTE_PHY_PDU_T **pdu_array, int num_ues) {
    // Validate the input parameters
    if (pdu_array == NULL || num_ues <= 0) {
        return -1;
    }

    // Check if the array is empty
    if (num_ues <= 0) {
        return -2;
    }

    // Remove the last UE instance from the array
    (*pdu_array)[--num_ues] = NULL;

    // Free the memory allocated for the removed UE instance
    free((*pdu_array)[num_ues]);
    (*pdu_array)[num_ues] = NULL;

    // Return success
    return 0;
}

// Define the function to validate the integrity of a PDU structure
int validate_pdu(NFAPI_LTE_PHY_PDU_T *pdu) {
    // Validate the input parameters
    if (pdu == NULL) {
        return -1;
    }

    // Check if the PDU has a valid size
    if (pdu->tx_ue_data_pdu.pdu_size <= 0 || pdu->mac_pdu.pdu_size <= 0) {
        return -2;
    }

    // Return success
    return 0;
}

// Define the function to add a new PDU structure to the array
int add_pdu(NFAPI_LTE_PHY_PDU_T **pdu_array, int num_ues) {
    // Validate the input parameters
    if (pdu_array == NULL || num_ues <= 0) {
        return -1;
    }

    // Check if the array is full
    if (num_ues >= MAX_ARRAY_SIZE) {
        return -2;
    }

    // Allocate memory for the new PDU structure
    NFAPI_LTE_PHY_PDU_T *new_pdu = (NFAPI_LTE_PHY_PDU_T *)calloc(1, sizeof(NFAPI_LTE_PHY_PDU_T));
    if (new_pdu == NULL) {
        return -3;
    }

    // Add the new PDU structure to the array
    (*pdu_array)[num_ues] = new_pdu;
    num_ues++;

    // Return success
