} NFAPI_LTE_PHY_CONTEXT_T;

// Define the function to initialize a PDU
void nfapi_lte_phy_pdu_init(NFAPI_LTE_PHY_CONTEXT_T *context, NFAPI_LTE_PHY_PDU_T *pdu) {
    assert(context != NULL);
    assert(pdu != NULL);

    // Initialize the PDU structure with default values
    pdu->valid = true;
    pdu->modulation_scheme = NFAPI_MODULATION_SCHEME_QPSK;
    pdu->transport_format = NFAPI_TRANSPORT_FORMAT_16QAM;
    memset(pdu->tx_ue_data_pdu, 0, NFAPI_LTE_MAX_UE_PER_CELL * NFAPI_LTE_MAX_PDU_SIZE);
    memset(pdu->mac_pdu, 0, NFAPI_LTE_MAX_MAC_PDU_SIZE);
}

// Define the function to add a PDU to the list of PDUS
void nfapi_lte_phy_pdu_add(NFAPI_LTE_PHY_CONTEXT_T *context, NFAPI_LTE_PHY_PDU_T *pdu) {
    assert(context != NULL);
    assert(pdu != NULL);

    // Add the PDU to the list of PDUS
    context->pdu_list[context->num_pdus++].pdu_list = pdu;
}

// Define the function to remove a PDU from the list of PDUs
void nfapi_lte_phy_pdu_remove(NFAPI_LTE_PHY_CONTEXT_T *context, NFAPI_LTE_PHY_PDU_T *pdu) {
    assert(context != NULL);
    assert(pdu != NULL);

    // Remove the PDU from the list of PDUs
    for (int i = 0; i < context->num_pdus; i++) {
        if (context->pdu_list[i].pdu_list == pdu) {
            memmove(&context->pdu_list[i], &context->pdu_list[i + 1], sizeof(NFAPI_LTE_PHY_PDU_T) * (context->num_pdus - i - 1));
            context->num_pdus--;
            break;
        }
    }
}

// Define the function to allocate a PDU from the list of PDUs
void nfapi_lte_phy_pdu_alloc(NFAPI_LTE_PHY_CONTEXT_T *context, NFAPI_LTE_PHY_PDU_T **pdu) {
    assert(context != NULL);
    assert(pdu != NULL);

    // Allocate a PDU from the list of PDUs
    if (context->num_pdus < NFAPI_MAX_PDU) {
        *pdu = malloc(sizeof(NFAPI_LTE_PHY_PDU_T));
        nfapi_lte_phy_pdu_init(context, *pdu);
    } else {
        printf("Maximum number of PDUs exceeded\n");
    }
}

// Define the function to deallocate a PDU from the list of PDUS
void nfapi_lte_phy_pdu_dealloc(NFAPI_LTE_PHY_CONTEXT_T *context, NFAPI_LTE_PHY_PDU_T **pdu) {
    assert(context != NULL);
    assert(pdu != NULL);

