    // Number of elements in the array
    size_t count;
    // Maximum capacity of the array
    size_t capacity;
    // Mutex to protect concurrent access from multiple threads
    pthread_mutex_t mutex;
};

// Define a function to manage memory allocation for the cache data structure
struct cache* allocate_cache(size_t initial_capacity) {
    struct cache* cache = malloc(sizeof(struct cache));
    if (!cache) {
        log_error("Failed to allocate cache");
        return NULL;
    }
    cache->records = malloc(initial_capacity * sizeof(struct record));
    if (!cache->records) {
        log_error("Failed to allocate records for cache");
        free(cache);
        return NULL;
    }
    cache->count = 0;
    cache->capacity = initial_capacity;
    pthread_mutex_init(&cache->mutex, NULL);
    return cache;
}

// Define a function to manage memory deallocation for the cache data structure
void free_cache(struct cache* cache) {
    if (!cache) {
        return;
    }
    pthread_mutex_destroy(&cache->mutex);
    free(cache->records);
    free(cache);
}

// Define a function to manage memory allocation for the record array
struct record* allocate_records(size_t size) {
    struct record* records = malloc(size * sizeof(struct record));
    if (!records) {
        log_error("Failed to allocate records");
        return NULL;
    }
    // Initialize each record with a random value within the specified range
    for (size_t i = 0; i < size; i++) {
        records[i].value = rand() % MAX_RANGE + MIN_RANGE;
    }
    return records;
}

// Define a function to manage memory deallocation for the record array
void free_records(struct record* records, size_t size) {
    if (!records) {
        return;
    }
    free(records);
}

// Define a function to manage memory allocation for the key array
int* allocate_keys(size_t size) {
    int* keys = malloc(size * sizeof(int));
    if (!keys) {
        log_error("Failed to allocate keys");
        return NULL;
    }
    // Initialize each key with a unique value within the specified range
    for (size_t i = 0; i < size; i++) {
        keys[i] = i + MIN_RANGE;
    }
    return keys;
}

// Define a function to manage memory deallocation for the key array
void free_keys(int* keys, size_t size) {
    if (!keys) {
        return;
    }
    free(keys);
}

// Define a function to manage dynamic scaling of the cache based on input size
struct cache* scale_cache(struct cache* cache, size_t new_capacity) {
    if (new_capacity <= cache->capacity) {
        return cache;
    }
    struct cache* new_cache = allocate_cache(new_capacity);
    if (!new_cache) {
        log_error("Failed to scale cache");
        free_cache(cache);
        return NULL;
    }
    // Copy the existing records into the new cache
    for (size_t i = 0; i < cache->count; i++) {
        struct record* record = &cache->records[i];
        new_cache->records[i] = *record;
    }
    // Update the count and capacity of the new cache
    new_cache->count = cache->count;
    new_cache->capacity = new_capacity;
    free_cache(cache);
    return new_cache;
}

// Define a function to manage dynamic scaling of the record array based on input size
struct record* scale_records(struct record* records, size_t new_size) {
    if (new_size <= records->capacity) {
        return records;
    }
    struct record* new_records = malloc(new_size * sizeof(struct record));
    if (!new_records) {
        log_error("Failed to scale records");
        free(records);
        return NULL;
    }
    // Copy the existing records into the new array
    for (size_t i = 0; i < records->count; i++) {
        struct record* record = &records[i];
        new_records[i] = *record;
    }
    // Update the count and capacity of the new array
    new_records->count = records->count;
    new_records->capacity = new_size;
    free(records);
    return new_records;
}

// Define a function to manage dynamic scaling of the key array based on input size
int* scale_keys(int* keys, size_t new_size) {
    if (new_size <= keys->capacity) {
        return keys;
    }
    int* new_keys = malloc(new_size * sizeof(int));
    if (!new_keys) {
        log_error("Failed to scale keys");
        free(keys);
        return NULL;
    }
    // Copy the existing keys into the new array
    for (size_t i = 0; i < keys->count; i++) {
        new_keys[i] = keys[i];
    }
    // Update the count and capacity of the new array
    new_keys->count = keys->count;
    new_keys->capacity = new_size;
    free(keys);
    return new_keys;
}

// Define a function to manage concurrent access to the cache data structure
void* manage_cache(struct cache* cache, size_t size) {
    if (!cache) {
        log_error("Cache is null");
        return NULL;
    }
    // Acquire the lock for the cache
    pthread_mutex_lock(&cache->mutex);
    // Check if the cache has enough capacity to store the new records
    if (size > cache->capacity) {
        // Scale the cache up to fit the new size
        struct cache* new_cache = scale_cache(cache, size);
        if (!new_cache) {
            log_error("Failed to scale cache");
            return NULL;
        }
        cache = new_cache;
    }
    // Release the lock for the cache
    pthread_mutex_unlock(&cache->mutex);
    return (void*) cache;
}

// Define a function to manage concurrent access to the record array
struct record* manage_records(struct record* records, size_t size) {
    if (!records) {
        log_error("Records are null");
        return NULL;
    }
    // Acquire the lock for the record array
    pthread_mutex_lock(&records->mutex);
    // Check if the record array has enough capacity to store the new records
    if (size > records->capacity) {
        // Scale the record array up to fit the new size
        struct record* new_records = scale_records(records, size);
        if (!new_records) {
            log_error("Failed to scale records");
            return NULL;
        }
        records = new_records;
    }
    // Release the lock for the record array
    pthread_mutex_unlock(&records->mutex);
    return (void*) records;
}

