    pthread_mutex_lock(&keys->mutex);
    // Check if the key array has enough capacity to store the new keys
    if (size > keys->capacity) {
        // Scale the key array up to fit the new size
        int* new_keys = scale_keys(keys, size);
        if (!new_keys) {
            log_error("Failed to scale keys");
            return NULL;
        }
        keys = new_keys;
    }
    // Release the lock for the key array
    pthread_mutex_unlock(&keys->mutex);
    return (void*) keys;
}

// Define a function to manage concurrent access to the cache data structure and the record array
struct cache* manage_cache_and_records(struct cache* cache, struct record* records, size_t size) {
    if (!cache || !records) {
        log_error("Cache or records are null");
        return NULL;
    }
    // Acquire the lock for both the cache and the record array
    pthread_mutex_lock(&cache->mutex);
    pthread_mutex_lock(&records->mutex);
    // Check if the cache has enough capacity to store the new records
    if (size > cache->capacity) {
        // Scale the cache up to fit the new size
        struct cache* new_cache = scale_cache(cache, size);
        if (!new_cache) {
            log_error("Failed to scale cache");
            return NULL;
        }
        cache = new_cache;
    }
    // Check if the record array has enough capacity to store the new records
    if (size > records->capacity) {
        // Scale the record array up to fit the new size
        struct record* new_records = scale_records(records, size);
        if (!new_records) {
            log_error("Failed to scale records");
