void check_duplicate_rntis() {
    // Iterate through the list and keep track of the number of unique RNTIs
    uint32_t num_unique_rntis = 0;
    for (size_t i = 0; i < list.num_elements; i++) {
        bool found = false;
        // Iterate through the rest of the list to find any duplicates
        for (size_t j = i + 1; j < list.num_elements; j++) {
            if (list.data[i].RNTI == list.data[j].RNTI) {
                found = true;
                break;
            }
        }
        // If no duplicate is found, increment the number of unique RNTIs
        if (!found) {
            num_unique_rntis++;
        }
    }

    // Print a warning message if any duplicates are found
    if (num_unique_rntis < list.num_elements) {
