NFAPI_CRC_INDICATION_PDU_T* init_crc_indication(int num_pdu, json_object *config) {
    // Allocate memory for the list of PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_pdu * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Read configuration settings from JSON file
    int seed = json_object_get_int(json_object_object_get(config, "seed"));
    int rx_ue_information_tag_min = json_object_get_int(json_object_object_get(config, "rx_ue_information_tag_min"));
    int rx_ue_information_tag_max = json_object_get_int(json_object_object_get(config, "rx_ue_information_tag_max"));
    float crcflag_probability = json_object_get_float(json_object_object_get(config, "crcflag_probability"));

    // Seed the random number generator with a specified seed
    srand(seed);

    for (int i = 0; i < num_pdu; i++) {
        // Initialize RX_UE_INFORMATION_TAG randomly between min and max values
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % (rx_ue_information_tag_max - rx_ue_information_tag_min + 1) + rx_ue_information_tag_min;

        // Initialize RNTI randomly between 0 and 65535
        pdu_list[i].RNTI = rand() % 65536;

        // Set CRCFLAG to true with the specified probability
        if (rand() / (double)RAND_MAX < crcflag_probability) {
            pdu_list[i].CRCFLAG = true;
        } else {
            pdu_list[i].CRCFLAG = false;
        }
    }

    return pdu_list;
}

// Function to free memory allocated for the list of PDUs
void free_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu_list) {
    // Free the memory allocated for the list of PDUs
    free(pdu_list);
}

