        // Increment the number of CRCFLAG values set if the current value is true
        if (buffer[i].crcflag) {
            num_crcflag_set++;
        }
    }

    // Ensure that the number of CRCFLAG values set does not exceed 50% of the total entries
    assert(num_crcflag_set <= size / 2);

    // Copy the buffer to the output list and unlock the buffer
    memcpy(list, buffer, sizeof(nfapi_crc_indication_pdu_t) * size);
    pthread_mutex_unlock(&buffer_lock);

    // Free the temporary buffer
    free(buffer);
}

// Define the function to resize the buffer if necessary
void resize_buffer(nfapi_crc_indication_pdu_t **list, uint32_t size) {
    // Check if the current buffer is too small for the new size
    if (size > MAX_BUFFER_SIZE / 2) {
        // Allocate a new buffer twice as large as the old one
        nfapi_crc_indication_pdu_t *new_buffer = (nfapi_crc_indication_pdu_t *)malloc(sizeof(nfapi_crc_indication_pdu_t) * size);

        // Copy the contents of the old buffer to the new one
        memcpy(new_buffer, *list, sizeof(nfapi_crc_indication_pdu_t) * size / 2);

        // Free the old buffer
        free(*list);

        // Update the pointer to point to the new buffer
        *list = new_buffer;
    }
}

// Define the function to check the integrity of the populated structures
void validate_crc_indication(nfapi_crc_indication_pdu_t *list, uint32_t size) {
    // Check that each structure has a valid RX_UE_INFORMATION_TAG value
    for (uint32_t i = 0; i < size; i++) {
        assert(list[i].rx_ue_information_tag == 1);
    }

    // Check that each structure has a valid RNTI value within the expected range
    for (uint32_t i = 0; i < size; i++) {
        assert(list[i].rnti >= 1000 && list[i].rnti <= 1500);
    }

    // Check that each structure has a valid CRC_INDICATION_REL8_TAG value
    for (uint32_t i = 0; i < size; i++) {
        assert(list[i].crc_indication_rel8_tag == 0 || list[i].crc_indication_rel8_tag == 1);
    }

    // Check that no duplicate RNTI values exist within the structures
    for (uint32_t i = 0; i < size - 1; i++) {
        for (uint32_t j = i + 1; j < size; j++) {
            assert(list[i].rnti != list[j].rnti);
        }
    }
}
