};

// Define a dynamic array of network event records
typedef struct {
    int capacity;
    int size;
    struct NetworkEventRecord* data;
} DynamicArrayOfNetworkEventRecords;

// Define the function to manage the dynamic array of network event records
void manageDynamicArray(DynamicArrayOfNetworkEventRecords* arr, int connectionID, time_t timestamp, char statusIndicator) {
    // Check if the array is full and needs to be resized
    if (arr->size == arr->capacity) {
        resizeDynamicArray(arr);
    }

    // Add a new network event record to the array
    struct NetworkEventRecord* newRecord = malloc(sizeof(struct NetworkEventRecord));
    newRecord->timestamp = timestamp;
    newRecord->connectionID = connectionID;
    newRecord->statusIndicator = statusIndicator;
    arr->data[arr->size++] = *newRecord;
}

// Define the function to add a network packet to the dynamic array of network event records
void addNetworkPacket(DynamicArrayOfNetworkEventRecords* arr, struct NetworkPacket* packet) {
    manageDynamicArray(arr, packet->connectionID, time(NULL), 'O');
}

// Define the function to update a network event record in the dynamic array
void updateNetworkEventRecord(DynamicArrayOfNetworkEventRecords* arr, int connectionID, time_t timestamp, char statusIndicator) {
    for (int i = 0; i < arr->size; i++) {
        if (arr->data[i].connectionID == connectionID && arr->data[i].timestamp == timestamp) {
            arr->data[i].statusIndicator = statusIndicator;
            return;
        }
    }
}

// Define the function to retrieve network event records by connection ID and timestamp range
void retrieveNetworkEventRecords(DynamicArrayOfNetworkEventRecords* arr, int connectionID, time_t startTime, time_t endTime) {
