            printf("%d %ld %s %ld\n", record->connectionID, record->timestamp, record->statusIndicator);
        }
    }
}

// Define the function to resize the dynamic array of network event records
void resizeDynamicArray(DynamicArrayOfNetworkEventRecords* arr) {
    // Double the capacity of the array
    int newCapacity = arr->capacity * 2;

    // Reallocate memory for the new array
    struct NetworkEventRecord* newData = realloc(arr->data, sizeof(struct NetworkEventRecord) * newCapacity);
    if (newData == NULL) {
        printf("Error: Failed to allocate memory for the new array\n");
        exit(1);
    }

    // Update the capacity and size of the array
    arr->capacity = newCapacity;
    arr->size++;
    arr->data = newData;
}

