    if (arr->apiVersion < 2 || arr->apiVersion > 3) {
        printf("Error: Incompatible API version\n");
        exit(1);
    }

    // Update the API version to ensure compatibility
    arr->apiVersion = 3;
}

// Define the function to evaluate correctness and performance under various workloads
void evaluatePerformanceUnderWorkloads(DynamicArrayOfNetworkEventRecords* arr, int numWorkloads) {
