function asyncTraverseDOM(selector) {
  const results = [];
  let queue = [document.body]; // Start with the root element

  while (queue.length > 0) {
    const node = queue.shift();
    if (node.matches(selector)) {
      results.push(node);
    }
    for (const child of node.childNodes) {
      queue.push(child); // Enqueue children for further traversal
    }
  }

  return results;
}
