#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Structure to represent a UE session
typedef struct UeSessionData {
    RrcConnectionStatus connection_state;
    RrcMessage* signaling_message;
    time_t last_update;
} UeSessionData;

// Global variable to store the list of UE sessions
static UeSessionData* ue_session_list = NULL;

// Mutex for protecting the list of UE sessions
pthread_mutex_t ue_session_list_lock = PTHREAD_MUTEX_INITIALIZER;

// External configuration file to define session expiration policies dynamically at runtime
#include "session_expiration_policies.h"

/**
 * Initializes and manages a dynamic linked list of UeSessionData structures.
 * @param[in]  ue_imsi  The IMSI of the UE to add/update the session for.
 * @param[in]  connection_state  The current RRC connection state of the UE.
 * @return 0 on success, -1 on failure.
 */
int init_ue_session(const char* ue_imsi, RrcConnectionStatus connection_state) {
    // Acquire lock for the list of UE sessions
    pthread_mutex_lock(&ue_session_list_lock);

    // Check if the UE session already exists in the list
    UeSessionData* ue_session = NULL;
    for (int i = 0; i < sizeof(ue_session_list) / sizeof(*ue_session_list); i++) {
        if (!strcmp(ue_session_list[i].imsi, ue_imsi)) {
            ue_session = &ue_session_list[i];
            break;
        }
    }

    // If the UE session does not exist, create a new one
    if (!ue_session) {
        // Allocate memory for the new UE session
        ue_session = (UeSessionData*) malloc(sizeof(UeSessionData));
        if (!ue_session) {
            pthread_mutex_unlock(&ue_session_list_lock);
            return -1;
        }

        // Initialize the new UE session with the given IMSI and connection state
        strcpy(ue_session->imsi, ue_imsi);
        ue_session->connection_state = connection_state;
        ue_session->last_update = time(NULL);

        // Add the new UE session to the list of UE sessions
        ue_session_list[sizeof(ue_session_list) / sizeof(*ue_session_list)] = *ue_session;
    } else {
        // Update the existing UE session with the given connection state
        ue_session->connection_state = connection_state;
        ue_session->last_update = time(NULL);
    }

    // Release lock for the list of UE sessions
    pthread_mutex_unlock(&ue_session_list_lock);

    return 0;
}

/**
 * Deletes an existing UE session from the dynamic linked list.
 * @param[in]  ue_imsi  The IMSI of the UE to delete the session for.
 * @return 0 on success, -1 on failure.
 */
int delete_ue_session(const char* ue_imsi) {
    // Acquire lock for the list of UE sessions
    pthread_mutex_lock(&ue_session_list_lock);

    // Check if the UE session exists in the list
    UeSessionData* ue_session = NULL;
    for (int i = 0; i < sizeof(ue_session_list) / sizeof(*ue_session_list); i++) {
        if (!strcmp(ue_session_list[i].imsi, ue_imsi)) {
            ue_session = &ue_session_list[i];
            break;
        }
    }

    // If the UE session exists, delete it from the list of UE sessions
    if (ue_session) {
        // Delete the UE session from the list of UE sessions
        memmove(ue_session, ue_session + 1, sizeof(*ue_session_list) * (sizeof(ue_session_list) / sizeof(*ue_session_list) - i));
        free(ue_session);
    } else {
        // Release lock for the list of UE sessions
        pthread_mutex_unlock(&ue_session_list_lock);

        return -1;
    }

    // Release lock for the list of UE sessions
    pthread_mutex_unlock(&ue_session_list_lock);

    return 0;
}

/**
 * Periodically cleans up outdated session data based on the defined policy.
 */
void cleanup_ue_sessions() {
    // Acquire lock for the list of UE sessions
    pthread_mutex_lock(&ue_session_list_lock);

    // Check if any of the UE sessions are outdated and should be deleted
    UeSessionData* ue_session = NULL;
    for (int i = 0; i < sizeof(ue_session_list) / sizeof(*ue_session_list); i++) {
        if (is_ue_session_outdated(&ue_session_list[i])) {
            // Delete the outdated UE session from the list of UE sessions
            memmove(ue_session, ue_session + 1, sizeof(*ue_session_list) * (sizeof(ue_session_list) / sizeof(*ue_session_list) - i));
            free(ue_session);
        } else {
            // Update the last update timestamp for the UE session
            ue_session_list[i].last_update = time(NULL);
            ue_session = &ue_session_list[i];
        }
    }

    // Release lock for the list of UE sessions
    pthread_mutex_unlock(&ue_session_list_lock);
}

/**
 * Checks if a UE session is outdated based on the defined policy.
 * @param[in]  ue_session  The UE session to check.
 * @return true if the UE session is outdated, false otherwise.
 */
bool is_ue_session_outdated(const UeSessionData* ue_session) {
    // Check if the UE session has expired based on the defined policy
    time_t current_time = time(NULL);
    switch (session_expiration_policy) {
        case SESSION_EXPIRATION_POLICY_TIMEOUT:
            return ue_session->last_update < current_time - session_timeout;
        case SESSION_EXPIRATION_POLICY_IDLE_TIMEOUT:
            return ue_session->last_update < current_time - idle_timeout;
        default:
            // Invalid session expiration policy, always consider the UE session as outdated
            return true;
    }
}
