    if (size > 0 && size <= MAX_POOL_SIZE) {
        // Allocate memory for the pool
        pool = malloc(size * sizeof(nfapi_crc_indication_pdu_t));
        memset(pool, 0, size * sizeof(nfapi_crc_indication_pdu_t));
