        // Allocate memory for the new structure
        nfapi_crc_indication_pdu_t* new_struct = malloc(sizeof(nfapi_crc_indication_pdu_t));
        new_struct->seq_num = seq_num;
        new_struct->data = data;
        // Add the new structure to the pool
