typedef struct NetworkPacket {
    NetworkEventRecord eventRecord;
    NFAPI_CRC_INDICATION_PDU_T pdu;
} NetworkPacket;

// memory pool for NetworkPackets
NetworkPacket* packetPool = NULL;
size_t numPackets = 0;
pthread_mutex_t packetMutex = PTHREAD_MUTEX_INITIALIZER;

/*
 * Initializes the network traffic analysis system and allocates memory for the dynamic array of NetworkEventRecords and NFAPI_CRC_INDICATION_PDU_T structures.
 */
void initNetworkTrafficAnalysisSystem() {
    // allocate memory for the packet pool
    numPackets = MAX_PACKETS;
    packetPool = (NetworkPacket*)malloc(sizeof(NetworkPacket) * numPackets);

    if (packetPool == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for network traffic analysis system\n");
        exit(1);
    }

    // initialize the packet pool with empty packets
    NetworkPacket* pkt = packetPool;
    for (size_t i = 0; i < numPackets; i++) {
        memset(&pkt->eventRecord, 0, sizeof(NetworkEventRecord));
        memset(&pkt->pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pkt++;
    }
}

/*
 * Adds a new NetworkPacket to the dynamic array of NetworkEventRecords and NFAPI_CRC_INDICATION_PDU_T structures.
 */
void addNetworkPacket(NetworkEventRecord eventRecord, NFAPI_CRC_INDICATION_PDU_T pdu) {
    // acquire lock on the packet pool
    pthread_mutex_lock(&packetMutex);

    // check if the packet pool is full
    if (numPackets >= MAX_PACKETS) {
        fprintf(stderr, "Error: network traffic analysis system is at capacity\n");
        pthread_mutex_unlock(&packetMutex);
        return;
    }

    // add the new packet to the pool
    NetworkPacket* newPkt = packetPool + numPackets;
    *newPkt = (NetworkPacket) {
        .eventRecord = eventRecord,
        .pdu = pdu
    };

    // increment the number of packets in the pool
    numPackets++;

    // release lock on the packet pool
    pthread_mutex_unlock(&packetMutex);
}

/*
 * Removes a NetworkPacket from the dynamic array of NetworkEventRecords and NFAPI_CRC_INDICATION_PDU_T structures.
 */
void removeNetworkPacket(size_t index) {
    // acquire lock on the packet pool
    pthread_mutex_lock(&packetMutex);

    // check if the index is valid
    if (index >= numPackets) {
        fprintf(stderr, "Error: network traffic analysis system does not contain a packet at index %zu\n", index);
        pthread_mutex_unlock(&packetMutex);
        return;
    }

    // remove the packet from the pool
    NetworkPacket* oldPkt = packetPool + index;
    memset(oldPkt, 0, sizeof(NetworkPacket));

    // move the last packet in the pool to the removed position
    numPackets--;
    if (index != numPackets) {
        NetworkPacket* newPkt = packetPool + index;
        *newPkt = *(packetPool + numPackets);
    }

    // release lock on the packet pool
    pthread_mutex_unlock(&packetMutex);
}

/*
 * Retrieves a NetworkPacket from the dynamic array of NetworkEventRecords and NFAPI_CRC_INDICATION_PDU_T structures.
 */
NetworkPacket* getNetworkPacket(size_t index) {
    // acquire lock on the packet pool
    pthread_mutex_lock(&packetMutex);

    // check if the index is valid
    if (index >= numPackets) {
        fprintf(stderr, "Error: network traffic analysis system does not contain a packet at index %zu\n", index);
        pthread_mutex_unlock(&packetMutex);
        return NULL;
    }

    // retrieve the requested packet from the pool
    NetworkPacket* pkt = packetPool + index;

    // release lock on the packet pool
    pthread_mutex_unlock(&packetMutex);

    return pkt;
}

/*
 * Frees all memory allocated for the dynamic array of NetworkEventRecords and NFAPI_CRC_INDICATION_PDU_T structures.
 */
void freeNetworkTrafficAnalysisSystem() {
    // acquire lock on the packet pool
    pthread_mutex_lock(&packetMutex);

    // release memory for the packet pool
    free(packetPool);

    // reset the number of packets in the pool
    numPackets = 0;

    // release lock on the packet pool
    pthread_mutex_unlock(&packetMutex);
}

int main() {
    initNetworkTrafficAnalysisSystem();

    NetworkEventRecord eventRecord1 = {
        .timestamp = time(NULL),
        .sourceIP = "192.168.0.1",
        .destinationIP = "192.168.0.2"
    };

    NFAPI_CRC_INDICATION_T pdu1 = {
        .crc_indication = 1,
