    NetworkEventRecord eventRecord2 = {
        .timestamp = time(NULL),
        .sourceIP = "192.168.0.3",
        .destinationIP = "192.168.0.4"
    };

    NFAPI_CRC_INDICATION_T pdu2 = {
        .crc_indication = 2,
        .crci = 3
    };

    addNetworkPacket(eventRecord2, pdu2);

    NetworkPacket* packet1 = getNetworkPacket(0);
    printf("Packet 1: %p\n", packet1);

    removeNetworkPacket(0);

    NetworkPacket* packet2 = getNetworkPacket(0);
    printf("Packet 2: %p\n", packet2);

    freeNetworkTrafficAnalysisSystem();

    return 0;
}
