#define MAX_STRUCTURES 1000
#define MAX_RX_UE_INFORMATION_TAG 256
#define MAX_RNTI 65536
#define MAX_CRC_INDICATION_REL8_TAG 256

typedef struct NFAPI_CRC_INDICATION_PDU {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint16_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdus = NULL;
size_t num_crc_indication_pdus = 0;

void add_crc_indication_pdu(uint16_t rx_ue_information_tag, uint16_t rnti, uint16_t crc_indication_rel8_tag) {
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = NULL;
    pthread_mutex_lock(&lock);
    if (num_crc_indication_pdus >= MAX_STRUCTURES) {
        // Handle memory allocation failure gracefully by dropping new PDU
        printf("Memory allocation failure in add_crc_indication_pdu()\n");
    } else {
        new_pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_pdu == NULL) {
            // Handle memory allocation failure gracefully by dropping new PDU
            printf("Memory allocation failure in add_crc_indication_pdu()\n");
        } else {
            new_pdu->rx_ue_information_tag = rx_ue_information_tag;
            new_pdu->rnti = rnti;
            new_pdu->crc_indication_rel8_tag = crc_indication_rel8_tag;
            crc_indication_pdus[num_crc_indication_pdus++] = *new_pdu;
        }
    }
    pthread_mutex_unlock(&lock);
}

void clear_crc_indication_pdus() {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < num_crc_indication_pdus; i++) {
        free(crc_indication_pdus[i]);
    }
    num_crc_indication_pdus = 0;
    pthread_mutex_unlock(&lock);
}

void handle_crc_indication_message() {
    // Handle CRC indication message from RU
    // Generate CRCFLAG based on pseudo-random number generator
    uint16_t crcfla = 0;
    for (int i = 0; i < MAX_RX_UE_INFORMATION_TAG; i++) {
        crcfla = (crcfla << 8) | (rand() % MAX_CRC_INDICATION_REL8_TAG);
    }
    // Iterate over all CRC indication PDUs and update CRCFLAG
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < num_crc_indication_pdus; i++) {
        crc_indication_pdus[i].crc_indication_rel8_tag = crcfla;
    }
    pthread_mutex_unlock(&lock);
}
```
