void destroy_list(NFAPI_CRC_INDICATION_PDU_T* list, int size) {
    // Lock the mutex to prevent race conditions during dynamic memory allocation and deallocation
    pthread_mutex_lock(mutex);

    // Free the dynamically allocated array of NFAPI_CRC_INDICATION_PDU_T structures
    free(list);

    // Unlock the mutex
    pthread_mutex_unlock(mutex);
}
