// Function to add an element to a hash table
void hashTableAdd(HashTable* table, int key) {
  // Find the first empty slot in the table
  for (int i = 0; i < table->size; i++) {
    if (table[i].key == NULL) {
      table[i].key = key;
      break;
    }
  }
}

// Function to check if a key exists in a hash table
bool hashTableContains(HashTable* table, int key) {
  // Loop through the elements of the table and check for the key
  for (int i = 0; i < table->size; i++) {
    if (table[i].key == key) {
