    // Generate sequence numbers and acknowledgment numbers using a seed value
    uint16_t seqNumber = htons(1);
    uint32_t ackNumber = htonl(1);
    packet->tcpSegment.sequenceNumber = seqNumber;
    packet->tcpSegment.acknowledgmentNumber = ackNumber;
}

void addTnlPacketToQueue(struct PacketQueue *queue, struct TNL_PACKET *packet) {
    // Check if the queue is full
    if (queue->numPackets == queue->capacity) {
        printf("Error: Packet queue is full!\n");
        return;
    }

    // Add the packet to the end of the queue
    queue->packets[queue->numPackets++] = packet;
}

