    printf("Sending TNL packet with sequence number %u and acknowledgment number %u\n",
           ntohs(packet->tcpSegment.sequenceNumber),
           ntohl(packet->tcpSegment.acknowledgmentNumber));
}

void handleTnlPacket(struct TNL_PACKET *packet) {
    // Handle the packet depending on its type (e.g., SYN, ACK, etc.)
    printf("Handling TNL packet with sequence number %u and acknowledgment number %u\n",
           ntohs(packet->tcpSegment.sequenceNumber),
           ntohl(packet->tcpSegment.acknowledgmentNumber));
}

void handlePacketQueue(struct PacketQueue *queue) {
    // Handle each packet in the queue, sending or handling them as appropriate
    for (unsigned int i = 0; i < queue->numPackets; ++i) {
        struct TNL_PACKET *packet = queue->packets[i];
        switch (packet->tcpSegment.flags) {
            case SYN:
                sendTnlPacket(packet);
                break;
            case ACK:
                handleTnlPacket(packet);
                break;
            default:
                printf("Error: Unsupported TNL packet flag %u\n", packet->tcpSegment.flags);
        }
    }
}

void initHashTable(struct HashTable *table) {
    // Initialize the hash table with a fixed size and empty slots
    table->size = 10;
    table->slots = malloc(table->size * sizeof(struct HashSlot));
    for (unsigned int i = 0; i < table->size; ++i) {
        table->slots[i].key = NULL;
        table->slots[i].value = NULL;
    }
}

void addEntryToHashTable(struct HashTable *table, char *key, struct TNL_PACKET *packet) {
    // Add an entry to the hash table with a specific key and value
    for (unsigned int i = 0; i < table->size; ++i) {
        if (table->slots[i].key == NULL) {
            table->slots[i].key = malloc(strlen(key) + 1);
            strcpy(table->slots[i].key, key);
            table->slots[i].value = packet;
            break;
        } else if (strcmp(table->slots[i].key, key) == 0) {
            printf("Error: Key %s already exists in the hash table!\n", key);
            return;
        }
    }
}

void lookupEntryInHashTable(struct HashTable *table, char *key, struct TNL_PACKET **packet) {
    // Look up an entry in the hash table with a specific key and return its value
    for (unsigned int i = 0; i < table->size; ++i) {
        if (strcmp(table->slots[i].key, key) == 0) {
            *packet = table->slots[i].value;
            break;
        }
    }
}

void freeHashTable(struct HashTable *table) {
    // Free the hash table and its slots
    for (unsigned int i = 0; i < table->size; ++i) {
        free(table->slots[i].key);
        table->slots[i].key = NULL;
        free(table->slots[i].value);
        table->slots[i].value = NULL;
    }
    free(table->slots);
}

int main() {
