    struct PacketQueue *queue = malloc(sizeof(struct PacketQueue));
    queue->numPackets = 0;
    queue->capacity = 100;
    queue->packets = malloc(queue->capacity * sizeof(struct TNL_PACKET*));
    struct HashTable *table = malloc(sizeof(struct HashTable));
