    char key2[] = "key2";
    struct TNL_PACKET packet1, packet2;
    initTnlPacket(&packet1);
    initTnlPacket(&packet2);
    addEntryToHashTable(table, key1, &packet1);
    addEntryToHashTable(table, key2, &packet2);
    addTnlPacketToQueue(queue, &packet1);
    addTnlPacketToQueue(queue, &packet2);

    // Handle the packets in the queue and update the hash table as necessary
    handlePacketQueue(queue);

    // Look up an entry in the hash table by key and print its value
