// Function to initialize and populate a dynamically allocated array of LTE_UESessionInfo structures
LTE_UESessionInfo* initSessionArray(int numSessions) {
    // Validate the input parameter
    if (numSessions <= 0) {
        printf("Invalid number of sessions provided. Cannot initialize session array.\n");
        return NULL;
    }

    // Allocate memory for the array of LTE_UESessionInfo structures
    LTE_UESessionInfo* sessionArray = (LTE_UESessionInfo*)malloc(sizeof(LTE_UESessionInfo) * numSessions);
    if (!sessionArray) {
        printf("Failed to allocate memory for session array.\n");
        return NULL;
    }

    // Initialize the array with default values
    for (int i = 0; i < numSessions; i++) {
        sessionArray[i].UE_ID = -1;
        sessionArray[i].RNTI = -1;
        sessionArray[i].PCI = -1;
        // Randomly generate a value for the measurementResult field
        srand(time(NULL));
        sessionArray[i].measurementResult = rand() % 10 + 1;
    }

    // Return the initialized array of LTE_UESessionInfo structures
    return sessionArray;
}

// Function to add a new session to the session array
int addSession(LTE_UESessionInfo* sessionArray, int numSessions) {
    // Validate the input parameters
    if (!sessionArray || numSessions <= 0) {
        printf("Invalid input parameters. Cannot add session.\n");
        return -1;
    }

    // Acquire the lock on the session array to prevent concurrent access
    pthread_mutex_lock(&sessionLock);

    // Increment the total number of sessions and check if the maximum number of sessions has been reached
    numSessions++;
    if (numSessions > MAX_SESSIONS) {
        printf("Maximum number of sessions exceeded. Cannot add new session.\n");
        pthread_mutex_unlock(&sessionLock);
        return -1;
    }

    // Allocate memory for the new session and copy the default values from the previous session
    LTE_UESessionInfo* newSession = (LTE_UESessionInfo*)malloc(sizeof(LTE_UESessionInfo));
    if (!newSession) {
        printf("Failed to allocate memory for new session.\n");
        pthread_mutex_unlock(&sessionLock);
        return -1;
    }
    memcpy(newSession, &sessionArray[numSessions - 2], sizeof(LTE_UESessionInfo));

    // Randomly generate a value for the new session's measurementResult field
    srand(time(NULL));
    newSession->measurementResult = rand() % 10 + 1;

