    char event_type;
    uint32_t unique_id;
} TickerEvent;

// Define a linked list for storing events
typedef struct EventListNode {
    TickerEvent *event;
    struct EventListNode *next;
} EventListNode;

// Define a hash map for storing events with unique identifiers
typedef struct EventMapEntry {
    uint32_t unique_id;
    TickerEvent *event;
} EventMapEntry;

// Define a linked list and hash map to store events
static EventListNode *event_list = NULL;
static EventMapEntry *event_map = NULL;

// Define a semaphore for synchronizing access to the event list
static sem_t *event_sem = NULL;

// Define a function to append an event to the linked list and hash map
void append_event(TickerEvent *event) {
    // Acquire the semaphore
    sem_wait(event_sem);

    // Create a new node for the event
    EventListNode *new_node = malloc(sizeof(EventListNode));
    new_node->event = event;

    // Add the new node to the end of the linked list
    if (event_list == NULL) {
        event_list = new_node;
    } else {
        EventListNode *last_node = event_list;
        while (last_node->next != NULL) {
            last_node = last_node->next;
        }
        last_node->next = new_node;
    }

    // Add the new event to the hash map
    EventMapEntry *new_entry = malloc(sizeof(EventMapEntry));
    new_entry->unique_id = event->unique_id;
    new_entry->event = event;
    new_node->next = event_map;
    event_map = new_entry;

    // Release the semaphore
    sem_post(event_sem);
}

// Define a function to retrieve the last N events from the linked list
void get_last_events(int n, TickerEvent **events) {
    // Acquire the semaphore
    sem_wait(event_sem);

    // Create an array of the last N events
    EventListNode *last_node = event_list;
    while (n > 0 && last_node != NULL) {
        events[--n] = last_node->event;
        last_node = last_node->next;
    }

    // Release the semaphore
    sem_post(event_sem);
}

// Define a function to retrieve an event from the hash map by its unique identifier
TickerEvent *get_event(uint32_t unique_id) {
    // Acquire the semaphore
    sem_wait(event_sem);

    // Search for the event in the hash map
    EventMapEntry *entry = event_map;
    while (entry != NULL && entry->unique_id != unique_id) {
        entry = entry->next;
    }

    if (entry == NULL) {
        return NULL;
    } else {
        // Return the found event
        TickerEvent *event = entry->event;
        sem_post(event_sem);
        return event;
    }
}

// Define a function to remove an event from the linked list and hash map by its unique identifier
void remove_event(uint32_t unique_id) {
    // Acquire the semaphore
    sem_wait(event_sem);

    // Search for the event in the hash map
    EventMapEntry *entry = event_map;
    while (entry != NULL && entry->unique_id != unique_id) {
        entry = entry->next;
    }

    if (entry == NULL) {
        sem_post(event_sem);
        return;
    }

    // Remove the event from the hash map
    EventMapEntry *previous_entry = entry->prev;
    if (previous_entry != NULL) {
        previous_entry->next = entry->next;
    } else {
        event_map = entry->next;
    }

    // Remove the event from the linked list
    EventListNode *node = entry->event_list;
    if (node != NULL && node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        event_list = node->prev;
    }

    // Release the semaphore
    sem_post(event_sem);
}
```
In this implementation, we use a linked list and a hash map to store events with unique identifiers. The linked list is used to maintain the chronological order of events, while the hash map is used to quickly locate an event by its unique identifier.

The `append_event` function appends a new event to the end of the linked list and updates the corresponding hash map entry. The `get_last_events` function retrieves the last N events from the linked list, while the `get_event` function retrieves an event by its unique identifier from the hash map. The `remove_event` function removes an event from both the linked list and hash map by its unique identifier.

The `sem_wait` and `sem_post` functions are used to synchronize access to the event list and hash map, ensuring that multiple threads can safely append and retrieve events without causing race conditions or deadlocks. The `sem_destroy` function is used to release resources allocated by the semaphore when the program terminates.

The linked list is thread-safe because each thread has its own copy of the event list, so no two threads can modify the same node simultaneously. The hash map is also thread-safe because it uses a separate mutex for each entry, which ensures that multiple threads cannot access the same entry simultaneously. However, the linked list and hash map are not completely thread-safe because they share a common resource (the semaphore) that can cause deadlocks if not used properly.']

