#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    uint32_t UEID; // Unique ID of the UE
    uint8_t crcFlag; // Flag indicating if CRC is present
    uint16_t rxInfoTag; // RX information tag
    uint16_t rnti; // RNTI value
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex; // Mutex for locking access to the list
    NFAPI_CRC_INDICATION_PDU_T *pduList; // List of PDUs
    size_t numPdus; // Number of PDUs in the list
} NFAPI_CRC_LIST_T;

// Function to initialize the CRC list
void nfapi_crc_list_init(NFAPI_CRC_LIST_T *list) {
    list->pduList = NULL;
    list->numPdus = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

// Function to populate the CRC list with UE IDs and RX information
void nfapi_crc_list_populate(NFAPI_CRC_LIST_T *list, uint32_t *ueIdList, size_t numUes) {
    pthread_mutex_lock(&list->mutex);

    // Allocate memory for the PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numUes);
    if (!pdu) {
        perror("Failed to allocate memory for PDUs");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Initialize the PDUs
    size_t i;
    for (i = 0; i < numUes; i++) {
        pdu[i].UEID = ueIdList[i];
        pdu[i].crcFlag = 0; // Default value for CRCFLAG
        pdu[i].rxInfoTag = 0; // Default value for RX information tag
        pdu[i].rnti = 0; // Default value for RNTI
    }

    // Add the PDUs to the list
    size_t numPdus = list->numPdus + numUes;
    NFAPI_CRC_INDICATION_PDU_T *pduList = realloc(list->pduList, sizeof(NFAPI_CRC_INDICATION_PDU_T) * numPdus);
    if (!pduList) {
        perror("Failed to allocate memory for PDU list");
        free(pdu);
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    memcpy(pduList + list->numPdus, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * numUes);
    list->pduList = pduList;
    list->numPdus = numPdus;

    // Clean up the memory
    free(pdu);

    pthread_mutex_unlock(&list->mutex);
}

// Function to synchronize the CRC list with an external database of UE IDs and RX information
void nfapi_crc_list_synchronize(NFAPI_CRC_LIST_T *list, uint32_t *ueIdList, size_t numUes) {
    pthread_mutex_lock(&list->mutex);

    // Iterate over the UE IDs and update the corresponding PDUs in the list
    size_t i;
    for (i = 0; i < numUes; i++) {
        uint32_t ueId = ueIdList[i];
        NFAPI_CRC_INDICATION_PDU_T *pdu = nfapi_crc_list_find(list, ueId);
        if (pdu) {
            // Update the CRCFLAG and RX information tag based on the external database
            pdu->crcFlag = 1; // Default value for CRCFLAG
            pdu->rxInfoTag = 0x1234; // Default value for RX information tag
            pdu->rnti = 0x5678; // Default value for RNTI
        } else {
            // Add a new PDU to the list if the UE ID is not found in the external database
            NFAPI_CRC_INDICATION_PDU_T *newPdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!newPdu) {
                perror("Failed to allocate memory for new PDU");
                pthread_mutex_unlock(&list->mutex);
                return;
            }
            newPdu->UEID = ueId;
            newPdu->crcFlag = 1; // Default value for CRCFLAG
            newPdu->rxInfoTag = 0x1234; // Default value for RX information tag
            newPdu->rnti = 0x5678; // Default value for RNTI
            size_t numPdus = list->numPdus + 1;
            NFAPI_CRC_INDICATION_PDU_T *pduList = realloc(list->pduList, sizeof(NFAPI_CRC_INDICATION_PDU_T) * numPdus);
            if (!pduList) {
                perror("Failed to allocate memory for PDU list");
                free(newPdu);
                pthread_mutex_unlock(&list->mutex);
                return;
            }
            memcpy(pduList + list->numPdus, newPdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->pduList = pduList;
            list->numPdus = numPdus;
        }
    }

    // Clean up the memory
    free(newPdu);

    pthread_mutex_unlock(&list->mutex);
