} NR_CELL_INFO_T;

// Define the list of cells
static NR_CELL_INFO_T* cell_list = NULL;
static size_t num_cells = 0;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_cell(NR_CELL_INFO_T cell) {
    // Lock the mutex to prevent concurrent access and modification of the list
    pthread_mutex_lock(&lock);

    // Check if there is enough memory allocated for the new cell
    if (num_cells >= MAX_CELLS) {
        size_t new_size = num_cells * 2;
        NR_CELL_INFO_T* new_list = realloc(cell_list, new_size * sizeof(NR_CELL_INFO_T));
        if (new_list == NULL) {
            perror("realloc");
            pthread_mutex_unlock(&lock);
            return;
        }
        cell_list = new_list;
    }

    // Copy the new cell into the list and update the number of cells
    memcpy(&cell_list[num_cells], &cell, sizeof(NR_CELL_INFO_T));
    num_cells++;

    // Log an error message if a duplicate cell ID is detected
    for (int i = 0; i < num_cells - 1; i++) {
        if (cell_list[i].cell_id == cell.cell_id) {
            fprintf(stderr, "Duplicate cell ID %d\n", cell.cell_id);
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // Unlock the mutex and update the timestamp of the new cell
    pthread_mutex_unlock(&lock);
    update_timestamp(cell.cell_id, cell.timestamp);
}

void update_timestamp(int cell_id, time_t timestamp) {
    // Lock the mutex to prevent concurrent access and modification of the list
    pthread_mutex_lock(&lock);

    // Find the index of the cell with the given ID in the list
    int index = -1;
    for (int i = 0; i < num_cells; i++) {
        if (cell_list[i].cell_id == cell_id) {
            index = i;
            break;
        }
    }

    // Update the timestamp of the cell and unlock the mutex
    if (index >= 0) {
        cell_list[index].timestamp = timestamp;
    }
    pthread_mutex_unlock(&lock);
}

void serialize_cells(FILE* file) {
    // Lock the mutex to prevent concurrent access and modification of the list
    pthread_mutex_lock(&lock);

    // Write the number of cells to the file
    fwrite(&num_cells, sizeof(size_t), 1, file);

    // Write each cell to the file
    for (int i = 0; i < num_cells; i++) {
        NR_CELL_INFO_T* cell = &cell_list[i];
        fwrite(cell, sizeof(NR_CELL_INFO_T), 1, file);
    }

    // Unlock the mutex and close the file
    pthread_mutex_unlock(&lock);
}

void deserialize_cells(FILE* file) {
    // Lock the mutex to prevent concurrent access and modification of the list
    pthread_mutex_lock(&lock);

    // Read the number of cells from the file
    size_t num_cells = 0;
    fread(&num_cells, sizeof(size_t), 1, file);

    // Allocate memory for the new list of cells
    NR_CELL_INFO_T* new_list = malloc(num_cells * sizeof(NR_CELL_INFO_T));
    if (new_list == NULL) {
        perror("malloc");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Read each cell from the file and store it in the new list
    for (int i = 0; i < num_cells; i++) {
        NR_CELL_INFO_T* cell = &new_list[i];
        fread(cell, sizeof(NR_CELL_INFO_T), 1, file);
    }

    // Update the list of cells and unlock the mutex
    cell_list = new_list;
    num_cells = new_list->num_cells;
    pthread_mutex_unlock(&lock);
}
