// Structure to represent an NFAPI_CRC_INDICATION_PDU
typedef struct {
    int crc;
} NFAPI_CRC_INDICATION_PDU_T;

// Array of NFAPI_CRC_INDICATION_PDU structures
NFAPI_CRC_INDICATION_PDU_T *crc_indications = NULL;

// Number of CRC indications in the array
int num_crc_indications = 0;

// Mutex to protect concurrent access to the array
pthread_mutex_t crc_indications_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new CRC indication to the array
void add_crc_indication(int crc) {
    pthread_mutex_lock(&crc_indications_mutex);
    // Dynamically allocate memory for the new CRC indication
    NFAPI_CRC_INDICATION_PDU_T *new_crc_indication = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_crc_indication->crc = crc;
    // If the array is empty, allocate memory for it
    if (num_crc_indications == 0) {
        crc_indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    // If the array is full, resize it
    else if (num_crc_indications == MAX_CRCS) {
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_CRCS);
        if (new_array == NULL) {
            free(new_crc_indication);
            pthread_mutex_unlock(&crc_indications_mutex);
            return;
        }
        crc_indications = new_array;
    }
    // Add the new CRC indication to the array
    crc_indications[num_crc_indications] = *new_crc_indication;
    num_crc_indications++;
    pthread_mutex_unlock(&crc_indications_mutex);
}

// Function to remove a CRC indication from the array
void remove_crc_indication(int crc) {
    pthread_mutex_lock(&crc_indications_mutex);
    // If the array is empty, do nothing
    if (num_crc_indications == 0) {
        pthread_mutex_unlock(&crc_indications_mutex);
        return;
    }
    // Find the index of the CRC indication to remove
    int idx = -1;
    for (int i = 0; i < num_crc_indications; i++) {
        if (crc_indications[i].crc == crc) {
            idx = i;
            break;
        }
    }
    // If the CRC indication was not found, do nothing
    if (idx == -1) {
        pthread_mutex_unlock(&crc_indications_mutex);
        return;
    }
    // Remove the CRC indication from the array
    for (int i = idx; i < num_crc_indications - 1; i++) {
        crc_indications[i] = crc_indications[i + 1];
    }
    num_crc_indications--;
    // If the array is now empty, free its memory
    if (num_crc_indications == 0) {
        free(crc_indications);
        crc_indications = NULL;
    }
    pthread_mutex_unlock(&crc_indications_mutex);
}

// Function to free all allocated memory when the list is no longer in use
void free_all() {
    pthread_mutex_lock(&crc_indications_mutex);
    if (crc_indications != NULL) {
        free(crc_indications);
        crc_indications = NULL;
    }
    num_crc_indications = 0;
    pthread_mutex_unlock(&crc_indications_mutex);
}
