// Function to initialize the linked list
void initList() {
    head = NULL;
}

// Function to insert a new node in the linked list
void insertNode(NFAPI_CRC_INDICATION_PDU_T* node) {
    // Check if the list is empty
    if (head == NULL) {
        head = node;
        return;
    }

    // Find the last node in the list
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current->next != NULL) {
        current = current->next;
    }

    // Insert the new node at the end of the list
    current->next = node;
}

// Function to delete a node from the linked list
void deleteNode(NFAPI_CRC_INDICATION_PDU_T* node) {
    // Check if the list is empty
    if (head == NULL) {
        return;
    }

    // Find the previous node of the target node
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current->next != node) {
        current = current->next;
    }

    // Remove the target node from the list
