// Function to add a new node to the doubly linked list
void add_stateie_node(struct LTE_ENB_STATEIE *data) {
    // Allocate memory for the new node
    struct Node *new_node = malloc(sizeof(struct Node));
    if (new_node == NULL) {
        printf("Failed to allocate memory for new node\n");
        exit(1);
    }

    // Set the data field of the new node
    new_node->data = data;

    // Insert the new node at the head of the linked list
    if (head == NULL) {
        head = new_node;
        new_node->prev = NULL;
        new_node->next = NULL;
    } else {
        new_node->prev = NULL;
        new_node->next = head;
        head->prev = new_node;
        head = new_node;
    }
}

// Function to remove a node from the doubly linked list
void remove_stateie_node(struct LTE_ENB_STATEIE *data) {
    // Find the node corresponding to the given data structure
    struct Node *curr_node = head;
    while (curr_node != NULL && curr_node->data != data) {
        curr_node = curr_node->next;
    }

    // If the node was found, remove it from the linked list
    if (curr_node != NULL) {
        // Update the links between neighboring nodes
        if (curr_node == head) {
            head = curr_node->next;
            if (head != NULL) {
                head->prev = NULL;
            }
        } else {
            curr_node->prev->next = curr_node->next;
            if (curr_node->next != NULL) {
                curr_node->next->prev = curr_node->prev;
            }
        }

        // Free the memory allocated for the node
        free(curr_node);
    } else {
        printf("Node not found in linked list\n");
    }
}

// Function to process a state information element (IE) and update the linked list
void process_stateie(struct LTE_ENB_STATEIE *data) {
    // If the data structure contains an EUTRAN cell ID, add it to the linked list
    if (data->EUTRAN_CELL_ID != 0) {
        add_stateie_node(data);
    }
}

// Function to handle integration errors with the external library
void handle_integration_errors() {
    // If there are any integration errors, print an error message and exit the program
    if (external_lib_handle == NULL) {
        printf("Failed to load external library\n");
        exit(1);
    }
}

// Function to report and handle any integration errors gracefully
void report_integration_errors() {
    // If there are any integration errors, print an error message and exit the program
    if (external_lib_handle == NULL) {
        printf("Failed to load external library\n");
        exit(1);
    }
}

// Function to support logging for debugging purposes
void enable_logging() {
    // Enable logging by setting a flag
    is_logging = 1;
}

void disable_logging() {
    // Disable logging by resetting the flag
    is_logging = 0;
}
