void allocate_and_populate_crc_pdu_list(size_t num_elements, size_t* list_size) {
    // Check if the number of elements is valid and greater than 0
    if (num_elements == 0) {
        *list_size = 0;
        return;
    }

    // Allocate memory for the list of PDUs
    NFAPI_CRC_INDICATION_PDU_T* crc_pdu_list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_pdu_list) {
        // Handle memory allocation failure gracefully
        printf("Failed to allocate memory for CRC PDU list\n");
        return;
    }

    // Initialize the RX_UE_INFORMATION_TAG and RNTI of each PDU
    size_t i;
    for (i = 0; i < num_elements; i++) {
        crc_pdu_list[i].RX_UE_INFORMATION_TAG = rand() % UINT16_MAX;
        crc_pdu_list[i].RNTI = rand() % UINT32_MAX;
        crc_pdu_list[i].CRCFLAG = (rand() % 2) ? true : false;
    }

    // Log the creation of each PDU
    for (i = 0; i < num_elements; i++) {
        printf("Created CRC PDU %zu with RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%d\n", i + 1, crc_pdu_list[i].RX_UE_INFORMATION_TAG, crc_pdu_list[i].RNTI, crc_pdu_list[i].CRCFLAG);
    }

    // Compress the allocated memory to reduce footprint without affecting data integrity
    size_t compressed_size = compress(crc_pdu_list, num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (compressed_size > 0) {
        printf("Compressed CRC PDU list from %zu to %zu\n", num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T), compressed_size);
    } else {
        // Handle compression failure gracefully
        printf("Failed to compress CRC PDU list\n");
    }

    // Set the size of the compressed list and return
    *list_size = num_elements;
    return;
}
