        printf("CRC indication queue is full, dropping oldest entry\n");
        free(crc_indication_queue[crc_indication_queue_front]);
        crc_indication_queue_front = (crc_indication_queue_front + 1) % crc_indication_queue_size;
    }
    crc_indication_queue[crc_indication_queue_back] = pdu;
    crc_indication_queue_back = (crc_indication_queue_back + 1) % crc_indication_queue_size;
    if (crc_indication_queue_back == crc_indication_queue_front) {
        crc_indication_queue_full = true;
    }

    // Log the CRC indication to the system administrator
    printf("Received CRC indication for RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", tag->value, rnti->value);
}

void nfapi_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
