void nfapi_populate_crc_indication_queue() {
    while (true) {
        // Check if there are any pending CRC indications to process
        if (crc_indication_queue_back == crc_indication_queue_front) {
            break;
        }

        // Get the next available entry in the queue
        size_t index = crc_indication_queue_front;
        crc_indication_queue_front = (crc_indication_queue_front + 1) % crc_indication_queue_size;

        // Process the CRC indication
        nfapi_crc_indication(crc_indication_queue[index]);
    }
