  for (size_t i = 0; i < n; i++) {
    for (size_t j = i + 1; j < n; j++) {
      if (pduArray[i].rxUeInformationTag == pduArray[j].rxUeInformationTag) {
        // Collision detected, increment both RX UE information tags by 1
        pduArray[i].rxUeInformationTag++;
        pduArray[j].rxUeInformationTag++;
