// Function to manage dynamic array of UESessionState structures
void manageUESessionArray(UESessionState **sessionArray, int numSessions) {
    // Allocate memory for the session array if necessary
    if (*sessionArray == NULL) {
        *sessionArray = (UESessionState *)malloc(sizeof(UESessionState) * numSessions);
        if (*sessionArray == NULL) {
            printf("Error: Failed to allocate memory for UE session array\n");
            return;
        }
    }

    // Populate the measurement results for each session
    for (int i = 0; i < numSessions; i++) {
        UESessionState *session = &(*sessionArray)[i];
        if (!session->measurementAvailable) {
            // Generate random SINR, RSSI, and Bandwidth values
            session->SINR = ((double)rand() / (double)(RAND_MAX)) * 2 - 1;
            session->RSSI = ((double)rand() / (double)(RAND_MAX)) * 50 - 25;
            session->Bandwidth = ((double)rand() / (double)(RAND_MAX)) * 5 + 1;
            session->measurementAvailable = true;
        }
    }

    // Integrate with external data source to fetch network configuration parameters for each session
    // If network configuration is not available, use default values
    for (int i = 0; i < numSessions; i++) {
        UESessionState *session = &(*sessionArray)[i];
        if (session->measurementAvailable) {
            double SINR_default = 1.5;
            double RSSI_default = -70;
            double Bandwidth_default = 2;
            if (!fetchNetworkConfig(session, &SINR_default, &RSSI_default, &Bandwidth_default)) {
                session->SINR = SINR_default;
                session->RSSI = RSSI_default;
                session->Bandwidth = Bandwidth_default;
            }
        }
    }

    // Ensure that the function is efficient enough to handle large numbers of sessions simultaneously
    for (int i = 0; i < numSessions; i++) {
        UESessionState *session = &(*sessionArray)[i];
        if (!session->measurementAvailable) {
            // Reallocate memory if necessary to add a new session
            int newSize = (*sessionArray)->size + 1;
            *sessionArray = (UESessionState *)realloc((*sessionArray), sizeof(UESessionState) * newSize);
            if (*sessionArray == NULL) {
                printf("Error: Failed to reallocate memory for UE session array\n");
                return;
            }
            // Initialize the new session state structure
            UESessionState *newSession = &(*sessionArray)[i];
            newSession->UE_ID = i + 1;
            newSession->SINR = ((double)rand() / (double)(RAND_MAX)) * 2 - 1;
            newSession->RSSI = ((double)rand() / (double)(RAND_MAX)) * 50 - 25;
            newSession->Bandwidth = ((double)rand() / (double)(RAND_MAX)) * 5 + 1;
            newSession->measurementAvailable = true;
        }
    }

    // Manage memory efficiently by balancing between allocating sufficient resources for all sessions and minimizing overhead
    int numActiveSessions = countActiveSessions(*sessionArray, numSessions);
    if (numActiveSessions < 0.5 * numSessions) {
        // Reallocate memory to free up space for new sessions
        int newSize = ceil(2 * numSessions / 3);
        *sessionArray = (UESessionState *)realloc((*sessionArray), sizeof(UESessionState) * newSize);
        if (*sessionArray == NULL) {
            printf("Error: Failed to reallocate memory for UE session array\n");
            return;
        }
    } else if (numActiveSessions > 2 * numSessions / 3) {
        // Reallocate memory to free up space for deleted sessions
        int newSize = floor(1.5 * numSessions);
        *sessionArray = (UESessionState *)realloc((*sessionArray), sizeof(UESessionState) * newSize);
        if (*sessionArray == NULL) {
            printf("Error: Failed to reallocate memory for UE session array\n");
            return;
        }
    }
}

// Count the number of active sessions in the session array
int countActiveSessions(UESessionState *sessionArray, int numSessions) {
    int count = 0;
    for (int i = 0; i < numSessions; i++) {
        if (sessionArray[i].measurementAvailable) {
            count++;
        }
    }
    return count;
}

// Function to fetch network configuration parameters from an external data source
bool fetchNetworkConfig(UESessionState *session, double *SINR_default, double *RSSI_default, double *Bandwidth_default) {
    // Simulate a failure to retrieve the network configuration
    int randVal = (int)(rand() % 10);
    if (randVal > 5) {
        printf("Error: Failed to fetch network configuration for UE session %d\n", session->UE_ID);
        return false;
    }

    // Use default values if the network configuration is not available
    *SINR_default = 1.5;
    *RSSI_default = -70;
    *Bandwidth_default = 2;
    return true;
}
