int init_cipher(const char *password, const char *salt) {
  // Create an EVP_CIPHER_CTX structure
  EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
  if (ctx == NULL) {
    return -1;
  }

  // Set the cipher type and mode
  const EVP_CIPHER *cipher = EVP_get_cipherbyname("aes-256-gcm");
  if (cipher == NULL) {
    EVP_CIPHER_CTX_free(ctx);
    return -1;
  }
  int cipher_mode = EVP_CIPH_GCM_MODE;

  // Set the password and salt
  const unsigned char *pw_ptr = (const unsigned char *)password;
  int pw_len = strlen(password);
  const unsigned char *salt_ptr = NULL;
  if (salt != NULL) {
    salt_ptr = (const unsigned char *)salt;
  }

  // Derive the key and IV using PBKDF2 with SHA-256
  int key_len = EVP_CIPHER_key_length(cipher);
  int iv_len = EVP_CIPHER_iv_length(cipher);
  unsigned char *key = (unsigned char *)malloc(key_len);
  unsigned char *iv = (unsigned char *)malloc(iv_len);
  if (key == NULL || iv == NULL) {
    free(key);
    free(iv);
    EVP_CIPHER_CTX_free(ctx);
    return -1;
  }
  int ret = PBKDF2((const unsigned char *)password, pw_len, salt_ptr,
                  salt != NULL ? strlen(salt) : 0, EVP_sha256(), key_len,
                  key, iv_len, iv);
  if (ret == 0) {
    free(key);
    free(iv);
    EVP_CIPHER_CTX_free(ctx);
    return -1;
  }

  // Set the cipher key and IV
  int key_len_out = key_len;
  ret = EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv);
  if (ret == 0) {
    free(key);
    free(iv);
    EVP_CIPHER_CTX_free(ctx);
    return -1;
  }

  // Store the cipher context in the library's state
  lib_state_t *lib_state = (lib_state_t *)malloc(sizeof(lib_state_t));
  if (lib_state == NULL) {
    free(key);
    free(iv);
    EVP_CIPHER_CTX_free(ctx);
    return -1;
  }
  lib_state->cipher_ctx = ctx;
  lib_state->num_nas_pdus = 0;
  lib_state->nas_pdus = NULL;

  // Return success
  return 0;
}

// Define a function to add a NAS PDU structure to the library's list
