import java.util.*;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;

public class MACProtocol {
    // Define constants for the AES key size and IV size
    private static final int KEY_SIZE = 32;
    private static final int IV_SIZE = 16;

    // Generate a random secret key and initialization vector
    private static byte[] secretKey = new byte[KEY_SIZE];
    private static byte[] iv = new byte[IV_SIZE];

    // Define the encryption and decryption functions
    public static byte[] encrypt(byte[] message, byte[] iv) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        SecretKeySpec secretKeySpec = new SecretKeySpec(secretKey, "AES");
        IvParameterSpec ivParameterSpec = new IvParameterSpec(iv);
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParameterSpec);
        return cipher.doFinal(message);
    }

    public static byte[] decrypt(byte[] ciphertext, byte[] iv) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        SecretKeySpec secretKeySpec = new SecretKeySpec(secretKey, "AES");
        IvParameterSpec ivParameterSpec = new IvParameterSpec(iv);
        cipher.init(Cipher.DECRYPT_MODE, secretKeySpec, ivParameterSpec);
        return cipher.doFinal(ciphertext);
    }

    // Define a function for adding MAC frames to the list
    public static void addMacFrame(List<byte[]> messages, byte[] header, int sequence, byte[] payload) {
        // Create a new MAC frame descriptor with the given header and payload
        byte[] macFrame = new byte[header.length + 4 + payload.length];
        System.arraycopy(header, 0, macFrame, 0, header.length);
        ByteBuffer.wrap(macFrame).order(ByteOrder.BIG_ENDIAN).putInt(sequence);
        System.arraycopy(payload, 0, macFrame, header.length + 4, payload.length);

        // Add the new MAC frame descriptor to the list of messages
        messages.add(macFrame);
    }

    // Define a function for retrieving and decrypting messages from the list
    public static byte[] receiveMessage(List<byte[]> messages) throws Exception {
        // Get the first message from the list
        byte[] message = messages.get(0);

        // Decrypt the message using the given header and payload
        return decrypt(message, iv);
    }

    // Define a function for updating MAC frames with new payload data
    public static void updateMacFrame(List<byte[]> messages, int sequence, byte[] payload) {
        byte[] macFrame = messages.get(sequence - 1);
        ByteBuffer.wrap(macFrame).order(ByteOrder.BIG_ENDIAN).putInt(payload.length);
        System.arraycopy(payload, 0, macFrame, header.length + 4, payload.length);
    }
}
