    unsigned char salt[16]; // Salt for key derivation
    int32_t keysize; // Size of the generated keys (in bytes)
    uint8_t *key; // Pointer to the generated keys
    pthread_mutex_t lock; // Mutex for thread-safe access to the cipher context
} cipher_context_t;

// Define the NAS PDU list structure
