    int32_t size; // Number of NAS PDUs in the list
    nas_pdu_t *nas_pdus; // Pointer to the array of NAS PDUs
} nas_pdu_list_t;

// Define the cipher context list structure
typedef struct {
    int32_t size; // Number of cipher contexts in the list
    cipher_context_t *cipher_contexts; // Pointer to the array of cipher contexts
} cipher_context_list_t;

// Define the error handling mechanism for the library
#define ERR_SUCCESS 0 // Successful operation
#define ERR_INVALID_PARAMETER -1 // Invalid parameter passed to function
#define ERR_ALLOCATION_FAILED -2 // Memory allocation failed
#define ERR_CIPHER_CONTEXT_GENERATION_FAILED -3 // Cipher context generation failed
#define ERR_NAS_PDU_ENCRYPTION_FAILED -4 // NAS PDU encryption failed
#define ERR_NAS_PDU_DECRYPTION_FAILED -5 // NAS PDU decryption failed

// Define the function for initializing multiple cipher contexts simultaneously
int32_t initialize_cipher_contexts(const char *password, const char *salt, int32_t count, cipher_context_list_t **cipher_contexts) {
    // Check if the password and salt are valid
    if (password == NULL || salt == NULL || count <= 0) {
        return ERR_INVALID_PARAMETER;
    }

    // Allocate memory for the cipher context list structure
    *cipher_contexts = malloc(sizeof(**cipher_contexts));
    if (*cipher_contexts == NULL) {
        return ERR_ALLOCATION_FAILED;
    }

    // Initialize the size of the cipher context list to 0
    (*cipher_contexts)->size = 0;

    // Iterate over each cipher context and generate a key
    for (int32_t i = 0; i < count; i++) {
        // Allocate memory for the cipher context structure
        cipher_context_t *cipher_context = malloc(sizeof(*cipher_context));
        if (cipher_context == NULL) {
            return ERR_ALLOCATION_FAILED;
        }

        // Generate a salt for the current cipher context
        if (salt != NULL) {
            memcpy(cipher_context->salt, salt, 16);
        } else {
            memset(cipher_context->salt, 0, 16);
        }

        // Generate the key using the password and salt
        if (generate_key(password, cipher_context->salt, &cipher_context->keysize, &cipher_context->key) != ERR_SUCCESS) {
            return ERR_CIPHER_CONTEXT_GENERATION_FAILED;
        }

        // Lock the cipher context mutex to ensure thread-safe access
        pthread_mutex_lock(&(cipher_context->lock));

        // Add the generated cipher context to the list of cipher contexts
        (*cipher_contexts)->size++;
        (*cipher_contexts)->cipher_contexts = realloc((*cipher_contexts)->cipher_contexts, (*cipher_contexts)->size * sizeof(**cipher_contexts));
        if ((*cipher_contexts)->cipher_contexts == NULL) {
            return ERR_ALLOCATION_FAILED;
        }
        (*cipher_contexts)->cipher_contexts[i] = cipher_context;
    }

    // Return success
    return ERR_SUCCESS;
}

// Define the function for encrypting a NAS PDU using a given cipher context
int32_t encrypt_nas_pdu(const nas_pdu_t *nas_pdu, const cipher_context_t *cipher_context, uint8_t **encrypted_nas_pdu) {
    // Check if the NAS PDU and cipher context are valid
    if (nas_pdu == NULL || cipher_context == NULL) {
        return ERR_INVALID_PARAMETER;
    }

    // Allocate memory for the encrypted NAS PDU
    *encrypted_nas_pdu = malloc(sizeof(**encrypted_nas_pdu));
    if (*encrypted_nas_pdu == NULL) {
        return ERR_ALLOCATION_FAILED;
    }

    // Lock the cipher context mutex to ensure thread-safe access
    pthread_mutex_lock(&(cipher_context->lock));

    // Encrypt the NAS PDU using the given key and salt
    int32_t result = encrypt_nas_pdu_(nas_pdu, cipher_context->key, cipher_context->salt, *encrypted_nas_pdu);

    // Unlock the cipher context mutex
    pthread_mutex_unlock(&(cipher_context->lock));

    // Return the result of the encryption operation
    return result;
}

// Define the function for decrypting a NAS PDU using a given cipher context
int32_t decrypt_nas_pdu(const nas_pdu_t *encrypted_nas_pdu, const cipher_context_t *cipher_context, uint8_t **decrypted_nas_pdu) {
    // Check if the encrypted NAS PDU and cipher context are valid
    if (encrypted_nas_pdu == NULL || cipher_context == NULL) {
        return ERR_INVALID_PARAMETER;
    }

    // Allocate memory for the decrypted NAS PDU
    *decrypted_nas_pdu = malloc(sizeof(**decrypted_nas_pdu));
    if (*decrypted_nas_pdu == NULL) {
        return ERR_ALLOCATION_FAILED;
    }

    // Lock the cipher context mutex to ensure thread-safe access
    pthread_mutex_lock(&(cipher_context->lock));

    // Decrypt the encrypted NAS PDU using the given key and salt
    int32_t result = decrypt_nas_pdu_(encrypted_nas_pdu, cipher_context->key, cipher_context->salt, *decrypted_nas_pdu);

    // Unlock the cipher context mutex
    pthread_mutex_unlock(&(cipher_context->lock));

