    // Check if the NAS PDU and cipher context list are valid
    if (nas_pdu == NULL || cipher_context_list == NULL) {
        return ERR_INVALID_PARAMETER;
    }

    // Lock the cipher context list mutex to ensure thread-safe access
    pthread_mutex_lock(&(cipher_context_list->lock));

    // Add the NAS PDU to the end of the list
    nas_pdu_t *new_nas_pdu = malloc(sizeof(*new_nas_pdu));
    if (new_nas_pdu == NULL) {
        return ERR_ALLOCATION_FAILED;
    }
    memcpy(new_nas_pdu, nas_pdu, sizeof(*new_nas_pdu));
    cipher_context_list->size++;
    cipher_context_list->nas_pdus = realloc(cipher_context_list->nas_pdus, cipher_context_list->size * sizeof(*new_nas_pdu));
    if (cipher_context_list->nas_pdus == NULL) {
        return ERR_ALLOCATION_FAILED;
    }
    cipher_context_list->nas_pdus[cipher_context_list->size - 1] = new_nas_pdu;

    // Unlock the cipher context list mutex
    pthread_mutex_unlock(&(cipher_context_list->lock));

    // Return success
    return ERR_SUCCESS;
}

// Define the function for removing a NAS PDU from a list of encrypted NAS PDUs
int32_t remove_nas_pdu_from_list(const nas_pdu_t *nas_pdu, cipher_context_list_t *cipher_context_list) {
    // Check if the NAS PDU and cipher context list are valid
    if (nas_pdu == NULL || cipher_context_list == NULL) {
        return ERR_INVALID_PARAMETER;
    }

    // Lock the cipher context list mutex to ensure thread-safe access
    pthread_mutex_lock(&(cipher_context_list->lock));

    // Remove the NAS PDU from the list
    int32_t result = remove_nas_pdu_from_list_(nas_pdu, cipher_context_list);

    // Unlock the cipher context list mutex
    pthread_mutex_unlock(&(cipher_context_list->lock));

    // Return the result of the removal operation
    return result;
}

// Define the function for clearing a list of encrypted NAS PDUs
int32_t clear_nas_pdu_list(cipher_context_list_t *cipher_context_list) {
    // Check if the cipher context list is valid
    if (cipher_context_list == NULL) {
        return ERR_INVALID_PARAMETER;
    }

    // Lock the cipher context list mutex to ensure thread-safe access
    pthread_mutex_lock(&(cipher_context_list->lock));

    // Clear the NAS PDU list
    cipher_context_list->size = 0;
    free(cipher_context_list->nas_pdus);
    cipher_context_list->nas_pdus = NULL;

    // Unlock the cipher context list mutex
    pthread_mutex_unlock(&(cipher_context_list->lock));

    // Return success
    return ERR_SUCCESS;
}']

