// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
std::vector<NFAPI_CRC_INDICATION_PDU_T> createAndPopulateCrcIndicationList(uint32_t numPdus) {
  // Initialize the list with the given number of PDUs
  std::vector<NFAPI_CRC_INDICATION_PDU_T> crcIndications;
  crcIndications.reserve(numPdus);

  // Randomly set the CRCFLAG for each PDU
  std::mt19937 gen(std::random_device()());
  std::uniform_int_distribution<uint8_t> crcflagDistribution(0, 1);

  // Populate the list with random PDUs and CRCFLAG values
  for (uint32_t i = 0; i < numPdus; ++i) {
    NFAPI_CRC_INDICATION_PDU_T crcIndication;
    crcIndication.validRXUEInformationTag = true;
    crcIndication.rnti = gen() % 65536; // random RNTI value in the range [0, 65535]
    crcIndication.crcIndicationRel8Tag = 0x12345678; // random CRCI indication tag
    crcIndication.crcflag = crcflagDistribution(gen); // randomly set the CRCFLAG value
    crcIndications.push_back(crcIndication);
  }

  return crcIndications;
}

// Function to add random vertices and edges to a graph database
void addRandomVerticesAndEdges(GraphDatabase& graphDb, uint32_t numVertices, uint32_t numEdges) {
  // Randomly generate vertex IDs and properties
  std::mt19937 gen(std::random_device()());
  std::uniform_int_distribution<uint16_t> vertexIdDistribution(0, 65535);
  std::vector<std::pair<uint16_t, uint16_t>> vertices;
  vertices.reserve(numVertices);
  for (uint32_t i = 0; i < numVertices; ++i) {
    vertices.push_back({vertexIdDistribution(gen), gen() % 65536}); // random vertex ID and property value
  }

  // Randomly generate edge sources and destinations
  std::uniform_int_distribution<uint16_t> edgeSourceDestinationDistribution(0, numVertices - 1);
  std::unordered_map<uint16_t, std::vector<uint16_t>> edges;
  for (uint32_t i = 0; i < numEdges; ++i) {
    uint16_t sourceId = edgeSourceDestinationDistribution(gen);
    uint16_t destinationId = edgeSourceDestinationDistribution(gen);
    while (sourceId == destinationId || edges.find({sourceId, destinationId}) != edges.end()) {
      // Generate a new random source and destination ID if the edge is invalid or already exists in the map
      sourceId = edgeSourceDestinationDistribution(gen);
      destinationId = edgeSourceDestinationDistribution(gen);
    }
    edges[sourceId].push_back(destinationId); // add the new edge to the map
  }

  graphDb.vertices = vertices; // assign the generated vertices to the graph database
  graphDb.edges = edges; // assign the generated edges to the graph database
}
