void add_structure(char *rx_ue_information_tag, int rnti) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Create a new structure and initialize it with the provided values
    NFAPI_MESSAGE_PDU_T *structure = malloc(sizeof(NFAPI_MESSAGE_PDU_T));
    structure->rx_ue_information_tag = rx_ue_information_tag;
    structure->rnti = rnti;

    // Add the new structure to the list
