        list = malloc(sizeof(NFAPI_MESSAGE_PDU_T));
        list[0] = structure;
    } else {
        size_t i;
        for (i = 0; i < sizeof(NFAPI_MESSAGE_PDU_T); i++) {
            if (list[i] == NULL) {
                list[i] = structure;
                break;
            }
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&lock);
}

void remove_structure(char *rx_ue_information_tag, int rnti) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Find the structure with the provided values and remove it from the list
    size_t i;
    for (i = 0; i < sizeof(NFAPI_MESSAGE_PDU_T); i++) {
        if (list[i] != NULL &&
