        fprintf(stderr, "Structure with RX_UE_INFORMATION_TAG '%s' and RNTI %d does not exist\n", rx_ue_information_tag, rnti);
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&lock);
}

void print_structures() {
