#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <syslog.h>
#include "network_common.h"

typedef struct {
    RLC_AM_SNAPSHOT_ID id;
    PDCP_SN pdcp_sn;
    DL_SNAPSHOT_TAG dl_snapshot_tag;
    SNDCP_STATUS sndcp_status;
} NR_RLC_AM_SNAPSHOT_PDU_T;

typedef struct {
    size_t capacity;
    size_t size;
    NR_RLC_AM_SNAPSHOT_PDU_T* elements;
    pthread_mutex_t mutex;
} NR_RLC_AM_SNAPSHOT_LIST;

void init_nr_rlc_am_snapshot_list(NR_RLC_AM_SNAPSHOT_LIST* list) {
    list->capacity = 0;
    list->size = 0;
    list->elements = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void free_nr_rlc_am_snapshot_list(NR_RLC_AM_SNAPSHOT_LIST* list) {
    if (list->size > 0) {
        pthread_mutex_lock(&list->mutex);
        for (size_t i = 0; i < list->size; ++i) {
            free(list->elements[i].dl_snapshot_tag.time);
            free(list->elements[i].dl_snapshot_tag.seq_num);
            free(list->elements[i].pdcp_sn.ip_addr);
        }
        pthread_mutex_unlock(&list->mutex);
    }
    list->size = 0;
    pthread_mutex_destroy(&list->mutex);
}

NR_RLC_AM_SNAPSHOT_PDU_T* add_nr_rlc_am_snapshot_element(NR_RLC_AM_SNAPSHOT_LIST* list, RLC_AM_SNAPSHOT_ID id, PDCP_SN pdcp_sn, DL_SNAPSHOT_TAG dl_snapshot_tag, SNDCP_STATUS sndcp_status) {
    if (list->size >= list->capacity) {
        pthread_mutex_lock(&list->mutex);
        NR_RLC_AM_SNAPSHOT_PDU_T* new_elements = realloc(list->elements, list->capacity * 2 * sizeof(NR_RLC_AM_SNAPSHOT_PDU_T));
        if (new_elements == NULL) {
            syslog(LOG_ERR, "Failed to allocate memory for RLC AM snapshot list");
            pthread_mutex_unlock(&list->mutex);
            return NULL;
        }
        list->capacity *= 2;
        list->elements = new_elements;
        pthread_mutex_unlock(&list->mutex);
    }
    pthread_mutex_lock(&list->mutex);
    NR_RLC_AM_SNAPSHOT_PDU_T* element = &(list->elements[list->size++]);
    element->id = id;
    element->pdcp_sn = pdcp_sn;
    element->dl_snapshot_tag = dl_snapshot_tag;
    element->sndcp_status = sndcp_status;
    pthread_mutex_unlock(&list->mutex);
    return element;
}

void remove_nr_rlc_am_snapshot_element(NR_RLC_AM_SNAPSHOT_LIST* list, size_t index) {
    if (index >= list->size) {
        syslog(LOG_ERR, "Invalid index for RLC AM snapshot list");
        return;
    }
    pthread_mutex_lock(&list->mutex);
    NR_RLC_AM_SNAPSHOT_PDU_T* last_element = &(list->elements[--list->size]);
    if (index != list->size) {
        memcpy(&(list->elements[index]), last_element, sizeof(NR_RLC_AM_SNAPSHOT_PDU_T));
    }
    pthread_mutex_unlock(&list->mutex);
}

void remove_nr_rlc_am_snapshot_id(NR_RLC_AM_SNAPSHOT_LIST* list, RLC_AM_SNAPSHOT_ID id) {
    pthread_mutex_lock(&list->mutex);
    size_t index = 0;
    for (; index < list->size; ++index) {
        if (list->elements[index].id == id) {
            break;
        }
    }
    if (index != list->size) {
        remove_nr_rlc_am_snapshot_element(list, index);
    } else {
        syslog(LOG_ERR, "RLC AM snapshot ID not found in list");
    }
    pthread_mutex_unlock(&list->mutex);
}

