    for (; index < list->size; ++index) {
        if (strcmp(list->elements[index].pdcp_sn.ip_addr, pdcp_sn.ip_addr) == 0 && list->elements[index].pdcp_sn.port == pdcp_sn.port) {
            break;
        }
    }
    if (index != list->size) {
        remove_nr_rlc_am_snapshot_element(list, index);
    } else {
        syslog(LOG_ERR, "RLC AM snapshot PDCP SN not found in list");
    }
    pthread_mutex_unlock(&list->mutex);
}

