// Struct to hold traffic event data
struct TrafficEvent {
    time_t timestamp;
    int type;
    void* metadata;
};

// Dynamic array to store traffic events
struct EventArray {
    struct TrafficEvent** events;
    size_t capacity;
    size_t count;
};

// Create a new event array with the specified capacity
static struct EventArray* createEventArray(size_t capacity) {
    struct EventArray* arr = (struct EventArray*) malloc(sizeof(struct EventArray));
    if (!arr) {
        return NULL;
    }
    arr->events = (struct TrafficEvent**) calloc(capacity, sizeof(struct TrafficEvent*));
    if (!arr->events) {
        free(arr);
        return NULL;
    }
    arr->capacity = capacity;
    arr->count = 0;
    return arr;
}

// Insert a new traffic event into the array, handling potential memory allocation failures
static int insertEvent(struct EventArray* arr, struct TrafficEvent* event) {
    if (arr->count >= arr->capacity) {
        // Array is full, allocate more memory
        size_t newCapacity = arr->capacity * 2;
        void** newEvents = realloc(arr->events, newCapacity * sizeof(struct TrafficEvent*));
        if (!newEvents) {
            return -1;
        }
        arr->events = (struct TrafficEvent**) newEvents;
        arr->capacity = newCapacity;
    }
    arr->events[arr->count++] = event;
    return 0;
}

// Retrieve a traffic event from the array by index, returning NULL if out of bounds
static struct TrafficEvent* getEvent(struct EventArray* arr, size_t index) {
    if (index >= arr->count) {
        return NULL;
    }
    return arr->events[index];
}

// Periodically clean up outdated events based on the specified expiration time
static void cleanupEvents(struct EventArray* arr, time_t expirationTime) {
    size_t i = 0;
    while (i < arr->count && arr->events[i]->timestamp < expirationTime) {
        // Free the event and remove it from the array
        free(arr->events[i]);
        memmove(&arr->events[i], &arr->events[i + 1], (arr->count - i - 1) * sizeof(struct TrafficEvent*));
        arr->count--;
    }
}
