#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Structure to hold a frame buffer entry
typedef struct {
    uint64_t timestamp;
    void *data;
    size_t data_len;
    bool is_active;
} FrameBufferEntry;

// Function to initialize the frame buffer pool
void init_frame_buffer_pool(size_t num_buffers) {
    // Allocate memory for the frame buffers and initialize them
    FrameBufferEntry *buffers = malloc(num_buffers * sizeof(FrameBufferEntry));
    for (size_t i = 0; i < num_buffers; i++) {
        buffers[i].timestamp = 0;
        buffers[i].data = NULL;
        buffers[i].data_len = 0;
        buffers[i].is_active = false;
    }

    // Initialize a semaphore to protect the frame buffer pool
    sem_init(&buffer_sem, 1, num_buffers);
}

// Function to acquire a frame buffer from the pool
FrameBufferEntry *acquire_frame_buffer() {
    FrameBufferEntry *buffer;

    // Acquire a free buffer from the pool
    sem_wait(&buffer_sem);
    for (size_t i = 0; i < num_buffers; i++) {
        if (!buffers[i].is_active) {
            buffers[i].is_active = true;
            buffer = &buffers[i];
            break;
        }
    }

    // If no free buffer is available, allocate a new one
    if (buffer == NULL) {
        buffer = malloc(sizeof(FrameBufferEntry));
        buffer->timestamp = 0;
        buffer->data = NULL;
        buffer->data_len = 0;
        buffer->is_active = true;
    }

    // Return the acquired buffer
    return buffer;
}

// Function to release a frame buffer back to the pool
void release_frame_buffer(FrameBufferEntry *buffer) {
    // Reset the buffer's timestamp and data pointer
    buffer->timestamp = 0;
    buffer->data = NULL;
    buffer->data_len = 0;

    // Set the buffer as inactive and release it back to the pool
    sem_post(&buffer_sem);
}

// Function to update a frame buffer with new data
void update_frame_buffer(FrameBufferEntry *buffer, uint64_t timestamp, void *data, size_t data_len) {
    // Update the buffer's timestamp and data pointer
    buffer->timestamp = timestamp;
    buffer->data = data;
    buffer->data_len = data_len;
}

// Function to handle buffer overflows by truncating excess data
void handle_buffer_overflow(FrameBufferEntry *buffer, size_t max_size) {
    // Truncate the excess data if the buffer is too large
    if (buffer->data_len > max_size) {
        buffer->data_len = max_size;
    }
}

// Function to monitor and log any failures in buffer allocation or overflow handling
void check_for_failure(FrameBufferEntry *buffer, size_t num_buffers) {
    // Check if the buffer is active
    if (buffer->is_active) {
        // Log a failure message if the buffer is full
        if (buffer->data_len == max_size) {
            printf("Buffer overflow: Buffer %zu is full\n", buffer - buffers);
        } else {
            printf("Buffer underflow: Buffer %zu is empty\n", buffer - buffers);
        }
    }
}
```
