struct L2CACHE_EVENT_RECORD {
    time_t timestamp;
    long transaction_id;
    float cpu_utilization;
    float memory_utilization;
    float io_wait_time;
};

typedef struct {
    struct L2CACHE_EVENT_RECORD *records;
    size_t capacity;
    size_t count;
} L2CACHE_LIST;

void l2cache_list_init(L2CACHE_LIST *list) {
    list->capacity = 1000; // initial capacity of the list
    list->count = 0;
    list->records = malloc(sizeof(struct L2CACHE_EVENT_RECORD) * list->capacity);
}

void l2cache_list_destroy(L2CACHE_LIST *list) {
    free(list->records);
}

int l2cache_list_add(L2CACHE_LIST *list, struct L2CACHE_EVENT_RECORD record) {
    if (list->count == list->capacity) {
        // resize the list when it reaches its capacity
        size_t new_capacity = list->capacity * 2;
        struct L2CACHE_EVENT_RECORD *new_records = malloc(sizeof(struct L2CACHE_EVENT_RECORD) * new_capacity);
        if (new_records == NULL) {
            return -1; // allocation failure
        }
        memcpy(new_records, list->records, sizeof(struct L2CACHE_EVENT_RECORD) * list->count);
        free(list->records);
        list->records = new_records;
        list->capacity = new_capacity;
    }
    list->records[list->count++] = record;
    return 0; // success
}

struct L2CACHE_EVENT_RECORD *l2cache_list_get(L2CACHE_LIST *list, size_t index) {
    if (index >= list->count) {
        return NULL; // invalid index
    }
    return &list->records[index];
}

void l2cache_list_print(L2CACHE_LIST *list) {
    for (size_t i = 0; i < list->count; i++) {
        struct L2CACHE_EVENT_RECORD record = list->records[i];
        printf("Timestamp: %ld\n", record.timestamp);
        printf("Transaction ID: %ld\n", record.transaction_id);
        printf("CPU Utilization: %.2f\n", record.cpu_utilization);
        printf("Memory Utilization: %.2f\n", record.memory_utilization);
        printf("I/O Wait Time: %.2f\n", record.io_wait_time);
    }
}
