    RNTI rnti;
    CRCFLAG crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variable to store the list of CRC indications
NFAPI_CRC_INDICATION_PDU_T *crcIndications = NULL;

// Function to add a new CRC indication to the list
void addCrcIndication(RX_UE_INFORMATION_TAG rxUeInformation, RNTI rnti, CRCFLAG crcFlag) {
    // Check if the list is full and needs to be resized
    if (crcIndications == NULL || crcIndications->size >= MAX_CRC_INDICATIONS) {
        resizeCrcIndications();
    }

    // Add a new CRC indication to the list
    NFAPI_CRC_INDICATION_PDU_T *newCrcIndication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newCrcIndication->rxUeInformation = rxUeInformation;
    newCrcIndication->rnti = rnti;
    newCrcIndication->crcFlag = crcFlag;
    crcIndications->size++;
    crcIndications->indications[crcIndications->size - 1] = newCrcIndication;
}

// Function to remove a CRC indication from the list
void removeCrcIndication(RNTI rnti) {
    // Find the index of the CRC indication with the given RNTI
    int index = -1;
    for (int i = 0; i < crcIndications->size; i++) {
        if (crcIndications->indications[i]->rnti == rnti) {
            index = i;
            break;
        }
    }

    // Remove the CRC indication from the list and free its memory
    if (index != -1) {
        NFAPI_CRC_INDICATION_PDU_T *removedCrcIndication = crcIndications->indications[index];
        memmove(&crcIndications->indications[index], &crcIndications->indications[index + 1], (crcIndications->size - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        crcIndications->size--;
        free(removedCrcIndication);
    }
}

// Function to resize the list of CRC indications if it exceeds its capacity
void resizeCrcIndications() {
    // Double the size of the list and allocate new memory for it
    NFAPI_CRC_INDICATION_PDU_T **newIndications = malloc((crcIndications->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(newIndications, crcIndications->indications, crcIndications->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(crcIndications);

    // Set the new list as the current list and return
    crcIndications = newIndications;
}

// Function to iterate over the list of CRC indications and print out their details
void printCrcIndications() {
    for (int i = 0; i < crcIndications->size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *crcIndication = crcIndications->indications[i];
