void add_message(NFAPI_MESSAGE_T *message, int cqi, int phr_tag) {
    // Check if there is enough space in the array for a new message
    if (num_messages < MAX_NUM_MESSAGES) {
        // Allocate memory for the new message metadata structure
        struct message_metadata *new_message = malloc(sizeof(struct message_metadata));
        // Initialize the fields of the new message metadata structure
        new_message->message = message;
        new_message->cqi = cqi;
        new_message->phr_tag = phr_tag;
        // Add the new message to the end of the array
        messages[num_messages++] = new_message;
    } else {
        // Print an error message if there is not enough space in the array
        printf("Error: Unable to add new message to list, maximum number of messages reached.\n");
    }
}

// Function to retrieve a message from the list
