    // Check if the index is within the bounds of the array
    if (index >= 0 && index < num_messages) {
        return messages[index]->message;
    } else {
        // Print an error message if the index is out of bounds
        printf("Error: Unable to retrieve message from list, invalid index.\n");
        return NULL;
    }
}

// Function to delete a message from the list
void delete_message(int index) {
    // Check if the index is within the bounds of the array
    if (index >= 0 && index < num_messages) {
        // Free the memory for the message metadata structure
        free(messages[index]);
        // Remove the deleted message from the array
        memmove(&messages[index], &messages[index + 1], sizeof(struct message_metadata) * (num_messages - index));
        num_messages--;
    } else {
        // Print an error message if the index is out of bounds
        printf("Error: Unable to delete message from list, invalid index.\n");
    }
}

// Function to update the CQI value for a message in the list
void update_cqi(int index, int cqi) {
    // Check if the index is within the bounds of the array
    if (index >= 0 && index < num_messages) {
        messages[index]->cqi = cqi;
    } else {
        // Print an error message if the index is out of bounds
        printf("Error: Unable to update CQI value for message, invalid index.\n");
    }
}

// Function to update the PHR tag value for a message in the list
void update_phr_tag(int index, int phr_tag) {
    // Check if the index is within the bounds of the array
    if (index >= 0 && index < num_messages) {
        messages[index]->phr_tag = phr_tag;
    } else {
        // Print an error message if the index is out of bounds
        printf("Error: Unable to update PHR tag value for message, invalid index.\n");
    }
}
