/* Function to generate an MD5 hash of a provided string */
unsigned char* generateMD5Hash(const unsigned char* data, size_t len) {
    /* Initialize the MD5 hash context */
    MD5_CTX ctx;
    MD5_Init(&ctx);

    /* Update the hash context with the provided data */
    MD5_Update(&ctx, data, len);

    /* Finalize the hash calculation and return the result */
    unsigned char* hash = (unsigned char*) malloc(MD5_DIGEST_LENGTH * sizeof(unsigned char));
    MD5_Final(hash, &ctx);

    return hash;
}

/* Function to initialize a list of UE radio resource configurations */
void initializeRadioResources(LTE_UERadioResourceConfig_Downlink_CGI_t** resources, int numEntries) {
    /* Allocate memory for the list of resources */
    *resources = (LTE_UERadioResourceConfig_Downlink_CGI_t*) malloc(numEntries * sizeof(LTE_UERadioResourceConfig_Downlink_CGI_t));

    /* Initialize each resource with default values */
    for (int i = 0; i < numEntries; ++i) {
        (*resources)[i].cellID = -1;
        (*resources)[i].band = -1;
        (*resources)[i].messages = NULL;
    }
}

/* Function to manage a list of UE radio resource configurations */
void manageRadioResources(LTE_UERadioResourceConfig_Downlink_CGI_t** resources, int numEntries, bool enableEnhancedMessageProcessing) {
    /* Initialize the list of resources if it is NULL */
    if (*resources == NULL) {
        initializeRadioResources(resources, numEntries);
    }

    /* Update each resource with new values */
    for (int i = 0; i < numEntries; ++i) {
        /* If enhanced message processing is enabled, add a PAGING_TYPE1 and PAGING_TYPE2 message to the list of messages */
        if (enableEnhancedMessageProcessing) {
            LTE_DL_CCCH_MessageList_T* messages = malloc(sizeof(LTE_DL_CCCH_MessageList_T));
            messages->messageType = PAGING_TYPE1;
            messages->paging.cause = 0x14;
            messages->paging.pagingCycle = 5;
            (*resources)[i].messages = messages;
        } else {
            /* Otherwise, clear the list of messages */
            free((*resources)[i].messages);
            (*resources)[i].messages = NULL;
        }
    }
}

/* Function to calculate and return the MD5 hash of a provided string */
unsigned char* generateMD5HashAndInitializeRadioResources(const unsigned char* data, size_t len, int numEntries, bool enableEnhancedMessageProcessing) {
    /* Initialize the list of UE radio resource configurations if it is NULL */
    if (resources == NULL) {
        initializeRadioResources(&resources, numEntries);
    }

    /* Manage each resource with new values */
    for (int i = 0; i < numEntries; ++i) {
        manageRadioResources(&resources[i], 1, enableEnhancedMessageProcessing);
    }

    /* Calculate the MD5 hash of the provided data */
    unsigned char* hash = generateMD5Hash(data, len);

    return hash;
}
