// Function for dynamically allocating memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(size_t num_packets) {
    // Check if the requested number of packets is within the allowed range
    if (num_packets > 10000) {
        fprintf(stderr, "Error: Requested number of packets exceeds maximum allowed value.\n");
        return NULL;
    }

    // Calculate the required memory size for the array of structures
    size_t mem_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_packets;

    // Allocate memory for the array using malloc() with error handling
    NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(mem_size);
    if (crc_indication_pdu == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for CRC indication PDU array.\n");
        return NULL;
    }

    // Initialize the structure fields for each element in the array
    for (size_t i = 0; i < num_packets; i++) {
        crc_indication_pdu[i].rx_ue_information_tag = 0x0000;
        crc_indication_pdu[i].rnti = 0x00000000;
        crc_indication_pdu[i].crc_indication_rel8_tag = 0x00;
        crc_indication_pdu[i].crcflag = false;
    }

    // Set a random seed for generating the CRC flags
    srand(time(NULL));

    // Generate random CRC flags for each element in the array
    for (size_t i = 0; i < num_packets; i++) {
        crc_indication_pdu[i].crcflag = rand() % 2 == 0;
    }

    // Return a pointer to the allocated memory
    return crc_indication_pdu;
}
