#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netdb.h>
#include <netinet/in.h>
#include <unistd.h>

#define BUFFER_SIZE 4096
#define SEQUENCE_NUMBER_MAX 65535
#define CHECKSUM_LEN 16
#define TIMEOUT_INTERVAL_MIN 100
#define TIMEOUT_INTERVAL_MAX 2000
#define BUFFER_SIZE_MIN 512
#define BUFFER_SIZE_MAX 4096
#define LOGGING_THRESHOLD_MIN 100
#define LOGGING_THRESHOLD_MAX 10000

typedef enum {
    STATE_INIT,
    STATE_CONNECTED,
    STATE_DISCONNECTED
} NetworkSessionState;

struct NetworkSession {
    int socket;
    struct sockaddr_in serverAddr;
    char *buffer;
    size_t bufferSize;
    size_t sequenceNumber;
    uint32_t checksum;
    bool isLoggingEnabled;
};

NetworkSessionState networkSessionInit(struct NetworkSession *session, const char *serverIP, uint16_t serverPort) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        return STATE_DISCONNECTED;
    }

    struct sockaddr_in serverAddr;
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(serverPort);
    if (inet_pton(AF_INET, serverIP, &serverAddr.sin_addr) <= 0) {
        close(sock);
        return STATE_DISCONNECTED;
    }

    session->socket = sock;
    session->serverAddr = serverAddr;
    session->buffer = malloc(BUFFER_SIZE * sizeof(char));
    if (!session->buffer) {
        close(sock);
        return STATE_DISCONNECTED;
    }
    session->bufferSize = BUFFER_SIZE;
    session->sequenceNumber = 0;
    session->checksum = 0;
    session->isLoggingEnabled = false;

    return STATE_INIT;
}

NetworkSessionState networkSessionSend(struct NetworkSession *session, const char *data, size_t dataSize) {
    if (!data || !dataSize) {
        return STATE_DISCONNECTED;
    }

    struct sockaddr_in serverAddr = session->serverAddr;
    ssize_t sentBytes = sendto(session->socket, data, dataSize, 0, (struct sockaddr *)&serverAddr, sizeof(serverAddr));
    if (sentBytes < 0) {
        return STATE_DISCONNECTED;
    }

    session->sequenceNumber++;
    session->checksum = 0xFFFFFFFF;
    for (int i = 0; i < sentBytes; i++) {
        session->checksum += data[i];
    }

    return STATE_CONNECTED;
}

NetworkSessionState networkSessionReceive(struct NetworkSession *session, char **data, size_t *dataSize) {
    if (!data || !dataSize) {
        return STATE_DISCONNECTED;
    }

    struct sockaddr_in clientAddr;
    socklen_t addrLen = sizeof(clientAddr);
    ssize_t receivedBytes = recvfrom(session->socket, session->buffer, session->bufferSize, 0, (struct sockaddr *)&clientAddr, &addrLen);
    if (receivedBytes < 0) {
        return STATE_DISCONNECTED;
    }

    uint32_t recvChecksum = 0xFFFFFFFF;
    for (int i = 0; i < receivedBytes; i++) {
        recvChecksum += session->buffer[i];
    }

    if (recvChecksum == session->checksum) {
        *data = session->buffer;
        *dataSize = receivedBytes;
        return STATE_CONNECTED;
    } else {
        return STATE_DISCONNECTED;
    }
}

NetworkSessionState networkSessionDisconnect(struct NetworkSession *session) {
    if (!session->socket || !session->serverAddr.sin_port || !session->buffer) {
        return STATE_DISCONNECTED;
    }

    close(session->socket);
    session->socket = 0;
    session->serverAddr = (struct sockaddr_in){};
    free(session->buffer);
    session->buffer = NULL;
    return STATE_DISCONNECTED;
}
```']

