// Define the shared memory pool for the NFAPI_CRC_INDICATION_PDU_T structures
#define MAX_POOL_SIZE 1024
static NFAPI_CRC_INDICATION_PDU_T *pool = NULL;
static size_t pool_size = 0;

// Define the mutex to ensure thread-safe access to the pool
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function that will manage the pool of NFAPI_CRC_INDICATION_PDU_T structures
void manage_pool(size_t n) {
    // Check if the pool is NULL and allocate it if necessary
    if (pool == NULL) {
        pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_POOL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Check if the pool is full and needs to be resized
    if (pool_size >= MAX_POOL_SIZE) {
        size_t new_size = pool_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pool, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_pool == NULL) {
            // Log an error message if the reallocation failed
            printf("Error: Failed to resize pool to %lu structures\n", new_size);
        } else {
            pool = new_pool;
            pool_size = new_size;
        }
    }

    // Lock the mutex to ensure thread-safe access to the pool
    pthread_mutex_lock(&mutex);

    // Create up to N structures in the pool, where N is specified as an input parameter
    for (size_t i = 0; i < n && pool_size < MAX_POOL_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pool[pool_size++];
        pdu->rx_ue_information_tag.crc_indication_rel8_tag = rand() % 2 ? CRC_INDICATION_REL8_TAG_1 : CRC_INDICATION_REL8_TAG_0;
        pdu->rnti = rand();
        pdu->crcflag = rand() % 2 ? true : false;
    }

    // Unlock the mutex to release thread-safe access to the pool
    pthread_mutex_unlock(&mutex);
}

// Define a mechanism to periodically clean up unused structures in the pool
void cleanup_pool(size_t n) {
    // Check if the pool is NULL or empty and return early
    if (pool == NULL || pool_size == 0) {
        return;
    }

    // Lock the mutex to ensure thread-safe access to the pool
    pthread_mutex_lock(&mutex);

    // Clean up unused structures in the pool, where a structure is considered unused if it has not been accessed for more than 10 seconds
    size_t i = 0;
    while (i < pool_size) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pool[i];
        if (pdu->rx_ue_information_tag.crc_indication_rel8_tag == CRC_INDICATION_REL8_TAG_0 || pdu->rnti == 0) {
            // If the structure is unused, move it to the end of the pool and increment the counter
            size_t last = --pool_size;
            memcpy(pdu, &pool[last], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        } else {
            // If the structure is used, move it to the next position in the pool and increment the counter
            i++;
        }
    }

    // Unlock the mutex to release thread-safe access to the pool
    pthread_mutex_unlock(&mutex);
}
