// Dynamically allocated array to store all network interfaces
network_interface_config *interfaces = NULL;
size_t num_interfaces = 0;

// Function to add a new network interface configuration
void add_interface(char *interface_name, uint32_t ip_address, uint32_t subnet_mask, uint32_t gateway) {
    // Check if the interface already exists in the list
    for (size_t i = 0; i < num_interfaces; ++i) {
        if (strcmp(interface_name, interfaces[i].interface_name) == 0) {
            return; // Interface already exists
        }
    }

    // Allocate memory for the new interface configuration
    network_interface_config *new_interface = malloc(sizeof(network_interface_config));
    if (new_interface == NULL) {
        printf("Error: unable to allocate memory for new interface configuration\n");
        return;
    }

    // Initialize the fields of the new interface configuration
    strcpy(new_interface->interface_name, interface_name);
    new_interface->ip_address = ip_address;
    new_interface->subnet_mask = subnet_mask;
    new_interface->gateway = gateway;
    new_interface->active_services[0] = NULL; // No active services by default

    // Add the new interface configuration to the list of interfaces
    interfaces = realloc(interfaces, (num_interfaces + 1) * sizeof(network_interface_config));
    if (interfaces == NULL) {
        printf("Error: unable to allocate memory for new interface configuration\n");
        free(new_interface);
        return;
    }
    interfaces[num_interfaces] = *new_interface;
    ++num_interfaces;
}

// Function to remove a network interface configuration
void remove_interface(char *interface_name) {
    // Find the index of the interface in the list
    size_t i;
    for (i = 0; i < num_interfaces; ++i) {
        if (strcmp(interface_name, interfaces[i].interface_name) == 0) {
            break; // Found the interface
        }
    }

    // Check if the interface was found in the list
    if (i >= num_interfaces) {
        printf("Error: interface %s not found\n", interface_name);
        return;
    }

    // Remove the interface configuration from the list of interfaces
    --num_interfaces;
    for (size_t j = i; j < num_interfaces; ++j) {
        interfaces[j] = interfaces[j + 1];
    }
}

// Function to update a network interface configuration
void update_interface(char *interface_name, uint32_t ip_address, uint32_t subnet_mask, uint32_t gateway) {
    // Find the index of the interface in the list
    size_t i;
    for (i = 0; i < num_interfaces; ++i) {
        if (strcmp(interface_name, interfaces[i].interface_name) == 0) {
            break; // Found the interface
        }
    }

    // Check if the interface was found in the list
    if (i >= num_interfaces) {
        printf("Error: interface %s not found\n", interface_name);
        return;
    }

    // Update the fields of the interface configuration
    interfaces[i].ip_address = ip_address;
    interfaces[i].subnet_mask = subnet_mask;
    interfaces[i].gateway = gateway;
}

// Function to query a network interface configuration
void get_interface(char *interface_name, uint32_t *ip_address, uint32_t *subnet_mask, uint32_t *gateway) {
    // Find the index of the interface in the list
    size_t i;
    for (i = 0; i < num_interfaces; ++i) {
        if (strcmp(interface_name, interfaces[i].interface_name) == 0) {
            break; // Found the interface
        }
    }

    // Check if the interface was found in the list
    if (i >= num_interfaces) {
        printf("Error: interface %s not found\n", interface_name);
        return;
    }

    // Return the fields of the interface configuration
    *ip_address = interfaces[i].ip_address;
    *subnet_mask = interfaces[i].subnet_mask;
    *gateway = interfaces[i].gateway;
}

// Function to validate an IP address format
int is_valid_ip(uint32_t ip) {
    // Check if the IP address is within a valid range
    uint8_t octets[4];
    uint8_t octet = 0;
    for (size_t i = 0; i < 4; ++i) {
        octets[i] = ip & 0xFF;
        ip >>= 8;
        if (octets[i] > 255) {
            return 0; // Invalid IP address format
        }
    }

    // Check if the IP address is within the same subnet as the gateway
    uint32_t subnet = interfaces[i].subnet_mask;
    for (size_t i = 0; i < 4; ++i) {
        octets[i] &= subnet & 0xFF;
        subnet >>= 8;
    }

    if (ip != interfaces[i].gateway) {
        return 0; // Gateway address is not within the same subnet as the IP address
    }

    return 1; // Valid IP address format and gateway address
}

// Function to validate a subnet mask
int is_valid_subnet(uint32_t subnet) {
    uint8_t octets[4];
    uint8_t octet = 0;
    for (size_t i = 0; i < 4; ++i) {
        octets[i] = subnet & 0xFF;
        subnet >>= 8;
        if (octets[i] > 255) {
            return 0; // Invalid subnet mask
        }
    }

    return 1; // Valid subnet mask
}
