// Define the data structure to store TCP connection requests
typedef struct {
    char ip_address[INET6_ADDRSTRLEN];
    uint16_t port;
    time_t timestamp;
} TCP_CONNECTION_REQUEST_PDU_T;

// Define the list data structure to store TCP connection requests
typedef struct {
    TCP_CONNECTION_REQUEST_PDU_T *elements;
    size_t num_elements;
    pthread_mutex_t lock; // Mutex for synchronizing access to the list
} LIST_T;

// Define the cache data structure to store recently accessed TCP connection requests
typedef struct {
    LIST_T *cache; // Cache of recent TCP connection requests
    size_t num_elements; // Number of elements in the cache
    time_t timestamp; // Timestamp for when the cache was last updated
} CACHE_T;

// Function to add a new TCP connection request to the list and cache
void add_tcp_connection_request(LIST_T *list, char *ip_address, uint16_t port) {
    // Lock the list before modifying it
    pthread_mutex_lock(&list->lock);

    // Allocate memory for the new TCP connection request structure
    TCP_CONNECTION_REQUEST_PDU_T *new_element = (TCP_CONNECTION_REQUEST_PDU_T *) malloc(sizeof(TCP_CONNECTION_REQUEST_PDU_T));

    // Check if memory allocation failed
    if (new_element == NULL) {
        printf("Memory allocation failure: %s\n", strerror(errno));
        pthread_mutex_unlock(&list->lock);
        return;
    }

    // Initialize the new TCP connection request structure
    memset(new_element, 0, sizeof(TCP_CONNECTION_REQUEST_PDU_T));
    strcpy(new_element->ip_address, ip_address);
    new_element->port = port;
    new_element->timestamp = time(NULL);

    // Add the new TCP connection request to the end of the list
    list->elements[list->num_elements] = *new_element;
    list->num_elements++;

    // Update the cache with the new TCP connection request
    update_cache(list, new_element);

    // Unlock the list after modifying it
    pthread_mutex_unlock(&list->lock);
}

// Function to update the cache with a newly added TCP connection request
void update_cache(LIST_T *list, TCP_CONNECTION_REQUEST_PDU_T *new_element) {
    // Check if the cache is full and needs to be updated
    if (list->num_elements > 0 && list->num_elements == list->cache->num_elements) {
        // Replace the oldest element in the cache with the newest TCP connection request
        LIST_T *oldest_element = &(list->elements[list->num_elements - 1]);
        memcpy(&(list->cache->elements[list->num_elements - 1]), new_element, sizeof(TCP_CONNECTION_REQUEST_PDU_T));
        list->cache->timestamp = time(NULL);
    } else {
        // Add the new TCP connection request to the end of the cache
        list->cache->elements[list->num_elements] = *new_element;
        list->cache->num_elements++;
    }
}

// Function to retrieve a TCP connection request from the cache by IP address and port number
TCP_CONNECTION_REQUEST_PDU_T* get_tcp_connection_request(LIST_T *list, char *ip_address, uint16_t port) {
    // Lock the list before accessing it
    pthread_mutex_lock(&list->lock);

    // Iterate through the elements in the cache to find a match
    for (int i = 0; i < list->cache->num_elements; i++) {
        TCP_CONNECTION_REQUEST_PDU_T *element = &(list->cache->elements[i]);
        if (strcmp(ip_address, element->ip_address) == 0 && port == element->port) {
            // Return the matching TCP connection request from the cache
            pthread_mutex_unlock(&list->lock);
            return element;
        }
    }

    // No match was found in the cache, so check if the list is full and needs to be updated
    if (list->num_elements == list->cache->num_elements) {
        // Replace the oldest element in the cache with the newest TCP connection request
        LIST_T *oldest_element = &(list->elements[list->num_elements - 1]);
        memcpy(&(list->cache->elements[list->num_elements - 1]), oldest_element, sizeof(TCP_CONNECTION_REQUEST_PDU_T));
        list->cache->timestamp = time(NULL);
    } else {
        // Add the new TCP connection request to the end of the cache
        list->cache->elements[list->num_elements] = *oldest_element;
        list->cache->num_elements++;
    }

    // Unlock the list after accessing it
    pthread_mutex_unlock(&list->lock);

    return NULL;
}
