// Function to add new entities to the list
void addEntity(NetworkEntityState **entityList, int entityId) {
    // Check if the entity already exists in the list
    for (int i = 0; i < (*entityList)->size; i++) {
        if ((*entityList)[i].entityId == entityId) {
            // Update the existing entity with the new data
            (*entityList)[i].status = true;
            return;
        }
    }

    // Allocate memory for the new entity
    NetworkEntityState *newEntity = (NetworkEntityState *) malloc(sizeof(NetworkEntityState));
    if (!newEntity) {
        perror("Memory allocation failed");
        exit(1);
    }

    // Initialize the new entity
    newEntity->entityId = entityId;
    newEntity->eventLogs = NULL;
    newEntity->status = false;

    // Add the new entity to the list
    (*entityList)->size++;
    (*entityList) = realloc(*entityList, (*entityList)->size * sizeof(NetworkEntityState));
    (*entityList)[*entityList].entityId = newEntity->entityId;
    (*entityList)[*entityList].eventLogs = NULL;
    (*entityList)[*entityList].status = false;
}

// Function to update the status of an entity in the list
void updateStatus(NetworkEntityState **entityList, int entityId, bool status) {
    // Check if the entity exists in the list
    for (int i = 0; i < (*entityList)->size; i++) {
        if ((*entityList)[i].entityId == entityId) {
            // Update the status of the entity
            (*entityList)[i].status = status;
            return;
        }
    }

    // Entity does not exist in the list, so do nothing
}

// Function to remove entities from the list based on a specific criteria
void removeEntities(NetworkEntityState **entityList, int entityId) {
    // Check if the entity exists in the list
    for (int i = 0; i < (*entityList)->size; i++) {
        if ((*entityList)[i].entityId == entityId) {
            // Remove the entity from the list
            free((*entityList)[i].eventLogs);
            memmove(&(*entityList)[i], &(*entityList)[i + 1], (*entityList)->size - i - 1);
            (*entityList)->size--;
            return;
        }
    }

    // Entity does not exist in the list, so do nothing
}

// Function to handle network events from external data sources
void handleNetworkEvent(NetworkEntityState **entityList, int entityId, char *eventLogs) {
    // Check if the entity exists in the list
    for (int i = 0; i < (*entityList)->size; i++) {
        if ((*entityList)[i].entityId == entityId) {
            // Update the event logs of the entity
            free((*entityList)[i].eventLogs);
            (*entityList)[i].eventLogs = strdup(eventLogs);
            return;
        }
    }

    // Entity does not exist in the list, so add it
    addEntity(entityList, entityId);
}

// Function to handle memory allocation failures
void handleMemoryAllocationFailure(NetworkEntityState **entityList) {
    perror("Memory allocation failed");
    exit(1);
}

int main() {
