    NetworkEntityState *entityList = (NetworkEntityState *) malloc(sizeof(NetworkEntityState));
    if (!entityList) {
        handleMemoryAllocationFailure(&entityList);
    }
    entityList->size = 0;

    // Add some entities to the list
    addEntity(&entityList, 1);
    addEntity(&entityList, 2);
    addEntity(&entityList, 3);

    // Update the status of an entity in the list
    updateStatus(&entityList, 1, true);

    // Remove entities from the list based on a specific criteria
    removeEntities(&entityList, 2);

    // Handle network events from external data sources
    handleNetworkEvent(&entityList, 1, "event log 1");
    handleNetworkEvent(&entityList, 3, "event log 3");

