    // Acquire the mutex for protecting the dynamic array
    pthread_mutex_lock(&user_data_mutex);

    // Check if the maximum number of entries has been reached
    if (MAX_ENTRIES == user_data_count) {
        // Handle overflow by expanding the dynamic array and copying existing data to new slots
        NFAPI_L1_API_USER_DATA *new_user_data = realloc(user_data, 2 * MAX_ENTRIES * sizeof(NFAPI_L1_API_USER_DATA));
        if (new_user_data == NULL) {
