// Function to add a new RNTI entry to the hash table
void nfapi_crc_indication_pdu_add(NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu) {
    // Lock the mutex to synchronize access to the hash tables
    pthread_mutex_lock(&hash_table_mutex);

    // Calculate the RNTI entry hash value
    uint32_t rnti_entry_hash = crc_indication_pdu->rnti % MAX_NUM_UE_SESSIONS;

