    pthread_mutex_lock(&hash_table_mutex);

    // Calculate the RNTI entry hash value
    uint32_t rnti_entry_hash = rnti % MAX_NUM_UE_SESSIONS;

    // Check if the RNTI entry exists in the hash table
    if (rnti_hash_table[rnti_entry_hash] != NULL) {
