// Struct to hold the data for each network interface
typedef struct NetworkInterfaceStatistics {
    char *interfaceName;
    int packetLossRate;
    long throughput;
    double latency;
} NetworkInterfaceStatistics;

// Linked list node to store the network interfaces statistics
typedef struct Node {
    NetworkInterfaceStatistics *data;
    struct Node *next;
} Node;

// Function to initialize and populate the linked list of network interfaces
void initNetworkInterfaceList(Node **head, int numInterfaces) {
    // Initialize the head node of the linked list
    *head = (Node *)malloc(sizeof(Node));
    (*head)->next = NULL;

    // Loop through each interface and add it to the linked list
    for (int i = 0; i < numInterfaces; i++) {
        // Create a new node for the current interface
        Node *newNode = (Node *)malloc(sizeof(Node));
        newNode->next = NULL;

        // Initialize the data fields for the current interface
        NetworkInterfaceStatistics *data = (NetworkInterfaceStatistics *)malloc(sizeof(NetworkInterfaceStatistics));
        data->interfaceName = (char *)malloc(sizeof(char) * 16);
        sprintf(data->interfaceName, "eth%d", i);
        data->packetLossRate = 0;
        data->throughput = 0;
        data->latency = 0.0;

        // Add the new node to the linked list
        Node *currentNode = *head;
        while (currentNode->next != NULL) {
            currentNode = currentNode->next;
        }
        currentNode->next = newNode;
    }
}

// Function to update the data for each network interface in the linked list
void updateNetworkInterfaceList(Node *head, int numInterfaces, int sampleInterval) {
    // Loop through each node in the linked list
    Node *currentNode = head;
    while (currentNode != NULL) {
        NetworkInterfaceStatistics *data = currentNode->data;

        // Update the packet loss rate for the current interface
        data->packetLossRate++;

        // Update the throughput and latency for the current interface
        long newThroughput = rand() % 100 + 1;
        double newLatency = (double)rand() / RAND_MAX * 5;
        data->throughput += newThroughput - data->throughput;
        data->latency += newLatency - data->latency;

        // Update the next pointer to move to the next node in the linked list
        currentNode = currentNode->next;
    }
}

// Function to clear and free the memory allocated for the linked list when it is no longer needed
void cleanupNetworkInterfaceList(Node *head) {
    // Loop through each node in the linked list and free its memory
    Node *currentNode = head;
    while (currentNode != NULL) {
        NetworkInterfaceStatistics *data = currentNode->data;

        // Free the data fields for the current interface
        free(data->interfaceName);
        free(data);

        // Update the next pointer to move to the next node in the linked list
        currentNode = currentNode->next;
    }

    // Free the head node of the linked list
    free(head);
}
```
