void initializeNetworkFlows(int num_flows) {
    // Dynamically allocate memory for the array of Network Flow Statistics (NFS) objects
    nfs = malloc(num_flows * sizeof(struct NFS));
    if (!nfs) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize each flow in the array with a unique identifier and default values for packet count and byte count
    for (int i = 0; i < num_flows; i++) {
        nfs[i].id = i + 1;
        nfs[i].packet_count = 0;
        nfs[i].byte_count = 0;
    }

    // Create a mutex to ensure thread safety when accessing the flow array
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Define a function to validate the integrity of a given flow identifier
    void validateFlow(int flow_id) {
        // Check if the flow identifier is valid and not already in use
        for (int i = 0; i < num_flows; i++) {
            if (nfs[i].id == flow_id && nfs[i].isValid()) {
                return;
            }
        }
        // If the flow identifier is not valid, retry validation up to three times
        for (int i = 0; i < 3; i++) {
            if (nfs[flow_id - 1].validate()) {
                return;
            }
        }
        // If the flow identifier could not be validated, mark it as invalid and return a default uninitialized state
        nfs[flow_id - 1].isValid = false;
    }

    // Define a function to update the packet count and byte count for a given flow
    void updateFlow(int flow_id) {
        pthread_mutex_lock(&mutex);
        validateFlow(flow_id);
        if (nfs[flow_id - 1].isValid()) {
            nfs[flow_id - 1].packet_count++;
            nfs[flow_id - 1].byte_count += sizeof(struct NFS);
        }
        pthread_mutex_unlock(&mutex);
    }

    // Define a function to clean up stale flows not updated within the last hour
    void cleanupStaleFlows() {
        time_t current_time = time(NULL);
        for (int i = 0; i < num_flows; i++) {
            if ((current_time - nfs[i].timestamp) > 3600) {
                nfs[i].isValid = false;
            }
        }
    }

    // Periodically clean up stale flows using a separate thread
    pthread_t cleaner;
    pthread_create(&cleaner, NULL, cleanupStaleFlows, NULL);
}
