};
typedef struct NFAPI_CRC_INDICATION_PDU_T NFAPI_CRC_INDICATION_PDU_T;

// thread-safe random number generator using a Mersenne Twister algorithm
void mt_random(uint32_t* seed, uint32_t max) {
    const uint32_t M = 624;
    const uint32_t N = 397;
    const uint32_t MATRIX_A = 0x9908b0df;
    const uint32_t UPPER_MASK = 0x80000000;
    const uint32_t LOWER_MASK = 0x7fffffff;

    *seed = (*seed ^ (*seed >> 11)) & LOWER_MASK;
    *seed *= MATRIX_A;
    if (*seed > N) {
        *seed -= N;
    }
    uint32_t t = *seed;
    if ((t & UPPER_MASK) == 0) {
        t |= UPPER_MASK;
    } else {
        t &= LOWER_MASK;
    }
    return (t % max);
}

// memory pool allocation strategy using a linked list
struct MemoryPoolNode {
    void* data;
    struct MemoryPoolNode* next;
};
typedef struct MemoryPoolNode MemoryPoolNode;

MemoryPoolNode* mempool = NULL; // head node of the memory pool linked list
void* allocate(uint32_t size) {
    if (mempool == NULL) {
        mempool = malloc(size);
    } else {
        void* data = malloc(size);
        MemoryPoolNode* current = mempool;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = malloc(size);
    }
    return mempool->data;
}
void deallocate(void* data) {
    MemoryPoolNode* current = mempool;
    while (current != NULL && current->data != data) {
        current = current->next;
    }
    if (current == NULL) {
        fprintf(stderr, "Memory pool corruption detected!\n");
        return;
    }
    free(current);
}

// function to manage and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_pdu_list(uint32_t num, uint32_t seed, uint32_t max) {
    // input validation and error handling
    if (num > MAX_N || seed < 0 || max > MAX_PAYLOAD_LENGTH) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    // initialize memory pool and random number generator
    mempool = NULL;
    srand(seed);

    // allocate and populate the list of structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < num; i++) {
        // generate a random RX_UE_INFORMATION_TAG and RNTI value
        pdu_list[i].RX_UE_INFORMATION_TAG = mt_random(&seed, UINT16_MAX);
        pdu_list[i].RNTI = mt_random(&seed, UINT32_MAX);

        // generate a random CRC_INDICATION_REL8_TAG value
        pdu_list[i].CRC_INDICATION_REL8_TAG = mt_random(&seed, UINT16_MAX);

        // set CRCFLAG to true or false randomly
        pdu_list[i].CRCFLAG = (bool)mt_random(&seed, 2);

        // generate a random payload for each structure using the memory pool allocation strategy
        uint32_t payload_size = mt_random(&seed, max);
        pdu_list[i].payload = allocate(payload_size);
        memset(pdu_list[i].payload, 0x00, payload_size);
    }

    // return the populated list of structures
    return pdu_list;
}

// function to serialize the list of structures into a binary format
void serialize(NFAPI_CRC_INDICATION_PDU_T* pdu_list, uint32_t num) {
    // initialize output buffer and counter for number of bytes written
    uint8_t* outbuf = malloc(num * (sizeof(uint16_t) + sizeof(uint32_t) + sizeof(bool) + MAX_PAYLOAD_LENGTH));
    int offset = 0;

    // iterate through the list of structures and serialize each one
    for (int i = 0; i < num; i++) {
        memcpy(outbuf + offset, &pdu_list[i].RX_UE_INFORMATION_TAG, sizeof(uint16_t));
        offset += sizeof(uint16_t);
        memcpy(outbuf + offset, &pdu_list[i].RNTI, sizeof(uint32_t));
        offset += sizeof(uint32_t);
        memcpy(outbuf + offset, &pdu_list[i].CRC_INDICATION_REL8_TAG, sizeof(uint16_t));
        offset += sizeof(uint16_t);
        memcpy(outbuf + offset, &pdu_list[i].CRCFLAG, sizeof(bool));
        offset += sizeof(bool);
        memcpy(outbuf + offset, pdu_list[i].payload, MAX_PAYLOAD_LENGTH);
        offset += MAX_PAYLOAD_LENGTH;
    }

    // write the serialized data to a file
    FILE* outfile = fopen("pdu_data.bin", "wb");
    fwrite(outbuf, 1, offset, outfile);
    fclose(outfile);
}
