    struct NFAPI_CRC_INDICATION_PDU_T *head;
    struct NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t size;
};

// Function to dynamically create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
struct NFAPI_CRC_INDICATION_LIST* createAndPopulateNfapiCrcIndicationList(size_t N) {
    // Check for invalid input size
    if (N <= 0) {
        return NULL;
    }

    // Allocate memory for the linked list structure and initialize its head and tail pointers
    struct NFAPI_CRC_INDICATION_LIST *list = malloc(sizeof(struct NFAPI_CRC_INDICATION_LIST));
    if (!list) {
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    // Iterate over the input size and dynamically allocate memory for each structure
    struct NFAPI_CRC_INDICATION_PDU_T *current = NULL;
    for (size_t i = 0; i < N; i++) {
        current = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (!current) {
            // If memory allocation fails, free the already allocated memory and return NULL
            freeNfapiCrcIndicationList(list);
            return NULL;
        }

        // Initialize the fields of the structure
        current->RX_UE_INFORMATION_TAG = 0xABCD;
        current->RNTI = i + 1;
        current->CRC_INDICATION_REL8_TAG = 0xEFGH;
        current->CRCFLAG = (i % 2 == 0) ? 0 : 1;

        // Add the structure to the linked list
        if (!list->head) {
            list->head = current;
            list->tail = current;
        } else {
            list->tail->next = current;
            list->tail = current;
        }
        list->size++;
    }

    // Return the linked list structure
    return list;
}

// Function to free the memory allocated for the linked list of NFAPI_CRC_INDICATION_PDU_T structures
void freeNfapiCrcIndicationList(struct NFAPI_CRC_INDICATION_LIST *list) {
    if (!list) {
        return;
    }

    // Free the memory allocated for each structure in the list
    struct NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        free(current);
        current = current->next;
    }

    // Free the memory allocated for the linked list structure itself
    free(list);
}

// Function to iterate over the elements of the linked list and perform a specific action on each element
void iterateOverNfapiCrcIndicationList(struct NFAPI_CRC_INDICATION_LIST *list, void (*action)(struct NFAPI_CRC_INDICATION_PDU_T *)) {
    if (!list || !action) {
        return;
    }

    // Iterate over the linked list and perform the action on each element
    struct NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        action(current);
        current = current->next;
    }
}

// Function to retrieve a specific element from the linked list by its index
struct NFAPI_CRC_INDICATION_PDU_T* getNfapiCrcIndicationListElementByIndex(struct NFAPI_CRC_INDICATION_LIST *list, size_t index) {
    if (!list || index >= list->size) {
        return NULL;
    }

    // Iterate over the linked list until we reach the desired index
    struct NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    for (size_t i = 0; i < index; i++) {
        current = current->next;
    }

    // Return the element at the desired index
    return current;
}
