// Define structure for traffic flow data
typedef struct TrafficFlow {
    char* source_ip;
    char* destination_ip;
    int protocol_type;
    time_t timestamp;
    unsigned long flow_id;
} TrafficFlow;

// Global variables to store traffic flow data
TrafficFlow* flows;
size_t num_flows = 0;
size_t max_flows = 10000; // default value

// Function to initialize traffic flow data structure
void init_traffic_flows(size_t num_flows) {
    if (num_flows > 0) {
        flows = calloc(num_flows, sizeof(TrafficFlow));
        max_flows = num_flows;
    } else {
        // Use default value for number of flows
        flows = calloc(max_flows, sizeof(TrafficFlow));
    }
}

// Function to add new traffic flow data
void add_traffic_flow(const char* source_ip, const char* destination_ip, int protocol_type) {
    // Check if there is enough space in the memory buffer for a new flow
    if (num_flows == max_flows) {
        // Increase the size of the memory buffer by 10%
        max_flows = (size_t)(max_flows * 1.1);
        flows = realloc(flows, max_flows * sizeof(TrafficFlow));
    }
    // Add new flow to the end of the list
    size_t index = num_flows++;
    TrafficFlow* flow = &flows[index];
    flow->source_ip = strdup(source_ip);
    flow->destination_ip = strdup(destination_ip);
    flow->protocol_type = protocol_type;
    flow->timestamp = time(NULL);
    flow->flow_id = index + 1;
}

// Function to update traffic flow data by IP pair
void update_traffic_flow(const char* source_ip, const char* destination_ip, int protocol_type) {
    // Find the flow with matching source and destination IPs
    for (size_t i = 0; i < num_flows; ++i) {
        TrafficFlow* flow = &flows[i];
        if (strcmp(source_ip, flow->source_ip) == 0 && strcmp(destination_ip, flow->destination_ip) == 0) {
            // Update the protocol type and timestamp for the found flow
            flow->protocol_type = protocol_type;
            flow->timestamp = time(NULL);
            break;
        }
    }
}

// Function to retrieve all traffic flows within a specified time window
void retrieve_traffic_flows(time_t start, time_t end) {
    // Iterate over the flows and print each one that falls within the specified time window
    for (size_t i = 0; i < num_flows; ++i) {
        TrafficFlow* flow = &flows[i];
        if (flow->timestamp >= start && flow->timestamp <= end) {
            printf("%lu: %s -> %s (%d, %ld)\n", flow->flow_id, flow->source_ip, flow->destination_ip, flow->protocol_type, flow->timestamp);
        }
    }
}

// Function to retrieve all traffic flows by flow identifier
void retrieve_traffic_flows(unsigned long flow_id) {
    // Iterate over the flows and print each one that matches the specified flow ID
    for (size_t i = 0; i < num_flows; ++i) {
        TrafficFlow* flow = &flows[i];
        if (flow->flow_id == flow_id) {
            printf("%lu: %s -> %s (%d, %ld)\n", flow->flow_id, flow->source_ip, flow->destination_ip, flow->protocol_type, flow->timestamp);
        }
    }
}
