#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <pthread.h>

// Structure to hold a CRC indication PDU
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// List of CRC indication PDUs
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* list;
    size_t size;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} CRC_INDICATION_LIST;

// Initialize the list with a given capacity
void init_list(CRC_INDICATION_LIST* list, size_t capacity) {
    list->size = 0;
    list->capacity = capacity;
    list->list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*capacity);
}

// Add a new CRC indication PDU to the list
bool add_crc_indication(CRC_INDICATION_LIST* list, uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRCFLAG) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) { // Check if the list is full
        pthread_mutex_unlock(&list->lock);
        return false;
    }
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = &list->list[list->size++];
    new_pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_pdu->RNTI = RNTI;
    new_pdu->CRCFLAG = CRCFLAG;
    pthread_mutex_unlock(&list->lock);
    return true;
}

// Remove a CRC indication PDU from the list
bool remove_crc_indication(CRC_INDICATION_LIST* list, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; i++) {
        if (list->list[i].RNTI == RNTI) { // Check if the PDU exists in the list
            memmove(list->list + i, list->list + i + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T)*(list->size - i));
            list->size--;
            pthread_mutex_unlock(&list->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return false;
}

// Get the number of CRC indication PDUs in the list
size_t get_crc_indication_count(CRC_INDICATION_LIST* list) {
    pthread_mutex_lock(&list->lock);
    size_t count = list->size;
    pthread_mutex_unlock(&list->lock);
    return count;
}

// Get the CRC indication PDU at a given index in the list
NFAPI_CRC_INDICATION_PDU_T* get_crc_indication(CRC_INDICATION_LIST* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
    if (index < list->size) {
        pdu = &list->list[index];
    }
    pthread_mutex_unlock(&list->lock);
    return pdu;
}

// Clear the list and free its memory
void clear_crc_indication_list(CRC_INDICATION_LIST* list) {
    pthread_mutex_lock(&list->lock);
    list->size = 0;
    free(list->list);
    list->list = NULL;
    pthread_mutex_unlock(&list->lock);
}
```
This code defines a structure `NFAPI_CRC_INDICATION_PDU_T` to hold the data of a CRC indication PDU, and a list of such structures `CRC_INDICATION_LIST`. The list is implemented as an array with a fixed capacity. The operations on the list are thread-safe using a mutex.

The `add_crc_indication` function adds a new CRC indication PDU to the list, and returns `false` if the list is full. The `remove_crc_indication` function removes a CRC indication PDU from the list by its RNTI, and returns `true` if the PDU exists in the list.

The `get_crc_indication_count` function returns the number of CRC indication PDUs in the list. The `get_crc_indication` function returns a pointer to the CRC indication PDU at a given index in the list, or `NULL` if the index is out of range.

The `clear_crc_indication_list` function clears the list and frees its memory.

Note that this code does not handle errors during allocation and deallocation, it's up to the caller to implement proper error handling and resource management."]

