    { .profile = 0, .enabled = false, .ipv4_addr = 0, .subnet_mask = 0, .gateway_addr = 0 },
    { .profile = 1, .enabled = false, .ipv4_addr = 0, .subnet_mask = 0, .gateway_addr = 0 },
    { .profile = 2, .enabled = false, .ipv4_addr = 0, .subnet_mask = 0, .gateway_addr = 0 }
};

// Current network interface configuration (default)
static netif_config_t* current_netif_config = &netif_configs[0];

// Function to update the network interface configuration based on a new profile
bool set_netif_profile(int new_profile) {
    if (new_profile < 0 || new_profile > 2) { // Out of bounds
        return false;
    }

    current_netif_config = &netif_configs[new_profile];

    // Update network interface parameters based on the new configuration
    update_network_interface(current_netif_config);

    return true;
}

// Function to validate and sanitize the input configuration parameters
bool validate_config_parameters(int profile, bool enabled, uint32_t ipv4_addr, uint32_t subnet_mask, uint32_t gateway_addr) {
    // Validate IP address parameters (IPv4 only for now)
    if (!inet_pton(AF_INET, inet_ntoa(*(struct in_addr*)&ipv4_addr), NULL)) {
        return false;
    }
    // Validate subnet mask parameter (valid range: 0-32)
    if (subnet_mask > 32 || subnet_mask < 0) {
        return false;
    }
    // Validate gateway address parameter (IPv4 only for now)
    if (!inet_pton(AF_INET, inet_ntoa(*(struct in_addr*)&gateway_addr), NULL)) {
        return false;
    }

    return true;
}

// Function to handle potential conflicts between new and existing configurations
bool resolve_conflicts(int profile, bool enabled, uint32_t ipv4_addr, uint32_t subnet_mask, uint32_t gateway_addr) {
    // Check for conflicting parameters (IP address, subnet mask, gateway address)
    if (!validate_config_parameters(profile, enabled, ipv4_addr, subnet_mask, gateway_addr)) {
        return false;
    }

    // Update network interface configuration based on the new parameters
    netif_configs[profile].enabled = enabled;
    netif_configs[profile].ipv4_addr = ipv4_addr;
    netif_configs[profile].subnet_mask = subnet_mask;
    netif_configs[profile].gateway_addr = gateway_addr;

    // Log configuration changes for debugging purposes
    printf("Updated network interface configuration: profile %d, enabled: %d, IP address: %u.%u.%u.%u, subnet mask: %u, gateway address: %u.%u.%u.%u\n",
            profile, enabled, ipv4_addr & 0xff, (ipv4_addr >> 8) & 0xff, (ipv4_addr >> 16) & 0xff, (ipv4_addr >> 24) & 0xff,
            subnet_mask, gateway_addr & 0xff, (gateway_addr >> 8) & 0xff, (gateway_addr >> 16) & 0xff, (gateway_addr >> 24) & 0xff);

    return true;
}

// Function to handle potential failures during configuration updates
bool handle_failure(int new_profile, bool enabled, uint32_t ipv4_addr, uint32_t subnet_mask, uint32_t gateway_addr) {
    // Check for temporary errors (e.g., resource allocation failure)
    if (errno == ENOMEM || errno == ENFILE) {
        return false;
    }

    // Check for permanent errors (e.g., invalid input parameters)
    if (!validate_config_parameters(new_profile, enabled, ipv4_addr, subnet_mask, gateway_addr)) {
        return false;
    }

    // Retry with a new profile (fallback strategy)
    return set_netif_profile(++new_profile);
}

// Function to update the network interface based on the current configuration
void update_network_interface(netif_config_t* config) {
    struct ifreq ifr;
    int sock = socket(AF_INET, SOCK_DGRAM, 0);

    // Get the interface index from the name
    strncpy(ifr.ifr_name, "eth0", IFNAMSIZ-1);
    ioctl(sock, SIOCGIFINDEX, &ifr);

    // Set the IP address for the interface
    struct sockaddr_in* addr = (struct sockaddr_in*)&ifr.ifr_addr;
    addr->sin_family = AF_INET;
    addr->sin_port = 0;
    addr->sin_addr.s_addr = htonl(config->ipv4_addr);

    // Set the subnet mask for the interface
    struct sockaddr_in* netmask = (struct sockaddr_in*)&ifr.ifr_netmask;
    netmask->sin_family = AF_INET;
    netmask->sin_port = 0;
    netmask->sin_addr.s_addr = htonl(config->subnet_mask);

    // Set the gateway address for the interface
    struct sockaddr_in* gw = (struct sockaddr_in*)&ifr.ifr_gateway;
    gw->sin_family = AF_INET;
    gw->sin_port = 0;
    gw->sin_addr.s_addr = htonl(config->gateway_addr);

    // Update the interface with the new configuration
    ioctl(sock, SIOCSIFADDR, &ifr);

    close(sock);
}

int main() {
    int profile = 0;
    bool enabled = true;
    uint32_t ipv4_addr = 192.168.1.1;
    uint32_t subnet_mask = 24;
    uint32_t gateway_addr = 192.168.1.254;

    // Set the network interface configuration using the input parameters
    if (!set_netif_config(profile, enabled, ipv4_addr, subnet_mask, gateway_addr)) {
        printf("Failed to set network interface configuration\n");
        return 1;
    }

    // Update the network interface based on the current configuration
    update_network_interface();

    return 0;
}
