        pthread_mutex_lock(&mutex);

        // Check if the shared list is full
        if (shared_list == NULL || total_count >= MAX_CAPACITY) {
            // Remove the least recently used element
            remove_lru();
        }

        // Add the incoming PDU to the shared list
        add_element(pdu);

        // Release the mutex
        pthread_mutex_unlock(&mutex);
