size_t numElements = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the list with M elements, where M is specified by the caller
void initTAIList(size_t M) {
  taiList = malloc(sizeof(TAI_PDU) * M);
  numElements = 0;
}

// Add a new TAI-PDU structure to the list, ensuring efficient memory usage and preventing leaks
void addTAIPDU(uint32_t UE_ID, uint16_t ServingCellID, TimeAdvancedIndication timeAdvancedIndication) {
  pthread_mutex_lock(&lock);
  if (numElements < M) {
    // Add new structure to the list
    taiList[numElements].UE_ID = UE_ID;
    taiList[numElements].ServingCellID = ServingCellID;
    taiList[numElements].timeAdvancedIndication = timeAdvancedIndication;
    numElements++;
  } else {
    // List is full, remove the oldest structure and add new one
    uint32_t oldestUE_ID = taiList[0].UE_ID;
    taiList[0] = taiList[numElements - 1];
    numElements--;
    free(taiList[numElements]);
    // Add new structure to the list
    taiList[numElements].UE_ID = UE_ID;
    taiList[numElements].ServingCellID = ServingCellID;
    taiList[numElements].timeAdvancedIndication = timeAdvancedIndication;
  }
  pthread_mutex_unlock(&lock);
}

// Remove a TAI-PDU structure from the list based on UE_ID, ensuring efficient memory usage and preventing leaks
void removeTAIPDU(uint32_t UE_ID) {
  pthread_mutex_lock(&lock);
  for (size_t i = 0; i < numElements; i++) {
    if (taiList[i].UE_ID == UE_ID) {
      // Remove the structure from the list
      taiList[i] = taiList[numElements - 1];
      numElements--;
      free(taiList[numElements]);
      break;
    }
  }
  pthread_mutex_unlock(&lock);
}

// Iterate over the list and print all TAI-PDU structures, ensuring thread safety when accessing and modifying the list concurrently
void iterateTAIList(void) {
  pthread_mutex_lock(&lock);
  for (size_t i = 0; i < numElements; i++) {
