#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>

// Define a structure to hold the TCP connection information
typedef struct {
    int session_id;
    char client_ip[16];
    char server_ip[16];
    time_t start_time;
    bool active;
} tcp_connection_record;

// Define a dynamic array to hold the list of TCP connection records
typedef struct {
    int count; // Number of elements in the array
    int capacity; // Total capacity of the array
    tcp_connection_record* elements;
} tcp_connection_list;

// Initialize a new TCP connection list with the specified capacity
tcp_connection_list* init_tcp_connection_list(int capacity) {
    tcp_connection_list* list = (tcp_connection_list*)malloc(sizeof(tcp_connection_list));
    list->count = 0;
    list->capacity = capacity;
    list->elements = (tcp_connection_record*)calloc(capacity, sizeof(tcp_connection_record));
    return list;
}

// Add a new TCP connection record to the list
void add_tcp_connection_record(tcp_connection_list* list, int session_id, char* client_ip, char* server_ip) {
    if (list->count == list->capacity) { // If the array is full, double its capacity
        tcp_connection_record* new_elements = (tcp_connection_record*)realloc(list->elements, 2 * list->capacity * sizeof(tcp_connection_record));
        if (new_elements == NULL) {
            printf("Error: Failed to allocate memory for TCP connection records\n");
            exit(1);
        }
        list->elements = new_elements;
        list->capacity *= 2;
    }
    tcp_connection_record* record = &list->elements[list->count++];
    record->session_id = session_id;
    strcpy(record->client_ip, client_ip);
    strcpy(record->server_ip, server_ip);
    record->start_time = time(NULL);
    record->active = true;
}

// Remove a TCP connection record from the list based on its session ID
bool remove_tcp_connection_record(tcp_connection_list* list, int session_id) {
    for (int i = 0; i < list->count; i++) {
        if (list->elements[i].session_id == session_id) {
            // Shift all elements following the removed element to preserve order
            for (int j = i; j < list->count - 1; j++) {
                list->elements[j] = list->elements[j + 1];
            }
            list->count--;
            return true;
        }
    }
    return false;
}

// Query a TCP connection record from the list based on its session ID
tcp_connection_record* query_tcp_connection_record(tcp_connection_list* list, int session_id) {
    for (int i = 0; i < list->count; i++) {
        if (list->elements[i].session_id == session_id) {
            return &list->elements[i];
        }
    }
    return NULL;
}

// Free the memory allocated for the TCP connection list
void free_tcp_connection_list(tcp_connection_list* list) {
    free(list->elements);
    free(list);
}

// Main function to demonstrate usage of the library
int main() {
    // Initialize a new TCP connection list with capacity for 10 connections
    tcp_connection_list* list = init_tcp_connection_list(10);

    // Add some TCP connection records
    add_tcp_connection_record(list, 1, "192.168.1.1", "192.168.1.2");
    add_tcp_connection_record(list, 2, "192.168.1.3", "192.168.1.4");
    add_tcp_connection_record(list, 3, "192.168.1.5", "192.168.1.6");

    // Remove a TCP connection record based on its session ID
    remove_tcp_connection_record(list, 1);

    // Query a TCP connection record based on its session ID
    tcp_connection_record* record = query_tcp_connection_record(list, 2);

    // Print the result of the query
    if (record == NULL) {
        printf("No such TCP connection\n");
    } else {
        printf("Client IP: %s\n", record->client_ip);
        printf("Server IP: %s\n", record->server_ip);
        printf("Start time: %ld\n", record->start_time);
        printf("Active: %d\n", record->active);
    }

    // Free the memory allocated for the TCP connection list
    free_tcp_connection_list(list);

    return 0;
}']

