    for (int i = 0; i < state->radioBearerCount; ++i) {
        RadioBearerState* bearer = &state->radioBearers[i];
        if (bearer->pduSessionId == pduSessionId) {
            bearer->ngApCause = ngApCause;
            strcpy(bearer->nasState, nasState);
            return;
        }
