    // Add new bearer if not present
    if (state->radioBearerCount < MAX_RADIO_BEARER_COUNT) {
        RadioBearerState* bearer = &state->radioBearers[state->radioBearerCount++];
        bearer->pduSessionId = pduSessionId;
        bearer->ngApCause = ngApCause;
        strcpy(bearer->nasState, nasState);
    }
}

void traverseSessionStates(void (*callback)(UESessionState*)) {
    // Traverse all session states and call callback function for each one
    for (int i = 0; i < numSessionStates; ++i) {
