            ERR_print_errors_fp(stderr);
            return -1;
        }

        // Encrypt the received data using the selected cipher and key
        encrypted_data_len = EVP_EncryptUpdate(ctx, encrypted_data, inl);
        if (encrypted_data_len <= 0) {
            ERR_load_crypto_strings();
            ERR_print_errors_fp(stderr);
            return -1;
        }

        // Add the cipher block chaining (CBC) tag to the encrypted data
        encrypted_data[encrypted_data_len] = CRC_INDICATION_REL8_TAG;

        // Decrypt the received data using the selected cipher and key
        decrypted_data_len = EVP_DecryptUpdate(ctx, decrypted_data, inl);
        if (decrypted_data_len <= 0) {
            ERR_load_crypto_strings();
            ERR_print_errors_fp(stderr);
            return -1;
        }

        // Check the decrypted data for errors and integrity using the cyclic redundancy check (CRC) mechanism
