typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    RX_UE_INFORMATION_TAG rxInfoTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndRel8Tag;
} UE_PDU_POOL_ENTRY_T;

typedef struct {
    UE_PDU_POOL_ENTRY_T *entries;
    size_t numEntries;
    pthread_mutex_t mutex;
} UE_PDU_POOL_T;

void manageUePduPool(UE_PDU_POOL_T *pool, RX_UE_INFORMATION_TAG rxInfoTag, RNTI rnti) {
    // Acquire the mutex to ensure thread-safe access to the pool
    pthread_mutex_lock(&pool->mutex);

    // Find an empty entry in the pool
    UE_PDU_POOL_ENTRY_T *entry = NULL;
    for (size_t i = 0; i < pool->numEntries; ++i) {
        if (!pool->entries[i].pdu) {
            entry = &pool->entries[i];
            break;
        }
    }

    // If no empty entry is found, resize the pool
    if (!entry) {
        UE_PDU_POOL_ENTRY_T *newEntries = realloc(pool->entries, (pool->numEntries + 1) * sizeof(*pool->entries));
        if (!newEntries) {
            pthread_mutex_unlock(&pool->mutex);
            return; // Handle out of memory error
        }
        entry = &newEntries[pool->numEntries];
        pool->entries = newEntries;
        pool->numEntries++;
    }

    // Initialize the new PDU and update the RX_UE_INFORMATION_TAG and RNTI values
    memset(entry->pdu, 0, sizeof(*entry->pdu));
    entry->rxInfoTag = rxInfoTag;
    entry->rnti = rnti;

    // Set the CRCFLAG based on the received signal strength indicators (RSSI)
    if (entry->rxInfoTag.rx_ue_information.rssi < 0) {
        entry->crcIndRel8Tag.crcf = true;
    } else {
        entry->crcIndRel8Tag.crco = true;
    }

    // Release the mutex and return the new PDU
    pthread_mutex_unlock(&pool->mutex);
    return entry->pdu;
}
```
