        nfs[i]->timestamp = 0;
        nfs[i]->packet_count = 0;
        nfs[i]->byte_count = 0;
        nfs[i]->flow_id = NULL;
        nfs[i]->metadata = NULL;
    }

    // Create a background thread for periodic cleanup of stale flows
    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, cleanup_flows, NULL)) {
        printf("Failed to create cleanup thread\n");
        return;
    }

    // Gracefully shutdown the function on request
    while (1) {
        char input[10];
        scanf("%s", input);
        if (strcmp(input, "shutdown") == 0) {
            break;
        }

        // Validate the flow identifier using an external network monitoring service
        int retry_count = 0;
        while (retry_count < 3) {
            if (validate_flow(nfs[input]) == 1) {
                break;
            } else {
                printf("Transient error validating flow, retrying...\n");
                retry_count++;
            }
        }

        // If validation fails or memory allocation fails, return a default uninitialized state for the flow
        if (retry_count == 3 || nfs[input] == NULL) {
            printf("Failed to validate flow, using default uninitialized state\n");
            continue;
        }

        // Increment the packet and byte counts for the flow
        nfs[input]->packet_count++;
        nfs[input]->byte_count += strlen(nfs[input]->metadata);
    }

    // Cleanup the function by freeing memory and terminating the cleanup thread
    for (int i = 0; i < num_flows; i++) {
        if (nfs[i] != NULL) {
            free(nfs[i]->metadata);
            free(nfs[i]);
        }
    }
    free(nfs);
    pthread_join(cleanup_thread, NULL);
}

void cleanup_flows() {
    // Remove stale flows that have not been updated within the last hour
    while (1) {
        sleep(3600);  // Sleep for one hour
