// Define a structure to hold the CRC indication data
typedef struct {
  uint8_t rx_ue_information_tag;
  uint16_t rnti;
  uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list node to hold the CRC indication data
typedef struct {
  NFAPI_CRC_INDICATION_PDU_T data;
  struct node* next;
} NODE_T;

// Function to manage the dynamic list of CRC indication PDUs
void manage_crc_indications(NODE_T** head, int N, int M) {
  // Check if the input parameters are valid
  assert(N > 0 && M > 0);

  // Initialize a temporary node to store the new data
  NODE_T* tmp = NULL;

  // Iterate through the list until we reach the maximum capacity
  while (tmp != NULL) {
    // Check if the current node has valid data
    if (tmp->data.rx_ue_information_tag == 0 || tmp->data.rnti == 0 || tmp->data.crc_indication_rel8_tag == 0) {
      // Release all allocated resources and return an error status
      printf("Invalid CRC indication data found!\n");
      free(tmp);
      return -1;
    }

    // Move to the next node in the list
    tmp = tmp->next;
  }

  // If we reach this point, all elements in the list are valid
  printf("All CRC indication data is valid!\n");

  // Allocate memory for a new node
  tmp = (NODE_T*)malloc(sizeof(NODE_T));

  // Check if allocation failed
  if (tmp == NULL) {
    // Release all allocated resources and return an error status
    printf("Memory allocation failed!\n");
    free(tmp);
    return -1;
  }

  // Initialize the new node with random data
  tmp->data.rx_ue_information_tag = rand();
  tmp->data.rnti = rand();
  tmp->data.crc_indication_rel8_tag = rand();

  // Add the new node to the end of the list
  if (*head == NULL) {
    *head = tmp;
  } else {
    NODE_T* cur = *head;
    while (cur->next != NULL) {
      cur = cur->next;
    }
    cur->next = tmp;
  }

  // Check if the list size exceeds the maximum capacity
  int list_size = 0;
  NODE_T* cur = *head;
  while (cur != NULL) {
    list_size++;
    cur = cur->next;
  }

  if (list_size > N) {
    // Remove the oldest element from the list
    cur = *head;
    *head = (*head)->next;
    free(cur);
  }

  return 0;
}
