void initialize_conn_list(conn_list_t* list) {
    list->num_connections = 0;
}

bool add_connection(conn_list_t* list, struct in_addr ip, uint16_t port, bool state) {
    if (list->num_connections >= MAX_CONNECTIONS) {
        return false;
    }
    list->connections[list->num_connections].ip = ip;
    list->connections[list->num_connections].port = port;
    list->connections[list->num_connections].state = state;
    list->num_connections++;
    return true;
}

bool remove_connection(conn_list_t* list, int index) {
    if (index < 0 || index >= list->num_connections) {
        return false;
    }
    for (int i = index; i < list->num_connections - 1; i++) {
        list->connections[i] = list->connections[i + 1];
    }
    list->num_connections--;
    return true;
}

void iterate_connections(conn_list_t* list, void (*func)(struct conn_info*)) {
    for (int i = 0; i < list->num_connections; i++) {
        func(&list->connections[i]);
    }
}

void log_allocation(conn_list_t* list, struct in_addr ip, uint16_t port) {
    FILE *fp = fopen(LOG_FILENAME, "a");
    if (fp == NULL) {
        perror("fopen");
        return;
    }
    fprintf(fp, "%s:%d\n", inet_ntoa(ip), port);
    fclose(fp);
}

void log_deallocation(conn_list_t* list, int index) {
