        return false;
    }
    if (info->port < 1 || info->port > 65535) {
        return false;
    }
    if (inet_addr(inet_ntoa(info->ip)) == INADDR_NONE) {
        return false;
    }
    return true;
}

void correct_conn_info(struct conn_info* info) {
    info->state = false;
    info->port = 0;
    memset(&info->ip, 0, sizeof(info->ip));
}

bool allocate_connection(conn_list_t* list, struct in_addr ip, uint16_t port) {
    // Check if there is a free slot for the new connection
    if (list->num_connections >= MAX_CONNECTIONS) {
        return false;
    }

    // Validate the incoming connection information
    struct conn_info* info = &list->connections[list->num_connections];
    if (!validate_conn_info(info)) {
        correct_conn_info(info);
        log_error(list, ip, port);
        return false;
    }

    // Add the new connection to the list
    add_connection(list, ip, port, true);
    log_allocation(list, ip, port);
    return true;
}

bool deallocate_connection(conn_list_t* list, int index) {
    // Check if the index is valid
    if (index < 0 || index >= list->num_connections) {
        log_deallocation(list, index);
        return false;
    }

    // Remove the connection from the list and deallocate it
    remove_connection(list, index);
    log_deallocation(list, index);
    return true;
}

