// Define the structure for the UE context
typedef struct {
    int UE_ID;
    NFAPI_RRC_UE_CONTEXT *context;
    unsigned long lastUpdateTime;
} UE_CONTEXT;

// Define the array of UE contexts
static UE_CONTEXT *ueContexts = NULL;

// Define the mutex for thread safety
static pthread_mutex_t ueContextMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new UE context
void addUEContext(int UE_ID, NFAPI_RRC_UE_CONTEXT *context) {
    pthread_mutex_lock(&ueContextMutex);
    // Check if the UE ID is already in use
    if (getUEContext(UE_ID) != NULL) {
        printf("Error: UE ID %d already in use\n", UE_ID);
        pthread_mutex_unlock(&ueContextMutex);
        return;
    }
    // Create a new UE context and add it to the array
    UE_CONTEXT *newContext = (UE_CONTEXT *)malloc(sizeof(UE_CONTEXT));
    newContext->UE_ID = UE_ID;
    newContext->context = context;
    newContext->lastUpdateTime = getCurrentTime();
    ueContexts = realloc(ueContexts, sizeof(UE_CONTEXT) * (1 + countUeContexts()));
    ueContexts[countUeContexts()] = newContext;
    pthread_mutex_unlock(&ueContextMutex);
}

// Function to update an existing UE context
void updateUEContext(int UE_ID, NFAPI_RRC_UE_CONTEXT *context) {
    pthread_mutex_lock(&ueContextMutex);
    // Check if the UE ID is in use
    UE_CONTEXT *context = getUEContext(UE_ID);
    if (context == NULL) {
        printf("Error: UE ID %d not found\n", UE_ID);
        pthread_mutex_unlock(&ueContextMutex);
        return;
    }
    // Update the context and set the last update time
    context->context = context;
    context->lastUpdateTime = getCurrentTime();
    pthread_mutex_unlock(&ueContextMutex);
}

// Function to remove a UE context based on its ID
void removeUEContext(int UE_ID) {
    pthread_mutex_lock(&ueContextMutex);
    // Check if the UE ID is in use
    UE_CONTEXT *context = getUEContext(UE_ID);
    if (context == NULL) {
        printf("Error: UE ID %d not found\n", UE_ID);
        pthread_mutex_unlock(&ueContextMutex);
        return;
    }
    // Remove the context from the array and free its memory
    int index = 0;
    while (index < countUeContexts() && ueContexts[index]->UE_ID != UE_ID) {
        index++;
    }
    if (index == countUeContexts()) {
        printf("Error: UE ID %d not found\n", UE_ID);
        pthread_mutex_unlock(&ueContextMutex);
        return;
    }
    free(context->context);
    memmove(ueContexts + index, ueContexts + index + 1, sizeof(UE_CONTEXT) * (countUeContexts() - index - 1));
    pthread_mutex_unlock(&ueContextMutex);
}

// Function to retrieve the number of UE contexts in the array
int countUeContexts() {
    return ueContexts == NULL ? 0 : (int)(sizeof(UE_CONTEXT) * (ueContexts - 1));
}

// Function to get a UE context based on its ID
UE_CONTEXT *getUEContext(int UE_ID) {
    pthread_mutex_lock(&ueContextMutex);
    int index = 0;
    while (index < countUeContexts() && ueContexts[index]->UE_ID != UE_ID) {
        index++;
    }
    if (index == countUeContexts()) {
        pthread_mutex_unlock(&ueContextMutex);
        return NULL;
    }
    pthread_mutex_unlock(&ueContextMutex);
    return ueContexts[index];
}

// Function to get the current time in milliseconds
unsigned long getCurrentTime() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (unsigned long)ts.tv_sec * 1000 + (unsigned long)ts.tv_nsec / 1000000;
}
