    // Find the index of the connection in the hash table
    int index = -1;
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (connections[i].ip == ip && connections[i].port == port) {
            index = i;
            break;
        }
    }

    // If the connection exists, update its state
    if (index != -1) {
        connections[index].state = state;
    } else {
        printf("Connection %d.%d does not exist\n", ip, port);
    }
}

// Hash function to map IP addresses and port numbers to hash table indices
int hash(uint32_t ip, uint16_t port) {
    return (ip + port) % HASH_TABLE_SIZE;
}
```
