} LTE_DL_FRAMEapoindt_t;

// Structure to store the dynamic array of frames
struct frame_array {
    // Array of LTE_DL_FRAMEapoindt structures
    LTE_DL_FRAMEapoindt_t **frames;
    // Size of the array
    size_t size;
    // Number of valid frames in the array
    size_t num_frames;
};

// Lock for thread-safe access to the frame array
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the frame array with a given capacity
void init_frame_array(struct frame_array *array, size_t capacity) {
    array->frames = (LTE_DL_FRAMEapoindt_t **)malloc(sizeof(LTE_DL_FRAMEapoindt_t *) * capacity);
    array->size = capacity;
    array->num_frames = 0;
}

// Add a new frame to the array, allocating memory for it if necessary
void add_frame(struct frame_array *array, LTE_DL_FRAMEapoindt_t *frame) {
    pthread_mutex_lock(&lock);
    // Check if we need to reallocate the array
    if (array->num_frames == array->size) {
        size_t new_size = array->size * 2;
        LTE_DL_FRAMEapoindt_t **new_frames = (LTE_DL_FRAMEapoindt_t **)realloc(array->frames, sizeof(LTE_DL_FRAMEapoindt_t *) * new_size);
        if (!new_frames) {
            pthread_mutex_unlock(&lock);
            return;
        }
        array->frames = new_frames;
        array->size = new_size;
    }
    // Allocate memory for the new frame's DL_FRAMEINFO structure if necessary
    size_t srs_samples = 100;
    if (frame->dl_frameinfo->srs_data == NULL) {
        frame->dl_frameinfo->srs_data = (short *)malloc(sizeof(short) * srs_samples);
        if (!frame->dl_frameinfo->srs_data) {
            pthread_mutex_unlock(&lock);
            return;
        }
    }
    // Add the new frame to the array
    array->frames[array->num_frames++] = frame;
    pthread_mutex_unlock(&lock);
}

// Update an existing frame in the array, freeing its previous memory if necessary
void update_frame(struct frame_array *array, size_t index, LTE_DL_FRAMEapoindt_t *frame) {
    pthread_mutex_lock(&lock);
    // Free the previous DL_FRAMEINFO structure's memory if necessary
    size_t srs_samples = 100;
    LTE_DL_FRAMEapoindt_t *prev_frame = array->frames[index];
    if (prev_frame->dl_frameinfo->srs_data) {
        free(prev_frame->dl_frameinfo->srs_data);
        prev_frame->dl_frameinfo->srs_data = NULL;
    }
    // Copy the new frame's data to the array slot
    memcpy(&array->frames[index], frame, sizeof(LTE_DL_FRAMEapoindt_t));
    pthread_mutex_unlock(&lock);
}

// Safely clear the frame array when done with it
void clear_frame_array(struct frame_array *array) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < array->num_frames; i++) {
        LTE_DL_FRAMEapoindt_t *frame = array->frames[i];
        if (frame) {
            // Free the frame's DL_FRAMEINFO structure's memory if necessary
            size_t srs_samples = 100;
            if (frame->dl_frameinfo->srs_data) {
                free(frame->dl_frameinfo->srs_data);
                frame->dl_frameinfo->srs_data = NULL;
            }
            // Free the frame itself
            free(frame);
        }
    }
    array->num_frames = 0;
    pthread_mutex_unlock(&lock);
}
