typedef struct {
    char imsi[16]; // 15-digit IMSI
    char guti[20]; // 19-digit GUTI
    uint32_t message_flags; // flags for message priority level
} MME_MESSAGE_T;

// Callback function to handle logging errors
void log_error(const char* msg) {
    printf("Error: %s\n", msg);
}

// Initialize the message pool with N structures
int initialize_MME_MESSAGE_POOL(size_t N, void (*log_error_callback)(const char*)) {
    // Validate input parameters
    if (N == 0) {
        return -1;
    }

    // Allocate memory for the message pool
    MME_MESSAGE_T* messages = malloc(sizeof(MME_MESSAGE_T) * N);
    if (messages == NULL) {
        log_error_callback("Failed to allocate memory for message pool");
        return -1;
    }

    // Initialize each structure in the pool
    size_t i = 0;
    while (i < N) {
        // Generate a random priority level within the valid range
        uint32_t priority_level = rand() % MAX_PRIORITY_LEVEL + MIN_PRIORITY_LEVEL;

        // Validate the priority level before setting it
        if (priority_level < MIN_PRIORITY_LEVEL || priority_level > MAX_PRIORITY_LEVEL) {
            log_error_callback("Priority level out of range");
            continue;
        }

        // Initialize the structure with unique IMSI and GUTI values
        strcpy(messages[i].imsi, generate_unique_imsi());
        strcpy(messages[i].guti, generate_unique_guti());
        messages[i].message_flags = priority_level;

        i++;
    }

    // Return the number of initialized structures
    return i;
}

// Generate a unique IMSI value
char* generate_unique_imsi() {
    char imsi[16];
    sprintf(imsi, "%015lu", rand());
    return strdup(imsi);
}

// Generate a unique GUTI value
char* generate_unique_guti() {
    char guti[20];
    sprintf(guti, "%019lu", rand());
    return strdup(guti);
}
