// Structures to represent LTE DL frames and frame information
typedef struct {
    // DL_FRAMEapo_TAG and DL_FRAMEINFOapo_TAG fields...
} LTE_DL_FRAME;

// Dynamic array of LTE_DL_FRAME structures to manage frames
typedef struct {
    LTE_DL_FRAME** frames; // Pointer to an array of pointers to LTE_DL_FRAME structures
    size_t num_frames; // Number of frames in the array
    size_t capacity; // Capacity of the array (number of slots available)
} FrameArray;

// Initialize a new frame array with the given initial capacity
FrameArray* init_frame_array(size_t capacity) {
    FrameArray* array = malloc(sizeof(FrameArray));
    assert(array != NULL);
    array->frames = calloc(capacity, sizeof(LTE_DL_FRAME*));
    assert(array->frames != NULL);
    array->num_frames = 0;
    array->capacity = capacity;
    return array;
}

// Add a new frame to the end of the array, allocating memory for it if necessary
void add_frame(FrameArray* array, LTE_DL_FRAME* frame) {
    // If the array is full, allocate more space and copy existing frames
    if (array->num_frames == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_DL_FRAME** new_frames = realloc(array->frames, sizeof(LTE_DL_FRAME*) * new_capacity);
        assert(new_frames != NULL);
        for (size_t i = 0; i < array->num_frames; i++) {
            new_frames[i] = malloc(sizeof(LTE_DL_FRAME));
            memcpy(new_frames[i], array->frames[i], sizeof(LTE_DL_FRAME));
        }
        free(array->frames);
        array->frames = new_frames;
        array->capacity = new_capacity;
    }
    // Add the new frame to the end of the array
    array->frames[array->num_frames++] = malloc(sizeof(LTE_DL_FRAME));
    memcpy(array->frames[array->num_frames - 1], frame, sizeof(LTE_DL_FRAME));
}

// Get the number of frames in the array
size_t get_num_frames(FrameArray* array) {
    return array->num_frames;
}

// Get a pointer to the frame at the given index, or NULL if the index is out of range
LTE_DL_FRAME* get_frame(FrameArray* array, size_t index) {
    if (index < array->num_frames) {
        return array->frames[index];
    } else {
        return NULL;
    }
}

// Free the memory allocated for the frame array
void free_frame_array(FrameArray* array) {
    for (size_t i = 0; i < array->num_frames; i++) {
        free(array->frames[i]);
    }
    free(array->frames);
    free(array);
}
