}

// Function to configure the L1 TDD parameters based on an external data source
bool configure_nfapi_l1_tdd_params(NFAPI_L1_TDD_PARAMS* params, int num_params, void* config_data) {
    // Validate the configuration data is not NULL
    if (!config_data) {
        return false;
    }

    // Iterate over each parameter structure and apply the configuration
    for (int i = 0; i < num_params; i++) {
        NFAPI_L1_TDD_PARAMS* param = &(params[i]);
        void* config_data_ptr = (char*)config_data + i * sizeof(NFAPI_L1_TDD_PARAMS);

        // Read the mode and slot offset values from the configuration data
        memcpy(&(param->mode), config_data_ptr, sizeof(int));
        memcpy(&(param->slot_offset), (char*)config_data_ptr + sizeof(int), sizeof(int));

        // Validate the slot offset against the specified mode
        if (!validate_slot_offset(param->mode, param->slot_offset)) {
            return false;
        }
    }

    return true;
}

// Function to validate a slot offset value based on an L1 TDD mode value
bool validate_slot_offset(int mode, int slot_offset) {
    // Check if the slot offset is within the valid range for the specified mode
    switch (mode) {
        case 0:
            return slot_offset >= 0 && slot_offset <= 12;
        case 1:
            return slot_offset >= 0 && slot_offset <= 7;
        default:
            return false;
    }
}

// Function to free the memory allocated for the dynamic array of NFAPI_L1_TDD_PARAMS structures
void free_nfapi_l1_tdd_params(NFAPI_L1_TDD_PARAMS* params, int num_params) {
    // Validate the parameters are not NULL
    if (!params || !num_params) {
        return;
    }

    // Free the memory allocated for each parameter structure
    for (int i = 0; i < num_params; i++) {
        free(params[i]);
    }

    // Free the memory allocated for the array of parameter structures
    free(params);
}
