// Define a hash table for storing the unique RNTIs in the list
static void* RNTI_hash[10000];

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void create_list(NFAPI_CRC_INDICATION_PDU_T** list, int n) {
    // Initialize the hash table for storing unique RNTIs
    memset(RNTI_hash, 0, sizeof(RNTI_hash));

    *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) {
        perror("malloc");
        exit(1);
    }

    for (int i = 0; i < n; i++) {
        // Generate a random RX_UE_INFORMATION_TAG and RNTI value
        uint32_t RX_UE_INFORMATION_TAG = rand() % 10000;
        uint32_t RNTI = rand() % 10000;

        // Check if the RNTI is already present in the list, and generate a new one if necessary
        while (RNTI_hash[RNTI]) {
            RNTI = rand() % 10000;
        }
        RNTI_hash[RNTI] = (void*) 1;

        // Set the CRCFLAG to a random value
        bool CRCFLAG = (rand() % 2) ? true : false;

        (*list)[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        (*list)[i].RNTI = RNTI;
        (*list)[i].CRC_INDICATION_REL8_TAG = rand() % 10000;
        (*list)[i].CRCFLAG = CRCFLAG;
    }
}

// Function to insert a new element in the list, checking for duplicates and thread safety
void insert(NFAPI_CRC_INDICATION_PDU_T* elem) {
    // Lock the hash table to prevent concurrent access
    pthread_mutex_lock(&RNTI_hash_mtx);

    if (RNTI_hash[elem->RNTI]) {
        // The RNTI is already present in the list, do not insert
        pthread_mutex_unlock(&RNTI_hash_mtx);
        return;
    }

    // Insert the new element at the end of the list
    NFAPI_CRC_INDICATION_PDU_T* new_elem = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elem) {
        perror("malloc");
        exit(1);
    }
    memcpy(new_elem, elem, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Insert the new element in the hash table to mark it as present
    RNTI_hash[elem->RNTI] = (void*) 1;

    pthread_mutex_unlock(&RNTI_hash_mtx);
}

// Function to retrieve an element from the list by its RNTI value, thread safely
NFAPI_CRC_INDICATION_PDU_T* get(uint32_t RNTI) {
    // Lock the hash table to prevent concurrent access
    pthread_mutex_lock(&RNTI_hash_mtx);

    if (!RNTI_hash[RNTI]) {
        // The RNTI is not present in the list, return NULL
        pthread_mutex_unlock(&RNTI_hash_mtx);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* elem = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!elem) {
        perror("malloc");
        exit(1);
    }
    memcpy(elem, RNTI_hash[RNTI], sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&RNTI_hash_mtx);
    return elem;
}

// Function to clear the entire list in constant time relative to its size
void clear() {
    // Lock the hash table to prevent concurrent access
    pthread_mutex_lock(&RNTI_hash_mtx);

    for (int i = 0; i < 10000; i++) {
        if (RNTI_hash[i]) {
            free(RNTI_hash[i]);
            RNTI_hash[i] = NULL;
        }
    }

    pthread_mutex_unlock(&RNTI_hash_mtx);
}

