// Define a struct to represent each network configuration entity
typedef struct NetworkConfig {
    char *nid; // Unique identifier for the network interface
    char **ip_addrs; // List of associated IP addresses
    time_t last_updated; // Timestamp marking the last configuration update
} NetworkConfig;

// Define a hashtable to store the network configurations
#define HASHTABLE_SIZE 1024
static NetworkConfig *configs[HASHTABLE_SIZE];

// Define a mutex to protect the hashtable during concurrent access
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

// Add a new network configuration entity
int add_network_config(char *nid, char **ip_addrs) {
    int i;
    NetworkConfig *config;

    // Check if the NID is already in use
    for (i = 0; i < HASHTABLE_SIZE; i++) {
        config = configs[i];
        if (config != NULL && strcmp(nid, config->nid) == 0) {
            return -1; // NID already in use
        }
    }

    // Allocate memory for the new configuration entity
    config = malloc(sizeof(NetworkConfig));
    if (config == NULL) {
        return -2; // Memory allocation failed
    }

    // Initialize the configuration entity
    config->nid = nid;
    config->ip_addrs = ip_addrs;
    config->last_updated = time(NULL);

    // Add the new configuration to the hashtable
    pthread_mutex_lock(&config_lock);
    for (i = 0; i < HASHTABLE_SIZE; i++) {
        if (configs[i] == NULL) {
            configs[i] = config;
            break;
        }
    }
    pthread_mutex_unlock(&config_lock);

    return 0; // Success
}

// Update a network configuration entity
int update_network_config(char *nid, char **ip_addrs) {
    int i;
    NetworkConfig *config;

    // Check if the NID is in use
    for (i = 0; i < HASHTABLE_SIZE; i++) {
        config = configs[i];
        if (config != NULL && strcmp(nid, config->nid) == 0) {
            break; // Found the NID in use
        }
    }

    // If the NID is not found, return an error
    if (i == HASHTABLE_SIZE) {
        return -1; // NID not found
    }

    // Update the IP addresses and timestamp for the configuration entity
    config->ip_addrs = ip_addrs;
    config->last_updated = time(NULL);

    return 0; // Success
}

// Retrieve a network configuration entity by NID
NetworkConfig *get_network_config(char *nid) {
    int i;
    NetworkConfig *config;

    // Search for the NID in the hashtable
    pthread_mutex_lock(&config_lock);
    for (i = 0; i < HASHTABLE_SIZE; i++) {
        config = configs[i];
        if (config != NULL && strcmp(nid, config->nid) == 0) {
            break; // Found the NID in use
        }
    }
    pthread_mutex_unlock(&config_lock);

    // If the NID is not found, return an error
    if (i == HASHTABLE_SIZE) {
        return NULL; // NID not found
    }

    return config; // Success
}

// Delete a network configuration entity by NID
int delete_network_config(char *nid) {
    int i;
    NetworkConfig *config;

    // Search for the NID in the hashtable
    pthread_mutex_lock(&config_lock);
    for (i = 0; i < HASHTABLE_SIZE; i++) {
        config = configs[i];
        if (config != NULL && strcmp(nid, config->nid) == 0) {
            break; // Found the NID in use
        }
    }
    pthread_mutex_unlock(&config_lock);

    // If the NID is not found, return an error
    if (i == HASHTABLE_SIZE) {
        return -1; // NID not found
    }

    // Free the memory associated with the configuration entity
    free(config->nid);
    free(config->ip_addrs);
    configs[i] = NULL;

    return 0; // Success
}

// Auto-expire configurations exceeding a specified inactivity threshold
void auto_expire_configs() {
    int i, j;
    NetworkConfig *config;

    // Search for expired configurations in the hashtable
