        config = configs[i];
        if (config != NULL && config->last_updated + INACTIVITY_THRESHOLD < current_time) {
            // Delete the expired configuration from the hashtable
            free(config->nid);
            free(config->ip_addrs);
            configs[i] = NULL;
        }
    }
    pthread_mutex_unlock(&config_lock);
