    int audio_bitrate;
    int video_bitrate;
    int resolution;
} Stream;

// Function to initialize and configure multimedia streaming service
void init_streaming(Stream* streams, int num_streams, int max_bandwidth) {
    // Initialize variables for total bandwidth usage and number of successfully configured streams
    int total_bandwidth = 0;
    int num_configured_streams = 0;

    // Iterate over the list of structures representing different media streams
    for (int i = 0; i < num_streams; i++) {
        Stream* stream = &streams[i];

        // Check if total bandwidth usage exceeds maximum limit, and adjust stream parameters if necessary
        if (total_bandwidth + stream->audio_bitrate + stream->video_bitrate > max_bandwidth) {
            int adjusted_audio_bitrate = stream->audio_bitrate * (max_bandwidth - total_bandwidth) / (stream->audio_bitrate + stream->video_bitrate);
            int adjusted_video_bitrate = stream->video_bitrate * (max_bandwidth - total_bandwidth) / (stream->audio_bitrate + stream->video_bitrate);

            // Update the stream parameters to fit within the maximum bandwidth limit
            stream->audio_bitrate = adjusted_audio_bitrate;
            stream->video_bitrate = adjusted_video_bitrate;
        }

        // Increase total bandwidth usage and update number of successfully configured streams
        total_bandwidth += stream->audio_bitrate + stream->video_bitrate;
        num_configured_streams++;
    }

    // Print feedback on the number of successfully configured streams
    printf("Number of successfully configured streams: %d\n", num_configured_streams);
}
