int createCrcIndicationList(int numPdus, int rnti, int crcFlag) {
    // Check if input is valid
    if (numPdus <= 0 || rnti < 0 || crcFlag < 0) {
        return -1;
    }

    CrcIndicationStruct *list = malloc(sizeof(CrcIndicationStruct) * numPdus);
    if (list == NULL) {
        return -2;
    }

    // Initialize mutexes for thread-safe operations
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    for (int i = 0; i < numPdus; i++) {
        pthread_mutex_init(&list[i].mutex, &attr);
    }

    // Populate the list with random RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG values
    for (int i = 0; i < numPdus; i++) {
        list[i].pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
