    // Initialize the hash table
    rnti_hash_table_t *table = (rnti_hash_table_t *)malloc(sizeof(rnti_hash_table_t));
    table->size = 0;
    table->rntis = NULL;
    table->pdus = NULL;

    // Allocate memory for the list of PDUs and initialize them
    nfapi_crc_indication_pdu_t *list = (nfapi_crc_indication_pdu_t *)malloc(sizeof(nfapi_crc_indication_pdu_t) * n);
    for (int i = 0; i < n; i++) {
        list[i].rx_ue_information_tag = 0;
        list[i].rnti = i + 1;
        list[i].crcflag = true;
    }

    // Create a hash table to store the RNTIs and their corresponding PDUs
    for (int i = 0; i < n; i++) {
        int rnti = list[i].rnti;
        bool found = false;

        // Check if the RNTI is already present in the table
        for (int j = 0; j < table->size; j++) {
            if (table->rntis[j] == rnti) {
                found = true;
                break;
            }
        }

        // If the RNTI is not present, add it to the table
        if (!found) {
            int new_size = table->size + 1;
            table->rntis = (uint32_t *)realloc(table->rntis, sizeof(uint32_t) * new_size);
            table->pdus = (nfapi_crc_indication_pdu_t **)realloc(table->pdus, sizeof(nfapi_crc_indication_pdu_t *) * new_size);
            table->rntis[new_size - 1] = rnti;
            table->pdus[new_size - 1] = &list[i];
            table->size++;
        }
    }

    return list;
}

// Function to update a PDU in the hash table
void update_pdu(nfapi_crc_indication_pdu_t *pdu) {
    // Check if the RNTI is present in the table
    int rnti = pdu->rnti;
    bool found = false;
    for (int i = 0; i < table->size; i++) {
        if (table->rntis[i] == rnti) {
            found = true;
            break;
        }
    }

    // If the RNTI is not present, add it to the table
    if (!found) {
        int new_size = table->size + 1;
        table->rntis = (uint32_t *)realloc(table->rntis, sizeof(uint32_t) * new_size);
        table->pdus = (nfapi_crc_indication_pdu_t **)realloc(table->pdus, sizeof(nfapi_crc_indication_pdu_t *) * new_size);
        table->rntis[new_size - 1] = rnti;
        table->pdus[new_size - 1] = pdu;
        table->size++;
    } else {
        // Update the PDU in the existing entry
        for (int i = 0; i < table->size; i++) {
            if (table->rntis[i] == rnti) {
                table->pdus[i] = pdu;
                break;
            }
        }
    }
}

// Function to retrieve a PDU from the hash table
nfapi_crc_indication_pdu_t *get_pdu(uint32_t rnti) {
    // Check if the RNTI is present in the table
    bool found = false;
    for (int i = 0; i < table->size; i++) {
        if (table->rntis[i] == rnti) {
            found = true;
            break;
        }
    }

    // If the RNTI is not present, return NULL
    if (!found) {
        return NULL;
    } else {
        // Return the corresponding PDU
        for (int i = 0; i < table->size; i++) {
            if (table->rntis[i] == rnti) {
                return table->pdus[i];
            }
        }
    }
}

// Function to delete a PDU from the hash table
void delete_pdu(uint32_t rnti) {
    // Check if the RNTI is present in the table
    bool found = false;
    for (int i = 0; i < table->size; i++) {
        if (table->rntis[i] == rnti) {
            found = true;
            break;
        }
    }

    // If the RNTI is not present, return
    if (!found) {
        return;
    } else {
        // Delete the corresponding PDU and update the table
        for (int i = 0; i < table->size; i++) {
            if (table->rntis[i] == rnti) {
                free(table->pdus[i]);
                table->pdus[i] = NULL;
                break;
            }
        }
    }
}

// Function to clear the hash table
void clear_table() {
    for (int i = 0; i < table->size; i++) {
        free(table->rntis[i]);
        free(table->pdus[i]);
    }
    free(table->rntis);
    free(table->pdus);
    table->rntis = NULL;
    table->pdus = NULL;
    table->size = 0;
}

// Function to export the hash table to a file
void export_table(FILE *file) {
    for (int i = 0; i < table->size; i++) {
