using System.IO;
using System.Xml;

public string ParseXMLForSetting(string xmlFilePath, string settingKey, int maxAcceptableDelay) {
    // Load the XML file into an XmlDocument object
    XmlDocument doc = new XmlDocument();
    try {
        doc.Load(xmlFilePath);
    } catch (XmlException ex) {
        Console.WriteLine("Error parsing XML: " + ex.Message);
        return null;
    }

    // Get the first instance of the specified setting key within the given delay limit
    XmlNodeList nodes = doc.SelectNodes("//" + settingKey);
    if (nodes == null || nodes.Count == 0) {
        Console.WriteLine("Warning: Could not find value for setting " + settingKey + " within acceptable delay.");
        return null;
    }

    // Return the corresponding value
    XmlNode node = nodes[0];
    string value = node.InnerText;
    return value;
