// Remove an element from the list of NFAPI_CRC_INDICATION_PDU_T structures
void nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST_T *list, size_t index) {
    // Check if the index is valid
    if (index >= list->size) {
        return;
    }

    // Remove the element from the list by shifting all elements behind it back one position
    for (size_t i = index; i < list->size - 1; i++) {
        list->list[i] = list->list[i + 1];
    }

    // Decrease the size of the list by 1
    list->size--;
}

