#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// define structure for RRC connection reconfiguration indication PDU
typedef struct NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU_T {
  uint16_t UE_ID; // UE identifier
  uint8_t RRC_message_type; // RRC message type
  void* RRC_configuration_update; // pointer to configuration update data
} NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU_T;

// define structure for RRC configuration update tags
typedef struct RRC_CONFIGURATION_UPDATE_TAG_T {
  uint8_t radio_resource_configuration_update; // flag indicating presence of radio resource configuration update
  void* dedicated_bearer_setup; // pointer to dedicated bearer setup data
  void* mobility_management_information; // pointer to mobility management information
} RRC_CONFIGURATION_UPDATE_TAG_T;

// define maximum number of simultaneous connections
#define MAX_CONNECTIONS 10000

// define mutex for synchronizing access to shared data structures
pthread_mutex_t connection_mutex = PTHREAD_MUTEX_INITIALIZER;

// define array of NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU_T structures
NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU_T* connections[MAX_CONNECTIONS];

// define function to initialize NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU_T structures
void init_connections(NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU_T* connections[MAX_CONNECTIONS]) {
  // initialize each connection structure with default values
  for (int i = 0; i < MAX_CONNECTIONS; i++) {
    connections[i]->UE_ID = 0;
    connections[i]->RRC_message_type = 0;
    connections[i]->RRC_configuration_update = NULL;
  }
}

// define function to add new RRC connection reconfiguration indication PDUs
void add_connection(NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU_T* connection) {
  // acquire mutex lock for shared data structures
  pthread_mutex_lock(&connection_mutex);

  // find next available connection index
  int i;
  for (i = 0; i < MAX_CONNECTIONS; i++) {
    if (connections[i] == NULL) {
      break;
    }
  }

  // check for buffer overflow
  if (i == MAX_CONNECTIONS) {
    pthread_mutex_unlock(&connection_mutex);
    return;
  }

  // allocate memory for connection structure
  connections[i] = malloc(sizeof(NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU_T));

  // initialize connection structure with input values
  connections[i]->UE_ID = connection->UE_ID;
  connections[i]->RRC_message_type = connection->RRC_message_type;
  connections[i]->RRC_configuration_update = connection->RRC_configuration_update;

  // release mutex lock
  pthread_mutex_unlock(&connection_mutex);
}

// define function to remove RRC connection reconfiguration indication PDUs
void remove_connection(NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU_T* connection) {
  // acquire mutex lock for shared data structures
  pthread_mutex_lock(&connection_mutex);

  // find connection index
  int i;
  for (i = 0; i < MAX_CONNECTIONS; i++) {
    if (connections[i] == connection) {
      break;
    }
  }

  // check for invalid input parameter
  if (i == MAX_CONNECTIONS) {
    pthread_mutex_unlock(&connection_mutex);
    return;
  }

  // deallocate memory for connection structure
  free(connections[i]);

  // set connection index to null
  connections[i] = NULL;

  // release mutex lock
  pthread_mutex_unlock(&connection_mutex);
}

// define function to update RRC configuration updates for a given UE ID
void update_configuration(uint16_t UE_ID, void* configuration_update) {
  // acquire mutex lock for shared data structures
  pthread_mutex_lock(&connection_mutex);

  // find connection index
  int i;
  for (i = 0; i < MAX_CONNECTIONS; i++) {
    if (connections[i] && connections[i]->UE_ID == UE_ID) {
      break;
    }
  }

  // check for invalid input parameter
  if (i == MAX_CONNECTIONS) {
    pthread_mutex_unlock(&connection_mutex);
    return;
  }

  // allocate memory for configuration update structure
  connections[i]->RRC_configuration_update = malloc(sizeof(RRC_CONFIGURATION_UPDATE_TAG_T));

  // initialize configuration update structure with input values
  RRC_CONFIGURATION_UPDATE_TAG_T* configuration_tag = (RRC_CONFIGURATION_UPDATE_TAG_T*)connections[i]->RRC_configuration_update;
  configuration_tag->radio_resource_configuration_update = configuration_update;
  configuration_tag->dedicated_bearer_setup = NULL; // initialize to null for now, may be updated later
  configuration_tag->mobility_management_information = NULL; // initialize to null for now, may be updated later

  // release mutex lock
  pthread_mutex_unlock(&connection_mutex);
}
