void init_nfapi_rrc_connection_reconfiguration_indication_pdu_array(NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU_T **pdu_array, size_t n) {
  // Check if the input is valid
  if (n <= 0 || pdu_array == NULL) {
    return;
  }

  // Initialize the array to NULL values
  for (size_t i = 0; i < n; i++) {
    pdu_array[i] = NULL;
  }

  // Dynamically allocate memory for each structure in the array
  for (size_t i = 0; i < n; i++) {
    pdu_array[i] = malloc(sizeof(NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU_T));
    if (pdu_array[i] == NULL) {
      break;
    }
  }

  // Initialize the structures with default values
  for (size_t i = 0; i < n; i++) {
    pdu_array[i]->ue_id = 0;
    pdu_array[i]->rrc_message_type = RRC_MESSAGE_TYPE_NONE;
    pdu_array[i]->rrc_configuration_update_tag = NULL;
  }

  // Initialize the RRC configuration update tag structures in each PDU
  for (size_t i = 0; i < n; i++) {
    if (pdu_array[i]->rrc_configuration_update_tag == NULL) {
      continue;
    }
    pdu_array[i]->rrc_configuration_update_tag->radio_resource_config.dl_carrier_frequency = 0;
    pdu_array[i]->rrc_configuration_update_tag->radio_resource_config.ul_carrier_frequency = 0;
    pdu_array[i]->rrc_configuration_update_tag->radio_resource_config.dl_bandwidth = 0;
    pdu_array[i]->rrc_configuration_update_tag->radio_resource_config.ul_bandwidth = 0;
    pdu_array[i]->rrc_configuration_update_tag->radio_resource_config.tx_antenna_ports = 0;
    pdu_array[i]->rrc_configuration_update_tag->dedicated_bearer_setup = false;
  }

  // Synchronize access to the array and deallocate memory if necessary
  pthread_mutex_lock(&array_mutex);
  if (pdu_array[n - 1] == NULL) {
    for (size_t i = 0; i < n; i++) {
      free(pdu_array[i]);
    }
    pthread_mutex_unlock(&array_mutex);
    return;
  }
  pthread_mutex_unlock(&array_mutex);
}
