// Define constants for the maximum size of the list and the threshold for RNTI values
#define MAX_LIST_SIZE 1024
#define RNTI_THRESHOLD 65535

// Structure to store a MAC PDU structure with SRS info, RNTI, and SFN fields
typedef struct {
    uint32_t srs_info_tag;
    uint16_t rnti;
    uint16_t sf_num;
} mac_pdu_t;

// Function to manage a dynamic list of MAC PDU structures
void manage_mac_pdus(mac_pdu_t *list, size_t num_elements, int fixed_offset, int random_offset) {
    // Initialize variables for memory allocation and synchronization
    mac_pdu_t *new_element = NULL;
    uint32_t random_num = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Loop until the list is full or a new element is added
    while (num_elements < MAX_LIST_SIZE) {
        // Acquire mutex to ensure exclusive access to the list
        pthread_mutex_lock(&mutex);

        // Check if there are any free elements in the list
        for (int i = 0; i < num_elements; i++) {
            if (list[i].rnti == 0) {
                new_element = &list[i];
                break;
            }
        }

        // If a free element was found, set its RNTI value based on the specified offset
        if (new_element != NULL) {
            if (fixed_offset == 1) {
                new_element->rnti = fixed_offset;
            } else {
                random_num = rand() % RNTI_THRESHOLD;
                while (random_num > RNTI_THRESHOLD || list[new_element->rnti].rnti != 0) {
                    random_num = rand() % RNTI_THRESHOLD;
                }
                new_element->rnti = random_num;
            }
        } else if (num_elements == MAX_LIST_SIZE) {
            // If the list is full, wait for a free element to be available
            pthread_cond_wait(&cond, &mutex);
        }

        // Update the SFN value based on the specified offset
        if (new_element != NULL) {
            new_element->sf_num = 0;
            for (int i = 0; i < num_elements; i++) {
                if (list[i].rnti == new_element->rnti && list[i].sf_num > new_element->sf_num) {
                    new_element->sf_num = list[i].sf_num + 1;
                }
            }
        }

        // Release mutex to allow other threads to access the list
        pthread_mutex_unlock(&mutex);

        // If a free element was found, increase the number of elements by one
        if (new_element != NULL) {
            num_elements++;

            // Signal that a new element is available for other threads to access
            pthread_cond_signal(&cond);
        }
    }
}

// Function to serialize the list into a binary format
void serialize_list(mac_pdu_t *list, size_t num_elements) {
    // Initialize variables for memory allocation and synchronization
    uint8_t *buffer = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the serialized buffer
    buffer = malloc(num_elements * sizeof(mac_pdu_t));
    if (buffer == NULL) {
        printf("Error: Failed to allocate memory for serialized list\n");
        return;
    }

    // Acquire mutex to ensure exclusive access to the list
    pthread_mutex_lock(&mutex);

    // Copy the list elements into the serialized buffer
    memcpy(buffer, list, num_elements * sizeof(mac_pdu_t));

    // Release mutex to allow other threads to access the list
    pthread_mutex_unlock(&mutex);
}
