// Memory pool for efficient allocation and deallocation of NFAPI_CRC_INDICATION_PDU_T structures
static NFAPI_CRC_INDICATION_PDU_T *memoryPool = NULL;

// Number of elements in the memory pool
static int numElements = 0;

// Mutex for protecting concurrent access to the memory pool and lifecycle management
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void *createNewElement() {
    // Allocate a new element from the memory pool
    NFAPI_CRC_INDICATION_PDU_T *element = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (element == NULL) {
        // Handle out-of-memory condition
        return NULL;
    }

    // Initialize the element with random values for RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    element->RX_UE_INFORMATION_TAG = rand() % 1000;
    element->RNTI = rand() % 1000;
    element->CRC_INDICATION_REL8_TAG = rand() % 1000;

    // Return the new element
    return element;
}

void addElement(NFAPI_CRC_INDICATION_PDU_T *element) {
    // Acquire the mutex to protect concurrent access to the memory pool and lifecycle management
    pthread_mutex_lock(&mutex);

    // If the memory pool is full, allocate a new element from the heap
    if (numElements == 1000000) {
        NFAPI_CRC_INDICATION_PDU_T *newElement = createNewElement();
        if (newElement != NULL) {
            // Add the new element to the end of the memory pool
            memoryPool[numElements] = newElement;
            numElements++;
        } else {
            // Handle out-of-memory condition
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // Add the element to the end of the memory pool
    memoryPool[numElements] = element;
    numElements++;

    // Release the mutex to allow other threads to access the memory pool
    pthread_mutex_unlock(&mutex);
}

void removeElement(NFAPI_CRC_INDICATION_PDU_T *element) {
    // Acquire the mutex to protect concurrent access to the memory pool and lifecycle management
    pthread_mutex_lock(&mutex);

    // Search for the element in the memory pool
    int index = 0;
    while (index < numElements && memoryPool[index] != element) {
        index++;
    }

    // If the element is found, remove it from the memory pool
    if (index < numElements) {
        // Shift all elements after the removed element one position to the left
        for (int i = index; i < numElements - 1; i++) {
            memoryPool[i] = memoryPool[i + 1];
        }
