static inline void get_random_ip(struct in_addr *ip) {
    uint32_t rand = (uint32_t)time(NULL);
    rand &= 0xffffff; // Keep only the last 24 bits for IPv4
    ip->s_addr = htonl(rand);
}

// Function to generate a random protocol type
