  // Lock mutex to ensure thread-safe access to array
  pthread_mutex_lock(&dl_frame_message_lock);

  // Check if index is valid
  if (index < 0 || index >= dl_frame_message_count) {
    pthread_mutex_unlock(&dl_frame_message_lock);
    return;
  }

  // Remove structure from array and decrement count
  free(dl_frame_message_array[index]);
  dl_frame_message_count--;
  for (int i = index; i < dl_frame_message_count; i++) {
    dl_frame_message_array[i] = dl_frame_message_array[i + 1];
  }

  // Reallocate memory for array to remove empty slot
  dl_frame_message_array = realloc(dl_frame_message_array, (dl_frame_message_count) * sizeof(LTE_DL_FRAME_MESSAGE_T));
  if (!dl_frame_message_array) {
    handle_memory_allocation_failure();
    pthread_mutex_unlock(&dl_frame_message_lock);
    return;
  }

  // Unlock mutex
  pthread_mutex_unlock(&dl_frame_message_lock);
}

