#define WARNING_THRESHOLD 900

// Define the lock for protecting concurrent access to the list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a variable to store the current size of the list
int list_size = 0;

// Define a variable to store the maximum capacity of the list
int max_capacity = MAX_ELEMENTS;

// Define a flag to indicate whether the list has reached its maximum capacity
bool is_full = false;

// Define a function to add an element to the list
void add_element(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the lock on the list
    pthread_mutex_lock(&mutex);

    // Check if the list is full
    if (is_full) {
        // Release the lock and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Check if the RNTI value is valid
    if (!is_valid_rnti(pdu->rnti)) {
        // Release the lock and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Add the element to the list
    list[list_size++] = *pdu;

    // Check if the list has reached its maximum capacity
    if (list_size == max_capacity) {
        is_full = true;
    }

    // Release the lock
    pthread_mutex_unlock(&mutex);
}

// Define a function to remove an element from the list
void remove_element(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the lock on the list
    pthread_mutex_lock(&mutex);

    // Check if the list is empty
    if (list_size == 0) {
        // Release the lock and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Find the element to remove
    for (int i = 0; i < list_size; i++) {
        if (list[i].rx_ue_information_tag == pdu->rx_ue_information_tag &&
            list[i].rnti == pdu->rnti &&
            list[i].crc_indication_rel8_tag == pdu->crc_indication_rel8_tag) {
            // Remove the element from the list
            for (int j = i; j < list_size - 1; j++) {
                list[j] = list[j + 1];
            }
            list_size--;
            break;
        }
    }

    // Check if the list has reached its maximum capacity
    if (list_size < max_capacity) {
        is_full = false;
    }

    // Release the lock
    pthread_mutex_unlock(&mutex);
}

// Define a function to get the size of the list
int get_list_size() {
    // Acquire the lock on the list
    pthread_mutex_lock(&mutex);

    // Get the size of the list
    int size = list_size;

    // Release the lock
    pthread_mutex_unlock(&mutex);

    return size;
}

// Define a function to iterate over the elements in the list
void iterate_elements(void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    // Acquire the lock on the list
    pthread_mutex_lock(&mutex);

    // Iterate over the elements in the list
    for (int i = 0; i < list_size; i++) {
        callback(&list[i]);
    }

    // Release the lock
    pthread_mutex_unlock(&mutex);
}

