// Define a struct to represent an NFAPI_L2_PDU_T structure with a valid DL_FRAME_PDU and a dynamically allocated DL_FRAME_PDU_RRC_TAG
typedef struct {
    NFAPI_L2_PDU l2_pdu;
    DL_FRAME_PDU_RRC_TAG* rrc_tag;
} nfapi_l2_pdu_t;

// Define a list of nfapi_l2_pdu_t structures to hold the frame configurations
static list_t frame_configs = NULL;

// Define a mutex to ensure thread safety when accessing and modifying the list of frames
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_frames(int num_frames, int bandwidth, int subcarrier_spacing, int modulation_scheme) {
    // Initialize the list of frames if it has not already been initialized
    if (frame_configs == NULL) {
        frame_configs = malloc(sizeof(nfapi_l2_pdu_t*) * num_frames);
        for (int i = 0; i < num_frames; i++) {
            nfapi_l2_pdu_t* frame_config = malloc(sizeof(nfapi_l2_pdu_t));
            memset(&frame_config->l2_pdu, 0, sizeof(NFAPI_L2_PDU));
            frame_config->rrc_tag = NULL;
            frame_configs[i] = frame_config;
        }
    }

    // Acquire the mutex to ensure thread safety when accessing and modifying the list of frames
    pthread_mutex_lock(&mutex);

    // Iterate over each frame configuration and initialize it with the specified parameters
    for (int i = 0; i < num_frames; i++) {
        nfapi_l2_pdu_t* frame_config = frame_configs[i];
        memset(&frame_config->l2_pdu, 0, sizeof(NFAPI_L2_PDU));
        frame_config->l2_pdu.num_dl_antennas = bandwidth;
        frame_config->l2_pdu.subcarrier_spacing = subcarrier_spacing;
        frame_config->l2_pdu.modulation_scheme = modulation_scheme;
        frame_config->rrc_tag = malloc(sizeof(DL_FRAME_PDU_RRC_TAG));
    }

    // Release the mutex and return the list of frames
    pthread_mutex_unlock(&mutex);
}

// Deinitialize the list of frames when no longer needed
void deinitialize_frames() {
    if (frame_configs != NULL) {
        for (int i = 0; i < num_frames; i++) {
            nfapi_l2_pdu_t* frame_config = frame_configs[i];
            free(frame_config->rrc_tag);
        }
    }
}
