#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Custom data structure to represent a transaction in the HFT system
typedef struct Transaction {
    char type[10]; // Type of transaction (e.g., buy, sell, short)
    int size; // Size of the transaction (in number of shares or contracts)
    double price; // Price at which the transaction was executed
    long timestamp; // Timestamp of the transaction (UTC)
} Transaction;

// Linked list node to store transactions in a dynamic collection
typedef struct Node {
    Transaction *data;
    struct Node *next;
} Node;

// Head node of the linked list
Node *head = NULL;

// Adds a transaction to the linked list and updates the head pointer if necessary
void addTransaction(Transaction *transaction) {
    // Create a new node for the transaction
    Node *new_node = malloc(sizeof(Node));
    new_node->data = transaction;
    new_node->next = NULL;

    // If the linked list is empty, set the head pointer to this node
    if (head == NULL) {
        head = new_node;
    } else {
        Node *curr = head;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_node;
    }
}

// Processes a transaction and updates the linked list accordingly
void processTransaction(char *type, int size, double price, long timestamp) {
    // Create a new transaction object
    Transaction *transaction = malloc(sizeof(Transaction));
    strcpy(transaction->type, type);
    transaction->size = size;
    transaction->price = price;
    transaction->timestamp = timestamp;

    // Add the transaction to the linked list
    addTransaction(transaction);
}

// Removes a transaction from the linked list and updates the head pointer if necessary
void removeTransaction(Transaction *transaction) {
    Node *curr = head, *prev = NULL;
    while (curr != NULL && curr->data != transaction) {
        prev = curr;
        curr = curr->next;
    }
    // If the transaction is found, remove it from the linked list
    if (curr != NULL) {
        if (prev == NULL) {
            head = curr->next;
        } else {
            prev->next = curr->next;
        }
        free(curr);
    }
}

// Retrieves a transaction from the linked list by its timestamp
Transaction *getTransactionByTimestamp(long timestamp) {
    Node *curr = head;
    while (curr != NULL && curr->data->timestamp <= timestamp) {
        if (curr->data->timestamp == timestamp) {
            return curr->data;
        }
        curr = curr->next;
    }
    return NULL;
}

// Retrieves the head node of the linked list
Node *getHead() {
    return head;
}
