struct NFAPI_CRC_INDICATION_PDU_T {
    NFAPI_CRC_INDICATION_PDU_T* next;
    bool crcflag;
    uint8_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
};

void allocate_nfapi_crc_indication_pdu(size_t n, NFAPI_CRC_INDICATION_PDU_T** pdu) {
    if (n == 0 || pdu == NULL) {
        return;
    }
    *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (*pdu == NULL) {
        fprintf(stderr, "Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T\n");
        return;
    }
    for (size_t i = 0; i < n; i++) {
        (*pdu)[i].next = NULL;
        (*pdu)[i].crcflag = true; // randomize crc flag
        (*pdu)[i].rx_ue_information_tag = rand() % UINT8_MAX;
        (*pdu)[i].rnti = rand() % UINT16_MAX;
        (*pdu)[i].crc_indication_rel8_tag = rand() % UINT8_MAX;
    }
}

void free_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu == NULL) {
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T* current = pdu;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    size_t n = 0;
    printf("Enter the number of elements: ");
    scanf("%zu", &n);
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
    allocate_nfapi_crc_indication_pdu(n, &pdu);
    if (pdu == NULL) {
        printf("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T\n");
        return 1;
    }
    for (size_t i = 0; i < n; i++) {
        printf("Element %zu: %u, %u, %u\n", i + 1, pdu[i].rx_ue_information_tag, pdu[i].rnti, pdu[i].crc_indication_rel8_tag);
    }
    free_nfapi_crc_indication_pdu(pdu);
    return 0;
}
