// Define a function to allocate and initialize an array of CrcIndicationStruct structures
CrcIndicationStruct* allocateAndInitializeCrcIndications(size_t numStructs) {
    // Check if the requested number of structures is valid
    if (numStructs <= 0 || numStructs > MAX_STRUCTURES) {
        return NULL;
    }

    // Allocate memory for the array of structures
    CrcIndicationStruct* crcIndications = malloc(sizeof(CrcIndicationStruct) * numStructs);
    if (crcIndications == NULL) {
        printf("Error: Failed to allocate memory for CRC indications\n");
        return NULL;
    }

    // Initialize all allocated structures to a known state
    memset(crcIndications, 0, sizeof(CrcIndicationStruct) * numStructs);

    // Set the RX UE information tag for each structure
    for (size_t i = 0; i < numStructs; ++i) {
        crcIndications[i].crc.rxUeInformation.tag = NFAPI_RX_UE_INFORMATION_TAG;
    }

    // Set the RNTI for each structure
