        crcIndications[i].crc.rxUeInformation.rnti = i + 1;
    }

    // Generate a random CRC flag for each structure
    int polynomial = 8; // Use the standard CRC-8 polynomial as default
    if (polynomial > 0) {
        srand(time(NULL));
        for (size_t i = 0; i < numStructs; ++i) {
            crcIndications[i].crc.rxUeInformation.crcFlag = rand() % polynomial;
