        crcIndications[i].crc.tag = NFAPI_CRC_INDICATION_REL8_TAG;
    }

    // Increment the total number of allocated and initialized structures
    numAllocatedStructures += numStructs;

    return crcIndications;
}

// Define a function to release an array of CrcIndicationStruct structures
void releaseCrcIndications(CrcIndicationStruct* crcIndications, size_t numStructs) {
    // Check if the input array is valid
    if (crcIndications == NULL || numStructs <= 0) {
        return;
    }

    // Decrement the total number of allocated and initialized structures
    numAllocatedStructures -= numStructs;

    // Release memory for the array of structures
    free(crcIndications);
}
