    new_ctx.pci = pci;
    new_ctx.tcrnti = tcrnti;
    memcpy(new_ctx.priority_order, priority_order, num_priority_orders);
    insert_hashmap(ue_contexts, &new_ctx, sizeof(UEContext));

    return true;
}

