void initNetworkEventCollection(int initialSize) {
    // Allocate memory for the initial number of events
    events = (NetworkEvent *)malloc(sizeof(NetworkEvent) * initialSize);
    if (!events) {
        printf("Failed to allocate memory for network event collection\n");
        return;
    }

    // Initialize the number of events to 0
    numEvents = 0;
}

// Function to add a new network event to the collection
void addNetworkEvent(EVENT_HEADER_T header, EVENT_DATA_T data, double timestamp) {
    // Check if the collection needs to be resized
    if (numEvents == initialSize) {
        int newSize = initialSize * 2;
        NetworkEvent *newEvents = realloc(events, sizeof(NetworkEvent) * newSize);
        if (!newEvents) {
            printf("Failed to resize network event collection\n");
            return;
        }
        events = newEvents;
        initialSize = newSize;
    }

    // Add the new event to the collection
    int index = numEvents++;
    events[index].header = header;
    events[index].data = data;
    events[index].timestamp = timestamp;
}

