};

// Array of messages, with capacity for N messages
struct Message* messages = NULL;
size_t num_messages = 0;
size_t max_messages = N; // Set N to a reasonable value based on the desired retention policy

// Function to add a new message to the array
void add_message(const struct Message *msg) {
    assert(msg != NULL);

    // Ensure there is enough capacity in the array
    if (num_messages == max_messages) {
        max_messages = max_messages * 2;
        messages = realloc(messages, max_messages * sizeof(struct Message));
    }

    // Add new message to the end of the array
    messages[num_messages++] = *msg;
}

// Function to remove outdated messages based on a configurable retention policy
void remove_outdated_messages() {
    time_t now = time(NULL);
    for (size_t i = 0; i < num_messages; i++) {
        if (messages[i].timestamp <= now - retention_period) {
            // Move last message to the current position and reduce array size by one
            messages[i] = messages[num_messages - 1];
            num_messages--;
            break;
        }
    }
}

// Function to retrieve the latest N messages
struct Message* get_latest_messages(size_t n) {
    assert(n <= num_messages);

    struct Message* result = malloc(n * sizeof(struct Message));
    if (result == NULL) {
        return NULL;
    }

    for (size_t i = 0; i < n; i++) {
        result[i] = messages[num_messages - n + i];
    }

    return result;
}

// Function to log all changes to the message array
void log_changes() {
    // Log each message as it is added or removed
    for (size_t i = 0; i < num_messages; i++) {
        struct Message* msg = messages + i;
        char* log_msg = malloc(sizeof(struct Message));
        if (log_msg == NULL) {
            continue; // Ignore message that cannot be logged
        }

        sprintf(log_msg, "%lu: %d, %s", msg->timestamp, msg->user_id, msg->status_flag ? "true" : "false");
        log_message(log_msg);
    }
}

// Function to throttle excessive requests from a single user
void throttle_requests() {
    // Implement throttling logic here
}

// Function to filter messages based on additional metadata
struct Message* filter_messages(const struct Message *msg, bool (*filter)(const struct Message *)) {
    assert(msg != NULL);
    assert(filter != NULL);

    struct Message* result = malloc(num_messages * sizeof(struct Message));
    if (result == NULL) {
        return NULL;
    }

    size_t num_results = 0;
    for (size_t i = 0; i < num_messages; i++) {
        struct Message* msg = messages + i;
        if (filter(msg)) {
            result[num_results++] = *msg;
        }
    }

    return result;
}
