// Define struct for GTPV2_C Session Contexts
typedef struct {
    char* guti;
    char* imsi;
    int teid;
} GTPV2_CSContext;

// Define hash function for TEID values
int getTeid(char* guti, char* imsi) {
    int hash = 0;
    // Calculate hash value based on concatenation of GUTI and IMSI
    for (int i = 0; i < strlen(guti); i++) {
        hash += guti[i] * imsi[i];
    }
    return hash % 1000000; // Modulo 1 million to ensure unique TEID values
}

// Function to manage dynamically allocated list of GTPV2_C Session Contexts
void manageSessions(GTPV2_CSContext* sessions, int numSessions) {
    // Initialize hash table with maximum number of possible collisions
    int* hashTable = (int*)malloc(sizeof(int) * 1000000);
    memset(hashTable, -1, sizeof(int) * 1000000);

    // Iterate over all sessions and add/update TEID values in hash table
    for (int i = 0; i < numSessions; i++) {
        int teid = getTeid(sessions[i].guti, sessions[i].imsi);
        if (hashTable[teid] == -1) { // No collision, add TEID to hash table
            hashTable[teid] = 1;
        } else { // Collision, find unique TEID value
            int uniqueTeid = getUniqueTeid(hashTable);
            sessions[i].teid = uniqueTeid;
            hashTable[uniqueTeid] = 1;
        }
    }

    // Free memory for hash table
    free(hashTable);
}

// Function to handle potential hash collisions and manage memory allocation efficiently
int getUniqueTeid(int* hashTable) {
    int teid = 0;
    while (hashTable[teid] != -1) {
        teid++;
        if (teid > 1000000) { // Maximum number of possible TEID values reached
            return -1;
        }
    }
    hashTable[teid] = 1;
    return teid;
}
