// Define the structure to hold a network flow record
typedef struct {
    uint64_t timestamp;
    uint16_t packet_length;
    uint32_t src_ip, dst_ip;
    bool is_tcp, is_udp, is_icmp;
    uint8_t protocol_version;
} flow_record_t;

// Define the dynamic array to store the network flow records
typedef struct {
    flow_record_t *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} flow_array_t;

// Function to initialize and manage a dynamic array of network flow records
flow_array_t *init_flow_array(size_t initial_capacity) {
    flow_array_t *arr = malloc(sizeof(flow_array_t));
    arr->records = calloc(initial_capacity, sizeof(flow_record_t));
    arr->capacity = initial_capacity;
    arr->count = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

// Function to add a network flow record to the dynamic array
void add_flow_record(flow_array_t *arr, flow_record_t record) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->count == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        flow_record_t *new_records = realloc(arr->records, sizeof(flow_record_t) * new_capacity);
        if (new_records == NULL) {
            pthread_mutex_unlock(&arr->mutex);
            return;
        }
        arr->records = new_records;
        arr->capacity = new_capacity;
    }
    arr->records[arr->count++] = record;
    pthread_mutex_unlock(&arr->mutex);
}

// Function to retrieve a network flow record from the dynamic array based on its index
flow_record_t get_flow_record(flow_array_t *arr, size_t idx) {
    if (idx >= arr->count) {
        return NULL;
    }
    pthread_mutex_lock(&arr->mutex);
    flow_record_t record = arr->records[idx];
    pthread_mutex_unlock(&arr->mutex);
    return record;
}

