LTE_NAS_Message** init_dynamic_array(int capacity) {
    // Allocate memory for the array of pointers
    LTE_NAS_Message** array = malloc(capacity * sizeof(LTE_NAS_Message*));
    if (array == NULL) {
        return NULL;
    }

    // Initialize each pointer in the array to point to a new LTE_NAS_Message structure
    for (int i = 0; i < capacity; ++i) {
        array[i] = malloc(sizeof(LTE_NAS_Message));
        if (array[i] == NULL) {
            return NULL;
        }
    }

    // Initialize the NAS_Message_ID, NAS_PDU, and NAS_EMM_TYPE fields for each LTE_NAS_Message structure
    for (int i = 0; i < capacity; ++i) {
        array[i]->NAS_Message_ID = -1; // initialize to an invalid value
        array[i]->NAS_PDU = NULL;
        array[i]->NAS_EMM_TYPE = -1;
    }

    return array;
}

// Define a function to allocate memory for a new LTE_NAS_Message structure and add it to the dynamic array
LTE_NAS_Message* alloc_and_add(int capacity, int index) {
    // Check if the index is within the bounds of the array
    if (index < 0 || index >= capacity) {
        return NULL;
    }

    // Allocate memory for a new LTE_NAS_Message structure
    LTE_NAS_Message* new_msg = malloc(sizeof(LTE_NAS_Message));
    if (new_msg == NULL) {
        return NULL;
    }

    // Initialize the NAS_Message_ID, NAS_PDU, and NAS_EMM_TYPE fields for the new LTE_NAS_Message structure
    new_msg->NAS_Message_ID = -1; // initialize to an invalid value
    new_msg->NAS_PDU = NULL;
    new_msg->NAS_EMM_TYPE = -1;

    // Insert the new LTE_NAS_Message structure into the array at the specified index
    for (int i = capacity - 1; i > index; --i) {
        array[i] = array[i - 1];
    }
    array[index] = new_msg;

    return new_msg;
}

// Define a function to free memory for an LTE_NAS_Message structure and remove it from the dynamic array
void free_and_remove(int capacity, int index) {
    // Check if the index is within the bounds of the array
    if (index < 0 || index >= capacity) {
        return;
    }

    // Free the memory for the LTE_NAS_Message structure at the specified index
    free(array[index]);

    // Shift all elements after the removed element to the left by one index
    for (int i = index; i < capacity - 1; ++i) {
        array[i] = array[i + 1];
    }

    return;
}
