// Function to sort an array of LTE PHY layer configuration structures based on RF channel frequency
void *sortLtePhyConfig(LTE_PHY_CONFIG_T **ltePhyConfigArray, int numElements) {
    // Sort the array using a quicksort algorithm
    for (int i = 0; i < numElements; ++i) {
        int j = i + 1;
        while (j < numElements) {
            if (ltePhyConfigArray[i]->RF_CHANNEL_FREQUENCY > ltePhyConfigArray[j]->RF_CHANNEL_FREQUENCY) {
                // Swap the two elements
                LTE_PHY_CONFIG_T *temp = ltePhyConfigArray[i];
                ltePhyConfigArray[i] = ltePhyConfigArray[j];
                ltePhyConfigArray[j] = temp;
            }
            ++j;
        }
    }
}
