// Function to initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
// with a maximum size of N and a predefined memory limit M bytes
nfapi_crc_indication_pdu_t* init_list(uint32_t n, uint32_t m) {
    // Check for edge cases
    if (n == 0 || m == 0) {
        return NULL;
    }

    // Allocate memory for the list of structures
    nfapi_crc_indication_pdu_t* list = malloc(sizeof(nfapi_crc_indication_pdu_t) * n);
    if (list == NULL) {
        return NULL;
    }

    // Initialize the structures with random values
    for (uint32_t i = 0; i < n; ++i) {
        list[i].rx_ue_information_tag = rand();
        list[i].rnti = rand();
        list[i].crc_indication_rel8_tag = rand() % 256;
        list[i].crcflag = (rand() % 2) == 0 ? true : false;
    }

    // Initialize the custom caching mechanism with a limited size cache
    uint32_t cache_size = m / sizeof(nfapi_crc_indication_pdu_t);
    nfapi_crc_indication_pdu_t* cache = malloc(sizeof(nfapi_crc_indication_pdu_t) * cache_size);
    if (cache == NULL) {
        free(list);
        return NULL;
    }

    // Initialize the list of structures with a maximum size of N and a predefined memory limit M bytes
    nfapi_crc_indication_pdu_t* current = list;
    uint32_t size = 0;
    while (current != NULL && size < n) {
        // Add the structure to the cache if it is not full
        if (size < cache_size) {
            cache[size++] = *current;
        }

        // Move to the next structure in the list
        current = current->next;
    }

    // Validate that all fields in the structures are correctly initialized
    bool valid = true;
    for (uint32_t i = 0; i < size && valid; ++i) {
        if (cache[i].rx_ue_information_tag == 0 || cache[i].rnti == 0 || cache[i].crc_indication_rel8_tag == 0) {
            valid = false;
        }
    }

    // Release all allocated resources if the validation fails
    if (!valid) {
        free(list);
        list = NULL;
    }

    return list;
}
