            if (queue[i].id == id) {
                queue[i].priority = priority;
                queue[i].bandwidth = bandwidth;
                break;
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    // Define a function to safely check if the QoS configuration structure is present in the queue.
    bool is_qos_config_present(int id) {
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < N; ++i) {
            if (queue[i].id == id) {
                return true;
            }
        }
        pthread_mutex_unlock(&mutex);
    }
}
