// Metric data structure to store metric values and moving average cache
typedef struct {
    int index; // Index of current entry in the data store
    float value; // Value of the metric at the current entry
    float movingAverageCache[MOVING_AVERAGE_CACHE_SIZE]; // Cache for the moving average calculation
} MetricDataStore;

// Configuration structure to specify processing options
typedef struct {
    int cacheSize; // Size of the moving average cache
    int metricIndex; // Index of the metric to be processed in the data store
    float windowSize; // Size of the moving average window (in days)
} ProcessingConfig;

// Function to process and aggregate metrics in a MetricDataStore
void processAndAggregateMetrics(int N, MetricDataStore* dataStore, ProcessingConfig config) {
    // Iterate through the first N entries of the data store
    for (int i = 0; i < N; i++) {
        // Get the current entry from the data store
        MetricDataStore* entry = &dataStore[i];

        // Check if the cache is full and update it accordingly
        if (entry->index >= config.cacheSize) {
            for (int j = 0; j < MOVING_AVERAGE_CACHE_SIZE - 1; j++) {
                dataStore[i].movingAverageCache[j] = dataStore[i + 1].movingAverageCache[j];
            }
        }

        // Calculate the moving average of the specified metric field over the cache
        float movingAverage = calculateMovingAverage(entry->value, config.windowSize);

        // Update the moving average cache for the current entry
        dataStore[i].movingAverageCache[MOVING_AVERAGE_CACHE_SIZE - 1] = movingAverage;
    }
}

// Function to calculate the moving average of a metric field over a given window size
float calculateMovingAverage(float value, float windowSize) {
    // Handle cases where the window size is greater than the number of data points available
    if (windowSize > N) {
        return 0;
    }

    // Calculate the moving average using a simple formula
    float sum = 0;
    for (int i = 0; i < windowSize; i++) {
        sum += dataStore[i].value;
    }
    return sum / windowSize;
}
