            if (src[i].RX_UE_INFORMATION_TAG == src[j].RX_UE_INFORMATION_TAG && src[i].RNTI == src[j].RNTI) {
                fprintf(stderr, "Duplicate elements in source CRC indication data\n");
                return -1;
            }
        }
    }

    // Append the elements of the source array to the destination array
    for (size_t i = 0; i < src_size && dest->size > 0; i++) {
        if (!is_valid_crc_indication(&src[i], 1)) {
            fprintf(stderr, "Invalid CRC indication data in source array\n");
            return -1;
        }
        add_crc_indication(dest, dest->size, src[i]);
    }

    return 0;
}

// Function to split the elements of an array into two separate arrays
int split_crc_indication(NFAPI_CRC_INDICATION_PDU_T *src, size_t src_size, NFAPI_CRC_INDICATION_PDU_T **dest1, size_t *dest1_size, NFAPI_CRC_INDICATION_PDU_T **dest2, size_t *dest2_size) {
