    // Initialize the size of the two destination arrays
    *dest1_size = src->size / 2;
    *dest2_size = src->size / 2;

    // Split the elements of the source array into the two destination arrays
    for (size_t i = 0; i < src->size && (*dest1_size > 0 || *dest2_size > 0); i++) {
        if (!is_valid_crc_indication(&src[i], 1)) {
            fprintf(stderr, "Invalid CRC indication data in source array\n");
            return -1;
        }
        if (*dest1_size > 0) {
            add_crc_indication(*dest1, *dest1_size, src[i]);
            (*dest1_size)--;
        } else {
