// Define the structure for the data records
typedef struct {
  char* name;
  int age;
} DATA_RECORD;

// Define a linked list node for storing data records
typedef struct Node {
  DATA_RECORD data;
  struct Node* next;
} Node;

// Global variables for the list and its mutex
Node* head = NULL;
pthread_mutex_t lock;

// Function to add a new record to the list
void addRecord(DATA_RECORD record) {
  // Create a new node for the record
  Node* newNode = malloc(sizeof(Node));
  newNode->data = record;
  newNode->next = NULL;

  // Acquire the lock on the list
  pthread_mutex_lock(&lock);

  // Check if the list is empty
  if (head == NULL) {
    head = newNode;
  } else {
    // Insert the new node at the end of the list
    Node* current = head;
    while (current->next != NULL) {
      current = current->next;
    }
    current->next = newNode;
  }

  // Release the lock on the list
  pthread_mutex_unlock(&lock);
}

// Function to remove a record from the list
void removeRecord(DATA_RECORD* record) {
  // Acquire the lock on the list
  pthread_mutex_lock(&lock);

  // Find the node containing the record
  Node* current = head;
  while (current != NULL && current->data.name != record->name) {
    current = current->next;
  }

  // Check if the record was found
  if (current == NULL) {
    pthread_mutex_unlock(&lock);
    return;
  }

  // Remove the node containing the record
  if (current == head) {
    head = current->next;
  } else {
    Node* previous = head;
    while (previous->next != current) {
      previous = previous->next;
    }
    previous->next = current->next;
  }

  // Release the lock on the list
  pthread_mutex_unlock(&lock);
}

// Function to update a record in the list
void updateRecord(DATA_RECORD* oldRecord, DATA_RECORD newRecord) {
  // Acquire the lock on the list
  pthread_mutex_lock(&lock);

  // Find the node containing the old record
  Node* current = head;
  while (current != NULL && current->data.name != oldRecord->name) {
    current = current->next;
  }

  // Check if the old record was found
  if (current == NULL) {
    pthread_mutex_unlock(&lock);
    return;
  }

  // Update the node containing the old record
  current->data = newRecord;

  // Release the lock on the list
  pthread_mutex_unlock(&lock);
}

// Function to search for a record in the list
int findRecord(DATA_RECORD* record) {
  // Acquire the lock on the list
  pthread_mutex_lock(&lock);

  // Find the node containing the record
  Node* current = head;
  while (current != NULL && current->data.name != record->name) {
    current = current->next;
  }

  // Check if the record was found
  int found = (current != NULL);

  // Release the lock on the list
  pthread_mutex_unlock(&lock);

  return found;
}
