// Function to create a new list with the given total number of PDUs, maximum allowed size per PDU, and memory allocation limit
nfapi_crc_indication_list_t *nfapi_create_crc_indication_list(size_t N, size_t MAX_SIZE, size_t MEMORY_LIMIT) {
    // Check that the input parameters are valid
    if (N == 0 || MAX_SIZE == 0 || MEMORY_LIMIT == 0) {
        return NULL;
    }

    // Calculate the initial capacity of the list based on the given memory allocation limit and maximum allowed size per PDU
    size_t init_capacity = (MEMORY_LIMIT / MAX_SIZE) + 1;

    // Create a new list with the calculated initial capacity
    nfapi_crc_indication_list_t *list = (nfapi_crc_indication_list_t *)malloc(sizeof(nfapi_crc_indication_list_t));
    if (list == NULL) {
        return NULL;
    }
    list->size = 0;
    list->capacity = init_capacity;
    list->data = (nfapi_crc_indication_pdu_t *)malloc(sizeof(nfapi_crc_indication_pdu_t) * init_capacity);
    if (list->data == NULL) {
        free(list);
        return NULL;
    }

    // Initialize the list with unique RX_UE_INFORMATION_TAGs and random CRC_INDICATION_REL8_TAGS
    for (size_t i = 0; i < init_capacity; i++) {
        list->data[i].rx_ue_information_tag = i + 1;
        list->data[i].rnti = hash(list->data[i].rx_ue_information_tag);
        list->data[i].crc_indication_rel8_tag = rand() & 0xFF;
    }

    // Return a pointer to the head of the list
    return list;
}

// Function to add a new PDU to the list, dynamically allocating memory as necessary
