    if (list == NULL || rx_ue_information_tag == 0) {
        return false;
    }

    // If the list is full, allocate more memory for it
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        nfapi_crc_indication_pdu_t *new_data = (nfapi_crc_indication_pdu_t *)realloc(list->data, sizeof(nfapi_crc_indication_pdu_t) * new_capacity);
        if (new_data == NULL) {
            return false;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    // Add the new PDU to the list
    nfapi_crc_indication_pdu_t *new_pdu = &list->data[list->size++];
    new_pdu->rx_ue_information_tag = rx_ue_information_tag;
    new_pdu->rnti = hash(rx_ue_information_tag);
    new_pdu->crc_indication_rel8_tag = rand() & 0xFF;

