    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to initialize the linked list
Node* initList() {
    Node* head = NULL;
    return head;
}

// Function to insert a new node into the linked list
void insertNode(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;

    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

// Function to search for a node in the linked list based on RNTI value
Node* findNode(Node* head, uint16_t rnti) {
