// Function to delete a node from the linked list based on RNTI value
void deleteNode(Node** head, uint16_t rnti) {
    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        LOG_DEBUG("Could not delete node for RNTI %d\n", rnti);
    } else {
        if (previous == NULL) {
            *head = current->next;
        } else {
            previous->next = current->next;
        }

        free(current);
    }
}

