    }
}

// Function to sort the linked list based on RNTI values
void sortList(Node** head) {
    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL) {
        if (previous == NULL || previous->data.RNTI > current->data.RNTI) {
            previous = current;
        } else {
            Node* next = current->next;

            // Swap nodes
            previous->next = next;
            current->next = head;

            head = current;
            current = next;
        }
    }

    *head = head;
}

// Function to search for a node in the linked list based on RNTI value and return its CRCFLAG value
