void init_network_events(NetworkEvent** events, size_t event_count) {
    for (size_t i = 0; i < event_count; i++) {
        (*events)[i] = malloc(sizeof(NetworkEvent));
        if ((*events)[i] == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for NetworkEvent %zu\n", i);
