        }
    }
}

void populate_network_events(NetworkEvent** events, size_t event_count) {
    for (size_t i = 0; i < event_count; i++) {
        (*events)[i]->ConnectionIdentifier = i + 1;
        (*events)[i]->EventTime = time(NULL);
        (*events)[i]->EventDetailsCount = 3;
        (*events)[i]->EventDetails = malloc((*events)[i]->EventDetailsCount * sizeof(NetworkEventDetail));
        if ((*events)[i]->EventDetails == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for NetworkEvent %zu\n", i);
            exit(1);
        }
        for (size_t j = 0; j < (*events)[i]->EventDetailsCount; j++) {
            NetworkEventDetail* event_detail = &(*events)[i]->EventDetails[j];
            event_detail->EventType = "Connection established";
            event_detail->EventSeverity = "INFO";
            event_detail->DetailedMessage = "The connection to the client was successful.";
        }
    }
}

void handle_network_event(NetworkEvent* event) {
    printf("Received network event:\n");
    printf("\tConnection Identifier: %u\n", event->ConnectionIdentifier);
    printf("\tEvent Time: %s\n", ctime(&event->EventTime));
    printf("\tNumber of Event Details: %zu\n", event->EventDetailsCount);
    for (size_t i = 0; i < event->EventDetailsCount; i++) {
        NetworkEventDetail* event_detail = &event->EventDetails[i];
        printf("\t\tEvent Type: %s\n", event_detail->EventType);
        printf("\t\tEvent Severity: %s\n", event_detail->EventSeverity);
        printf("\t\tDetailed Message: %s\n", event_detail->DetailedMessage);
    }
}

int main() {
    const size_t EVENT_COUNT = 100;
    NetworkEvent** events = malloc(EVENT_COUNT * sizeof(NetworkEvent*));
    if (events == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for NetworkEvents\n");
        exit(1);
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    init_network_events(&events, EVENT_COUNT);
    populate_network_events(&events, EVENT_COUNT);

    for (size_t i = 0; i < EVENT_COUNT; i++) {
        pthread_mutex_lock(&mutex);
        handle_network_event(events[i]);
        pthread_mutex_unlock(&mutex);
    }

    for (size_t i = 0; i < EVENT_COUNT; i++) {
        free(events[i]->EventDetails);
        free(events[i]);
    }
    free(events);
    return 0;
}
