NFAPI_CRC_INDICATION_PDU *g_crcIndicationPdus = NULL;

// Mutex for synchronizing access to the global variable
pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new CRC indication PDU to the list
void addCrcIndicationPdu(NFAPI_CRC_INDICATION_PDU pdu) {
  // Acquire the mutex to prevent concurrent access to the global variable
  pthread_mutex_lock(&g_mutex);

  // Check if the list is empty and allocate memory for it if necessary
  if (g_crcIndicationPdus == NULL) {
    g_crcIndicationPdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
  } else {
    // Allocate more memory for the list
    NFAPI_CRC_INDICATION_PDU *newPdus = realloc(g_crcIndicationPdus, (sizeof(NFAPI_CRC_INDICATION_PDU) * (g_crcIndicationPdus->length + 1)));
    if (newPdus == NULL) {
      // Handle memory allocation failure gracefully by releasing the mutex and returning
      pthread_mutex_unlock(&g_mutex);
      return;
    }
    g_crcIndicationPdus = newPdus;
  }

  // Add the new CRC indication PDU to the list
  g_crcIndicationPdus[g_crcIndicationPdus->length++] = pdu;

  // Release the mutex and return
  pthread_mutex_unlock(&g_mutex);
}

// Function to remove a CRC indication PDU from the list
void removeCrcIndicationPdu(NFAPI_CRC_INDICATION_PDU *pdu) {
  // Acquire the mutex to prevent concurrent access to the global variable
  pthread_mutex_lock(&g_mutex);

  // Find the index of the CRC indication PDU in the list
  int index = -1;
  for (int i = 0; i < g_crcIndicationPdus->length; i++) {
    if (g_crcIndicationPdus[i].rxUeInformationTag == pdu->rxUeInformationTag &&
        g_crcIndicationPdus[i].rnti == pdu->rnti &&
        g_crcIndicationPdus[i].crcIndicationRel8.CRCFLAG == pdu->crcIndicationRel8.CRCFLAG) {
      index = i;
      break;
    }
  }

  // If the CRC indication PDU was found, remove it from the list and release the mutex
  if (index != -1) {
    g_crcIndicationPdus->length--;
    memmove(g_crcIndicationPdus + index, g_crcIndicationPdus + index + 1, sizeof(NFAPI_CRC_INDICATION_PDU) * (g_crcIndicationPdus->length - index));
    pthread_mutex_unlock(&g_mutex);
    return;
  }

  // If the CRC indication PDU was not found, release the mutex and return
  pthread_mutex_unlock(&g_mutex);
}

// Function to validate that each RX UE information tag is unique within the list
void validateUniqueRxUeInformationTags() {
  // Acquire the mutex to prevent concurrent access to the global variable
  pthread_mutex_lock(&g_mutex);

  // Create a hash map to store the RX UE information tags and their corresponding indices
  HASHMAP *rxUeInfoTagMap = createHashMap();

  // Iterate over the list of CRC indication PDUs and add each RX UE information tag to the hash map
  for (int i = 0; i < g_crcIndicationPdus->length; i++) {
    // Check if the RX UE information tag already exists in the hash map
    void *value = hashGet(rxUeInfoTagMap, g_crcIndicationPdus[i].rxUeInformationTag);
    if (value == NULL) {
      // If it doesn't exist, add it to the hash map with its corresponding index
      value = i;
      hashSet(rxUeInfoTagMap, g_crcIndicationPdus[i].rxUeInformationTag, value);
    } else {
