      NFAPI_CRC_INDICATION_PDU *pdu = g_crcIndicationPdus + (int)value;
      removeCrcIndicationPdu(pdu);
    }
  }

  // Release the hash map and release the mutex
  hashDestroy(rxUeInfoTagMap);
  pthread_mutex_unlock(&g_mutex);
}

// Function to free the allocated memory for the list of CRC indication PDUs
void freeCrcIndicationPdus() {
  // Acquire the mutex to prevent concurrent access to the global variable
  pthread_mutex_lock(&g_mutex);

  // Free the memory allocated for the list of CRC indication PDUs
  free(g_crcIndicationPdus);
  g_crcIndicationPdus = NULL;

  // Release the mutex and return
  pthread_mutex_unlock(&g_mutex);
}
