// Function to initialize and manage the dynamic array of SRB1 entries
nfapi_srb1_array_t* nfapi_srb1_array_init(size_t initial_capacity) {
    // Allocate memory for the array and its elements
    nfapi_srb1_array_t* array = malloc(sizeof(nfapi_srb1_array_t));
    if (array == NULL) {
        // Handle allocation failure
        return NULL;
    }
    array->elements = malloc(initial_capacity * sizeof(nfapi_srb1_t));
    if (array->elements == NULL) {
        free(array);
        // Handle allocation failure
        return NULL;
    }
    array->capacity = initial_capacity;
    array->count = 0;

    // Initialize the mutex and condition variable
    pthread_mutex_init(&srb1_mutex, NULL);
    pthread_cond_init(&srb1_condition, NULL);

    return array;
}

// Function to add a new SRB1 entry to the array
bool nfapi_srb1_array_add(nfapi_srb1_array_t* array, uint32_t srb1_id, uint32_t configuration) {
    // Acquire the mutex to protect the shared data structure
    pthread_mutex_lock(&srb1_mutex);

    // Check if the array needs to be resized
    if (array->count == array->capacity) {
        // Double the capacity of the array
        size_t new_capacity = array->capacity * 2;
        nfapi_srb1_t* new_elements = realloc(array->elements, new_capacity * sizeof(nfapi_srb1_t));
        if (new_elements == NULL) {
            pthread_mutex_unlock(&srb1_mutex);
            // Handle allocation failure
            return false;
        }
        array->elements = new_elements;
        array->capacity = new_capacity;
    }

    // Add the new SRB1 entry to the array
    array->elements[array->count].srb1_id = srb1_id;
    array->elements[array->count].configuration = configuration;
    array->elements[array->count].status = 0;
    array->count++;

    // Signal any waiting threads that the array has changed
    pthread_cond_broadcast(&srb1_condition);

    // Release the mutex and return success
    pthread_mutex_unlock(&srb1_mutex);
    return true;
}

// Function to get the configuration of an SRB1 entry in the array
uint32_t nfapi_srb1_array_get_configuration(nfapi_srb1_array_t* array, uint32_t srb1_id) {
    // Acquire the mutex to protect the shared data structure
    pthread_mutex_lock(&srb1_mutex);

    // Search for the requested SRB1 entry in the array
    size_t i;
    for (i = 0; i < array->count; i++) {
        if (array->elements[i].srb1_id == srb1_id) {
            break;
        }
    }
    if (i == array->count) {
        // SRB1 entry not found, return an error
        pthread_mutex_unlock(&srb1_mutex);
        return 0;
    }

    // Return the configuration of the SRB1 entry
    uint32_t configuration = array->elements[i].configuration;

    // Release the mutex and return success
    pthread_mutex_unlock(&srb1_mutex);
    return configuration;
}

