            break;
        }
    }
    if (i == array->count) {
        // SRB1 entry not found, return an error
        pthread_mutex_unlock(&srb1_mutex);
        return false;
    }

    // Update the status of the SRB1 entry
    array->elements[i].status = status;

    // Release the mutex and return success
    pthread_mutex_unlock(&srb1_mutex);
    return true;
}

// Function to free the memory allocated for the dynamic array of SRB1 entries
void nfapi_srb1_array_free(nfapi_srb1_array_t* array) {
    // Acquire the mutex to protect the shared data structure
    pthread_mutex_lock(&srb1_mutex);

    // Release the memory allocated for the array and its elements
    free(array->elements);
    free(array);

    // Reset the mutex and condition variable
