### C++ Implementation

Here is an example of how the `NFP` interface can be implemented in C++:

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>

using namespace std;

// A class to represent an NFP (Network Function Plane) interface
class NFP {
private:
    // A mutex to protect the shared data structure
    mutex mtx;

    // A condition variable to signal changes to the shared data structure
    condition_variable cv;

    // A vector of NFPs
    vector<string> nfps;

    // An unordered map from NFP ID to NFP name
    unordered_map<string, string> nfp_ids;

public:
    // Constructor
    NFP() {
        mtx = mutex();
        cv = condition_variable();
        nfps = vector<string>();
        nfp_ids = unordered_map<string, string>();
    }

    // Destructor
    ~NFP() {
        mtx.lock();
        cv.notify_all();
        mtx.unlock();
    }

    // Add a new NFP to the interface
    void add_nfp(string nfp_id, string nfp_name) {
        mtx.lock();
        nfps.push_back(nfp_id);
        nfp_ids[nfp_id] = nfp_name;
        cv.notify_all();
        mtx.unlock();
    }

    // Remove an NFP from the interface
    void remove_nfp(string nfp_id) {
        mtx.lock();
        auto it = find(begin(nfps), end(nfps), nfp_id);
        if (it != end(nfps)) {
            nfps.erase(it);
            nfp_ids.erase(nfp_id);
        }
        cv.notify_all();
        mtx.unlock();
    }

    // Get the list of NFPs currently connected to the interface
    vector<string> get_nfps() {
        vector<string> nfps;
        mtx.lock();
        for (auto it = begin(this->nfps); it != end(this->nfps); ++it) {
            nfps.push_back(*it);
        }
        mtx.unlock();
        return nfps;
    }

    // Get the name of an NFP given its ID
    string get_nfp_name(string nfp_id) {
        string nfp_name;
        mtx.lock();
        auto it = nfp_ids.find(nfp_id);
        if (it != end(nfp_ids)) {
            nfp_name = it->second;
        }
        mtx.unlock();
        return nfp_name;
    }
};
```

