import threading
import time
from typing import List, Dict, Optional

class NFP:
  def __init__(self):
    self._nfps: List[str] = []
    self._nfp_names: Dict[str, str] = {}
    self._lock = threading.Lock()

  def add_nfp(self, nfp_id: str, nfp_name: str):
    with self._lock:
      self._nfps.append(nfp_id)
      self._nfp_names[nfp_id] = nfp_name

  def remove_nfp(self, nfp_id: str):
    with self._lock:
      self._nfps.remove(nfp_id)
      del self._nfp_names[nfp_id]

  def get_nfps(self) -> List[str]:
    with self._lock:
      return list(self._nfps)

  def get_nfp_name(self, nfp_id: str) -> Optional[str]:
    with self._lock:
      return self._nfp_names.get(nfp_id)
