package nfp

import (
	"sync"
)

type NFP struct {
	nfps      []string
	nfpNames  map[string]string
	lock      sync.Mutex
}

func (this *NFP) AddNfp(id string, name string) {
	this.lock.Lock()
	defer this.lock.Unlock()
	this.nfps = append(this.nfps, id)
	this.nfpNames[id] = name
}

func (this *NFP) RemoveNfp(id string) {
	this.lock.Lock()
	defer this.lock.Unlock()
	for i := range this.nfps {
		if this.nfps[i] == id {
			this.nfps = append(this.nfps[:i], this.nfps[i+1:]...)
			break
		}
	}
	delete(this.nfpNames, id)
}

func (this *NFP) GetNfps() []string {
	this.lock.Lock()
	defer this.lock.Unlock()
	return append([]string{}, this.nfps...)
}

func (this *NFP) GetNfpName(id string) string {
	this.lock.Lock()
	defer this.lock.Unlock()
	return this.nfpNames[id]
}
