    head = lte_enb_rrc_conn_reconfig_complete_list.head;
    if (!head) {
        pthread_mutex_unlock(&lock);
        return;
    }

    // Iterate through the linked list and update the state of each message
    while (head != NULL) {
        char imsi[15];
        strcpy(imsi, head->msg->imsi);
        int pusch = head->msg->pusch;
        int pucch = head->msg->pucch;
        int srs = head->msg->srs;
        unsigned long timer = head->msg->timer;

        // Update the state of the message in the external monitoring system
        monitor_state(imsi, pusch, pucch, srs);

        head = head->next;
    }

    pthread_mutex_unlock(&lock);
}

// Function to handle potential network disruptions or data transmission failures and ensure the system remains operational
void lte_enb_rrc_conn_reconfig_complete_fallback() {
    node_t *head = NULL;
    pthread_mutex_lock(&lock);
    head = lte_enb_rrc_conn_reconfig_complete_list.head;
    if (!head) {
        pthread_mutex_unlock(&lock);
        return;
    }

    // Iterate through the linked list and log any failed updates to the radio resource configurations
    while (head != NULL) {
