// Function to optimize the function for performance, taking into account the need for frequent updates and retrieval operations
void lte_enb_rrc_conn_reconfig_complete_optimize() {
    node_t *head = NULL;
    pthread_mutex_lock(&lock);
    head = lte_enb_rrc_conn_reconfig_complete_list.head;
    if (!head) {
        pthread_mutex_unlock(&lock);
        return;
