        int pusch = head->msg->pusch;
        int pucch = head->msg->pucch;
        int srs = head->msg->srs;
        unsigned long timer = head->msg->timer;

        // Check if the message is a duplicate and remove it from the linked list
        if (push(imsi, pusch, pucch, srs) == -1) {
            duplicates = (node_t *)malloc(sizeof(node_t));
            duplicates->msg = head->msg;
            duplicates->next = NULL;
            head = head->next;
        } else {
            head = head->next;
        }
    }

    // Sort the linked list by IMSI to optimize updates and retrieval operations
    node_t *sorted_list = sort_by_imsi(duplicates);
    pthread_mutex_unlock(&lock);
