#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <stdbool.h>

// Define the maximum number of connections that can be handled by the network interface
#define MAX_CONNECTIONS 1024

// Define the QoS classes and their corresponding priorities
#define QOS_CLASS_BEST_EFFORT 0
#define QOS_CLASS_GUARANTEED 1
#define QOS_CLASS_CRITICAL 2

// Define the maximum number of connections for each QoS class
#define MAX_CONNECTIONS_BEST_EFFORT 50
#define MAX_CONNECTIONS_GUARANTEED 100
#define MAX_CONNECTIONS_CRITICAL 200

// Define the connection state enum
typedef enum {
    CONN_STATE_IDLE,
    CONN_STATE_CONNECTING,
    CONN_STATE_ESTABLISHED,
    CONN_STATE_CLOSING,
    CONN_STATE_CLOSED
} conn_state_t;

// Define the connection struct
typedef struct {
    int socket;
    struct sockaddr_in address;
    uint32_t sequence_number;
    char* buffer;
    size_t buffer_size;
    conn_state_t state;
} connection_t;

// Define the QoS class enum
typedef enum {
    QOS_CLASS_UNKNOWN,
    QOS_CLASS_BEST_EFFORT,
    QOS_CLASS_GUARANTEED,
    QOS_CLASS_CRITICAL
} qos_class_t;

// Define the connection manager struct
typedef struct {
    int socket;
    size_t num_connections;
    connection_t* connections[MAX_CONNECTIONS];
    bool is_running;
} conn_manager_t;

// Define the function to initialize and configure the network interface
void init_network_interface(conn_manager_t* manager) {
    // Create a new socket for the network interface
    int socket = socket(AF_INET, SOCK_STREAM, 0);
    if (socket < 0) {
        perror("Failed to create socket");
        exit(1);
    }

    // Set the maximum number of connections for each QoS class
    manager->num_connections = MAX_CONNECTIONS;
    manager->connections[QOS_CLASS_BEST_EFFORT] = malloc(sizeof(connection_t) * MAX_CONNECTIONS_BEST_EFFORT);
    manager->connections[QOS_CLASS_GUARANTEED] = malloc(sizeof(connection_t) * MAX_CONNECTIONS_GUARANTEED);
    manager->connections[QOS_CLASS_CRITICAL] = malloc(sizeof(connection_t) * MAX_CONNECTIONS_CRITICAL);

    // Initialize the connection state for each QoS class
    for (int i = 0; i < MAX_CONNECTIONS_BEST_EFFORT; ++i) {
        manager->connections[QOS_CLASS_BEST_EFFORT][i].state = CONN_STATE_IDLE;
    }
    for (int i = 0; i < MAX_CONNECTIONS_GUARANTEED; ++i) {
        manager->connections[QOS_CLASS_GUARANTEED][i].state = CONN_STATE_IDLE;
    }
    for (int i = 0; i < MAX_CONNECTIONS_CRITICAL; ++i) {
        manager->connections[QOS_CLASS_CRITICAL][i].state = CONN_STATE_IDLE;
    }

    // Set the socket to non-blocking mode
    int flags = fcntl(socket, F_GETFL);
    if (flags < 0) {
        perror("Failed to get file status flags");
        exit(1);
    }
    flags |= O_NONBLOCK;
    if (fcntl(socket, F_SETFL, flags) < 0) {
        perror("Failed to set non-blocking mode for socket");
        exit(1);
    }

    // Set the manager's socket to the new socket
    manager->socket = socket;
}

// Define the function to handle a connection
void handle_connection(conn_manager_t* manager, int socket) {
    // Get the next available connection slot for the QoS class of the incoming connection
    size_t slot = 0;
    switch (get_qos_class(socket)) {
        case QOS_CLASS_BEST_EFFORT:
            slot = find_next_available_slot(manager, QOS_CLASS_BEST_EFFORT);
            break;
        case QOS_CLASS_GUARANTEED:
            slot = find_next_available_slot(manager, QOS_CLASS_GUARANTEED);
            break;
        case QOS_CLASS_CRITICAL:
            slot = find_next_available_slot(manager, QOS_CLASS_CRITICAL);
            break;
    }

    // Create a new connection object and set the socket
    connection_t* conn = &manager->connections[get_qos_class(socket)][slot];
    conn->socket = socket;

    // Set the connection state to connecting
    conn->state = CONN_STATE_CONNECTING;

    // Start the connection establishment process
    if (connect(conn->socket, (struct sockaddr*)&conn->address, sizeof(conn->address)) < 0) {
        perror("Failed to connect");
        conn->state = CONN_STATE_IDLE;
    } else {
        conn->state = CONN_STATE_ESTABLISHED;
    }
}

// Define the function to find the next available connection slot for a given QoS class
size_t find_next_available_slot(conn_manager_t* manager, qos_class_t qos_class) {
    // Initialize the next available slot index
    size_t slot = 0;

    // Search for the first unused connection slot in the given QoS class
    while (slot < MAX_CONNECTIONS && manager->connections[qos_class][slot].state != CONN_STATE_IDLE) {
        ++slot;
    }

    // Return the next available slot index
    return slot;
}

// Define the function to get the QoS class of a given socket
qos_class_t get_qos_class(int socket) {
    // Get the priority class of the socket
    int prio = getsockopt(socket, SOL_SOCKET, SO_PRIORITY);

    // Return the corresponding QoS class
    switch (prio) {
        case 0:
            return QOS_CLASS_BEST_EFFORT;
        case 1:
            return QOS_CLASS_GUARANTEED;
        case 2:
            return QOS_CLASS_CRITICAL;
    }
}

// Define the function to handle a connection establishment request
void handle_establishment(conn_manager_t* manager, int socket) {
    // Get the next available connection slot for the QoS class of the incoming connection
    size_t slot = find_next_available_slot(manager, get_qos_class(socket));

    // Create a new connection object and set the socket
    connection_t* conn = &manager->connections[get_qos_class(socket)][slot];
    conn->socket = socket;

    // Set the connection state to establishing
    conn->state = CONN_STATE_ESTABLISHING;

    // Start the connection establishment process
    if (connect(conn->socket, (struct sockaddr*)&conn->address, sizeof(conn->address)) < 0) {
        perror("Failed to connect");
        conn->state = CONN_STATE_IDLE;
    } else {
        conn->state = CONN_STATE_ESTABLISHED;
    }
}

// Define the function to handle a connection termination request
void handle_termination(conn_manager_t* manager, int socket) {
    // Get the QoS class of the incoming connection
    qos_class_t qos_class = get_qos_class(socket);

    // Find the corresponding connection object
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (manager->connections[qos_class][i].state != CONN_STATE_IDLE && manager->connections[qos_class][i].socket == socket) {
            // Set the connection state to closing
            manager->connections[qos_class][i].state = CONN_STATE_CLOSING;

            // Close the socket
            close(manager->connections[qos_class][i].socket);

            // Set the connection state to closed
            manager->connections[qos_class][i].state = CONN_STATE_CLOSED;
        }
    }
}

// Define the function to handle a message transmission request
void handle_transmission(conn_manager_t* manager, int socket) {
    // Get the QoS class of the incoming connection
    qos_class_t qos_class = get_qos_class(socket);

    // Find the corresponding connection object
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (manager->connections[qos_class][i].state != CONN_STATE_IDLE && manager->connections[qos_class][i].socket == socket) {
            // Set the connection state to transmitting
            manager->connections[qos_class][i].state = CONN_STATE_TRANSMITTING;

            // Start the message transmission process
            send(manager->connections[qos_class][i].socket, manager->buffer, BUFFER_SIZE, 0);
        }
    }
}
