void populate_nfapi_crc_indication_pdu_list(int n, int rx_ue_information_tag, uint16_t rnti, char crc_indication_rel8_tag[2]) {
  // Create a list of NFAPI_CRC_INDICATION_PDU_T structures
  NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);

