    nfapi_crc_indication_pdu_list[i].rx_ue_information_tag = rx_ue_information_tag;
    nfapi_crc_indication_pdu_list[i].rnti = rnti + i;
    memcpy(nfapi_crc_indication_pdu_list[i].crc_indication_rel8_tag, crc_indication_rel8_tag, 2);
  }

  // Resolve a list of hostnames concurrently using an asynchronous DNS resolution mechanism with a callback for handling resolved IPs
  struct addrinfo *addr_list;
  getaddrinfo("example.com", NULL, &hints, &addr_list);
  pthread_t thread;
  int rc = pthread_create(&thread, NULL, resolve_hostname_async, (void *)addr_list);
  if (rc) {
    printf("Error creating thread: %d\n", rc);
    return;
  }

  // DNS caching to optimize performance for repeated queries
  struct addrinfo *cache = NULL;
  int cache_size = 0;
  for (struct addrinfo *cur = addr_list; cur != NULL; cur = cur->ai_next) {
    if (!resolve_cached(cur, &cache, &cache_size)) {
      // If the hostname is not cached, resolve it asynchronously and cache the result
      pthread_t thread;
      int rc = pthread_create(&thread, NULL, resolve_hostname_async, (void *)cur);
      if (rc) {
        printf("Error creating thread: %d\n", rc);
        return;
      }
    }
  }

  // Handle memory allocation and deallocation carefully to prevent leaks and ensure thread-safety
  void *addr_buf = malloc(cache_size);
  for (struct addrinfo *cur = cache; cur != NULL; cur = cur->ai_next) {
    struct sockaddr_in *addr = (struct sockaddr_in *)cur->ai_addr;
    memcpy(addr_buf + (cur - cache) * sizeof(struct sockaddr_in), addr, sizeof(struct sockaddr_in));
  }
  freeaddrinfo(cache);
  free(addr_buf);
}

// Function to resolve a hostname asynchronously using an asynchronous DNS resolution mechanism with a callback for handling resolved IPs
void *resolve_hostname_async(void *arg) {
  struct addrinfo *addr_list = (struct addrinfo *)arg;

  // Perform DNS resolution asynchronously using the getaddrinfo() function
  struct addrinfo hints;
  memset(&hints, 0, sizeof(struct addrinfo));
  hints.ai_family = AF_UNSPEC;
  hints.ai_socktype = SOCK_DGRAM;
  int rc = getaddrinfo(NULL, NULL, &hints, &addr_list);
  if (rc) {
    printf("Error resolving hostname: %d\n", rc);
    return NULL;
  }

  // Create a thread-safe queue to handle the resolved IP addresses
  pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
  pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
  struct addrinfo *addr_queue = NULL;

  // Process the resolved IP addresses and add them to the queue
  for (struct addrinfo *cur = addr_list; cur != NULL; cur = cur->ai_next) {
    pthread_mutex_lock(&mutex);
    struct addrinfo *new_addr = malloc(sizeof(struct addrinfo));
    memcpy(new_addr, cur, sizeof(struct addrinfo));
    new_addr->ai_next = addr_queue;
    addr_queue = new_addr;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
  }
  freeaddrinfo(addr_list);

  // Wait for the queue to be empty before returning
  while (1) {
    pthread_mutex_lock(&mutex);
    if (addr_queue == NULL) {
      pthread_cond_wait(&cond, &mutex);
    } else {
      break;
    }
    pthread_mutex_unlock(&mutex);
  }
  return NULL;
}

// Function to resolve a hostname asynchronously using an asynchronous DNS resolution mechanism with a callback for handling resolved IPs
int resolve_cached(struct addrinfo *addr, struct addrinfo **cache, int *cache_size) {
  // Check if the cache is already populated
  if (*cache == NULL) {
    return 0;
  }

  // Search for a cached entry that matches the specified hostname and family
  for (struct addrinfo *cur = *cache; cur != NULL; cur = cur->ai_next) {
    if (!strcmp(addr->ai_canonname, cur->ai_canonname) && addr->ai_family == cur->ai_family) {
      // If a matching entry is found, return it and update the cache size
      *cache_size = cur - *cache;
      return 1;
    }
  }
  return 0;
}
