  // Initialize the counters for the number of valid structures added to the list and discarded due to exceeding the memory limit
  int numValidStructures = 0;
  int numDiscardedStructures = 0;

  // Set the maximum threshold for total memory usage in kilobytes
  int maxMemoryUsage = 1024; // 1 MB

  // Create a mutex to ensure thread-safe operations
  pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

  while (true) {
