// Define the linked list insertion function
void insertNode(Node **head, Node **tail, NFAPI_CRC_INDICATION_PDU_T *pdu) {
  // Allocate memory for a new node and set its value to the given pdu pointer
  Node *newNode = malloc(sizeof(Node));
  newNode->pdu = pdu;

  // If the list is empty, set the head and tail pointers to the new node
  if (*head == NULL) {
    *head = newNode;
    *tail = newNode;
  } else {
    // Otherwise, update the tail pointer to point to the new node
    *tail->next = newNode;
    *tail = newNode;
  }
}

// Define the linked list deletion function
void deleteNode(Node **head, Node **tail, int tag) {
  // If the list is empty, return
  if (*head == NULL) {
    return;
  }

  // If the head pointer points to a node with the given tag, set the head pointer to the next node in the list and free the memory for the deleted node
  if ((*head)->pdu->RX_UE_INFORMATION_TAG == tag) {
