// UE context struct
struct UEContext {
    uint64_t ueId; // Unique UE ID
    uint8_t macAddress[6]; // MAC address of the UE
    std::vector<PDUSession> pdusessions; // Vector of PDU sessions associated with the UE
};

// PDU session struct
struct PDUSession {
    uint32_t id; // Unique ID for the PDU session
    uint64_t imsi; // IMSI associated with the PDU session
    std::string ipAddress; // IP address of the UE
};

// Main data structure to manage UE contexts and PDU sessions
class UEManger {
private:
    std::unordered_map<uint64_t, UEContext> ueMap; // Map of UE IDs to their corresponding contexts
    std::mutex mutex; // Mutex for thread-safe access to the data structure
public:
    UEManger() {
        // Initialize the data structure with a fixed capacity
        ueMap.reserve(1000);
    }

    // Add a new UE context to the data structure
    void addUEContext(uint64_t ueId, uint8_t macAddress[6], std::vector<PDUSession> pdusessions) {
        std::lock_guard<std::mutex> lock(mutex);
        UEContext context;
        context.ueId = ueId;
        memcpy(context.macAddress, macAddress, 6);
        context.pdusessions = pdusessions;
        ueMap[ueId] = context;
    }

    // Update a PDU session associated with an existing UE context
    void updatePDUSession(uint64_t ueId, uint32_t sessionId, std::string ipAddress) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = ueMap.find(ueId);
        if (it != ueMap.end()) {
            for (auto& pdusession : it->second.pdusessions) {
                if (pdusession.id == sessionId) {
                    pdusession.ipAddress = ipAddress;
                    return;
                }
            }
        }
    }

    // Remove a PDU session associated with an existing UE context
    void removePDUSession(uint64_t ueId, uint32_t sessionId) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = ueMap.find(ueId);
        if (it != ueMap.end()) {
            for (auto& pdusession : it->second.pdusessions) {
                if (pdusession.id == sessionId) {
                    it->second.pdusessions.erase(std::remove_if(it->second.pdusessions.begin(), it->second.pdusessions.end(), [&](PDUSession session){ return session.id == sessionId; }));
                    if (it->second.pdusessions.empty()) {
                        ueMap.erase(ueId);
                    }
                }
            }
        }
    }

    // Get the PDU sessions associated with a given UE ID
    std::vector<PDUSession> getPDUsessions(uint64_t ueId) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = ueMap.find(ueId);
        if (it != ueMap.end()) {
            return it->second.pdusessions;
        }
    }

};

// Main function to demonstrate the usage of the UEManger class
int main() {
    UEManger manager;

    // Add a new UE context with ID 1234, MAC address 00:00:5E:00:53:01, and 2 PDU sessions
    manager.addUEContext(1234, {0x00, 0x00, 0x5e, 0x00, 0x53, 0x01}, {{"session-1", "192.168.1.1"}, {"session-2", "192.168.1.2"}});

