    NFAPI_CRC_INDICATION_PDU_T* crc_array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_array) {
        printf("Error: Failed to allocate memory for CRC indication array\n");
        return NULL;
    }

    // Populate the array with unique RX_UE_INFORMATION_TAG values
    uint16_t tag = 0;
    for (int i = 0; i < N; i++) {
        crc_array[i].RX_UE_INFORMATION_TAG = tag++;
    }

    // Assign unique RNTIs and set CRCFLAG to random values
    uint32_t rnti = 0;
    for (int i = 0; i < N; i++) {
        crc_array[i].RNTI = rnti++;
        crc_array[i].CRCFLAG = rand() % 2 == 1;
    }

    // Verify that at least one element has a CRCFLAG set to 1
    assert(crc_array->CRCFLAG);

    return crc_array;
}

// Function to free the allocated memory when no longer needed
void free_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T* crc_array) {
