#include <stdlib.h>
#include <stdbool.h>

typedef struct TX_EVM_MEASUREMENT {
    int tag;
    unsigned long time_slot;
    int evm_value;
} TX_EVM_MEASUREMENT;

// Linked list node structure
typedef struct LIST_NODE {
    TX_EVM_MEASUREMENT measurement;
    struct LIST_NODE *next;
} LIST_NODE;

// Function prototypes
void init_list(int n);
void add_node(TX_EVM_MEASUREMENT measurement);
bool is_full();
void free_list();
void print_list();

#endif // LINKED_LIST_H

// C source file: linked_list.c
#include "linked_list.h"

// Linked list head
static LIST_NODE *head = NULL;

// Number of nodes in the list
static int num_nodes = 0;

// Maximum number of nodes allowed in the list
static const int MAX_NODES = 1000;

void init_list(int n) {
    // Check input validation
    if (n < 1 || n > MAX_NODES) {
        return;
    }

    // Initialize the list with the given number of nodes
    num_nodes = n;

    // Allocate memory for the linked list nodes
    head = (LIST_NODE *) malloc(sizeof(LIST_NODE) * n);
    if (!head) {
        return;
    }
}

void add_node(TX_EVM_MEASUREMENT measurement) {
    // Check if the list is full
    if (is_full()) {
        return;
    }

    // Add a new node to the linked list
    LIST_NODE *new_node = (LIST_NODE *) malloc(sizeof(LIST_NODE));
    if (!new_node) {
        return;
    }

    // Set the measurement data for the new node
    new_node->measurement.tag = measurement.tag;
    new_node->measurement.time_slot = measurement.time_slot;
    new_node->measurement.evm_value = measurement.evm_value;

    // Add the new node to the end of the linked list
    LIST_NODE *current = head;
    while (current->next) {
        current = current->next;
    }
    current->next = new_node;
}

bool is_full() {
    // Check if the number of nodes exceeds the maximum allowed
    return num_nodes >= MAX_NODES;
}

void free_list() {
    // Free the memory allocated for the linked list nodes
    LIST_NODE *current = head;
    while (current) {
        LIST_NODE *next = current->next;
        free(current);
        current = next;
    }
}

void print_list() {
    // Print the contents of the linked list for debugging purposes
    LIST_NODE *current = head;
    while (current) {
        printf("Node %d: tag=%d, time_slot=%lu, evm_value=%d\n", current->measurement.tag, current->measurement.time_slot, current->measurement.evm_value);
        current = current->next;
    }
}

