void insert(NFAPI_CRC_INDICATION_PDU_T data) {
    // Get the current time in seconds and nanoseconds
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    int sequenceNumber = (int)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);

    // Create a new node and insert it at the head of the list
    Node* newNode = malloc(sizeof(Node));
    newNode->data = data;
    newNode->sequenceNumber = sequenceNumber;
    newNode->next = head;
    head = newNode;

