    // Search for a node with the same RX_UE_INFORMATION_TAG and RNTI as the input data
    Node* current = head;
    while (current != NULL) {
        if (current->data.rx_ue_information_tag == data.rx_ue_information_tag &&
            current->data.rnti == data.rnti) {
            break;
        }
        current = current->next;
    }

    // Unlock the linked list after searching
    pthread_mutex_unlock(&lock);

    return current;
}

// Function to remove a node from the linked list based on its sequence number
void remove(int sequenceNumber) {
    // Lock the linked list before removing
    pthread_mutex_lock(&lock);

    // Search for a node with the same sequence number as the input parameter
