        // If so, shift all subsequent entries one position to the left
        memmove(&list->list[index], &list->list[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size - index));

        // Decrement the list size
        --list->size;
    }
}

