// Define a structure to represent a PDU
typedef struct MAC_PDU {
    unsigned char *data;
    size_t size;
    enum L2_PDU_TYPE type;
} MAC_PDU;

// A dynamic array of MAC_PDU structures, with thread-safe access
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static MAC_PDU *pdus[MAX_PDUS] = {NULL};

// Function to add a new PDU to the array
int mac_pdu_add(enum L2_PDU_TYPE type, size_t size) {
    // Check for valid input parameters
    if (type > MAX_L2_PDU_TYPE || size > MAX_L2_PDU_SIZE) {
        return -1;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Find an empty slot in the array and allocate memory for the PDU
    int i = 0;
    while (pdus[i] != NULL) {
        i++;
        if (i == MAX_PDUS) {
            break;
        }
    }
    if (i == MAX_PDUS) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    pdus[i] = malloc(sizeof(MAC_PDU));
    pdus[i]->data = malloc(size);
    pdus[i]->size = size;
    pdus[i]->type = type;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return i;
}

// Function to update the payload content of an existing PDU
int mac_pdu_update(int index, unsigned char *data, size_t size) {
    // Check for valid input parameters and existence of a PDU with that index
    if (index < 0 || index >= MAX_PDUS || pdus[index] == NULL) {
        return -1;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Ensure that the new data fits within the allocated size
    if (pdus[index]->size < size) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Copy the new data into the PDU's buffer
    memcpy(pdus[index]->data, data, size);
    pdus[index]->size = size;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to clean up unused elements in the array periodically
void mac_pdu_cleanup() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Iterate over the array and free any empty slots
    for (int i = 0; i < MAX_PDUS; i++) {
        if (pdus[i] != NULL && pdus[i]->size == 0) {
            free(pdus[i]->data);
            free(pdus[i]);
            pdus[i] = NULL;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}
