    // Acquire a lock to prevent race conditions
    acquire_lock(&mutex);

    // Call the function with the input parameters
    int count = create_crc_indication_pdu(pdu_list, num_pdus);
    if (count < 0) {
        handle_error(count);
        release_lock(&mutex);
        return;
    }

    // Log the successful PDUs
    printf("Successfully created %d NFAPI_CRC_INDICATION_PDU_T structures\n", count);

    // Release the lock
    release_lock(&mutex);
}']

