package com.example.util;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Utility class for computing the MD5 hash of a variable-length input string,
 * with optimal performance and minimal memory usage.
 */
public class Md5Hasher {
    private static final Logger LOGGER = LoggerFactory.getLogger(Md5Hasher.class);

    /** The number of threads to use for parallel processing. */
    public static final int THREAD_COUNT = 4;

    /** The maximum amount of time to wait for each thread to finish. */
    public static final long TIMEOUT_MILLIS = 1000L;

    /** The maximum amount of memory to use for buffering data. */
    public static final int MAX_BUFFER_SIZE = 512 * 1024;

    private Md5Hasher() {}

    /**
     * Computes the MD5 hash of a variable-length input string, with optimal performance and minimal memory usage.
     *
     * @param input The input string to hash.
     * @return The MD5 hash of the input string.
     */
    public static String computeHash(String input) {
        // Use a configurable number of threads for parallel processing
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_COUNT);
        try {
            // Split the input into chunks and submit them to the executor service
            List<Callable<String>> tasks = new ArrayList<>();
            int chunkSize = (int) Math.ceil((double) input.length() / THREAD_COUNT);
            for (int i = 0; i < input.length(); i += chunkSize) {
                tasks.add(() -> computeHash(input, i, Math.min(i + chunkSize, input.length())));
            }

            // Use a configurable timeout for each thread to finish
            long startTime = System.currentTimeMillis();
            List<Future<String>> futures = executor.invokeAll(tasks, TIMEOUT_MILLIS, TimeUnit.MILLISECONDS);

            // Wait for all threads to finish and combine the results
            StringBuilder resultBuilder = new StringBuilder();
            for (Future<String> future : futures) {
                try {
                    resultBuilder.append(future.get());
                } catch (InterruptedException | ExecutionException e) {
                    LOGGER.error("Error computing MD5 hash", e);
                }
            }
            long endTime = System.currentTimeMillis();

            // Log execution metrics and return the result
            LOGGER.info("Computed MD5 hash for {} characters in {} ms ({} MB)", input.length(), endTime - startTime,
                    getMemoryUsage(resultBuilder.toString()));
            return resultBuilder.toString();
        } catch (TimeoutException e) {
            LOGGER.warn("Timed out computing MD5 hash", e);
            return "";
        } finally {
            executor.shutdown();
        }
    }

    /** Computes the MD5 hash of a portion of an input string. */
    private static String computeHash(String input, int startIndex, int endIndex) {
        try {
            // Create a MessageDigest instance for computing the MD5 hash
            MessageDigest digester = MessageDigest.getInstance("MD5");

            // Update the digester with the portion of the input string to be hashed
            byte[] buffer = new byte[MAX_BUFFER_SIZE];
            int readBytes;
            int offset = 0;
            while (startIndex < endIndex && (readBytes = input.substring(startIndex, endIndex).getBytes("UTF-8", buffer, offset, MAX_BUFFER_SIZE)) > 0) {
                digester.update(buffer, 0, readBytes);
                startIndex += readBytes;
            }

            // Return the hashed result as a hexadecimal string
            byte[] result = digester.digest();
            return DatatypeConverter.printHexBinary(result).toLowerCase();
        } catch (NoSuchAlgorithmException | UnsupportedEncodingException e) {
            LOGGER.error("Error computing MD5 hash", e);
            return "";
        }
    }

    /** Returns the memory usage of a string in MB. */
    private static double getMemoryUsage(String input) {
        return (input.length() * 2L) / (1024 * 1024);
    }
}
