// Define data structure for UE measurement records
typedef struct {
    int ue_id;
    time_t timestamp;
    SignalStrengthSample *signal_strength_samples;
} UeMeasurementRecord;

// Define data structure for signal strength samples
typedef struct {
    time_t sample_time;
    int signal_strength;
    bool quality_indicator;
} SignalStrengthSample;

// Define function to initialize and populate an array of UE measurement records
UeMeasurementRecord *initialize_ue_measurement_records(int num_ue, int num_samples) {
    // Allocate memory for the array of UE measurement records
    UeMeasurementRecord *ue_measurement_records = malloc(num_ue * sizeof(UeMeasurementRecord));
    if (ue_measurement_records == NULL) {
        // Handle error during memory allocation
        return NULL;
    }

    // Initialize each UE measurement record with a unique identifier, timestamp, and signal strength samples
    for (int i = 0; i < num_ue; i++) {
        ue_measurement_records[i].ue_id = i + 1;
        ue_measurement_records[i].timestamp = time(NULL);
        ue_measurement_records[i].signal_strength_samples = malloc(num_samples * sizeof(SignalStrengthSample));
        if (ue_measurement_records[i].signal_strength_samples == NULL) {
            // Handle error during memory allocation for signal strength samples
            free(ue_measurement_records);
            return NULL;
        }

        for (int j = 0; j < num_samples; j++) {
            ue_measurement_records[i].signal_strength_samples[j].sample_time = time(NULL);
            ue_measurement_records[i].signal_strength_samples[j].signal_strength = generate_random_signal_strength();
            ue_measurement_records[i].signal_strength_samples[j].quality_indicator = generate_random_quality_indicator();
        }
    }

    return ue_measurement_records;
}

// Define function to generate random signal strength and quality indicator values within specified ranges
int generate_random_signal_strength() {
    // Generate random signal strength value between 0 and 31
    int signal_strength = rand() % 32;
    return signal_strength;
}

// Define function to generate random quality indicator flag within specified ranges
bool generate_random_quality_indicator() {
    // Generate random quality indicator value between 0 and 1
    int quality_indicator = rand() % 2;
    return quality_indicator ? true : false;
}

// Define function to track the number of successfully created structures
int count_created_structures(UeMeasurementRecord *ue_measurement_records, int num_ue) {
    int count = 0;
    for (int i = 0; i < num_ue; i++) {
        if (ue_measurement_records[i].signal_strength_samples != NULL) {
            count++;
        }
    }
    return count;
}

// Define function to handle memory allocation failures gracefully with error logging
void handle_memory_allocation_failure(UeMeasurementRecord *ue_measurement_records, int num_ue) {
    // Log error message and free allocated memory for failed structures
    for (int i = 0; i < num_ue; i++) {
        if (ue_measurement_records[i].signal_strength_samples == NULL) {
            printf("Error: Memory allocation failure for UE measurement record %d\n", i + 1);
            free(ue_measurement_records[i].signal_strength_samples);
        }
    }
}
```
In this example, the `initialize_ue_measurement_records` function takes two parameters: `num_ue`, the number of UE identifiers to be processed, and `num_samples`, the number of signal strength samples to be generated for each UE identifier. The function returns a dynamically allocated array of `UeMeasurementRecord` structures, each containing a unique UE identifier, a timestamp, and a vector of `SignalStrengthSample` structures.

The function first allocates memory for the array of `UeMeasurementRecord` structures using `malloc`. If the allocation fails, the function returns NULL to indicate an error.

Next, the function initializes each `UeMeasurementRecord` structure with a unique identifier and timestamp. It then allocates memory for the vector of `SignalStrengthSample` structures within each record. If the allocation fails, the function frees the previously allocated memory and returns NULL to indicate an error.

Within the loop that generates the signal strength samples, the function uses `generate_random_signal_strength()` and `generate_random_quality_indicator()` to generate random signal strength and quality indicator values within specified ranges. It then populates each `SignalStrengthSample` structure with these values.

The function also defines a helper function `count_created_structures()` that counts the number of successfully created structures. The `handle_memory_allocation_failure()` function handles memory allocation failures by logging an error message and freeing allocated memory for failed structures.

In a real-world scenario, this function can be used to process a batch of UE information tags and return the list of successfully processed structures along with their counts. For example:
```c
#include <stdio.h>
