typedef struct TrafficFlowStats {
    int packet_loss; // Percentage of packets lost during the session
    double throughput; // Average data transfer rate (in Mbps)
    double latency; // Average latency (in milliseconds)
} TrafficFlowStats;

// Function to initialize a dynamic array of TrafficFlowStats structures, simulating traffic data based on realistic distribution patterns
TrafficFlowStats* init_traffic_data(int num_sessions) {
    // Allocate memory for the array of TrafficFlowStats structures
    TrafficFlowStats* traffic_data = (TrafficFlowStats*)malloc(num_sessions * sizeof(TrafficFlowStats));
    if (!traffic_data) {
        printf("Error: unable to allocate memory for traffic data\n");
        exit(1);
    }

    // Initialize the array with default values
    for (int i = 0; i < num_sessions; i++) {
        traffic_data[i].packet_loss = 5; // Default value if no data available from external source
        traffic_data[i].throughput = 1.5; // Default value if no data available from external source
        traffic_data[i].latency = 100; // Default value if no data available from external source
    }

    // Simulate traffic data based on realistic distribution patterns
    for (int i = 0; i < num_sessions; i++) {
        traffic_data[i].packet_loss = get_random_packet_loss(); // Get random packet loss percentage from external source or default value if no data available
        traffic_data[i].throughput = get_random_throughput(); // Get random throughput (in Mbps) from external source or default value if no data available
        traffic_data[i].latency = get_random_latency(); // Get random latency (in milliseconds) from external source or default value if no data available
    }

    return traffic_data;
}

// Function to retrieve a random packet loss percentage based on realistic distribution patterns
int get_random_packet_loss() {
    int min = 0, max = 100;
    double random_number = (double)rand() / RAND_MAX; // Generate random number between 0 and 1
    return min + (int)(random_number * (max - min)); // Convert to percentage
}

// Function to retrieve a random throughput (in Mbps) based on realistic distribution patterns
double get_random_throughput() {
    int min = 0, max = 100;
    double random_number = (double)rand() / RAND_MAX; // Generate random number between 0 and 1
    return min + (int)(random_number * (max - min)); // Convert to percentage
}

// Function to retrieve a random latency (in milliseconds) based on realistic distribution patterns
double get_random_latency() {
    int min = 0, max = 100;
    double random_number = (double)rand() / RAND_MAX; // Generate random number between 0 and 1
    return min + (int)(random_number * (max - min)); // Convert to percentage
}
