#define INVALID_ARGUMENTS_ERROR -2
#define MAX_SIZE_EXCEEDED_ERROR -3
#define RNTI_NOT_UNIQUE_ERROR -4
#define DUPLICATE_CONSECUTIVE_RNTIS_ERROR -5

// Define the logging levels
