#define LOGGING_ENABLED 1

// Define the function to initialize the arrays and allocate memory for them
int init_arrays(
    long *offset_values,
    int *keys,
    Record **records,
    NFAPI_CRC_INDICATION_PDU_T **nfapi_crc_indication_pdus,
    uint16_t *num_allocated_structures,
    bool clear_memory
) {
    // Validate the arguments
    if (!offset_values || !keys || !records || !nfapi_crc_indication_pdus || !num_allocated_structures) {
        return INVALID_ARGUMENTS_ERROR;
    }

    // Clear the memory if requested
    if (clear_memory) {
        memset(offset_values, 0, sizeof(long) * MAX_OFFSET_VALUES);
        memset(keys, 0, sizeof(int) * MAX_KEYS);
        memset(records, 0, sizeof(Record *) * MAX_RECORDS);
        memset(nfapi_crc_indication_pdus, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * MAX_RNTI);
    }

    // Initialize the arrays with default values
    for (int i = 0; i < MAX_OFFSET_VALUES; i++) {
        offset_values[i] = 0;
    }
    for (int i = 0; i < MAX_KEYS; i++) {
        keys[i] = 1;
    }
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i] = NULL;
    }
    for (int i = 0; i < MAX_RNTI; i++) {
        nfapi_crc_indication_pdus[i] = NULL;
    }

    // Set the number of allocated structures to zero
    *num_allocated_structures = 0;

    return OK;
}

// Define the function to add a new structure to the arrays and allocate memory for it
int add_new_structure(
    long *offset_values,
    int *keys,
    Record **records,
    NFAPI_CRC_INDICATION_PDU_T **nfapi_crc_indication_pdus,
    uint16_t *num_allocated_structures,
    uint8_t RX_UE_INFORMATION_TAG,
    uint16_t RNTI,
    uint8_t CRC_INDICATION_REL8_TAG,
    int32_t value,
    char *name
) {
    // Validate the arguments
    if (!offset_values || !keys || !records || !nfapi_crc_indication_pdus || !num_allocated_structures) {
        return INVALID_ARGUMENTS_ERROR;
    }

    // Check if the RNTI is unique and not exceeding the maximum value
    for (int i = 0; i < *num_allocated_structures; i++) {
        if (RNTI == nfapi_crc_indication_pdus[i]->RNTI) {
            return RNTI_NOT_UNIQUE_ERROR;
        }
    }
    if (RNTI > MAX_RNTI) {
        return MAX_SIZE_EXCEEDED_ERROR;
    }

    // Check if there is enough memory to allocate a new structure
    if (*num_allocated_structures >= MAX_RECORDS) {
        return MAX_SIZE_EXCEEDED_ERROR;
    }

    // Allocate memory for the new structure
    records[*num_allocated_structures] = (Record *) malloc(sizeof(Record));
    if (!records[*num_allocated_structures]) {
        return MEMORY_ALLOCATION_ERROR;
    }

    // Initialize the new structure
    records[*num_allocated_structures]->value = value;
    strcpy(records[*num_allocated_structures]->name, name);

    // Allocate memory for the NFAPI_CRC_INDICATION_PDU_T structure
    nfapi_crc_indication_pdus[RNTI] = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfapi_crc_indication_pdus[RNTI]) {
        return MEMORY_ALLOCATION_ERROR;
