    // Initialize the NFAPI_CRC_INDICATION_PDU_T structure
    nfapi_crc_indication_pdus[RNTI]->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    nfapi_crc_indication_pdus[RNTI]->RNTI = RNTI;
    nfapi_crc_indication_pdus[RNTI]->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    nfapi_crc_indication_pdus[RNTI]->length = 0;

    // Add the new structure to the arrays
    offset_values[*num_allocated_structures] = 0;
    keys[*num_allocated_structures] = RNTI;
    (*num_allocated_structures)++;

    return OK;
}

