// Define the structure for logging events
typedef struct LogEventRecord {
    // The log level (debug, info, warning, error)
    int logLevel;

    // The message to be logged
    char* message;
} LOG_EVENT_RECORD_T;

// Define the linked list node for storing log event records
typedef struct LogEventRecordNode {
    // The log event record itself
    LOG_EVENT_RECORD_T record;

    // Pointer to the next node in the list
    struct LogEventRecordNode* next;
} LOG_EVENT_RECORD_NODE_T;

// Define the linked list for storing log event records
typedef struct LogEventRecordList {
    // The head of the list (first allocated record)
    LOG_EVENT_RECORD_NODE_T* head;

    // The tail of the list (last allocated record)
    LOG_EVENT_RECORD_NODE_T* tail;

    // The number of records in the list
    size_t count;
} LOG_EVENT_RECORD_LIST_T;

// Define the function to dynamically allocate and initialize a linked list of log event records
LOG_EVENT_RECORD_LIST_T* LogEventRecordListInit(void) {
    // Allocate memory for the list structure
    LOG_EVENT_RECORD_LIST_T* list = malloc(sizeof(LOG_EVENT_RECORD_LIST_T));

    // Initialize the count to 0 and the head and tail pointers to NULL
    list->count = 0;
    list->head = NULL;
    list->tail = NULL;

    return list;
}

// Define the function to allocate a new log event record in the linked list
LOG_EVENT_RECORD_NODE_T* LogEventRecordAlloc(int logLevel, const char* message) {
    // Allocate memory for the record structure
    LOG_EVENT_RECORD_NODE_T* node = malloc(sizeof(LOG_EVENT_RECORD_NODE_T));

    // Initialize the record with the provided log level and message
    node->record.logLevel = logLevel;
    node->record.message = strdup(message);

    return node;
}

// Define the function to insert a new log event record into the linked list
void LogEventRecordInsert(LOG_EVENT_RECORD_LIST_T* list, int logLevel, const char* message) {
    // Allocate a new log event record and initialize it with the provided log level and message
    LOG_EVENT_RECORD_NODE_T* node = LogEventRecordAlloc(logLevel, message);

    // Insert the new record into the list
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }

    // Increment the count of records in the list
    list->count++;
}

// Define the function to clear all allocated log event records and free their memory
void LogEventRecordClear(LOG_EVENT_RECORD_LIST_T* list) {
    // Loop through each record in the list and free its memory
    while (list->head != NULL) {
        LOG_EVENT_RECORD_NODE_T* node = list->head;
        list->head = node->next;
        free(node);
    }

    // Reset the tail pointer and count of records in the list
    list->tail = NULL;
    list->count = 0;
}

// Define the function to set the log level for all log event records in the linked list
void LogEventRecordSetLogLevel(LOG_EVENT_RECORD_LIST_T* list, int logLevel) {
    // Loop through each record in the list and update its log level
    LOG_EVENT_RECORD_NODE_T* node = list->head;
    while (node != NULL) {
        node->record.logLevel = logLevel;
        node = node->next;
    }
}

// Define the function to clear a single log event record from the linked list and free its memory
void LogEventRecordClear(LOG_EVENT_RECORD_LIST_T* list, int index) {
    // Check if the provided index is valid
    if (index < 0 || index >= list->count) {
        printf("Error: Invalid log event record index.\n");
        return;
    }

    // Loop through each record in the list until the one at the provided index is found
    LOG_EVENT_RECORD_NODE_T* node = list->head;
    int i = 0;
    while (i < index) {
        node = node->next;
        i++;
    }

    // Free the memory of the record at the provided index and update the linked list accordingly
    LOG_EVENT_RECORD_NODE_T* nextNode = node->next;
    free(node);
    if (nextNode == NULL) {
        list->tail = NULL;
    } else {
        list->tail = nextNode;
    }

    // Decrement the count of records in the list
    list->count--;
}
