NODE* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    NODE* node = (NODE*)malloc(sizeof(NODE));
    node->pdu = pdu;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

void insert_node(NODE** head, NFAPI_CRC_INDICATION_PDU_T pdu) {
    NODE* new_node = create_node(pdu);
    if (*head == NULL) {
        *head = new_node;
    } else {
        NODE* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
        new_node->prev = current;
    }
}

void remove_node(NODE** head, NFAPI_CRC_INDICATION_PDU_T pdu) {
    NODE* node = *head;
    if (node != NULL && node->pdu.RX_UE_INFORMATION_TAG == pdu.RX_UE_INFORMATION_TAG) {
