// Structure to represent a Network Interface Control Protocol (NICP) frame
typedef struct NICP_FRAME {
    uint16_t RX_SESSION_TAG;
    uint8_t MAC_ADDRESS[6];
    uint16_t VLAN_ID;
} NICP_FRAME;

// Structure to represent a TX_PACKET_TAG structure
typedef struct TX_PACKET_TAG {
    uint32_t packetSequenceNumber;
    uint16_t payloadLength;
} TX_PACKET_TAG;

// Structure to represent the dynamic array of Network Interface Control Protocol (NICP) frames
typedef struct NICP_FRAMES {
    size_t capacity;
    size_t count;
    NICP_FRAME* frames;
} NICP_FRAMES;

// Function to dynamically manage a doubly linked list of NFAPI_CRC_INDICATION_PDU structures
void* dynamicListManage(void* data, bool add) {
    ListNode* newNode = NULL;
    if (data != NULL) {
        // Create a new node with the given data
        newNode = malloc(sizeof(ListNode));
        newNode->data = data;
        newNode->next = NULL;
        newNode->prev = NULL;
    }

    ListNode* head = NULL;
    ListNode* tail = NULL;
    if (add) {
        // Add the new node to the end of the list
        if (head == NULL && tail == NULL) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            newNode->prev = tail;
            tail = newNode;
        }
    } else {
        // Remove the first node from the list and return its data
        if (head == NULL && tail == NULL) {
            return NULL;
        } else {
            head = head->next;
            free(tail);
            tail = NULL;
        }
    }

    return head;
}

// Function to dynamically manage a dynamic array of Network Interface Control Protocol (NICP) frames
void* nicpFramesManage(NICP_FRAMES* frames, bool add) {
    if (frames->count == 0 && !add) {
        // Return NULL if the list is empty and we're not adding a new frame
        return NULL;
    } else if (frames->count == frames->capacity && add) {
        // Reallocate memory for the array if it's full
        size_t newCapacity = frames->capacity * 2;
        NICP_FRAME* newFrames = realloc(frames->frames, newCapacity);
        assert(newFrames != NULL);
        frames->frames = newFrames;
        frames->capacity = newCapacity;
    }

    if (add) {
        // Add a new frame to the array
        NICP_FRAME* frame = &frames->frames[frames->count];
        memcpy(frame, data, sizeof(NICP_FRAME));
        frames->count++;
    } else {
        // Remove the first frame from the array and return its data
        NICP_FRAME* frame = &frames->frames[0];
        memmove(frame, frame + 1, sizeof(NICP_FRAME) * (frames->count - 1));
        frames->count--;
    }

    return frames;
}

// Function to dynamically manage a doubly linked list of TX_PACKET_TAG structures
void* txPacketTagsManage(TX_PACKET_TAG* tags, bool add) {
    if (tags->count == 0 && !add) {
        // Return NULL if the list is empty and we're not adding a new tag
        return NULL;
    } else if (tags->count == tags->capacity && add) {
        // Reallocate memory for the array if it's full
        size_t newCapacity = tags->capacity * 2;
        TX_PACKET_TAG* newTags = realloc(tags->frames, newCapacity);
        assert(newTags != NULL);
        tags->frames = newTags;
        tags->capacity = newCapacity;
    }

    if (add) {
        // Add a new tag to the array
        TX_PACKET_TAG* tag = &tags->frames[tags->count];
        memcpy(tag, data, sizeof(TX_PACKET_TAG));
        tags->count++;
    } else {
        // Remove the first tag from the array and return its data
        TX_PACKET_TAG* tag = &tags->frames[0];
        memmove(tag, tag + 1, sizeof(TX_PACKET_TAG) * (tags->count - 1));
        tags->count--;
    }

    return tags;
}

int main() {
    // Initialize the dynamic arrays of Network Interface Control Protocol (NICP) frames and TX_PACKET_TAG structures
    NICP_FRAMES* nicpFrames = malloc(sizeof(NICP_FRAMES));
    nicpFrames->capacity = 10;
    nicpFrames->count = 0;
    nicpFrames->frames = malloc(nicpFrames->capacity * sizeof(NICP_FRAME));

    TX_PACKET_TAG* txPacketTags = malloc(sizeof(TX_PACKET_TAG));
    txPacketTags->capacity = 10;
    txPacketTags->count = 0;
    txPacketTags->frames = malloc(txPacketTags->capacity * sizeof(TX_PACKET_TAG));

    // Loop until we receive a signal to stop
