            NICP_FRAME* nicpFrame = malloc(sizeof(NICP_FRAME));
            memcpy(nicpFrame, buffer, sizeof(NICP_FRAME));

            // Add the new frame to the list of frames
            dynamicListManage((void*)nicpFrame, true);

            // Check if the received frame contains a TX packet tag
            for (size_t i = 0; i < nicpFrame->numberOfTags; i++) {
                // If the frame contains a TX packet tag, add it to the list of tags
                if (nicpFrame->tags[i].tagId == NICP_TX_PACKET_TAG) {
                    TX_PACKET_TAG* txPacketTag = malloc(sizeof(TX_PACKET_TAG));
                    memcpy(txPacketTag, &nicpFrame->tags[i], sizeof(TX_PACKET_TAG));
                    dynamicListManage((void*)txPacketTag, true);
                }
            }
