void populateList(NFAPI_CRC_INDICATION_PDU_T **list, size_t count) {
    // Initialize cache for RNTIs
    Cache *cache = (Cache *)malloc(sizeof(Cache));
    cache->RNTIs = (uint32_t *)malloc(count * sizeof(uint32_t));
    cache->size = 0;

    // Populate doubly linked list with random CRCFLAG values
    for (int i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->RX_UE_INFORMATION_TAG = i;
