        list[i] = pdu;

        // Add RNTI to cache
        if (cache->size < count) {
            cache->RNTIs[cache->size++] = pdu->RNTI;
        } else {
            // Evict least recently used RNTI from cache
            uint32_t *old_rnti = cache->RNTIs + (cache->size - 1);
            uint32_t *new_rnti = old_rnti - 1;
            memcpy(old_rnti, new_rnti, sizeof(uint32_t));
            free(old_rnti);
            cache->size--;
        }
    }

    // Validate linked list for circular references and proper pointer alignment
    validateList(list, count);

    // Clean up cache
    free(cache->RNTIs);
    free(cache);
}

// Fetch RNTI value from external data source using caching strategy
uint32_t fetchRNTI() {
    // Use cache if available and recent enough
    Cache *cache = (Cache *)malloc(sizeof(Cache));
    if (cache->size > 0) {
        uint32_t *rnti = cache->RNTIs + (rand() % cache->size);
        return *rnti;
    }

    // Fetch new RNTI value from external data source
    uint32_t rnti = rand() % 1000000;
    printf("Fetched new RNTI value: %u\n", rnti);

    // Add new RNTI to cache if space available
    if (cache->size < count) {
        cache->RNTIs[cache->size++] = rnti;
    } else {
        // Evict least recently used RNTI from cache
        uint32_t *old_rnti = cache->RNTIs + (cache->size - 1);
        uint32_t *new_rnti = old_rnti - 1;
        memcpy(old_rnti, new_rnti, sizeof(uint32_t));
        free(old_rnti);
        cache->size--;
    }

    return rnti;
}

// Validate doubly linked list for circular references and proper pointer alignment
void validateList(NFAPI_CRC_INDICATION_PDU_T **list, size_t count) {
    // Check for circular references
    for (int i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = list[i];
        while (pdu != NULL) {
            if (pdu->RX_UE_INFORMATION_TAG == pdu->RNTI) {
                printf("Detected circular reference in PDU %u\n", i);
                return;
            }
            pdu = pdu->next;
        }
    }

    // Check for proper pointer alignment
    for (int i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = list[i];
        while (pdu != NULL) {
            if (!isAligned(pdu)) {
                printf("Detected misaligned pointer in PDU %u\n", i);
                return;
            }
            pdu = pdu->next;
        }
    }
}

// Check if pointer is properly aligned for memory access
bool isAligned(void *ptr) {
    uintptr_t addr = (uintptr_t)ptr;
    return ((addr % sizeof(uint32_t)) == 0);
}

// Garbage collection strategy to minimize memory leaks and support scalable growth
void garbageCollect(NFAPI_CRC_INDICATION_PDU_T **list, size_t count) {
    // Iterate over list and free any PDUs that are no longer in use
    for (int i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = list[i];
        while (pdu != NULL) {
            if (!isInUse(pdu)) {
                // Free PDU and update pointers to skip over freed memory
                NFAPI_CRC_INDICATION_PDU_T *next = pdu->next;
                free(pdu);
                list[i] = next;
            } else {
                pdu = pdu->next;
            }
        }
    }
}

// Check if PDU is still in use
bool isInUse(NFAPI_CRC_INDICATION_PDU_T *pdu) {
