#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "NFAPI_CRC_INDICATION_PDU_T.h"

#define MAX_BUFFER_SIZE 5000
#define LOG_FILE_SIZE (1<<20) // 1 MB
#define NUM_LOG_FILES 10

// Circular buffer to store the NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *buffer[MAX_BUFFER_SIZE];

// Index of the next free slot in the circular buffer
int buffer_index = 0;

// Mutex for protecting the access to the circular buffer and the log file
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// File descriptor of the log files
FILE *log_files[NUM_LOG_FILES];

void manageQueue(NFAPI_CRC_INDICATION_PDU_T *msg) {
    // Check if the circular buffer is full, if so drop the oldest message
    if (buffer_index == MAX_BUFFER_SIZE) {
        pthread_mutex_lock(&mutex);
        free(buffer[buffer_index]);
        buffer_index--;
        pthread_mutex_unlock(&mutex);
    }

    // Add the new message to the circular buffer
    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T *new_msg = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(new_msg, msg, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    buffer[buffer_index] = new_msg;
    buffer_index++;
    pthread_mutex_unlock(&mutex);

    // Update the RNTI value in the log file name
    char log_file_name[256];
    sprintf(log_file_name, "log/%d.txt", new_msg->ue_id);

    // Open the log file if it doesn't exist or truncate to 0 bytes if it does
    int fd = open(log_file_name, O_RDWR|O_CREAT|O_TRUNC, 0644);
    if (fd < 0) {
        perror("Failed to open log file");
        exit(1);
    }

    // Write the creation details of the new message to the log file
    off_t offset = lseek(fd, 0, SEEK_END);
    if (offset < 0) {
        perror("Failed to seek end of log file");
        exit(1);
    }
    ssize_t written = write(fd, new_msg, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (written < 0) {
        perror("Failed to write to log file");
        exit(1);
    }

    // Close the log file and update the file descriptor
    close(fd);
    log_files[new_msg->ue_id] = fd;
}
