int addEvent(NFAPI_CELLULAR_EVENT_PDU_T *event) {
    // Check if the collection is full
    if (numEvents >= MAX_EVENTS) {
        return -1;
    }

    // Generate a unique event type
    int eventType = generateEventType();

    // Set the UE ID and CELL ID for the event
    event->ueId = rand() % 10 + 1;
    event->cellId = rand() % 10 + 1;

    // Set the status tag for the event
    event->statusTag = NFAPI_CELLULAR_EVENT_PDU_T_STATUS_TAG;

    // Set the event type for the event
    event->eventType = eventType;

    // Add the event to the collection
    events[numEvents++] = *event;

    return 0;
}

// Define a function to remove an event from the collection
int removeEvent(NFAPI_CELLULAR_EVENT_PDU_T *event) {
    // Find the event in the collection
    for (int i = 0; i < numEvents; i++) {
        if (events[i].ueId == event->ueId && events[i].cellId == event->cellId && events[i].eventType == event->eventType) {
            // Remove the event from the collection
            memmove(&events[i], &events[i + 1], sizeof(EventInfo) * (numEvents - i));
            numEvents--;
            return 0;
        }
    }

