void init_cell_configs(int num_cells) {
    // Allocate memory for the array of NRCellConfig structures
    cell_configs = (NRCellConfig*) malloc(num_cells * sizeof(NRCellConfig));

    // Initialize the NRCellID, NRCellRSRP, and NRCellRSRQ values for each structure
    for (int i = 0; i < num_cells; i++) {
