    return (cell_id * 0.1f) - 90.0f;
}

// Function to calculate the longitude based on a given cell ID
float calculate_longitude(int cell_id) {
    // Calculate the longitude based on the cell ID
    return (cell_id * 0.1f) + 180.0f;
}

