    uint64_t rnti;
    bool duplicate;
} RNTI_HASH_MAP_ENTRY_T;

// Define the hash map to store the RNTIs
typedef struct {
    size_t count;
    RNTI_HASH_MAP_ENTRY_T *entries[MAX_BATCH_SIZE];
} RNTI_HASH_MAP_T;

// Define the resource pool for memory management
