NFAPI_CRC_INDICATION_PDU_T* manage_crc_indication_batch(CRC_INDICATION_BATCH_T *batch) {
    // Initialize the hash map for RNTIs
    RNTI_HASH_MAP_T *rnti_map = calloc(1, sizeof(RNTI_HASH_MAP_T));
    rnti_map->count = 0;

    // Iterate over each NFAPI_CRC_INDICATION_PDU_T structure in the batch
    for (size_t i = 0; i < batch->count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = batch->pdu[i];

        // Check if the RNTI is already in the hash map
        bool duplicate = false;
        for (size_t j = 0; j < rnti_map->count; j++) {
            if (rnti_map->entries[j]->rnti == pdu->rnti) {
                duplicate = true;
                break;
            }
        }

        // If the RNTI is a duplicate, retry up to three times before failing
        if (duplicate) {
            for (size_t j = 0; j < MAX_RETRY_COUNT; j++) {
                pdu->rnti = generate_random_rnti();
                duplicate = false;
                for (size_t k = 0; k < rnti_map->count; k++) {
                    if (rnti_map->entries[k]->rnti == pdu->rnti) {
                        duplicate = true;
                        break;
                    }
                }
            }
            if (duplicate) {
                // Log the error and return NULL
                printf("Error: failed to generate unique RNTI after %d retries\n", MAX_RETRY_COUNT);
                free(rnti_map);
                return NULL;
            }
        }

        // Add the RNTI to the hash map
        RNTI_HASH_MAP_ENTRY_T *entry = calloc(1, sizeof(RNTI_HASH_MAP_ENTRY_T));
        entry->rnti = pdu->rnti;
        entry->duplicate = false;
        rnti_map->entries[rnti_map->count++] = entry;
    }

    // Free the hash map memory
    free(rnti_map);

    return batch;
}

// Generate a random RNTI value
uint64_t generate_random_rnti() {
    uint64_t rnti = 0;
    for (size_t i = 0; i < sizeof(uint64_t); i++) {
        rnti |= rand() << (8 * i);
    }
    return rnti;
}

// Initialize the resource pool for memory management
void init_resource_pool(RESOURCE_POOL_T *pool) {
    pool->mem_size = 1024 * 1024 * 1024; // 1 GB
    pool->mem_pool = malloc(pool->mem_size);
    pool->free_list = 0;
}

// Allocate memory from the resource pool
void* allocate_memory(RESOURCE_POOL_T *pool, size_t size) {
    // Check if there is enough memory in the pool to satisfy the allocation
    if (pool->mem_size - pool->free_list < size) {
        // Log the error and return NULL
        printf("Error: out of memory\n");
        return NULL;
    }

    // Find a contiguous block of memory in the pool to allocate from
    void *allocated_memory = (void*)((uintptr_t)pool->mem_pool + pool->free_list);
    pool->free_list += size;

    return allocated_memory;
}

// Free memory back into the resource pool
void free_memory(RESOURCE_POOL_T *pool, void *ptr) {
    // Insert the freed memory block into the pool's free list
    size_t mem_size = pool->free_list - (uintptr_t)ptr;
    if (mem_size >= sizeof(void*)) {
        void **freelist = ptr;
        *freelist = pool->freelist;
        pool->freelist = freelist;
    }
}

// Define the main function
int main() {
    // Initialize the resource pool for memory management
    RESOURCE_POOL_T pool;
    init_resource_pool(&pool);

    // Create a batch of NFAPI_CRC_INDICATION_PDU structures
    CRC_INDICATION_BATCH_T *batch = calloc(1, sizeof(CRC_INDICATION_BATCH_T));
    batch->count = 5;
    for (size_t i = 0; i < batch->count; i++) {
        NFAPI_CRC_INDICATION_PDU *pdu = allocate_memory(&pool, sizeof(NFAPI_CRC_INDICATION_PDU));
        if (pdu) {
            pdu->rnti = generate_random_rnti();
        } else {
            // Log the error and break out of the loop
            printf("Error: failed to allocate memory\n");
            break;
        }
    }

    // Manage the batch of NFAPI_CRC_INDICATION_PDU structures
    CRC_INDICATION_BATCH_T *managed_batch = manage_crc_indication_batch(batch);
    if (managed_batch) {
        for (size_t i = 0; i < managed_batch->count; i++) {
            NFAPI_CRC_INDICATION_PDU *pdu = managed_batch->pdu[i];
            printf("RNTI: %lu\n", pdu->rnti);
        }
    }

    // Clean up the resource pool and free all memory
    free_memory(&pool, batch);
    free(pool.mem_pool);
    return 0;
}
