// Define the maximum number of PDUs to be processed in parallel
#define MAX_PDUS 10000

// Define the structure for holding NFAPI CRC indication PDU data
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for holding the expected CRC values for each UE and RNTI pair
typedef struct {
    int UE_ID;
    int RNTI;
    int EXPECTED_CRC;
} UE_EXPECTED_CRC_T;

// Define the configuration file that specifies the expected CRC values for each UE and RNTI pair
#define CONFIG_FILE "crc_config.txt"

int manage_pdus(NFAPI_CRC_INDICATION_PDU_T *pdu, int num_pdus) {
    // Define the array of NFAPI CRC indication PDU data structures
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_PDUS];

    // Initialize the array with the input PDU data
    for (int i = 0; i < num_pdus; i++) {
        pdus[i] = pdu[i];
    }

    // Load the expected CRC values from the configuration file
    UE_EXPECTED_CRC_T *expected_crcs = load_expected_crcs(CONFIG_FILE);

    // Validate the integrity of each PDU by checking its CRC flag against the expected value
    int failed_pdus = 0;
    for (int i = 0; i < num_pdus; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pdus[i];
        UE_EXPECTED_CRC_T *expected_crc = find_expected_crc(expected_crcs, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
        if (expected_crc != NULL && expected_crc->EXPECTED_CRC != pdu->CRCFLAG) {
            printf("CRC check failed for PDU %d: UE %d, RNTI %d, CRCFLAG %d\n", i, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRCFLAG);
            failed_pdus++;
        }
    }

    // Free the memory used for the expected CRC values
    free(expected_crcs);

    // Return the number of failed PDUs
    return failed_pdus;
}

// Load the expected CRC values from the configuration file
UE_EXPECTED_CRC_T *load_expected_crcs(char *config_file) {
    FILE *f = fopen(config_file, "r");
    if (f == NULL) {
        printf("Error: failed to open config file\n");
        return NULL;
    }

    // Count the number of lines in the configuration file
    int num_lines = 0;
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, f)) != -1) {
        num_lines++;
    }
    free(line);
    line = NULL;

    // Allocate memory for the expected CRC values
    UE_EXPECTED_CRC_T *expected_crcs = malloc(sizeof(UE_EXPECTED_CRC_T) * num_lines);
    if (expected_crcs == NULL) {
        printf("Error: failed to allocate memory for expected CRC values\n");
        fclose(f);
        return NULL;
    }

    // Read the configuration file and populate the expected CRC values array
    int i = 0;
    while ((read = getline(&line, &len, f)) != -1) {
        char *token = strtok(line, " ");
        if (token == NULL) {
            printf("Error: failed to parse config file\n");
            free(expected_crcs);
            fclose(f);
            return NULL;
        }
        expected_crcs[i].UE_ID = atoi(token);
        token = strtok(NULL, " ");
        if (token == NULL) {
            printf("Error: failed to parse config file\n");
            free(expected_crcs);
            fclose(f);
            return NULL;
        }
        expected_crcs[i].RNTI = atoi(token);
        token = strtok(NULL, " ");
        if (token == NULL) {
            printf("Error: failed to parse config file\n");
            free(expected_crcs);
            fclose(f);
            return NULL;
        }
        expected_crcs[i].EXPECTED_CRC = atoi(token);
        i++;
    }
    free(line);
    line = NULL;

    // Return the expected CRC values array
    fclose(f);
    return expected_crcs;
}

// Find the expected CRC value for a given UE and RNTI pair in the expected CRC values array
UE_EXPECTED_CRC_T *find_expected_crc(UE_EXPECTED_CRC_T *expected_crcs, int UE_ID, int RNTI) {
    for (int i = 0; i < num_pdus; i++) {
        if (expected_crcs[i].UE_ID == UE_ID && expected_crcs[i].RNTI == RNTI) {
            return &expected_crcs[i];
        }
    }
    return NULL;
}
