  while (current_list_size < max_list_size && retries < 10) {
    // Fetch UE information from the external data source
    NFAPI_CRC_INDICATION_PDU_T *pdu = fetchUeInfo();

    // Check if the RNTI is unique
    if (isRntiUnique(pdu->RNTI)) {
      // Add the element to the list if it is unique
      addElementToNfapiList(pdu);
    } else {
      // Append a suffix to the RNTI to resolve collisions
      pdu->RNTI = pdu->RNTI + 1;

      // Add the element to the list with the appended RNTI
      addElementToNfapiList(pdu);
    }

    retries++;
  }
}

// Function to check if the RNTI is unique in the list
bool isRntiUnique(uint16_t rnti) {
  // Loop through the list and check if the RNTI already exists
  for (int i = 0; i < current_list_size; i++) {
    if (nfapi_list[i].RNTI == rnti) {
