}

// Function to add an element to the NFAPI list
bool addElementToNfapiList(NFAPI_CRC_INDICATION_PDU_T *pdu) {
  // Check if there is space in the list for another element
  if (current_list_size < max_list_size) {
    // Add the element to the list and increment the current list size
    nfapi_list[current_list_size++] = *pdu;

    return true;
  } else {
    return false;
  }
}

