    configs[M++] = config;
    pkts[M] = pkt;

    return 0;
}

static void removeConfig(uint16_t band, uint8_t subframeNum) {
    // Find the configuration to be removed in the collection
    for (int i = 0; i < M; i++) {
        if (band == configs[i].band && subframeNum == configs[i].subframeNum) {
            // Remove the configuration and packet data from the collection
            for (int j = i; j < M - 1; j++) {
                configs[j] = configs[j + 1];
                pkts[j] = pkts[j + 1];
            }
            M--;
            break;
        }
    }
}

