        if (config.band == configs[i].band && config.subframeNum == configs[i].subframeNum) {
            // Update the configuration and packet data in the collection
            configs[i] = config;
            pkts[i] = pkt;
            break;
        }
    }
}

static NFAPI_TRANSPORT_CONFIG_PDU getConfig(uint16_t band, uint8_t subframeNum) {
    // Find the configuration in the collection
    for (int i = 0; i < M; i++) {
        if (band == configs[i].band && subframeNum == configs[i].subframeNum) {
            return configs[i];
        }
    }
    return NULL;
}

static NFAPI_RX_PKT_PDU getPkt(uint16_t band, uint8_t subframeNum) {
    // Find the packet data in the collection
    for (int i = 0; i < M; i++) {
        if (band == pkts[i].band && subframeNum == pkts[i].subframeNum) {
            return pkts[i];
        }
    }
    return NULL;
}
