// Lock for synchronizing access to the array
static pthread_mutex_t crc_indication_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a CRC indication to the array
void nfapi_add_crc_indication(NFAPI_CRC_INDICATION_PDU_T *crc_indication) {
    // Acquire lock for synchronizing access to the array
    pthread_mutex_lock(&crc_indication_lock);

    // Check if the array is full
    if (crc_indications == NULL || crc_indications->length >= 1000) {
        // Array is full, allocate a new one with double the size
        NFAPI_CRC_INDICATION_PDU_T *new_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 2);
        if (new_array == NULL) {
            // Memory allocation failed, release lock and return
            pthread_mutex_unlock(&crc_indication_lock);
            return;
        }

        // Copy existing elements to the new array
        for (int i = 0; i < crc_indications->length; i++) {
            new_array[i] = crc_indications[i];
        }

        // Free the old array
        free(crc_indications);

        // Set the new array as the current one
        crc_indications = new_array;
    }

    // Add the new CRC indication to the array
    crc_indications[crc_indications->length++] = *crc_indication;

    // Release lock and return
    pthread_mutex_unlock(&crc_indication_lock);
}

// Function to remove a CRC indication from the array
void nfapi_remove_crc_indication(uint16_t rx_ue_information_tag, uint32_t rnti) {
    // Acquire lock for synchronizing access to the array
    pthread_mutex_lock(&crc_indication_lock);

    // Search for the CRC indication to remove
    int index = -1;
    for (int i = 0; i < crc_indications->length; i++) {
        if (crc_indications[i].rx_ue_information_tag == rx_ue_information_tag &&
                crc_indications[i].rnti == rnti) {
            index = i;
            break;
        }
    }

    // If the CRC indication was found, remove it from the array and free the memory
    if (index >= 0) {
        memmove(&crc_indications[index], &crc_indications[index + 1],
                sizeof(NFAPI_CRC_INDICATION_PDU_T) * (crc_indications->length - index));
        crc_indications->length--;
    }

    // Release lock and return
    pthread_mutex_unlock(&crc_indication_lock);
}
