// Structure to hold a CRC indication PDU
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU;

// Structure to hold a doubly-linked list of CRC indication PDUs
typedef struct NFAPI_CRC_INDICATION_PDU_LIST {
    struct NFAPI_CRC_INDICATION_PDU *first;
    struct NFAPI_CRC_INDICATION_PDU *last;
} NFAPI_CRC_INDICATION_PDU_LIST;

// Global variable to hold the list of CRC indication PDUs
NFAPI_CRC_INDICATION_PDU_LIST crc_indication_pdu_list = {NULL, NULL};

// Lock for thread-safe access to the list
pthread_mutex_t crc_indication_pdu_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to create a new CRC indication PDU structure and add it to the list
void add_crc_indication_pdu(uint16_t rx_ue_information_tag, uint32_t rnti, bool crcflag) {
    NFAPI_CRC_INDICATION_PDU *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!new_pdu) {
        printf("Failed to allocate memory for new CRC indication PDU\n");
        return;
    }
    new_pdu->rx_ue_information_tag = rx_ue_information_tag;
    new_pdu->rnti = rnti;
    new_pdu->crc_indication_rel8_tag = crcflag ? 1 : 0;
    pthread_mutex_lock(&crc_indication_pdu_list_lock);
    if (crc_indication_pdu_list.first == NULL) {
        // First element in the list
        crc_indication_pdu_list.first = new_pdu;
        crc_indication_pdu_list.last = new_pdu;
    } else {
        // Add to the end of the list
        crc_indication_pdu_list.last->next = new_pdu;
        new_pdu->prev = crc_indication_pdu_list.last;
        crc_indication_pdu_list.last = new_pdu;
    }
    pthread_mutex_unlock(&crc_indication_pdu_list_lock);
}

// Function to remove a CRC indication PDU structure from the list
void remove_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU *pdu) {
    pthread_mutex_lock(&crc_indication_pdu_list_lock);
    if (pdu->prev == NULL) {
        // First element in the list
        crc_indication_pdu_list.first = pdu->next;
    } else {
        pdu->prev->next = pdu->next;
    }
    if (pdu->next == NULL) {
        // Last element in the list
        crc_indication_pdu_list.last = pdu->prev;
    } else {
        pdu->next->prev = pdu->prev;
    }
    free(pdu);
    pthread_mutex_unlock(&crc_indication_pdu_list_lock);
}

// Function to traverse the list and process each CRC indication PDU structure
void traverse_crc_indication_pdus() {
    NFAPI_CRC_INDICATION_PDU *current = crc_indication_pdu_list.first;
    while (current != NULL) {
        // Process the current CRC indication PDU structure
        current->crc_indication_rel8_tag = 0;
        current = current->next;
    }
}

// Function to log a message about memory allocation failure and return an error status
int memory_allocation_failure(char *message) {
    printf("Memory allocation failed: %s\n", message);
    return -1;
}

// Main function to test the CRC indication PDU management functions
int main() {
    // Add a few CRC indication PDU structures to the list
    add_crc_indication_pdu(1, 2, false);
    add_crc_indication_pdu(3, 4, true);
    add_crc_indication_pdu(5, 6, false);

    // Remove the first CRC indication PDU structure from the list
    NFAPI_CRC_INDICATION_PDU *first = crc_indication_pdu_list.first;
    remove_crc_indication_pdu(first);

    // Traverse the list and process each CRC indication PDU structure
    traverse_crc_indication_pdus();

