// Structure to represent a TCP connection metadata
typedef struct tcp_conn {
    char ip[16]; // IP address as a string
    int port; // Port number
    int status; // Connection status (e.g., CONNECTED, DISCONNECTED)
    time_t last_active; // Last active timestamp
} tcp_conn;

// Array to store all TCP connections
static tcp_conn *tcp_conns = NULL;

// Size of the array
static int tcp_conn_size = 0;

// Mutex for protecting access to the array
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new TCP connection
void add_tcp_conn(char *ip, int port) {
    // Acquire mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the IP and port are already in the array
    for (int i = 0; i < tcp_conn_size; i++) {
        if (strcmp(tcp_conns[i].ip, ip) == 0 && tcp_conns[i].port == port) {
            // If they are already in the array, update the status and last active timestamp
            tcp_conns[i].status = CONNECTED;
            tcp_conns[i].last_active = time(NULL);
            break;
        }
    }

    // If not already in the array, add a new entry
    if (i == tcp_conn_size) {
        tcp_conn *new_conn = malloc(sizeof(tcp_conn));
        strcpy(new_conn->ip, ip);
        new_conn->port = port;
        new_conn->status = CONNECTED;
        new_conn->last_active = time(NULL);
        tcp_conns[i] = new_conn;
        tcp_conn_size++;
    }

    // Release mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a TCP connection by IP and port
tcp_conn *get_tcp_conn(char *ip, int port) {
    // Acquire mutex lock
    pthread_mutex_lock(&mutex);

    // Search for the IP and port in the array
    for (int i = 0; i < tcp_conn_size; i++) {
        if (strcmp(tcp_conns[i].ip, ip) == 0 && tcp_conns[i].port == port) {
            // If found, return the pointer to the structure
            pthread_mutex_unlock(&mutex);
            return &tcp_conns[i];
        }
    }

    // If not found, return NULL
    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Function to update the status of a TCP connection
void update_tcp_conn(char *ip, int port, int new_status) {
    // Acquire mutex lock
    pthread_mutex_lock(&mutex);

    // Search for the IP and port in the array
    for (int i = 0; i < tcp_conn_size; i++) {
        if (strcmp(tcp_conns[i].ip, ip) == 0 && tcp_conns[i].port == port) {
            // If found, update the status and last active timestamp
            tcp_conns[i].status = new_status;
            tcp_conns[i].last_active = time(NULL);
            break;
        }
    }

    // Release mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to remove a TCP connection by IP and port
void remove_tcp_conn(char *ip, int port) {
    // Acquire mutex lock
    pthread_mutex_lock(&mutex);

    // Search for the IP and port in the array
    for (int i = 0; i < tcp_conn_size; i++) {
        if (strcmp(tcp_conns[i].ip, ip) == 0 && tcp_conns[i].port == port) {
            // If found, remove the entry and update the array size
            free(tcp_conns[i]);
            memmove(&tcp_conns[i], &tcp_conns[i + 1], (tcp_conn_size - i - 1) * sizeof(tcp_conn));
            tcp_conn_size--;
            break;
        }
    }

    // Release mutex lock
    pthread_mutex_unlock(&mutex);
}
```
