struct LTE_UE_Context {
    MAC_CE *mac_ce; // MAC-CE structure
    RRC_ConnectionSetupRequest_t rrc_conn_setup_req; // RRC connection setup request
};

// Context list for managing dynamic allocation of contexts
struct ContextList {
    struct LTE_UE_Context **contexts; // array of pointers to context structures
    size_t num_contexts; // number of contexts in the list
    pthread_mutex_t lock; // mutex for thread safety
};

// Function to add a new context to the list
void addContext(struct ContextList *list, struct LTE_UE_Context *context) {
    pthread_mutex_lock(&list->lock);
    if (list->num_contexts >= 10000) {
        // handle allocation failure gracefully
        perror("Allocation failure");
        exit(EXIT_FAILURE);
    }
    list->contexts[list->num_contexts++] = context;
    pthread_mutex_unlock(&list->lock);
}

// Function to update an existing context in the list
void updateContext(struct ContextList *list, struct LTE_UE_Context *context) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->num_contexts; ++i) {
        if (list->contexts[i] == context) {
            list->contexts[i] = context;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to remove a context from the list
void removeContext(struct ContextList *list, struct LTE_UE_Context *context) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->num_contexts; ++i) {
        if (list->contexts[i] == context) {
            memmove(list->contexts + i, list->contexts + i + 1, sizeof(*context) * (--list->num_contexts - i));
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to retrieve a context from the list based on its MAC-CE structure
struct LTE_UE_Context *getContext(struct ContextList *list, MAC_CE *mac_ce) {
    struct LTE_UE_Context *context = NULL;
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->num_contexts; ++i) {
        if (list->contexts[i]->mac_ce == mac_ce) {
            context = list->contexts[i];
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return context;
}

// Function to free the memory of a context
void freeContext(struct LTE_UE_Context *context) {
    if (context != NULL) {
        free(context->mac_ce);
        free(context->rrc_conn_setup_req.SI.pdu);
        free(context);
    }
}

// Function to clean up the context list and free all memory
void clearContextList(struct ContextList *list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->num_contexts; ++i) {
        freeContext(list->contexts[i]);
    }
    free(list->contexts);
    pthread_mutex_unlock(&list->lock);
}
