    // Find the index of the element to be removed
    size_t i = find_element(list, rx_ue_information_tag, rnti);
    if (i == MAX_SIZE) {
        fprintf(stderr, "Element not found. Cannot remove.\n");
        return -1;
    }

    // Remove the element from the list
    free(list->array[i]);
    memmove(&list->array[i], &list->array[i + 1], (MAX_SIZE - i) * sizeof(struct nfapi_crc_indication_pdu));
    list->num_elements--;

    return 0;
}

// Define the function to find an element in the list by RNTI
size_t find_element(struct nfapi_crc_indication_list *list, uint32_t rx_ue_information_tag, uint32_t rnti) {
    for (size_t i = 0; i < list->num_elements; i++) {
        if (list->array[i]->rx_ue_information_tag == rx_ue_information_tag && list->array[i]->rnti == rnti) {
            return i;
        }
    }

    return MAX_SIZE;
}

// Define the function to track CRC status of each indication
void update_crc_status(struct nfapi_crc_indication_list *list) {
    // Check if the list is empty
    if (list->num_elements == 0) {
        return;
    }

    // Update CRC status of each indication
    for (size_t i = 0; i < list->num_elements; i++) {
        if ((i % 10) == 0 && list->array[i]->crc_indication_rel8.crcflag == 0) {
            list->array[i]->crc_indication_rel8.crcflag = (uint8_t)rand();
        }
    }
}

// Define the function to handle memory allocation failures
void handle_memory_allocation_failure(struct nfapi_crc_indication_list *list, int error_code) {
    fprintf(stderr, "Memory allocation failure (error code %d).\n", error_code);
    // Release resources and retry operations if possible
}

// Define the function to serialize the list to a binary format for persistence
void serialize_list(struct nfapi_crc_indication_list *list, char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s for serialization.\n", filename);
        return;
    }

    // Write the number of elements in the list to the file
    size_t num_elements = list->num_elements;
    if (fwrite(&num_elements, sizeof(size_t), 1, fp) != 1) {
        fprintf(stderr, "Error writing number of elements to file %s.\n", filename);
        return;
    }

    // Write each element in the list to the file
    for (size_t i = 0; i < num_elements; i++) {
        if (fwrite(list->array[i], sizeof(struct nfapi_crc_indication_pdu), 1, fp) != 1) {
            fprintf(stderr, "Error writing element %lu to file %s.\n", i, filename);
            return;
        }
    }
}

// Define the function to deserialize the list from a binary format for persistence
void deserialize_list(struct nfapi_crc_indication_list *list, char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s for deserialization.\n", filename);
        return;
    }

    // Read the number of elements in the list from the file
    size_t num_elements = 0;
    if (fread(&num_elements, sizeof(size_t), 1, fp) != 1) {
        fprintf(stderr, "Error reading number of elements from file %s.\n", filename);
        return;
    }

    // Allocate memory for the list
    list->array = malloc(num_elements * sizeof(struct nfapi_crc_indication_pdu));
    if (list->array == NULL) {
        fprintf(stderr, "Error allocating memory for list.\n");
        return;
    }

    // Read each element in the list from the file
    size_t i = 0;
    while (fread(&list->array[i], sizeof(struct nfapi_crc_indication_pdu), 1, fp) == 1) {
        if ((++i) > num_elements) {
            break;
        }
    }

    // Set the number of elements in the list
    list->num_elements = i;
}

// Define the function to handle CRC indications from the network
void handle_crc_indication(struct nfapi_crc_indication *ind) {
    // Check if the list is empty
    if (list.num_elements == 0) {
        return;
    }

    // Find the index of the CRC indication in the list
    size_t i = find_element(&list, ind->rx_ue_information.rx_ue_information_rel8.rnti, ind->rx_ue_information.rx_ue_information_rel8.rnti);
    if (i == MAX_SIZE) {
        // CRC indication not found in the list, add it to the list
        add_element(&list, ind->rx_ue_information.rx_ue_information_rel8.rnti, ind->crc_indication);
    } else {
        // Update the element in the list with the new CRC indication
        update_element(&list, ind->rx_ue_information.rx_ue_information_rel8.rnti, ind->crc_indication);
    }
}

