// Define the structure to store the NFAPI_CRC_INDICATION_PDU_T data
typedef struct NFAPITag {
  RX_UE_INFORMATION_TAG rxUETag;
  RNTI rnti;
  CRC_INDICATION_REL8_TAG crcIndTag;
  int crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list structure to store the NFAPITag data
typedef struct Node {
  NFAPI_CRC_INDICATION_PDU_T* tag;
  struct Node* next;
} Node;

// Global variables for the linked list and mutex lock
Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate a new node in the linked list
Node* allocNewNode(RX_UE_INFORMATION_TAG rxUETag, RNTI rnti, CRC_INDICATION_REL8_TAG crcIndTag) {
  NFAPI_CRC_INDICATION_PDU_T* tag = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
  tag->rxUETag = rxUETag;
  tag->rnti = rnti;
  tag->crcIndTag = crcIndTag;
  tag->crcFlag = rand() % 2; // Randomly set the CRCFLAG value
  Node* newNode = (Node*)malloc(sizeof(Node));
  newNode->tag = tag;
  newNode->next = NULL;
  return newNode;
}

// Function to add a new node in the linked list
void addNewNode(RX_UE_INFORMATION_TAG rxUETag, RNTI rnti, CRC_INDICATION_REL8_TAG crcIndTag) {
  Node* newNode = allocNewNode(rxUETag, rnti, crcIndTag);
  pthread_mutex_lock(&mutex);
  if (head == NULL) {
    head = newNode;
  } else {
    Node* current = head;
    while (current->next != NULL) {
      current = current->next;
    }
    current->next = newNode;
  }
  pthread_mutex_unlock(&mutex);
}

// Function to remove a node from the linked list
void removeNode(RNTI rnti) {
  Node* current = head;
  Node* previous = NULL;
  while (current != NULL && current->tag->rnti != rnti) {
    previous = current;
    current = current->next;
  }
  if (current == NULL) {
    return;
  }
  if (previous == NULL) {
    head = head->next;
  } else {
    previous->next = current->next;
  }
  free(current->tag);
  free(current);
}

// Function to update a node in the linked list
void updateNode(RX_UE_INFORMATION_TAG rxUETag, RNTI rnti, CRC_INDICATION_REL8_TAG crcIndTag) {
  Node* current = head;
  while (current != NULL && current->tag->rnti != rnti) {
    current = current->next;
  }
  if (current == NULL) {
    return;
  }
  current->tag->rxUETag = rxUETag;
  current->tag->crcIndTag = crcIndTag;
}

// Function to check the consistency of the linked list
void checkConsistency() {
  Node* current = head;
  while (current != NULL) {
    if (current->next != NULL && current->next->tag->rnti == current->tag->rnti) {
      printf("Duplicate RNTI value found in the linked list\n");
      return;
    }
    current = current->next;
  }
}

// Function to calculate the average CRC value across the linked list
int calcAverageCrc() {
  int totalCrc = 0;
  Node* current = head;
  while (current != NULL) {
    totalCrc += current->tag->crcIndTag.crci;
    current = current->next;
  }
  return totalCrc / getListSize();
}

// Function to get the size of the linked list
int getListSize() {
  int size = 0;
  Node* current = head;
  while (current != NULL) {
    size++;
    current = current->next;
  }
  return size;
}

// Function to get the unique RNTI values in the linked list
int getUniqueRntiCount() {
  int count = 0;
  Node* current = head;
  while (current != NULL) {
    if (current->next == NULL || current->next->tag->rnti != current->tag->rnti) {
      count++;
    }
    current = current->next;
  }
  return count;
}

// Function to print the linked list
void printList() {
  Node* current = head;
  while (current != NULL) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", current->tag->rxUETag, current->tag->rnti, current->tag->crcIndTag);
    current = current->next;
  }
}

// Main function to demonstrate the usage of the linked list
int main() {
  // Initialize the linked list
  head = NULL;

  // Add a few nodes to the linked list
  addNewNode(RX_UE_INFORMATION_TAG{0}, RNTI{1}, CRC_INDICATION_REL8_TAG{1});
  addNewNode(RX_UE_INFORMATION_TAG{1}, RNTI{2}, CRC_INDICATION_REL8_TAG{2});
  addNewNode(RX_UE_INFORMATION_TAG{2}, RNTI{3}, CRC_INDICATION_REL8_TAG{3});

  // Update a node in the linked list
  updateNode(RX_UE_INFORMATION_TAG{3}, RNTI{1}, CRC_INDICATION_REL8_TAG{4});

  // Remove a node from the linked list
  removeNode(RNTI{2});

  // Check the consistency of the linked list
  checkConsistency();

  // Print the linked list
  printList();

  // Calculate the average CRC value across the linked list
  int avgCrc = calcAverageCrc();
  printf("Average CRC: %d\n", avgCrc);

  // Get the size of the linked list
  int listSize = getListSize();
  printf("Linked List Size: %d\n", listSize);

  // Get the number of unique RNTI values in the linked list
  int uniqueRntiCount = getUniqueRntiCount();
  printf("Number of Unique RNTIs: %d\n", uniqueRntiCount);

  return 0;
}
