// Define a global allocator for NFAPI_CRC_INDICATION_PDU_T structures
static struct nfapi_crc_indication_pdu_allocator g_allocator = {malloc, free};

// Define a function to generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void generate_and_populate_nfapi_crc_indications(int num_structures) {
  // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
  NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)g_allocator.malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures);
  if (!pdu_list) {
    // Handle memory allocation failure gracefully by returning an error code
    return -1;
  }

  // Populate the list of NFAPI_CRC_INDICATION_PDU_T structures with valid data
  for (int i = 0; i < num_structures; i++) {
    pdu_list[i].rx_ue_information_tag = rand() % 1024;
    pdu_list[i].rnti = rand() % 65536;
    pdu_list[i].crc_indication_rel8_tag = rand() % 1024;
